window.__D("text/zohar/c014",{"p":[[9520011587,"<p>וַיְהִי בַּחֲצִי הַלַּיְלָה וַיְיָ' הִכָּה כָּל בְּכוֹר וְגוֹ'. (כתיב (תהילים ס״ט:י״ד) ואני תפלתי לך יי עת רצון וגו') ר' חִיָּיא ור' יוֹסֵי הֲווֹ אַזְלֵי מֵאוּשָׁא לְלוּד, וַהֲוָה רִבִּי חִיָּיא רָכִיב בְּחַמְרָא. אָמַר ר' יוֹסֵי, נֵיתִיב הָכָא וְנַצְלֵי, דְּהָא מָטָא זִמְנָא דִּצְלוֹתָא דְּמִנְחָה, וְתָנֵינָן, לְעוֹלָם יְהֵא אָדָם זָהִיר בִּצְלוֹתָא דְּמִנְחָה. אֲמַאי זָהִיר. מִשּׁוּם דְּהִיא שַׁעֲתָא דְּתַלְיָא דִּינָא וּבָעֵי בַּר נָשׁ לְכַוְּונָא דַּעְתֵּיהּ, נָחַת ר' חִיָּיא וְצַלֵּי.</p>\n<p>עַד דַּהֲווֹ אַזְלֵי, נָטָה שִׁמְשָׁא לְמֵיעַל. אָמַר רִבִּי חִיָּיא לְר' יוֹסֵי אֲמַאי אַתְּ שָׁתִיק. אָמַר רִבִּי יוֹסֵי, מִסְתַּכֵּל הֲוֵינָא בְּדַעְתָּאי, דְּלֵית עָלְמָא מִתְקַיְּימָא, אֶלָּא עַל רֵישֵׁיהוֹן דְּעַמָּא. אִי רֵישֵׁי עַמָּא זַכָּאִין, טַב לְעָלְמָא, טַב לְעַמָּא. וְאִי לָא זַכָּאִין, וַוי לְעָלְמָא, וַוי לְעַמָּא.</p>\n<p>אָמַר רִבִּי חִיָּיא, וַדַּאי כַּךְ הוּא, מְנָלָן. דִּכְתִּיב, (דברי הימים ב י״ח:ט״ז) רָאִיתִי אֶת כָּל יִשְׂרָאֵל נְפוֹצִים עַל הֶהָרִים כְּצֹאן אֲשֶׁר אֵין לָהֶן רוֹעֶה וַיֹּאמֶר יְיָ לא אֲדֹנִים לָאֵלֶּה יָשׁוּבוּ אִישׁ לְבֵיתוֹ בְּשָׁלוֹם. יָשׁוּבוּ, יֵשְׁבוּ מִבָּעֵי לֵיהּ. לְבֵיתוֹ, בְּבֵיתוֹ מִבָּעֵי לֵיהּ. דְּהָא בְּאַתְרַיְיהוּ קַיְימֵי.</p>\n<p>אֶלָּא הָכִי תָּנֵינָן, אִי רֵישָׁא דְּעַמָּא לָא זָכֵי, עַמָּא מִתָּפְסָן בְּחוֹבֵיהּ. מְנָלָן. דִּכְתִּיב, (שמואל ב כ״ד:י״ז) וַיֹּאמֶר דָּוִד וְגוֹ' הִנֵּה אָנֹכִי חָטָאתִי וְאָנֹכִי הֶעֱוֵיתִי וְאֵלֶּה הַצֹּאן מֶה עָשׂוּ, (ס\"א וכתיב (דברי הימים א כ״א:י״ז) ואני הוא אשר חטאתי וגו') דָּוִד חָב, וְיִשְׂרָאֵל סָבְלוּ. וְאִי רֵישָׁא דְּעַמָּא מִתְפַּס בְּחוֹבֵיהּ, עַמָּא מִשְׁתֵּזְבָן. דְּהָא דִּינָא לָא שַׁרְיָא עָלַיְיהוּ. דִּכְתִּיב, וַיֹּאמֶר יְיָ לֹא אֲדֹנִים לָאֵלֶּה, כְּלוֹמַר, (ס\"א אם אלו) אִלּוּ לָא הֲווֹ רֵישִׁין לְעַמָּא, מֵהַאי אוֹרְחָא יָשׁוּבוּ אִישׁ לְבֵיתוֹ בְּשָׁלוֹם. כֻּלְּהוּ מִשְׁתֵּזְבָן, אִי רֵישֵׁיהוֹן מִתָּפְסָן. וַאֲפִילּוּ יְהוֹשָׁפָט אִתְגְּזַר עָלֵיהּ לְאִתְעַנְּשָׁא, מִשּׁוּם דְּאִתְחֲבָּר בְּאַחְאָב. אִי לָאו הַהוּא צְוָוחָא, דִּכְתִּיב, (מלכים א כ״ב:ל״ב) וַיִּזְעַק יְהוֹשָׁפָט.</p>\n<p>עַד דַּהֲווֹ אַזְלֵי רָמַשׁ לֵילְיָא, אָמְרוּ, מַה נַּעְבִיד, אִי נֵיזִיל חָשַׁךְ לֵילְיָא, אִי נֵיתִיב דַּחֲלָא הוּא. סָטוּ מֵאוֹרְחָא, יָתְבוּ תְּחוֹת אִילָנָא חַד. וְיָתְבוּ וַהֲווּ אַמְרֵי מִלֵּי דְּאוֹרַיְיתָא, וְלָא דְּמִיכוּ.</p>\n<p>בְּפַלְגוּת לֵילְיָא, חָמוּ חַד אַיַּלְתָּא דְּעָבְרָא קָמַיְיהוּ, וַהֲוַת צַוְחַת וּרְמִיאַת קָלִין שָׁמְעוּ, קָמוּ ר' חִיָּיא ור' יוֹסֵי וְאִזְדַּעֲזָעוּ. שָׁמְעוּ חַד קָלָא דְּמַכְרְזָא וְאָמַר, מִתְעָרִין קוּמוּ. נַיְימִין אִתְּעָרוּ. עָלְמִין, אִזְדְּמָנוּ לְקָדְמַת מָרֵיכוֹן. (דהא קלא נפק דכאיב אילתא דלעילא ותתא. דכתיב (תהילים כ״ט:ט׳) קול יי' יחולל אילות ויחשוף יערות) דְּהָא מָרֵיכוֹן מַפִיק לְגַּן עֵדֶן, דְּאִיהוּ הֵיכָלֵיהּ, לְאִשְׁתַּעְשְׁעָא עִם צַדִּיקַיָּא, דִּכְתִּיב וּבְהֵיכָלוֹ כֻּלּוֹ אוֹמֵר כָּבוֹד.</p>\n<p>אָמַר רִבִּי חִיָּיא, הַשְׁתָּא פָּלְגוּ דְּלֵילְיָא מַמָּשׁ. וְקָלָא דָּא, הוּא קָלָא דְּנָפַק, וְכָאִיב אַיַּלְתָּא דִּלְעֵילָּא וְתַתָּא, דִּכְתִּיב קוֹל יְיָ' יְחוֹלֵל אַיָּלוֹת. זַכָּאָה חוּלָקָנָא, דְּזָכֵינָא לְמִשְׁמַע דָּא.</p>\n<p>וְתָא חֲזֵי רָזָא דְּמִלָּה, בְּשַׁעֲתָא דְּקוּדְשָׁא בְּרִיךְ הוּא אִתְחָזֵי עַל (ויצא קע\"ו) גִּנְתָּא, כָּל גִּנְתָּא אִתְכְּנַשׁ, וְלָא מִתְפְּרַשׁ מֵעֵדֶן. וּמֵהַאי עֵדֶן מַבּוּעֵי נָפְקִין, לְכַמָּה אוֹרְחִין וּשְׁבִילִין, וְהַאי גִּנְתָּא, אִתְקְרֵי צְרוֹרָא (קע\"ג) דְּחַיֵּי, דְּתַמָּן מִתְעַדְּנִין צַדִּיקַיָּא, מִנְּהִירוּ דְּעָלְמָא דְּאָתֵי. וּבְהַאי שַׁעֲתָא, קוּדְשָׁא בְּרִיךְ הוּא אִתְגְּלֵי עָלַיְיהוּ. וְתָנֵינָן בְּשַׁעֲתָא דְקוּדְשָׁא בְּרִיךְ הוּא אִתְעַר בְּגִנְתָּא דְעֶדֶן לְאִשְׁתָּעֲשֶׁעָא עִם צָדִיקַיָּיא כָּרוֹזָא נָפִיק וְקַרֵי עוּרִי צָפוֹן וּבֹאִי תֵּימָן הֲפִיחִי גָּנִי יִזְּלוּ בְּשַׂמָיו יָבוֹא דּוֹדִי לְגָנוֹ וְיֹאכַל פֶּרִי מְגַדָיו מַאי וְיֹאכַל פֶּרִי מְגַדָיו אִלֵין קֹרְבָּנִין דְּאִתְקְרַבוּ קַמֵּיהּ מִּנִשְׁמָתֵּיהוֹן דְצַדִיקָיָּיא הָאי בְּפַלְגוּת לֵילְיָא בְּשַׁעֲתָא אַחֲרָא שְׁאָר קֹרְבָּנִין מַמָּשׁ.</p>\n<p>יָתְבוּ רִבִּי חִיָּיא וְרִבִּי יוֹסֵי, אָמַר רִבִּי יוֹסֵי, בְּכַמָּה זִמְנִין שָׁאִילְנָא, הַאי דִּכְתִּיב, וַיְהִי בַּחֲצִי הַלַּיְלָה וַיְיָ' הִכָּה כָל בְּכוֹר בְּאֶרֶץ מִצְרַיִם אֲמַאי לָא הֲוָה בִּימָמָא, דְּיִתְגְּלֵי לְכָל פִּרְסוּמֵי נִיסָא, וַאֲמַאי מִיתוּ כָּל אִינּוּן חַלָּשֵׁי דְּבָתַר רֵחַיָּיא, וְאִינּוּן טַלְיָיא דִּבְנֵי עָאנָא, וְלָא מִיתוּ מַלְכֵי וּפַרְדַּשְׁכֵי, וְגוּבְרֵי מַגִּיחֵי קְרָבָא, כְּמָה דְּהֲוָה בְּסַנְחֵרִיב, דִּכְתִּיב, (מלכים ב י״ט:ל״ה) וַיֵּצֵא מַלְאַךְ יְיָ' וַיַּךְ בְּמַחֲנֵה אַשּׁוּר וְגוֹ'. וְתָנֵינָן, כֻּלְּהוּ מַלְכִין בְּנֵי מַלְכִין רוּפִינוּס וּפַרְדַּשְׁכֵי, הָתָם <Nonei></i>אִתְחָזֵי גְּבוּרְתָּא דְּחָד שְׁלִיחָא דִּילֵיהּ, יַתִּיר מֵהַאי, דְּהֲוָה יֵאוֹת לְמֶהֱוֵי דִּילֵּיהּ יַתִּיר.</p>\n<p>אָמַר לֵיהּ יֵאוֹת שָׁאַלְתְּ, וַאֲנָא לָא שְׁמַעְנָא מִידִי בְּהַאי, וְלָא אֵימָא, אֲבָל הָא זָכֵינָא לְכָל הַאי, וְאָרְחָא אִתְתְּקַן קָמָן. אֲנָא שְׁמַעְנָא דְּרִבִּי שִׁמְעוֹן בֶּן יוֹחָאי מַדְכֵי שְׁוָקִין דִּטְבֶרְיָה, נֵיזִיל גַּבֵּיהּ. יָתְבוּ, עַד דְּהֲוָה נָהִיר יְמָמָא. כַּד סָלִיק נְהוֹרָא, קָמוּ וְאַזְלֵי. כַּד מָטוּ גַּבֵּיהּ. אַשְׁכְּחוּהוּ, דְּהֲוָה יָתִיב, וְסִפְרָא דְּאַגַּדְתָּא בִּידֵיהּ.</p>\n<p>פָּתַח וְאָמַר, (ישעיהו מ׳:י״ז) כָּל הַגּוֹיִם כְּאַיִן נֶגְדּוֹ מֵאֶפֶס וָתֹהוּ נֶחְשְׁבוּ לוֹ. כֵּיוָן דְּאָמַר, כָּל הַגּוֹיִם כְּאַיִן נֶגְדּוֹ, לָמָּה כְּתִיב מֵאֶפֶס וָתֹהוּ נֶחְשְׁבוּ לוֹ. אֶלָּא אוֹלִיפְנָא, דַּעְתַּיְיהוּ דְּכָל עַמִּין דְּעָלְמָא, דִּמְהֵימָנוּתָא דִּלְהוֹן הוּא כְּאַיִן, דְּלָא אִדְבָּקוּ עִלָּאִין וְתַתָּאִין, (בתתאין) וְשַׁוְיָין לָקָבְלַיְיהוּ מְהֵימָנוּתָא דִּשְׁטוּתָא, אֲבָל מֵאֶפֶס וָתֹהוּ נֶחְשְׁבוּ לוֹ, כְּהַאי עִלְעוֹלָא, דְּסַחֲרָא (ס\"א דפרחא) בְּרוּחָא, וּמִתְגַּלְגְּלָא בְּקָיְטָא בְּרֵיקַנְיָּא, הֲדָא הוּא דִכְתִיב, (דניאל ד׳:ל״ב) וְכָל דַּיְּירֵי אַרְעָא כְּלָא חֲשִׁיבִין.</p>\n<p>עוֹד פָּתַח וְאָמַר, בְּרֵאשִׁית בָּרָא אֱלֹהִים אֵת הַשָּׁמַיִם וְאֵת הָאָרֶץ, אֵת דָּא יְמִינָא דְּקוּדְשָׁא בְּרִיךְ הוּא, וְאֵת דָּא שְׂמָאלָא. אוֹלִיפְנָא, דְּסָטָא קוּדְשָׁא בְּרִיךְ הוּא יְמִינֵיהּ, וּבָרָא יַת שְׁמַיָּא, וְסָטָא שְׂמָאלָא, וּבָרָא יַת אַרְעָא. הֲדָא הוּא דִכְתִיב, (ישעיהו מ״ח:י״ג) אַף יָדִי יָסְדָה אֶרֶץ וִימִינִי טִפְּחָה שָׁמָיִם קוֹרֵא אֲנִי אֲלֵיהֶם יַעַמְדוּ יַחְדָּו.</p>\n<p>מַהוּ יַעַמְדוּ יַחְדָּו. סַלְּקָא דַּעְתָּךְ שְׁמַיָּא וְאַרְעָא לָאו הָכִי, (נ\"א מהשמים קורא אני אליהם והארץ לאו הכי) אֶלָּא יְמִינָא וּשְׂמָאלָא דְּאִינּוּן אֵ\"ת וְאֵ\"ת, וְהֵיאַךְ יַעַמְדוּ יַחְדָּו. בְּזֹאת הַהִיא, דְּשַׁלְטָא בְּפַלְגוּת לֵילְיָא, דִּכְלִילָא אֵ\"ת בְּזֹאת.</p>\n<p>וְתָנִינָן, כְּתִיב (קהלת ג׳:י״א) אֶת הַכֹּל עָשָׂה יָפֶה בְעִתּוֹ. אֶ\"ת, הָא דְּאַמָרָן. הַכֹּל, כְּמָה דְאַתְּ אָמֵר, (בראשית כ״ד:א׳) וַיְיָ' בֵּרַךְ אֶת אַבְרָהָם בַּכֹּל. וְתָאנָא, דְּהִיא כִּתְרָא דְּאִתְקְרֵי זֹא\"ת, דִּכְלִילָא מֵאֶ\"ת וְאֵ\"ת. וְשָׁלְטָא בְּפַלְגוּת לֵילְיָא, בִּתְרֵין סִטְרוֹי, בְּרַחֲמֵי וְדִינָא, רַחֲמֵי לְיִשְׂרָאֵל, וְדִינָא לְעַמִּין עוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת.</p>\n<p>פָּתַח ר' חִיָּיא וְאָמַר, אִי נִיחָא קָמֵיהּ דְּמֹר, דְּנֵימָא חַד מִלָּה, עַל מַה דְּאָתֵינָא כְּתִיב, וַיְהִי בַּחֲצִי הַלַּיְלָה וַיְיָ' הִכָּה כָל בְּכוֹר בְּאֶרֶץ מִצְרַיִם. וּמֵהַאי דְּאָמַר מֹר, אִשְׁתְּמַע דְּהַאי פְּסוּקָא בְּהַהוּא מִלָּה אָתָא וַאֲנָן אוֹרְחָא אִתְתַּקְנָא קָמָּן, לְמֵיתֵי לְמִשְׁאַל קַמָּךְ.</p>\n<p>פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר, (תהילים קי״ג:ה׳) מִי כַּיְיָ' אֱלֹהֵינוּ הַמַּגְבִּיהִי לָשָׁבֶת וְגוֹ'. מִי כַּיְיָ' אֱלֹהֵינוּ, דְּסָלִיק וְאִתְעַטָּר לְאִתְיַשְּׁבָא בְּכִתְרָא עִלָּאָה קַדִּישָׁא, נְהִירוּ עַל כָּל בּוּצִינִי דְּנָהֲרוּ כִּתְרִין וְעִטְּרִין. הַמַּשְׁפִּילִי לִרְאוֹת, דְּנָחִית בְּכִתְרוֹי, מִכִּתְרָא לְכִתְרָא, מִנִּזְרָא לְנִזְרָא, מִנְּהִירוּ לִנְהִירוּ, מִבּוּצִינָא לְבוּצִינָא. לְאַשְׁגְּחָא בְּעִלָּאִין וְתַתָּאִין, הֲדָא הוּא דִכְתִיב, (תהילים י״ד:ב׳) יְיָ' מִשָּׁמַיִם הִשְׁקִיף עַל בְּנֵי אָדָם וְגוֹ'.</p>\n<p>תָּא חֲזֵי, כְּתִיב, וַיְהִי בַּחֲצִי הַלַּיְלָה. כַּחֲצִי מִבָּעֵי לֵיהּ, אוֹ כַּחֲצוֹת, כְּגַוְונָא דְּאָמַר מֹשֶׁה. וְאִי כְּמָה דְּאַמְרֵי חַבְרָנָא, דְּלָא יִיִמְרוּן אִצְטַגְנִינֵי פַּרְעֹה, מֹשֶׁה בַּדַּאי הוּא. הָא קוּשְׁיָא בְּאַתְרֵיהּ קַיְּימָא, בג' גַּוְונֵי, דְּאֲפִילּוּ יִשְׂרָאֵל יֵימְרוּן הָכִי. חַד, דְּאִי הָכִי הֲוָה לֵיהּ לְמֵימָר וַיֹּאמֶר מֹשֶׁה כַּחֲצוֹת הַלַּיְלָה. אֲמַאי קָאָמַר, כֹּה אָמַר יְיָ' וְגוֹ'. כְּמָה דְּלָא אִתְכְּוָון שַׁעֲתָא, דְּהָא לָא יִתָּפְסוּן בְּמֹשֶׁה, אֶלָּא בְּפַטְרוֹנָא, בְּגִין דְּאָמַר כֹּה אָמַר יְיָ' וְגוֹ'. תְּרֵי, דְּהָא מֹשֶׁה אָמַר, עַד בְּכוֹר הַשִּׁפְחָה אֲשֶׁר אַחַר הָרֵחָיִם, וְלָא הֲוָה הָכִי, אֶלָּא עַד בְּכוֹר הַשְּׁבִי אֲשֶׁר בְּבֵית הַבּוֹר. עַל כָּל פָּנִים אֲפִילּוּ יִשְׂרָאֵל נַמֵי יִיִמְרוּן הָכִי, דְּהָא לָא אִתְבַּרְרוּן מִלֵּי. תְּלַת דְּאִיהוּ אָמַר מִשְׁמָא דְּפַטְרוֹנָא כַּחֲצוֹת, וּכְתִיב וַיְהִי בַּחֲצִי הַלַּיְלָה.</p>\n<p>וְעוֹד, שְׁאֵלְתָּא דִּילְכוֹן, יַתִּיר עַל מָטוּל דְּלָא יָכִיל בְּעִירָא לְמִסְבַּל. אֲמַאי הֲוָה בְּפַלְגוּת לֵילְיָא, וְלָא בִּימָמָא. וַאֲמַאי מִיתוּ כָּל אִינּוּן חַלָּשִׁין דְּבָתַר רֵחַיָּא. אֶלָּא כֹּלָּא רָזָא עִלָּאָה הוּא, בֵּין מְחַצְּדֵי חַקְלָא, וְכֹלָּא אִתְכְּשַׁר (נ\"א אתבשר) בִּנְבִיאָה מְהֵימָנָא.</p>\n<p>זַכָּאָה חוּלָקֵיהּ דְּמֹשֶׁה, דְּעָלֵיהּ כְּתִיב (תהלים נה) יָפְיָפִיתָ מִבְּנֵי אָדָם הוּצַק חֵן בְּשִׂפְתוֹתֶיךָ עַל כֵּן בֵּרַכְךָ אֱלֹהִים לְעוֹלָם. אָהַבְתָּ צֶּדֶק וַתִּשְׂנָא רֶשַׁע עַל כֵּן מְשָׁחֲךָ אֱלהִים אֱלֹהֶיךָ שֶׁמֶן <Nonei></i>שָׂשׂוֹן מֵחֲבֵרֶיךָ. יָפְיָפִיתָ מִבְּנֵי אָדָם: מִשֵּׁת וַחֲנוֹךְ. הוּצַק חֵן בְּשִׂפְתוֹתֶיךָ: מִנֹּחַ וּבָנָיו. עַל כֵּן מְשָׁחֲךָ אֱלֹהִים אֱלֹהֶיךָ: מֵאַבְרָהָם וְיִצְחָק. שֶׁמֶן שָׂשׂוֹן: מִיַּעֲקֹב. מֵחֲבֵרֶיךָ: מִשְּׁאָר נְבִיאֵי. וְכִי גֶּבֶר דְּסָלִיק בְּדַרְגִּין עִלָּאִין דְּלָא סָלִיק בַּר נָשׁ אַחֲרָא, לָא יָדַע מַה דְּאָמַר.</p>\n<p>אֶלָּא הָכִי תָּנֵינָן, הַאי כִּתְרָא דְּאִקְרֵי זֹא\"ת, אִתְקְרֵי אִשָּׁ\"ה, כְּמָה דְאַתְּ אָמֵר, (בראשית ב׳:כ״ג) לְזֹאת יִקָּרֵא אִשָּׁה. אֲמַאי. מִשּׁוּם כִּי מֵאִישׁ לֻקֳּחָה זֹּאת. מַאן הוּא אִישׁ. הַהוּא דְּאִקְרֵי זֶה. וְדָא הוּא אִישׁ דְּכָר, כְּמָה דְאַתְּ אָמֵר (שמות ל״ב:א׳) כִּי זֶה מֹשֶׁה הָאִישׁ. הָאִישׁ הַזֶּה. וְאִקְרֵי אִישׁ זֶה, וְזֶה אִישׁ. וְזֹאת, אִתְנְסִיבַת מִזֶּה דְּאִקְרֵי זָכָר.</p>\n<p>וּבְגִין דָּא, אִיהִי תָּמָר דְּכָר וְנוּקְבָּא, דְּלָא סָלִיק דָּא בְּלֹא דָּא. תָּמָר: כְּמָה דְאַתְּ אָמֵר, (שיר השירים ג׳:ו׳) כְּתִמְרוֹת עָשָׁן. מַה עָשָׁן, סָלִיק חִוָּור וְאוּכָם, אוּף הָכָא, כֹּלָּא כָּלִיל בָּהּ בְּפַלְגוּת לֵילְיָא, לְמֶעְבַּד נִימוּסוֹי בְּחַד שַׁעֲתָא, חִוָּור לְיִשְׂרָאֵל, וְאוּכָם לְעוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת.</p>\n<p>וְעוֹד דְּהַאי לֵילְיָא לָא אִתְפְּלַג, לָא עָבִיד נִימוּסוֹי. מְנָא לָן. מֵאַבְרָהָם. דִּכְתִּיב, (בראשית י״ד:ט״ו) וַיֵּחָלֵק עֲלֵיהֶם לַיְלָה, דְּאִתְפְּלַג לְמֶעְבַּד נִימוּסוֹי. (מהו כחצות כמה דאת אמר (מלכים א' י\"ח) כעלות המנחה (איוב ה׳:כ״ו) כעלות גדיש אוף הכא כחצות) כְּמִפְלַג. דְּמֹשֶׁה יָדַע דְּלָא יַעְבֵּיד נִימוּסוֹי, עַד דְּאִתְפְּלַג.</p>\n<p>וְהָכִי הֲוָה, דְּלָא עָבִיד לֵילְיָא נִימוּסוֹי, עַד דְּאִתְפְּלַג, בְּפַלְגוּת בַּתְרָאָה, עָבֵד נִימוּסוֹי, הֲדָא הוּא דִכְתִיב וַיְהִי בַּחֲצִי הַלַּיְלָה. מַאי בַּחֲצִי. בְּפַלְגוּת בַּתְרָאָה, בְּזִמְנָא דְּאִיהִי שַׁלְטָא, וְאִשְׁתְּכַח הַאי זֹאת, לְמֶעְבַּד נִמּוּסִין תָּדִירָא, וְכָל נִימוּסָא דְּאִתְעָבִיד בְּלֵילְיָא, בְּפַלְגוּתָא בַּתְרָאָה אִתְעָבִיד.</p>\n<p>וַיְיָ' הִכָּה כָל בְּכוֹר, וַיְיָ': הוּא וּבֵית דִּינוֹ, וַיְיָ': הוּא וְנִימוּסוֹי. הִכָּה כָל בְּכוֹר הִכָּה, מֹשֶׁה לֹא אָמַר אֶלָּא וּמֵת וְגוֹ', מַהוּ הִכָּה. אֶלָּא, דְּאִתְּעַר כֹּה, כְּמָה דְּאַגְזִים מֹשֶׁה, דִּכְתִּיב וְהִנֵּה לֹא שָׁמַעְתָּ עַד כֹּה.</p>\n<p>וְתָאנָא, פַּרְעֹה חַכִּים הֲוָה מִכָּל חֲרָשׁוֹי, וְאִסְתַּכַּל בְּהַאי זֹאת, דְּיַעֲבֵיד בֵּיהּ דִּינָא, וְזַמִין לְחָרְבָא אַרְעֵיהּ, כְּמָה דְּאָמַר מֹשֶׁה, בְּזֹאת תֵּדַע כִּי אֲנִי יְיָ'. וּבְאִיהוּ מַה כְּתִיב, וַיִּפֶן פַּרְעֹה. מַהוּ וַיִּפֶן. דְּאַפְנֵי לִבֵּיהּ מֵהִרְהוּרָא דָּא. כְּמָה דְאַתְּ אָמֵר, (במדבר י״ב:י׳) וַיִּפֶן אַהֲרֹן. וַיָּבוֹא אֶל בֵּיתוֹ וְלֹא שָׁת לִבּוֹ גַּם לְזֹאת. גַּם לְרַבּוֹת הַאי דִּזְמִינָא לְחָרְבָא אַרְעֵיהּ, וְלָא שָׁוֵי לִבֵּיהּ לָקֳבְלֵיהּ דְּזֹא\"ת.</p>\n<p>כָל בְּכוֹר, אֲפִילּוּ דַּרְגִּין עִלָּאִין וְתַתָּאִין, אִתְּבָּרוּ מִשּׁוּלְטָנֵהוֹן, (ס\"א משלשוליהון) כָל אִינּוּן דְּשַׁלְטִין בְּחָכְמְתָא דִּלְהוֹן, דִּכְתִּיב, בְּאֶרֶץ מִצְרַיִם. וְכֻלְּהוּ דַּרְגִּין, עִלָּאִין וְתַתָּאִין, דְּאִתְּבָּרוּ מִשּׁוּלְטָנִהוֹן, (ס\"א משלשוליהון) כֻּלְּהוּ בִּפְסוּקָא אִתְחָזוּן, (ס\"א אתרמיזו) דִּכְתִּיב מִבְּכוֹר פַּרְעֹה הַיּוֹשֵׁב עַל כִּסְאוֹ עַד בְּכוֹר הַשִּׁפְחָה אֲשֶׁר אַחַר הָרֵחָיִם וְכֹל בְּכוֹר בְּהֵמָה, הָא כֻּלְּהוּ אִתְחָזוּן בִּפְסוּקָא.</p>\n<p>סְתָמָא דְּמִלָּה, מִבְּכוֹר פַּרְעֹה הַיּוֹשֵׁב עַל כִּסְאוֹ, כִּתְרָא תַּתָּאָה דְּקוּזְמִיטָא דְּמַלְכוּתָא (נ\"א ממלכותא) דִּלְעֵילָּא. עַד בְּכוֹר הַשִּׁפְחָה, כִּתְרָא שְׂמָאלָא, תַּתָּאָה מִינָהּ, דְּקוּזְמִיטָא מִבָּתַר אַרְבַּע (נ\"א מכתרה אחר) רְחַיִּין, אַרְבַּע מַשִׁירְיָין. (משמע') מִשּׁוּם דִּכְתִּיב אַחַר הָרֵחָיִם, (ולא מן הרחים.) וְכֹל בְּכוֹר בְּהֵמָה, תַּתָּאִין מִתַּתָּאִין, נוּקְבָּא מִנּוּקְבְתָא, דְּאִשְׁתְּכָחוּ בְּאָתָנֵי בִּבְעִירֵי וַחֲמָרֵי, בְּרַבְרְבֵי בְּזוּטְרֵי, וּמְקַבְּלִין מִנְּהוֹן גּוּבְרִין וְנוּקְבִין. עַד בְּכוֹר הַשְּׁבִי אֲשֶׁר בְּבֵית הַבּוֹר, אִינּוּן דְּנָפְקִין מִשִּׁפְחָה. דִּי בְּהוֹן עַבְדִין לַאֲסִירֵי, דְּיִשְׁתַּעְבְּדוּן בְּהוֹן לְעָלְמִין, וְלָא יִפְקוּן לְחֵירוּ.</p>\n<p>וּבְרוּחְצָנוּתָא דְּאִלֵּין דַּרְגִּין, סָרִיבוּ מִצְרָאֵי, דִּי בְּהוֹן עֲבָדוּ קִשְׁרָא לְיִשְׂרָאֵל, דְּלָא יִפְקוּן מִן עַבְדוּתְהוֹן לְעָלְמִין. וּבְהַאי אִתְחָזֵי גְּבוּרְתָּא וְשֻׁלְטָנוּתָא דְּקוּדְשָׁא בְּרִיךְ הוּא, וְדֻכְרָנָא דָּא לָא יִשְׁתֵּצֵי מִיִּשְׂרָאֵל לְדָרֵי <Nonei></i>דָּרִין, דְּאִי לָא הֲוָה חֵילָא וּגְבוּרְתָּא דְּקוּדְשָׁא בְּרִיךְ הוּא, כָּל מַלְכֵי עַמִּין, וְכָל חָרָשֵׁי עָלְמִין, וְחַכִּימֵי עָלְמִין, לָא יִפְקוּן לְיִשְׂרָאֵל מִן עַבְדוּתָא, דְּשָׁרָא קִטְרִין דִּלְהוֹן, וְתָבַר כָּל אִינּוּן כִּתְרִין, בְּגִין לְאַפָּקָא לוֹן. עַל דָּא כְּתִיב, (ירמיהו י׳:ז׳) מִי לֹא יִרָאֲךָ מֶלֶךְ הַגּוֹיִם כִּי לְךָ יָאָתָה כִּי בְכָל חַכְמֵי הַגּוֹיִם וּבְכָל מַלְכוּתָם מֵאֵין כָּמוֹךָ.</p>\n<p>בָּכָה רַבִּי שִׁמְעוֹן, אָרִים קָלֵיהּ וְאַתְנַח, אָמַר קִנְטוּרָא דְּקִיטְפָא אִשְׁתְּכַח, חֲשַׁבְתּוּן דְּשָׁבַח קוּדְשָׁא בְּרִיךְ הוּא כַּמָּה זִמְנִין, (דברים ה׳:ו׳) אֲשֶׁר הוֹצֵאתִיךָ מֵאֶרֶץ מִצְרַיִם, (דברים ט״ז:ג׳) הוֹצִיאֲךָ יְיָ' אֱלהֶיךָ מִמִּצְרַיִם, (דברים ה׳:ט״ו) וַיּוֹצִיאֲךָ יְיָ' אֱלהֶיךָ מִשָּׁם, (שמות י״ב:י״ז) הוֹצֵאתִי אֶת צִבְאוֹתֵיכֶם, (שמות י״ג:ג׳) זָכוֹר אֶת הַיּוֹם הַזֶּה אֲשֶׁר יְצָאתֶם מִמִּצְרַיִם, (דברים יד) וַיּוֹצִיאֲךָ בְּפָנָיו בְּכֹחוֹ הַגָּדוֹל מִמִּצְרַיִם, (שמות י״ג:ג׳) הוֹצִיא יְיָ' אֶתְכֶם מִזֶּה.</p>\n<p>אֶלָּא תָּאנָא, י' כִּתְרִין, אִינּוּן לְתַתָּא, כְּגַוְונָא דִּלְעֵילָּא, וְכֻלְּהוּ סְתִימִין, בִּתְלָתָא אִלֵּין דְּאַמָרָן. וּתְלַת קִשְׁרִין קְשִׁירוּ בְּהוּ, עַל ג' דַּרְגִּין אִלֵּין דִּבְהוּ עַבְדוּ, דְּיִשְׂרָאֵל לָא יִפְקוּן מִשִּׁעְבּוּדְהוֹן לְעָלְמִין.</p>\n<p>זַכָּאִין אַתּוּן אַבְרָהָם יִצְחָק וְיַעֲקֹב, דְּבִזְכוּתְכוֹן שָׁרִיאוּ קִטְרִין, וְקוּדְשָׁא בְּרִיךְ הוּא דְּכָר תְּלַת קִטְרֵי מְהֵימָנוּתָא דִּלְכוֹן הֲדָא הוּא דִכְתִיב, (שמות ב׳:כ״ד) וַיִּזְכֹּר אֱלֹהִים אֶת בְּרִיתוֹ אֶת אַבְרָהָם אֶת יִצְחָק וְאֶת יַעֲקֹב. אֶת אַבְרָהָם, הָא קִשְׁרָא חֲדָא, דְּאַבְרָהָם. אֶת יִצְחָק, הָא קִשְׁרָא תִּנְיָינָא, דְּיִצְחָק. וְאֶת יַעֲקֹב, הָא קִשְׁרָא תְּלִיתָאָה, שְׁלֵימָתָא דְּיַעֲקֹב.</p>\n<p>תָּנָא, כָּל זִמְנִין וְחַגִּין וְשַׁבָּתִין, כֻּלְּהוּ דּוּכְרָנָא לְהַאי, וְעַל הַאי אִתְקַיְימוּ כֻּלְּהוּ, דְּאִלְמָלֵא הַאי, לָא הֲוָה נְטוּרָא דְּזִמְנִין וְחַגִּין וְשַׁבָּתִין. וּבְגִינֵי כַּךְ, לָא אִשְׁתְּצֵי דֻּכְרָנָא דְּמִצְרַיִם מִכָּל זִמְנִין וְחַגִּין וְשַׁבָּתִין. תָּא חֲזֵי דִּינָא (ס\"א דא') הוּא יְסוֹדָא וְשָׁרָשָׁא דְּאוֹרַיְיתָא, וְכָל פִּקוּדוֹי, וְכָל מְהֵימָנוּתָא שְׁלֵימָתָא דְּיִשְׂרָאֵל.</p>\n<p>וְעוֹד אֲמַאי לָא הֲוָה בִּימָמָא דְּשָׁאִילְתּוּ. תָּנֵינָן, כְּתִיב הַיּוֹם אַתֶּם יוֹצְאִים, וּכְתִיב הוֹצִיאֲךָ יְיָ' אֱלֹהֶיךָ מִמִּצְרַיִם לַיְלָה. אֶלָּא תָּאנָא, עִקָרָא דְּפוּרְקָנָא דְּיִשְׂרָאֵל, לָא הֲוָה אֶלָּא בַּלַּיְלָה, דְּלֵילְיָא שָׁרָא קִטְרִין, וְעָבִיד נוּקְמִין, וְיוֹמָא אַפִּיק לוֹן בְּרֵישׁ גַּלֵּי, הֲדָא הוּא דִּכְתִּיב, (במדבר ל״ג:ג׳) יָצְאוּ בְּנֵי יִשְׂרָאֵל בְּיַד רָמָה לְעֵינֵי כָּל מִצְרָיִם. (נ\"א ועוד לילה שארי קטרין ועבד נוקמין ודינין ויומא גלי ופרסם ניסא ונוקמא דאתעביד הדא הוא דכתיב יצאו בני ישראל ביד רמה וגו'.) וּכְתִיב וּמִצְרַיִם מְקַבְּרִים אֵת אֲשֶׁר הִכָּה יְיָ' בָּהֶם כָּל בְּכוֹר, דָּא הוּא פִּרְסוּמֵי נִיסָא.</p>\n<p>אָתוּ ר' חִיָּיא ור' יוֹסֵי, אִשְׁתְּטָחוּ קָמֵיהּ, וְנָשְׁקוּ יְדוֹי. וּבָכוּ וְאָמְרוּ, גְּלִיפִין עִלָּאִין וְתַתָּאִין, זַקְפָן רֵישָׁא בְּגִינָךְ, עָבֵד קוּדְשָׁא בְּרִיךְ הוּא יְרוּשָׁלַיִם לְתַתָּא, כְּגַוְונָא דִּלְעֵילָּא. עָבֵד (רשב\"י) שׁוּרֵי קַרְתָּא קַדִּישָׁא וְתַרְעוֹי. מַאן דְּעָיִיל, לָא עָיֵיל, עַד דְּיִפְתְּחוּן תַּרְעִין. מַאן דְּסָלִיק, לָא סָלִיק, עַד דְּיִתְתַּקְנוּן דַּרְגִין דְּשׁוּרֵי מַאן יָכִיל לְמִפְתַּח תַּרְעִין דְּקַרְתָּא קַדִּישָׁא, וּמַאן יָכִיל לְאַתְקְנָא דַּרְגִּין דְּשׁוּרֵי, דָּא רִבִּי שִׁמְעוֹן בֶּן יוֹחָאי, דְּאִיהוּ פָּתַח תַּרְעִין דְּרָזֵי דְּחָכְמְתָא, וְאִיהוּ אַתְקִין דַּרְגִּין עִלָּאִין, וּכְתִיב (שמות לה) יֵרָאֶה כָּל זְכוּרְךָ אֶת פְּנֵי הָאָדוֹן יְיָ'. מַאן פְּנֵי הָאָדוֹן יְיָ', דָּא רִבִּי שִׁמְעוֹן בֶּן יוֹחָאי, דְּמַאן דְּאִיהוּ דְּכוּרָא מִן דְּכֻרְנָיא, בָּעֵי לְאִתְחֲזָאָה קָמֵיהּ.</p>\n<p>אָמַר לוֹן, עַד הַשְׁתָּא, לָא סִיַּימְנָא מִלָּה דִּשְׁאֶלְתָּא דִּילְכוֹן, דְּהָא תָּנֵינָן, וַיְיָ' הִכָּה כָל בְּכוֹר, כָל בְּכוֹר סְתָם, כִּדְקָאמְרַן. וְכֹלָּא הֲוָה כְּמָה דְּאִינּוּן דְּמִיתוּ, אִינּוּן קְטוּרֵי קִטְרִין, דַּהֲווֹ מִשְׁתַּמְּשֵׁי בְּחָרָשַׁיְיהוּ בְּאִינּוּן כִּתְרִין. מִנְהוֹן מִשְׁתַּמְּשֵׁי בְּעִלָּאֵי, וּמִנְהוֹן בְּתַתָּאֵי, וְאַף עַל גַּב דְּכֻלְּהוּ תַּתָּאִין אִינּוּן. וְכָל אַרְעָא דְּמִצְרַיִם מַלְיָא חֲרָשִׁין הֲוָה. וּכְתִיב כִּי אֵין בַּיִת אֲשֶׁר אֵין שָׁם מֵת.</p>\n<p>וְאִתְעָבִיד דִּינָא בְּכֹלָּא, בְּשַׁעֲתָא דְּאִתְכְּנָשׁוּ כֻּלְּהוּ בְּבָתֵּיהוֹן, וְלָא הֲווֹ מִתְפַּזְּרֵי בְּמַדְבְּרָא וּבְחַקְלָא, אֶלָּא כֻּלְּהוּ אִשְׁתְּכָחוּ בְּבָתֵּיהוֹן, (ואור הנר יפה לבדיקה מבחוץ) וְעָבִיד לֵילְיָא דִּינוֹי בְּכֹלָּא בְּהַהִיא שַׁעֲתָא. וְתָנָא הֲוָה נָהִיר לֵילְיָא כְּיוֹמָא דִּתְקוּפָה דְּתַמּוּז, וְחָמָא כָּל עַמָּא דִּינוֹי דְּקוּדְשָׁא בְּרִיךְ הוּא, הֲדָא הוּא דִכְתִיב (תהילים קל״ט:י״ב) וְלַיְלָה כַּיּוֹם יָאִיר כַּחֲשֵׁכָה כָּאוֹרָה.</p>\n<p>וּבְשַׁעֲתָא דְּנָפְקוּ אִשְׁתְּכָחוּ כֻּלְּהוֹן מֵתִין בַּשְּׁוָקִין לְעֵינֵיהוֹן דְּכֹלָּא, בַּעְיָין לְאַקְבְרָא לְהוּ וְלָא אַשְׁכָּחוּ, וְדָא אַקְשֵׁי לְהוּ מִכֹּלָּא. חָמוּ לְיִשְׂרָאֵל נָפְקִין <Nonei></i>לְעֵינֵיהוֹן בְּחַד גִּיסָא, וְחָמוּ לְמֵיתֵיהוֹן בְּאִידָךְ גִּיסָא. וּבְכֹלָּא הֲוָה פִּרְסוּמֵי נִיסָא, דְּלָא הֲוָה כְּהַאי מִיּוֹמָא דְּאִתְבְּרֵי עָלְמָא.</p>\n<p>וְתָּא חֲזֵי, כְּתִיב לֵיל שִׁמוּרִים הוּא לַיְיָ' לְהוֹצִיאָם וְגוֹ', הוּא הַלַּיְלָה הַזֶּה לַיְיָ' שִׁמוּרִים לְכָל בְּנֵי יִשְׂרָאֵל וְגוֹ', הַאי פְּסוּקָא קַשְׁיָא כֵּיוָן דְּאָמַר לֵיל, מַהוּ שִׁמוּרִים, וְלָא שִׁמּוּר, שִׁמּוּר מִבָּעֵי לֵיהּ. וּכְתִיב הוּא הַלַּיְלָה הַזֶּה, לֵיל קָאָמַר בְּקַדְמִיתָא, וּבָתַר לַיְלָה.</p>\n<p>אֶלָּא הָכִי תָּנֵינָן, כְּתִיב, (דברים כ״ב:כ״ג) כִּי יִהְיֶה נַעֲרָה בְתוּלָה. נַעַר כְּתִיב, מַאי טַעְמָא. מִשּׁוּם דְּכָל זְמָן דְּלָא קַבִּילַת דְּכַר, אִתְקְרֵי נַעַר, מִדְּקַבִּילַת דְּכַר, אִתְקְרֵי נַעֲרָה. אוּף הָכָא, לֵיל עַד לָא קַבִּילַת דְּכַר. וְאַף עַל גַּב דִּכְתִּיב בֵּיהּ שִׁמוּרִים דְּכַר הֲוָה זַמִּין לְאִתְחַבְּרָא עִמָּהּ וּבְשַׁעֲתָא דְּאִתְחֲבָּר עִמָּהּ דְּכַר, כְּתִיב, הוּא הַלַּיְלָה הַזֶּה לַיְיָ' שִׁמוּרִים. שִׁמוּרִים: דְּכַר וְנוּקְבָּא. וּבְגִינֵי כַּךְ כְּתִיב הַלַּיְלָה הַזֶּה.</p>\n<p>וּבַאֲתַר דְּאִשְׁתְּכָחוּ דְּכַר וְנוּקְבָּא, לֵית שְׁבָחָא אֶלָּא לִדְכוּרָא. וְהָכִי שַׁבָּחוּ יִשְׂרָאֵל בְּתוּשְׁבַּחְתַּיְיהוּ. לִדְכוּרָא וְלָא לְנוּקְבָּא, הֲדָא הוּא דִכְתִיב, (שמות ט״ו:ב׳) זֶה אֵלִי וְאַנְוֵהוּ. דְּלֵית שְׁבָחָא בְּאֲתָר דִּדְכוּרָא וְנוּקְבָּא אִשְׁתְּכָחוּ, אֶלָּא לִדְכוּרָא. וְעַל דָּא (נ\"א ולדא) מְחַכָּאן יִשְׂרָאֵל, דִּכְתִּיב, (ישעיה יב) זֶה יְיָ' קִוִּינוּ לוֹ נָגִילָה וְנִשְׂמְחָה בִּישׁוּעָתוֹ. מִשּׁוּם דְּהָכִי זַמִּין לְמֶעְבַּד לְהוּ, דִּכְתִּיב, (מיכה ו׳:ד׳) כִּימֵי צֵאתְךָ מֵאֶרֶץ מִצְרָיִם אַרְאֶנּוּ נִפְלָאוֹת.</p>\n<p>וְרָזָא דָּא הָכִי הוּא, כְּגַוְונָא דְּהָכָא לֵיל וְלַיְלָה, כַּךְ זַמִּין קוּדְשָׁא בְּרִיךְ הוּא לְמֶעְבַּד לְהוּ, דִּכְתִּיב, (ישעיהו כ״א:י״א) שׁוֹמֵר מַה מִּלַּיְלָה שׁוֹמֵר מַה מִלֵּיל. מַה לְּהַלָּן שְׁמִירָה וְלֵיל, אוּף כָּאן שְׁמִירָה וְלֵיל. מַה לְּהַלָּן שְׁמִירָה וְלַיְלָה, אוּף כָּאן שְׁמִירָה וְלַיְלָה.</p>\n<p>וְלַיְלָה אִתְקְרֵי אֲגַב דְּכוּרָא, הֲדָא הוּא דִכְתִיב, (ישעיהו כ״א:י״ב) אָתָא בֹּקֶר וְגַם לַיְלָה. בֹּקֶר: כְּמָה דְאַתְּ אָמֵר (בראשית י״ט:כ״ז) וַיַּשְׁכֵּם אַבְרָהָם בַּבֹּקֶר. דְּהוּא מִדָּתוֹ מַמָּשׁ. וּכְתִיב (תהילים ה׳:ד׳) יְיָ' בֹּקֶר תִּשְׁמַע קוֹלִי, בֹּקֶר מַמָּשׁ.</p>\n<p>יָתְבוּ ר' חִיָּיא ור' יוֹסֵי, וְאוֹלִיף לְהוּ רָזָא דְּתוֹרַת כֹּהֲנִים, וַהֲווּ מְהַדְּרֵי בְּכָל יוֹמָא וְיַתְבֵי קָמֵיהּ. חַד יוֹמָא נָפַק רַבִּי שִׁמְעוֹן לְבַר, אָזְלוּ בַּהֲדֵיהּ, מָטוּ לְחַד חַקְלָא יָתְבוּ.</p>"],[9520011588,"<p>פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר, תָּא חֲזֵי, כְּתִיב, (קהלת ז׳:ט״ו) אֶת הַכֹּל רָאִיתִי בִּימֵי הֶבְלִי יֵשׁ צַדִּיק אוֹבֵד בְּצִדְקוֹ וְיֵשׁ רָשָׁע מַאֲרִיךְ בְּרָעָתוֹ, שְׁלמֹה דַּהֲוַת חָכְמְתָא יְתֵירָא (נ\"א יקירא) עַל כֹּלָּא, מַאי קָאָמַר בְּהַאי קְרָא. אֶלָּא, שְׁלֹמֹה רֶמֶז דְּחָכְמְתָא קָא רָמַז. דְּהָא חָזֵינָן אוֹרְחוֹי דְּקוּדְשָׁא בְּרִיךְ הוּא דְּלָאו הָכִי, דְּהָא כְּתִיב, (ירמיהו י״ז:י׳) וְלָתֵת לְאִישׁ כִּדְרָכָיו וְכִּפְרִי מַעֲלָלָיו. אֶלָּא תְּרֵי עִנְיָינֵי נִינְהוּ, דְּקָא רָמַז הָכָא.</p>\n<p>דְּתָנֵינָן, כַּד עֵינוֹי דְּקוּדְשָׁא בְּרִיךְ הוּא בָּעָאן לְאַשְׁגָּחָא בְּעָלְמָא, וּלְעַיְינָא בֵּיהּ, כְּמָה דִּכְתִּיב (ס\"א עיני ה' המה משוטטות בכל הארץ (זכריה ד׳:י׳) וכתיב כי וגו') (דברי הימים ב ט״ז:ט׳) כִּי יְיָ' עֵינָיו מְשׁוֹטְטוֹת בְּכָל הָאָרֶץ, וְאַשְׁכְּחָן חַיָּיבִין בְּעָלְמָא, הַהוּא צַדִּיקָא דְּאִשְׁתְּכַח בְּדָרָא, אִתְּפַס בְּחוֹבַיְיהוּ. וְחַיָּיבַיָּא מַאֲרִיךְ קוּדְשָׁא בְּרִיךְ הוּא רוּגְזֵיהּ עִמְּהוֹן עַד דִּיתוּבוּן. וְאִי לָאו, לָא יִשְׁתְּכַּח מַאן דְּיִתְבַּע רַחֲמֵי עֲלֵיהוֹן, הֲדָא הוּא דִכְתִיב, יֵשׁ צַדִּיק אוֹבֵד בְּצִדְקוֹ, מִשּׁוּם דְּהַהוּא זַכָּאָה, אִסְתַּלָּק מֵעָלְמָא.</p>\n<p>בְּגִינֵי כַּךְ תָּנֵינָן, לְעוֹלָם אַל יָדוּר אָדָם אֶלָּא בִּמְקוֹם שֶׁאַנְשֵׁי מַעֲשֵׂה דָּרִים בְּתוֹכוֹ. מַאי טַעֲמָא. מִשּׁוּם דְּוַוי לְהַאי דְּמָדוֹרֵיהּ בֵּין חַיָּיבַיָּא, דְּהוּא אִתְּפַס בְּחוֹבַיְיהוּ, וְאִי דִּיוֹרֵיהּ בֵּין זַכָּאִין, אוֹטִיבִין לֵיהּ בְּגִינֵיהוֹן.</p>\n<p>דְּהָא רַב חַסְדָּא, הֲוָה דִּיוֹרֵיהּ בְּקַדְמִיתָא בֵּינֵי קַפּוּטְקָאֵי, וַהֲוָה דְּחִיקָא לֵיהּ שַׁעֲתָא, וּמַרְעִין רַדְפִין אֲבַתְרוֹי. נָטַל וְשַׁוֵּי מָדוֹרֵיהּ בֵּין מָארֵי תְּרִיסִין דְּצִפּוֹרִי, וְסָלִיק, וְזָכָה לְכַמָּה טָבִין, לְכַמָּה עוּתְרָא, לְכַמָּה אוֹרַיְיתָא, וְאָמַר, כָּל הַאי זָכֵינָא, עַל דְּעָאלִית בֵּין אִינּוּן דְּקוּדְשָׁא בְּרִיךְ הוּא אַשְׁגַּח לְאוֹטָבָא לְהוּ.</p>\n<p>דָּבָר אַחֵר, אֶת הַכֹּל רָאִיתִי בִּימֵי הֶבְלִי. וְכִי שְׁלֹמֹה, דְּדַרְגִּין עִלָּאִין דְּחָכְמְתָא הֲווֹ בֵּיהּ, עַל כָּל בְּנֵי דָּרָא דִּכְתִּיב (מלכים א ה׳:י״א) וַיֶּחְכַּם מִכָּל הָאָדָם, (ואשתדלותיה באורייתא למעבד טיבו וקשוט) דִּכְתִּיב, (דברי הימים א כ״ט:כ״ג) וַיֵּשֶׁב שְׁלמֹה עַל כִּסֵּא יְיָ' לְמֶלֶךְ, אָמַר בִּימֵי הֶבְלִי. וּכְתִיב, (קהלת א׳:ב׳) הֲבֵל הֲבָלִים אָמַר קֹהֶלֶת.</p>\n<p>וְתָנָא, ז' שֵׁמוֹת נִקְרָא: שְׁלֹמֹה. יְדִידְיָ\"ה, אָגוּר. בִּן יָקֶ\"א, אִיתִיאֵ\"ל, לְמוֹאֵל. קֹהֶלֶת. קֹהֶלֶת כְּנֶגֶד כֻּלָּם. וְכֻלָּם נִקְרָא <Nonei></i>כְּעֵין שֶׁל מַעְלָה, קֹהֶלֶת כְּנוּפְיָא קַדִּישָׁא דְּבֵי עֲשָׂרָה, בְּגִין כַּךְ קָהָל אֵין פָּחוּת מֵעֲשָׂרָה. וְקָהָל אֲפִילּוּ מֵאָה, וְקֹהֶלֶת כְּלָלָא דְּכֹלָּא, כְּמָה דְאַתְּ אָמֵר (דברים ל״ג:ד׳) קְהִלַת יַעֲקֹב.</p>\n<p>וְתָאנָא, שְׁמוֹתָיו עַל שֵׁם הַחָכְמָה אִתְקְרוּן, וּבְגִין כַּךְ ג' סִפְרִין עָבֵד, שִׁיר הַשִּׁירִים. קֹהֶלֶת. מִשְׁלֵי. וְכֻלְּהוּ לְאַשְׁלְמָא חָכְמְתָא. שִׁיר הַשִּׁירִים לָקֳבֵל דְּחֶסֶד. קֹהֶלֶת לָקֳבֵל דְּדִינָא. מִשְׁלֵי לָקֳבֵל דְּרַחֲמֵי. בְּגִין לְאַשְׁלְמָא חָכְמְתָא, וְהוּא עָבֵד כָּל מַה דְּעָבַד בְּגִין לְאַחֲזָאָה חָכְמְתָא, וְלָקֳבֵל דַּרְגָּא (נ\"א ולקבל דרזא) עִלָּאָה, וְהוּא אָמַר בִּימֵי הֶבְלִי הֲבֵל הֲבָלִים.</p>\n<p>אֶלָּא, רָזָא דְּהֶבֶל יַקִּירָא הוּא. וְהוּא הֶבֶל דְּנָפִיק מִפּוּמָא, וְרָזָא דְּהֶבֶל דְּנָפִיק מִפּוּמָא, קָלָא אִתְעָבִיד מִנֵיהּ. וְתָאנָא, אֵין הָעוֹלָם מִתְקַיֵּים אֶלָּא בְּהֶבֶל פִּיהֶם שֶׁל תִּינוֹקוֹת שֶׁל בֵּית רַבָּן שֶׁלֹּא חָטְאוּ. שֶׁלֹּא חָטְאוּ מַמָּשׁ. וְהֶבֶל אִתְעָבִיד בְּרוּחָא וּמַיָּא, וְכָל מַה דְּאִתְעָבִיד בְּעָלְמָא בְּהֶבֶל אִתְעָבִיד. וְרָזָא דְּהַאי הֶבֶל שֶׁל תִּינוֹקוֹת אִתְעָבִיד קָלָא, וְאִתְפָּשַּׁט בְּעָלְמָא, וְאִינּוּן נְטוּרֵי עָלְמָא, וּנְטוּרֵי קַרְתָּא, הֲדָא הוּא דִכְתִיב, (תהילים קכ״ז:א׳) אִם יְיָ' לֹא יִשְׁמָר עִיר וְגוֹ'.</p>\n<p>וְתָּא חֲזֵי, הוּא הֶבֶל, הוּא קָלָא. מַה בֵּין הַאי לְהַאי. הֶבֶל (הוא קלא) קָאִים בְּחֵילָא, לְמֵיפַק קָלָא. קָלָא מַמָּשׁ קָאִים בְּקִיּוֹמֵהּ (דלא) לְאַפָּקָא (אחרא) מִלָּה. וְהַהוּא הֶבֶל דְּהֲוָה אַחַסַנְתֵּיהּ דַּאֲבוֹי קַרְיֵיהּ הֶבֶל, וּמִנֵּיהּ חָזָא כָּל מַה דְּחָזָא. וְאַף עַל גַּב דְּסִיּוּעִין סַגִּיאִין מֵעֵילָּא אַחֲרָנִין הֲווֹ לֵיהּ, וּלְאִשְׁתְּמוֹדְעָא מִלָּה, אָמַר בִּימֵי הֶבְלִי. דְּמִלָּה דָּא מִתַּמָּן אָתָא.</p>\n<p>וְרָזָא דְּמִלָּה הַכֹּל, הָבֶל אֶת הַכֹּל רָאִיתִי בִּימֵי הֶבְלִי, יֵשׁ צַדִּיק אוֹבֵד בְּצִדְקוֹ, דָּא הוּא רָזָא דְּמִלָּה, דְּגַלֵּי וּפַרְסֵם, דְּכֹלָּא תַּלְיָא בִּימֵי הֶבְלִי, כְּלוֹמַר בְּזִמְנָא דְּהַאי הֶבֶל יַנְקָא מִן דִּינָא, בְּגִין לְמֶעְבַּד דִּינָא, צַדִּיק אוֹבֵד בְּצִדְקוֹ, וּבְזִמְנָא דְּהַאי הֶבֶל יַנְקָא מֵרַחֲמֵי. רָשָׁע מַאֲרִיךְ בְּרָעָתוֹ. וְתַרְוַויְיהוּ תַּלְיָין בְּהַאי הֶבֶל, וּבְגִין כָּךְ כְּתִיב בִּימֵי, וְלָא כְּתִיב בְּיוֹם. וְכֹלָּא תַּלְיָין בִּימֵי הֶבֶל דָּא. מַאן דְּאַעְרַע בְּדִינָא, בְּדִינָא. מַאן דְּאַעְרַא בְּרַחֲמֵי, בְּרַחֲמֵי.</p>\n<p>וְאִי תֵּימָא יֵשׁ צַדִּיק אוֹבֵד וְלָא קָאָמַר אָבוּד. הָכִי הוּא אוֹבֵד מַמָּשׁ. דְּהַהוּא דִּינָא אוֹבֵד לַצַּדִּיק מֵעָלְמָא וּמִדָּרָא. וְיֵשׁ רָשָׁע מַאֲרִיךְ בְּרָעָתוֹ, מַאֲרִיךְ מַמָּשׁ, דְּהַהוּא דִּינָא (ס\"א הבל) כַּד יַנְקָא מֵרַחֲמֵי, עָבִיד רַחֲמֵי לְהַהוּא רָשָׁע, וּמַאֲרִיךְ לֵיהּ.</p>\n<p>עַד דַּהֲווֹ יַתְבֵי חָמוּ קִטוֹרָא דְּהֲוָה סָלִיק לְעֵילָּא וְנָחִית לְתַתָּא. אָמַר אִתְעַטָּרוּתָא אִתְעַטָּר בְּטִינָתָא (נ\"א בעניותא) דְּאַרְעָא, מִגּוֹ לְעֵילָּא. אַדְּהָכִי, סָלִיק הַהוּא חַקְלָא רֵיחָא, מִכָּל בּוּסְמִין, אָמַר נֵיתִיב הָכָא, דִּשְׁכִינְתָּא גַּבָּן אִתְקְיָים. בְּגִין כַּךְ, כְּרֵיחַ שָׂדֶה אֲשֶׁר בֵּרַכוֹ יְיָ'.</p>"],[9520011589,"<p>פָּתַח וְאָמַר, (בראשית כ״ז:כ״ז) וַיָּרַח אֶת רֵיחַ בְּגָדָיו וַיְבָרַכֵהוּ וַיֹּאמֶר רְאֵה רֵיחַ בְּנִי וְגוֹ', וַיָּרַח אֶת רֵיחַ בְּגָדָיו, מַשְׁמַע דְּאִינּוּן לְבוּשִׁין הֲווֹ סַלְּקִין רֵיחָא טָבָא, (ס\"א דלא אתעדי) וּלְבַתָר אִתְעָדֵי מִנְּהוֹן הַהוּא רֵיחָא. הַשְׁתָּא אִית לְאִסְתַּכְּלָא, כְּתִיב, רֵיחַ בְּגָדָיו, וּכְתִיב רֵיחַ בְּנִי, וְלָא אָמַר רֵיחַ הַבְּגָדִים, אֶלָּא רֵיחַ בְּנִי. אֶלָּא תָּאנָא, כֵּיוָן שֶׁנִּכְנָס יַעֲקֹב, נִכְנַס עִמּוֹ גַּן עֵדֶן. וְתָאנָא, אוֹתָן הַבְּגָדִים הָיוּ שֶׁל אָדָם הָרִאשׁוֹן, דִּכְתִּיב, (בראשית ג׳:כ״א) וַיַּעַש יְיָ' אֱלֹהִים לְאָדָם וּלְאִשְׁתּוֹ כָּתְנוֹת עוֹר וַיַּלְבִּישֵׁם, וְהוֹצִיאָם מִגַּן עֵדֶן.</p>\n<p>וְאִי תֵּימָא, דִּכְתִּיב וַיִּתְפְּרוּ עֲלֵה תְאֵנָה דְּאִינּוּן הֲווֹ, אִי הָכִי, אֲמַאי כְּתִיב וַיַּעַש ה' אֱלֹהִים. וּכְתִיב כָּתְנוֹת עוֹר, הָא לָא הֲווֹ אֶלָּא עֲלֵה תְאֵנָה אֶלָּא כְּתַרְגּוּמוֹ, לְבוּשִׁין דִּיקָר וַהֲווּ סַלְּקִין רֵיחִין מִבּוּסְמָא דְּעֵדֶן.</p>\n<p>וְתַנְיָא, בְּשֵׁם מָלֵא אִתְעָבִידוּ, דִּכְתִּיב וַיַּעַש ה' אֱלֹהִים. מַה דְּלָא אִתְעָבִידוּ בֵּיהּ שְׁמַיָּא וְאַרְעָא. וְלָא. וְהָא כְּתִיב, (בראשית ב׳:ד׳) בְּיוֹם עֲשׂוֹת יְיָ' אֱלֹהִים אֶרֶץ וְשָׁמָיִם. לָא קַשְׁיָא הַאי כַּד אִתְעָבִידוּ, לָא אִתְעָבִידוּ בְּשֵׁם מָלֵא, בַּר כַּד אִתְקַיְימוּ, בְּשֵׁם מָלֵא אִתְקַיְימוּ.</p>\n<p>וּמַה דְּאָמְרוּ דְּאִינּוּן לְבוּשִׁין אָתוּ לְהַהוּא רָשָׁע דְּעֵשָׂו, דְּנָסִיב לוֹ מִן נִמְרוֹד הָכִי אוֹקִימְנָא, וְקַשְׁיָא מִלָּה, דְּאִי הָכִי הָא כְּתִיב לְאָדָם וּלְאִשְׁתּוֹ, לְבוּשִׁין לְאָדָם, וּלְבוּשִׁין לְחַוָּה. לְבוּשִׁין דְּחַוָּה מַה אִתְעָבִידוּ. וְתוּ, דְּאִי הָכִי <Nonei></i>בְּמַאי אִתְקְבָרוּ, סַלְּקָא דַּעְתָּךְ דְּאִינּוּן שָׁבְקוּ וְרָאמוּ מִנְּהוֹן זֹהֲרָא עִלָּאָה, דְּיָהִיב לוֹן קוּדְשָׁא בְּרִיךְ הוּא.</p>\n<p>אֶלָּא אִינּוּן לְבוּשִׁין דְּאִתְלְבָּשׁוּ בְּהוּ אָדָם וְאִתְּתֵיהּ, לָא אִתְלָבַשׁ בְּהוּ בַּר נָשׁ אַחֲרָא, דִּבְאִינּוּן לְבוּשִׁין דָּמוּ כְּגַוְונָא דִּלְעֵילָּא וְאִי סַלְּקָא דַּעְתָּךְ, דְּאִינּוּן אִתְלַבָּשׁוּ מִגַּרְמֵיהוֹן בְּהוּ. תָּא חֲזֵי, כְּתִיב וַיַּלְבִּישֵׁם, דְּקוּדְשָׁא בְּרִיךְ הוּא אַלְבִּישׁ לוֹן, זַכָּאָה חוּלָקֵיהוֹן.</p>\n<p>כְּתִיב. (תהילים ק״ד:א׳) ה' אֱלֹהַי גָּדַלְתָּ מְאֹד הוֹד וְהָדָר לָבָשְׁתָּ. וּכְתִיב (תהילים צ״ו:ו׳) הוֹד וְהָדָר לְפָנָיו. וּכְתִיב (תהילים ק״ד:ב׳) עוֹטֶה אוֹר כַּשַּׂלְמָה וְגוֹ'. כֵּיוָן דְּאִתְלָבַּשׁ (מה דאתלבש) עָבֵד מַה דְּעָבַד. מְלַמֵּד, שֶׁנִּתְעַטָּף קוּדְשָׁא בְּרִיךְ הוּא בְּאוֹר, וּבָרָא יַת שְׁמַיָּא. אֶלָּא בְּמַאי אוֹקִימְנָא הַחֲמֻדֹת אֲשֶׁר אִתָּה בַּבָּיִת. הַחֲמוּדוֹת: בִּגְדֵי מַלְכוּת (נ\"ח ע\"ג) בְּמֶשִׁי וְזָהָב, וְאָרְחָא דְּעָלְמָא דְּגַנְזֵי לוֹן בְּבוּסְמִין וְרִיחִין, לִיקָרָא דִּלְבוּשֵׁיהוֹן.</p>\n<p>תָּא חֲזֵי וַיָּרַח אֶת רֵיחַ בְּגָדָיו, בַּתְּחִלָּה. וְכַד אַרְגִּישׁ, אָמַר רְאֵה רֵיחַ בְּנִי, דְּיָדַע דְּבֵיהּ הֲוָה תַּלְיָא מִלְּתָא, דִּבְגִינֵיהּ סָלִיק רֵיחָא. כְּרֵיחַ שָׂדֶה אֲשֶׁר בֵּרַכוֹ יְיָ', וְכִי מְנַּיִין הֲוָה יָדַע יִצְחָק רִיחַ שָׂדֶה אֲשֶׁר בֵּרַכוֹ יְיָ'.</p>\n<p>אֶלָּא, תְּרֵין מִלִּין אִינּוּן, וְכֹלָּא הוּא חַד. דִּכְתִּיב, (בראשית כ״ד:ס״ג) וַיֵּצֵא יִצְחָק לָשׂוּחַ בַּשָּׂדֶה לִפְנוֹת עָרֶב. וְכִי לָא הֲוָה לֵיהּ בֵּיתָא, אוֹ מָקוֹם אַחֵר לְהִתְפַּלֵּל. אֶלָּא אוֹתָהּ הַשָּׂדֶה הָיָה אֲשֶׁר קָנָה אַבְרָהָם סָמוּךְ לַמְּעָרָה, דִּכְתִּיב, (בראשית כ״ג:כ׳) הַשָּׂדֶה אֲשֶׁר קָנָה אַבְרָהָם מֵאֵת בְּנִי חֵת. וּבְשַׁעֲתָא דְּהֲוָה יִצְחָק עָאל גַּבֵּיהּ, חָמָא שְׁכִינְתָּא עָלֵיהּ, וְסָלִיק רֵיחִין עִלָּאִין קַדִּישִׁין, וּבְגִינֵי כַּךְ הֲוָה מְצַלֵּי תַּמָּן, וּקְבָעֵיהּ לִצְלוֹתֵיהּ.</p>\n<p>וְאַבְרָהָם אֲמַאי לָא הֲוָה מְצַלֵּי תַּמָּן, מִשּׁוּם דִּקְבִיעוּתָא דְּאַתְרָא אַחֲרָא הֲוָה לֵיהּ בְּקַדְמִיתָא, וּמִלָּה אַחֲרָא רֵיחָא דְּחָמָא בְּהַר הַמּוֹרִיָּה. וְלָמָּה נִקְרָא מוֹרִיָּה. עַל שֵׁם הַמֹּר הַטּוֹב דְּהֲוָה תַּמָּן.</p>\n<p>וְכֹלָּא הֲוָה, וְגַּן עֵדֶן דְּעָאל עִמֵּיהּ וּבַרְכֵיהּ. וּבְגִין כַּךְ לָא תָּלָה מִלָּה בִּלְבוּשִׁין, אֶלָּא בְּיַעֲקֹב מַמָּשׁ, דְּחָמָא דְּבֵיהּ הֲוָה תַּלְיָא מִלָּה (ס\"א ו' אות הוה לאתברכה) וְאִתְחַזֵּי, וּזְכוּתֵיהּ סָלִיק לְאִתְבָּרְכָא, וְעָאל עִמֵּיהּ גַּן עֵדֶן. וּבְגִין כָּךְ כַּד אִתְרָעַם עֵשָׂו, אֲמַר גַּם בָּרוּךְ יִהְיֶה. (מלה)</p>\n<p>אָמַר רִבִּי יִצְחָק, לָא אִצְטְרִיךְ אוֹרַיְיתָא לְמִכְתַּב אֶלָּא מֵהַחֹדֶשׁ הַזֶּה לָכֶם רֹאשׁ חֳדָשִׁים. מַאי טַעֲמָא. מִשּׁוּם דְּשֵׁירוּתָא דְּסִיהֲרָא הֲוֵי, וְעַל דָּא אוֹרַיְיתָא הֲוָה אִצְטְרִיךְ לְמִכְתַּב מֵהָכָא, דְּהָא בְּקוּדְשָׁא בְּרִיךְ הוּא אִתְקָשַּׁר מִלָּה.</p>\n<p>וְלָא קַשְׁיָא, דְּלָא כְּתִיב זֹאת, הַחֹדֶשׁ הַזֹּאת, דְּהָא זֶה וְזֹאת כְּחַד מִתְקַשְּׁרִין וּבַאֲתַר דְּאִית בֵּיהּ דְּכָר וְנוּקְבָּא כַּחֲדָא, לֵית שְׁבָחָא אֶלָּא לִדְכוּרָא, וְעַל דָּא רִאשׁוֹן הוּא לָכֶם לְחָדְשֵׁי הַשָּׁנָה, לְחָדְשֵׁי הַשָּׁנָה וַדַּאי. אָמַר רִבִּי יְהוּדָה, לָכֶם תְּרֵי זִמְנֵי לָמָּה. אָמַר רִבִּי יִצְחָק, מִנַּיְיהוּ, אִשְׁתְּמַע יַתִּיר, כְּמָה דִּכְתִּיב, (דברים ל״ב:ט׳) כִּי חֵלֶק ה' עַמּוֹ. אִתְקְשָׁרוּתָא דָּא לָכֶם, וְלָא לִשְׁאַר עַמִּין.</p>"],[9520011590,"<p>(שמות י״ב:ג׳) דַּבְּרוּ אֶל כָּל עֲדַת יִשְׂרָאֵל לֵאמֹר בֶּעָשׂוֹר לַחֹדֶשׁ הַזֶּה וְיִקְחוּ לָהֶם אִישׁ שֶׂה וְגוֹ', בֶּעָשׂוֹר, אֲמַאי בֶּעָשׂוֹר. אָמַר רִבִּי אַבָּא, בְּזִמְנָא דְּאַנְהִיר יוֹבְלָא לְסִיהֲרָא, דִּכְתִּיב בְּיוֹבְלָא, בֶּעָשׂוֹר לַחֹדֶשׁ הַשְּׁבִיעִי הַזֶּה יוֹם הַכִּפּוּרִים הוּא.</p>\n<p>וְיִקְחוּ לָהֶם אִישׁ שֶׂה לְבֵית אָבוֹת, אֲמַאי, בְּגִין דִּבְזִמְנָא דָּא אִצְטְרִיךְ לְמֵיגַד לֵיהּ. דְּהָא תָּנֵינָן, בְּמִלְּתָא דָּא אִתְּבַר כִּתְרָא (חדא) תַּתָּאָה, (ע' ע\"ב) דְּמִתְאַחֲדִין בֵּיהּ כָּל שְׁאַר כִּתְרִין תַּתָּאִין, וְעַל דָּא פָּרִישׁ מֹשֶׁה וְאָמַר, מִשְׁכוּ וּקְחוּ לָכֶם צֹאן, כְּמָה דִּכְתִּיב, צֹאן וְעֶבֶד וְשִׁפְחָה.</p>\n<p>אָמַר קוּדְשָׁא בְּרִיךְ הוּא, עֲבִידוּ אַתּוּן עוֹבָדָא לְתַתָּא, וַאֲנָא אִתְּבַר תֻּקְפֵיהוֹן לְעֵילָּא, וּכְמָה דְּתַעְבְּדוּן בְּנוּרָא אַתּוּן, דִּכְתִּיב כִּי אִם צְלִי אֵשׁ, אֲנָא אוּף הָכִי אַעְבִיר אוֹתוֹ בָּאֵשׁ בִּנְהַר דִּינוּר.</p>\n<p>אֲמַאי אִתְנְגִיד בַּעֲשָׂרָה, וְאִתְנְכִיס בְּאַרְבָּעָה עָשָׂר. אָמַר רִבִּי אַבָּא בְּדָא אִתְקַשָּׁרוּ יִשְׂרָאֵל אַרְבַּע מְאָה שְׁנִין. וְאַף עַל גַּב דְּאַרְבַּע מְאָה שְׁנִין לָא אִשְׁתַּעֲבִידוּ בְּהוּ, מִכָּל מָקוֹם, הוֹאִיל וַהֲוָה זַמִּין לְאִתְקַשְּׁרָא בְּהוּ, אִתְחַשִׁיב עָלֵיהּ כְּאִילּוּ אִשְׁתַּעֲבִידוּ בְּהוּ כָּל ת' שְׁנִין. בְּגִין כָּךְ, מְעַכְּבִין לֵיהּ אַרְבַּע יוֹמִין, קְטִירָא בִּרְשׁוּתַיְיהוּ דְּיִשְׂרָאֵל, וּלְבָתַר וְשָׁחֲטוּ אוֹתוֹ כֹּל קְהַל עֲדַת יִשְׂרָאֵל בֵּין הָעַרְבָּיִם.</p>\n<p>אֲמַאי בֵּין הָעַרְבַּיִם. בְּשַׁעֲתָא דְּדִינָא תַּלְיָא, וּבְשַׁעֲתָא דְּאִתְּמְסַר <Nonei></i>מִלָּה דָּא לֵיהּ, עַל יְדוֹי דְּאַבְרָהָם, דִּכְתִּיב (בראשית ט״ו:י״ב) וַיְהִי הַשֶּׁמֶשׁ לָבוֹא וְתַרְדֵּמָה נָפְלָה עַל אַבְרָם וְהִנֵּה אֵימָה חֲשֵׁכָה גְּדוֹלָה נוֹפֶלֶת עָלָיו. אֵימָה: כִּתְרָא חֲדָא. חֲשֵׁכָה: כִּתְרָא אַחֲרָא. גְּדוֹלָה: הַאי דְּהִיא רַבְרְבָא מִכֹּלָּא. וְאַף עַל גַּב דְּאוֹקִימְנָא קְרָא דָּא עַל שְׁאַר שִׁעְבּוּדַיְיהוּ דְּיִשְׂרָאֵל, וְכֹלָּא הֲוָה. כְּגַוְונָא דָּא, (שמות י״ז:י״ד) כִּי מָחֹה אֶמְחֶה, אַתּוּן מִתַּתָּא, וַאֲנָא מֵעֵילָּא.</p>\n<p>תָּנָא, לָא נָפְקוּ יִשְׂרָאֵל מִמִּצְרַיִם, עַד דְּאִתְּבָּרוּ כֻּלְּהוּ שִׁלְטוֹנִין דִּלְעֵילָּא (משלשוליהון) מִשּׁוּלְטָנִיהוֹן, וְנַפְקוּ יִשְׂרָאֵל מֵרְשׁוּתְהוֹן, וְאָעלוּ לִרְשׁוּתָא קַדִּישָׁא עִלָּאָה בְּקוּדְשָׁא בְּרִיךְ הוּא, וְאִתְקָטִירוּ בֵּיהּ, הֲדָא הוּא דִּכְתִּיב, (ויקרא כ״ה:נ״ה) כִּי לִי בְנֵי יִשְׂרָאֵל עֲבָדִים עֲבָדַי הֵם. מַאי טַעֲמָא עֲבָדַי הֵם. אֲשֶׁר הוֹצֵאתִי אוֹתָם מֵאֶרֶץ מִצְרָיִם, דְּאַפָּקִית לְהוּ מֵרְשׁוּתָא אַחֲרָא, וְעָאַלִית לוֹן בִּרְשׁוּתִי.</p>"],[9520011591,"<p>וְהַיְינוּ דְּאָמַר רִבִּי שִׁמְעוֹן, מַאי דִּכְתִּיב, אַךְ בַּיּוֹם הָרִאשׁוֹן תַּשְׁבִּיתוּ שְּׂאוֹר מִבָּתֵּיכֶם כִּי כָּל אוֹכֵל מַחְמֶצֶת. אֲנָא הָכִי אוֹקִימְנָא, הַאי שְּׂאוֹר, וְהַאי מַחְמֶצֶת, דַּרְגָּא חַד אִינּוּן, וְכֻלְּהוּ חַד. רְשׁוּ אוֹחֲרֵי, אִינּוּן שָׁלְטָנִין, דִּמְמָנָן עַל שְׁאַר עַמִּין, וְקָרֵינָן לְהוּ יֵצֶר הָרָע, רְשׁוּתָא אַחֲרָא, אֵל נֵכָר, אֱלהִים אֲחֵרִים. אוּף הָכִי, שְּׂאוֹר, וּמַחְמֶצֶת, וְחָמֵץ, וְכֹלָּא חַד. אָמַר קוּדְשָׁא בְּרִיךְ הוּא, כָּל הָנֵי שָׁנֵי, קַיְימִתוּ בִּרְשׁוּתָא אַחֲרָא, עַבְדִין לְעַם אַחֲרָא, מִכָּאן וּלְהָלְאָה דְּאַתּוּן בְּנִי חוֹרִין, אַךְ בַּיּוֹם הָרִאשׁוֹן תַּשְׁבִּיתוּ שְּׂאוֹר מִבָּתֵּיכֶם. כָּל מַחְמֶצֶת לא תֹאכֵלוּ. וְלֹא יֵרָאֶה לְךָ חָמֵץ.</p>\n<p>אָמַר רִבִּי יְהוּדָה, אִי הָכִי כָּל יְמֵי שַׁתָּא נָמֵי, אֲמַאי שִׁבְעַת יוֹמִין, דִּכְתִּיב שִׁבְעַת יָמִים שְּׂאוֹר לא יִמָּצֵא בְּבָתֵּיכֶם, שִׁבְעַת יָמִים, וְלָא יַתִּיר. אֲמַר לֵיהּ, כָּל זִמְנָא דְּאִתְחַיָּיב בַּר נָשׁ לְאִתְחֲזָאָה גַּרְמֵיהּ בֶּן חוֹרִין, הָכִי אִצְטְרִיךְ, כָּל זִמְנָא דְּלָא אִתְחַיָּיב לָא אִצְטְרִיךְ.</p>\n<p>לְמַלְכָּא דְּעָבַד לְחַד בַּר נָשׁ רוּפִינוּס, כָּל אִינּוּן יוֹמִין דְּסָלִיק לְהַאי דַּרְגָּא, חַדֵּי, וְלָבִישׁ לְבוּשֵׁי יְקַר, לְבָתַר לָא אִצְטְרִיךְ. לְשַׁתָּא אַחֲרָא נָטִיר אִינּוּן יוֹמִין דְּסָלִיק לְיָקִירוּ דָּא, וְלָבַשׁ אִינּוּן לְבוּשִׁין, וְכֵן כָּל שַׁתָּא וְשַׁתָּא כְּהַאי גַּוְונָא יִשְׂרָאֵל, כְּתִיב, שִׁבְעַת יָמִים שְּׂאוֹר לא יִמָּצֵא, דְּאִינּוּן יוֹמֵי חֶדְוָותָא, יוֹמִין דְּסָלִיקוּ לִיקָרָא דָּא, וְנַפְקוּ מִשִּׁעְבּוּדָא אַחֲרָא. וּבְגִין כַּךְ, נַטְרִין בְּכָל שַׁתָּא וְשַׁתָּא, יוֹמִין דְּסָלִיקוּ לְהַאי יְקַר, וְנַפְקוּ מֵרְשׁוּתָא אַחֲרָא, וְעָאלוּ בִּרְשׁוּתָא קַדִּישָׁא, וְעַל דָּא כְּתִיב, שִׁבְעַת יָמִים מַצּוֹת תֹאכֵלוּ.</p>"],[9520011592,"<p>אָמַר רִבִּי שִׁמְעוֹן, מַצַּת כְּתִיב, כְּמָה דְאַתְּ אָמֵר, (יחזקאל א׳:א׳) מַרְאֹת אֱלהִים. וְלָמָּה אִתְקְרֵי מַצַּת. דִּינָא. (רכ\"ג ב') דִּינָא קַדִּישָׁא. דִּינָא דְּאִתְאַחֲדָא בִּשְׁמָא קַדִּישָׁא. דִּינָא דְּלָא הֲוָה תַּקִּיפָא כָּל הַהוּא זִמְנָא בְּגַוַויְיהוּ דְּיִשְׂרָאֵל, דְּהָא קַיְּימָא סִיהֲרָא בִּפְגִימוּתָא. וְעַל דְּקַיְּימָא סִיהֲרָא בִּפְגִימוּתָא, (דברים ט״ז:ג׳) לֶחֶם עֹנִי כְּתִיב.</p>\n<p>מַאי טַעְמָא קַיְּימָא בִּפְגִימוּתָא. בְּגִין דְּלָא אִתְפְּרָעוּ, וְלָא אִתְגַּלְיָא הַאי אָת קַדִּישָׁא. גְּזִירִין הֲווֹ וְלָא אִתְפְּרָעוּ, אֵימָתַי אִתְפְּרָעוּ, בְּשַׁעֲתָא דִּכְתִּיב, (שמות ט״ו:כ״ה) שָׁם שָׂם לוֹ חֹק וּמִשְׁפָּט וְשָׁם נִסָּהוּ, וְאַף עַל גַּב דְּאוֹקִימְנָא הַאי קְרָא בְּמִלָּה אַחֲרָא, כֹּלָּא הֲוָה וְיֵאוֹת.</p>\n<p>וְאִי תֵּימָא דְּבִימֵי יְהוֹשֻׁעַ אִתְפְּרָעוּ. לָאו הָכִי, אֶלָּא אִינּוּן דִּכְתִּיב, (יהושע ה׳:ה׳) וְכָל הָעָם הַיִּלּוֹדִים בַּמִּדְבָּר בַּדֶּרֶךְ וְגוֹ'. בָּתַר דְּאִתְפְּרָעוּ, אָמַר קוּדְשָׁא בְּרִיךְ הוּא, בְּקַדְמִיתָא אֲכַלְתּוּן מַצּוֹת, דְּקַיְּימָא סִיהֲרָא בִּפְגִימוּתָא, וְאִקְרֵי לֶחֶם עֹנִי, מִכָּאן וּלְהָלְאָה הַאי לֶחֶם מֵאֲתָר אַחֲרָא לֶהֱוֵי. מַאי הוּא. דִּכְתִּיב, (שמות ט״ז:ד׳) הִנְנִי מַמְטִיר לָכֶם לֶחֶם מִן הַשָּׁמָיִם. לָא מִן סִיהֲרָא כְּהַהוּא זִמְנָא, אֶלָּא מִן הַשָּׁמָיִם מַמָּשׁ, כְּמָה דִּכְתִּיב, (בראשית כ״ז:כ״ח) וְיִתֵּן לְךָ הָאֱלהִים מִטַּל הַשָּׁמַיִם.</p>\n<p>וְיִשְׂרָאֵל קַדִּישִׁין, נַטְרִין אִינּוּן יוֹמִין דְּעָאלוּ תְּחוֹת גַּדְפוֹי דִּשְׁכִינְתָּא, וְנַטְרִין הַהוּא נַהֲמָא דְּאַתְיָא מִסִּטְרָהָא, וְעַל דָּא כְּתִיב, (שמות כ״ג:ט״ו) אֶת חַג הַמַּצוֹת תִּשְׁמֹר וְגוֹ', וּכְתִיב וּשְׁמַרְתֶּם אֶת הַמַּצּוֹת. מַהוּ וּשְׁמַרְתֶּם אֶת הַמַּצּוֹת. כְּמָה דְאַתְּ אָמֵר, (שמות י״ט:ה׳) וּשְׁמַרְתֶּם אֶת בְּרִיתִי. וְכֹלָּא בְּחַד דַּרְגָּא סַלְּקָא וְאִתְאֲחָד.</p>\n<p>וְאִי תֵּימָא מֹשֶׁה הֵיךְ לָא פָּרַע לְהוּ. אֶלָּא, בְּגִין דְּלָא יִתְעַכְּבוּן יִשְׂרָאֵל תַּמָן עַד דְּיִתְסִיאוּ, וְעַל דָּא כְּתִיב, (דברים ט״ז:ג׳) שִׁבְעַת יָמִים תֹּאכַל עָלָיו מַצּוֹת לֶחֶם עֹנִי. מַאי טַעְמָא לֶחֶם <Nonei></i>עֹנִי, מִשּׁוּם כִּי בְּחִפָּזוֹן יָצָאתָ וְגוֹ' וּכְתִיב וְלא יָכְלוּ לְהִתְמַהְמֵהַּ.</p>\n<p>תָּא חֲזֵי, כַּד עָאלוּ יִשְׂרָאֵל לְאַרְעָא, עָאלוּ גְּזִירִין וְאִתְפְּרָעוּ. וּמַה כְּתִיב, (דברים ח׳:ט׳) אֶרֶץ אֲשֶׁר לא בְמִסְכֵּנוּת תֹּאכַל בָּהּ לֶחֶם. מַאי בְמִסְכֵּנוּת. לֶחֶם עֹנִי. אֲמַאי אִקְרֵי לֶחֶם עֹנִי. מִשּׁוּם דְּקַיְּימָא סִיהֲרָא בִּפְגִימוּתָא, וְלָא מִתְבָּרְכָא מִשִּׁמְשָׁא, וְלָא מִתְנַהֲרָא מִן שִׁמְשָׁא, כְּמָה דְּאַתְּ אָמֵר, (דברי הימים א כ״ט:י״א) כִּי כֹל בַּשָׁמַיִם וּבָאָרֶץ, וְלָא אִתְנַהֲרָא (מכל) מִיּוֹבְלָא. מַאי טַעֲמָא. מִשּׁוּם דְּלָא אִתְפְּרָעוּ. אֲבָל הָכָא, דְּאִתְגְּזָרוּ יִשְׂרָאֵל וְאִתְפְּרָעוּ, לֹא תֶחְסַר כֹּל בָּהּ כְּתִיב, וְעַל דָּא לא בְמִסְכֵּנוּת תֹּאכַל בָּהּ לֶחֶם. מַאי טַעֲמָא. מִשּׁוּם דְּלָא תֶחְסַר כֹּ\"ל בָּהּ, כְּמָה דְּחָסְרוּ לֵיהּ בְּמִצְרַיִם.</p>\n<p>וּבְכָל שַׁתָּא וְשַׁתָּא דּוּכְרָנָא דְּמִצְרַיִם קָא עַבְדֵי יִשְׂרָאֵל, וְאַכְלֵי וְלָא אִשְׁתְּצֵי מִדָּרֵי דָּרִין. וּבְגִין דְּלָא אִתְפְּרָעוּ הָכָא בְּמִצְרַיִם, חַסְרוּ לֵיהּ לְהַאי כָּל, וְקַיְּימָא סִיהֲרָא בִּפְגִימוּתָא, וְאִקְרֵי לֶחֶם עֹנִי, עֹנִי: כְּתַרְגּוּמוֹ מִסְכֵּנוּת. וּמַאי דְּאַכְלוּ לֵיהּ תַּמָּן בְּאַרְעָא, בְּגִין דּוּכְרָנָא דְּמִצְרַיִם הֲוָה, וְהַאי לְדָרֵי דָּרִין, וּלְזִמְנָא דְּאָתֵי כְּתִיב, (ישעיהו ס׳:כ׳) לֹא יָבֹא עוֹד שִׁמְשֵׁךְ וִירֵחֵךְ וְגוֹ'.</p>\n<p>תַּנָּא אָמַר רִבִּי שִׁמְעוֹן כְּתִיב בֶּעָשׂוֹר לַחֹדֶשׁ הַזֶּה וְיִקְחוּ לָהֶם וְגוֹ', וּכְתִיב (ויקרא כ״ג:כ״ז) אַךְ בֶּעָשׂוֹר לַחֹדֶשׁ הַשְּׁבִיעִי הַזֶּה יוֹם הַכִּפּוּרִים הוּא, אִשְׁתְּמַע כְּמָה דְּאִתְּמַר, דִּכְתִּיב בֶּעָשׂוֹר לַחֹדֶשׁ הַזֶּה. מַאי קָא מַיְירֵי. אֶלָּא בֶּעָשׂוֹר, מִלָּה דָּא בֶּעָשׂוֹר תַּלְיָא. לַחֹדֶשׁ הַזֶּה בַּחֹדֶשׁ הַזֶּה מִבָּעֵי לֵיהּ. אֶלָּא, כַּד אָתָא נִימוּסָא לְהַאי דַּרְגָּא, כְּתִיב לַחֹדֶשׁ הַזֶּה דַּיְקָא.</p>\n<p>(שמות י״ב:ג׳) וְיִקְחוּ לָהֶם אִישׁ שֶׂה לְבֵית אָבוֹת שֶׂה לַבָּיִת. תָּנָא תְּלַת קִשְׁרִין אִינּוּן, בְּכוֹר בְּהֵמָה, בְּכוֹר הַשְּׁבִי, בְּכוֹר הַשִּׁפְחָה. (דתלת קשרין) דְּכָל שְׁאַר מִתְקַשְּׁרֵי בְּהוּ בְּאִלֵּין תְּלַת גַּוְונֵי דִּלְעֵילָּא. וּבְהַאי דְּאִתְקְרֵי צֹאן, אִתְקָשַּׁר כֹּלָּא, וְכֹלָּא כָּלִיל בַּצֹּאן, אִתְקָשַּׁר צֹאן בַּצֹּאן, וְלָא יָכִיל לְאִתְפָּרְשָׁא מִקִּטְרוֹי, וּבְהַאי כֻּלְּהוּ אִתְקַשָּׁרוּ, וְעַל דָּא כְּתִיב, וְהָיָה לָכֶם לְמִשְׁמֶרֶת, קְטִירוּ לֵיהּ בִּקְטִירוּתָא, וִיְהֵא אִתְמְסָר בִּידֵיכוֹן בִּרְשׁוּתְכוֹן, עַד דְּתַנְכְסוּ לֵיהּ, וְתַעְבְּדוּן בֵּיהּ דִּינָא, וּלְזִמְנָא דְּאָתֵי כְּתִיב (ישעיה סג) מִי זֶה בָּא מֵאֱדוֹם. וּכְתִיב, (ישעיה לה) כִּי זֶבַח לַיְיָ' בְּבָצְרָה. וּכְתִיב, (זכריה י״ד:ט׳) וְהָיָה יְיָ' לְמֶלֶךְ עַל כָּל הָאָרֶץ בַּיּוֹם הַהוּא יִהְיֶה יְיָ' אֶחָד וּשְׁמוֹ אֶחָד.</p>"],[9520011593,"<p><Noneb>רעיא מהימנא</b> (שמות י״ב:ל״ד) וְיִשָּׂא הָעָם אֶת בְּצֵקוֹ טֶרֶם יֶחְמָץ וְגוֹ'. כ\"ה פִּקּוּדָא דָּא, לְבָעֵר חָמֵץ. דְּהָא פִּקּוּדָא דָּא, אִתְמְסַר לְהוּ לְיִשְׂרָאֵל וְיִשָּׂא הָעָם אֶת בְּצֵקוֹ טֶרֶם יֶחְמָץ. וּכְתִיב שְּׂאוֹר לא יִמָּצֵא בְּבָתֵּיכֶם, וְהָא אוּקְמוּהָ חַבְרַיָּא, וְרָזָא אוֹקִימְנָא, בֵּין חָמֵץ וּמַצָּה דְּכַמָּה דּוּכְתֵּי, דָּא יֵצֶר רַע, וְדָא יֵצֶר טוֹב.</p>\n<p>כ\"ו פִּקּוּדָא בָּתַר דָּא, לְסַפֵּר בִּשְׁבָחָא דִּיצִיאַת מִצְרַיִם, דְּאִיהוּ חִיּוּבָא עַל בַּר נָשׁ, לְאִשְׁתָּעֵי בְּהַאי שְׁבָחָא לְעָלְמִין. הָכִי אוֹקִימְנָא, כָּל בַּר נָשׁ דְּאִשְׁתָּעֵי בִּיצִיאַת מִצְרַיִם, וּבְהַהוּא סִפּוּר חַדֵּי בְּחֶדְוָה, זַמִּין אִיהוּ לְמֶחדֵי בִּשְׁכִינְתָּא לְעָלְמָא דְּאָתֵי דְּהוּא חֵדוּ מִכֹּלָּא, דְּהַאי אִיהוּ בַּר נָשׁ דְּחַדֵּי בְּמָרֵיהּ, וְקוּדְשָׁא בְּרִיךְ הוּא חַדֵּי בְּהַהוּא סִפּוּר.</p>\n<p>בֵּיהּ שַׁעֲתָא, כָּנִישׁ קוּדְשָׁא בְּרִיךְ הוּא לְכָל פָּמַלְיָיא דִּילֵיהּ, וְאָמַר לוֹן, זִילוּ וּשְׁמָעוּ סִפּוּרָא דִּשְׁבָחָא דִּילִי, דְּקָא מִשְׁתָּעוּ בָּנַי, וְחַדָּאן בְּפוּרְקָנִי. כְּדֵין כֻּלְּהוּ מִתְכַּנְּשִׁין, וְאַתְיָין וּמִתְחַבְּרִין בַּהֲדַיְיהוּ דְּיִשְׂרָאֵל, וּשְׁמָעוּ סִפּוּרָא דִּשְׁבָחָא, דְּקָא חַדָּאן בְּחֶדְוָא דְּפוּרְקָנָא דְמָרֵיהוֹן, כְּדֵין אַתְיָין וְאוֹדָן לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא, עַל כָּל אִינּוּן נִסִּין וּגְבוּרָן וְאוֹדָאן לֵיהּ עַל עַמָּא קַדִּישָׁא דְּאִית לֵיהּ בְּאַרְעָא, דְּחַדָּאן בְּחֶדְוָה דְּפוּרְקָנָא דְּמָארִיהוֹן.</p>\n<p>כְּדֵין אִתּוֹסָף לֵיהּ חֵילָא וּגְבוּרְתָּא לְעֵילָּא, וְיִשְׂרָאֵל בְּהַהוּא סִפּוּרָא יַהֲבֵי חֵילָא לְמָארֵיהוֹן, כְּמַלְכָּא, דְּאִתּוֹסָף חֵילָא וּגְבוּרְתָּא, כַּד מְשַׁבְּחִין גְּבוּרְתֵּיהּ, וְאוֹדָן לֵיהּ, וְכֻלְּהוּ דַּחֲלִין מִקָמֵיהּ, וְאִסְתַּלָּק יְקָרֵיהּ עַל כֻּלְּהוּ. וּבְגִין כָּךְ, אִית לְשַׁבְּחָא וּלְאִשְׁתָּעֵי בְּסִפּוּר דָּא <Nonei></i>כְּמָה דְּאִתְּמַר. כְּגַוְונָא דָּא, חוֹבָה אִיהוּ עַל בַּר נָשׁ, לְאִשְׁתְּעֵי תָּדִיר קָמֵי קוּדְשָׁא בְּרִיךְ הוּא, וּלְפַרְסוּמֵי נִיסָא בְּכָל אִינּוּן נִיסִּין דְּעָבַד.</p>\n<p>וְאִי תֵּימָא, אֲמַאי אִיהוּ חוֹבָתָא, וְהָא קוּדְשָׁא בְּרִיךְ הוּא יָדַע כֹּלָּא, כָּל מַה דְּהֲוָה, וְיֶהוֵי לְבָתַר דְּנָא, אֲמַאי פִּרְסוּמָא דָּא קָמֵיהּ, עַל מַה דְּאִיהוּ עָבַד, וְאִיהוּ יָדַע. אֶלָּא וַדַּאי אִצְטְרִיךְ בַּר נָשׁ לְפַרְסוּמֵי נִיסָא, וּלְאִשְׁתָּעֵי קָמֵיהּ בְּכָל מַה דְּאִיהוּ עָבַד, בְּגִין דְּאִינּוּן מִלִּין סַלְּקִין, וְכָל פָּמַלְיָא דִּלְעֵילָּא מִתְכַּנְּשִׁין, וְחָמָאן לוֹן, וְאוֹדָאן כֻּלְּהוּ לְקוּדְשָׁא בְּרִיךְ הוּא, וְאִסְתַּלָּק יְקָרֵיהּ עָלַיְיהוּ עֵילָּא וְתַתָּא.</p>\n<p>כְּגַוְונָא דָּא, מַאן דְּאִשְׁתָּעֵי וּמְפָרֵט חֶטְאוֹי עַל כָּל מַה דְּעָבַד, אִי תֵּימָא לְמָאי אִצְטְרִיךְ. אֶלָּא מְקַטְרְגָא קָאִים תָּדִיר קָמֵי קוּדְשָׁא בְּרִיךְ הוּא, בְּגִין לְאִשְׁתְּעֵי וּלְמִתְבַּע חוֹבֵי בְּנֵי נָשָׁא, וּלְמִתְבַּע עֲלֵיהוֹן דִּינָא. כֵּיוָן דְּאַקְדִּים בַּר נָשׁ, וּמְפָרֵיט חֶטְאוֹי, כָּל חַד וְחַד, לָא אַשְׁאִיר פִּטְרָא דְּפוּמָא לְהַהוּא מְקַטְרְגָא, וְלָא יָכִיל לְמִתְבַּע עָלֵיהּ דִּינָא. דְּהָא תָּדִיר תָּבַע דִּינָא בְּקַדְמִיתָא, וּלְבָתַר מִשְׁתָּעֵי וּמְקַטְרֵג פְּלוֹנִי עָבֵד כַּךְ. וְעַל דָּא, אִצְטְרִיךְ לֵיהּ לְבַר נָשׁ לְאַקְדְּמָא, וּלְפָרֵט חֶטְאוֹי.</p>\n<p>כֵּיוָן דִּמְקַטְרְגָא חָמֵי דָּא, לֵית לֵיהּ פִּטְרָא דְּפוּמָא עָלֵיהּ, וּכְדֵין אִתְפְּרַשׁ מִנֵיהּ מִכֹּל וָכֹל. אִי תָּב בְּתִיוּבְתָּא יֵאוֹת, וְאִי לָאו, הָא מְקַטְרְגָא אִשְׁתְּכַח עָלֵיהּ, וְאָמַר פְּלוֹנִי דְּאָתָא לְקָמָךְ בְּתּוּקְפָא דְּאַפִּין, בָּעִיט בְּמָרֵיהּ, חוֹבוֹי כַּךְ וְכָךְ. עַל דָּא יֵאוֹת לְאִזְדַּהֲרָא בַּר נָשׁ בְּכָל הָנֵי, בְּגִין דְּיִשְׁתְּכַח עַבְדָּא מְהֵימָנָא קָמֵי קוּדְשָׁא בְּרִיךְ הוּא.</p>\n<p>כ\"ז פִּקּוּדָא בָּתַר דָּא, לֶאֱכוֹל מַצָּה בְּפֶסַח, בְּגִין דְּאִיהוּ דּוּכְרָנָא לְדָרֵי דָּרִין, עַל רָזָא דִּמְהֵימְנוּתָא. וְהָא אוּקְמוּהָ, דְּיִשְׂרָאֵל נָפְקוּ בְּהַהוּא זִמְנָא מֵרָזָא דְּטַעֲוָון אַחֲרָן, וְעָאלוּ בְּרָזָא דִּמְהֵימָנוּתָא. וְהָא אוּקְמוּהָ רָזָא דְּנָא בְּכַמָּה דּוּכְתֵּי.</p>"],[9520011594,"<p>(שמות י״ב:מ״ג) וַיֹּאמֶר יְיָ' אֶל מֹשֶׁה וְאַהֲרֹן זֹאת חֻקַּת הַפָּסַח וְגוֹ'. כ\"ח פִּקּוּדָא דָּא, לְמִשְׁחַט פֶּסַח בֵּין הָעַרְבַּיִם, בְּי\"ד בְּנִיסָן, דּוּכְרָנָא דְּהַהוּא פֶּסַח דְּמִצְרַיִם. וְדָא אִיהוּ חוֹבָתָא עַל כֹּלָּא, כְּמָה דְּאַתְּ אָמֵר, וְשָׁחֲטוּ אוֹתוֹ כָּל קְהַל עֲדַת יִשְׂרָאֵל בֵּין הָעַרְבַּיִם.</p>\n<p>פֶּסַח דָּא, אִצְטְרִיךְ לְמֶהוֵי נָטִיר, מֵעֲשָׂרָה יוֹמִין וּלְהָלְאָה, דִּכְתִּיב בֶּעָשׂוֹר לַחֹדֶשׁ הַזֶּה וְיִקְחוּ לָהֶם וְגוֹ'. מַאי טַעֲמָא. בְּגִין דְּהָא כְּדֵין שָׁרִיאַת סִיהֲרָא לְאַנְהָרָא, מֵעֲשָׂרָה יוֹמִין וּלְהָלְאָה, עַד דְּאִשְׁתְּלִים בַּחֲמֵיסָר. וְאַרְבֵּיסָר דְּלֶיהֱוִי נָכִיס, בְּשַׁעֲתָא דְּדִינָא תַּלְיָא עַל עָלְמָא.</p>\n<p>רָזָא דָּא, לְאַעְבְּרָא זוּהֲמָא, מִקָּמֵי בְּרִית קַדִּישָׁא, וּלְאִתְהֲנָאָה בְּהַהוּא רֵיחָא דְּנָדִיף טְוִי נוּר. וְעַל דָּא לָא אַתְיָא אֶלָּא עַל שָׂבְעָא. וְעַל דָּא, וְכָל עָרֵל לא יֹאכַל בּוֹ. מַאן דְּאִית בֵּיהּ בְּרִית קַדִּישָׁא, יֵיכוּל בֵּיהּ. מַאן דְּלָא אִית בֵּיהּ בְּרִית קַדִּישָׁא, לָא יֵיכוּל בֵּיהּ. דְּהַאי מִבְּנֵי בְּרִית אִיהוּ לְתַבְרָא תּוּקְפָּא דְּחֵילָא אַחֲרָא, לְאַעְבְּרָא עָרְלָה מִקָּמֵי בְּרִית. בְּגִין כַּךְ, הַאי בִּבְנֵי בְּרִית אִיהוּ לְמֶעְבַּד, וְלָא בִּבְנֵי עָרְלָה.</p>\n<p>כַּד אָתָא קוּדְשָׁא בְּרִיךְ הוּא לְמִצְרַיִם, חָמָא דָּמָא דְּהַהוּא פֶּסַח, דְּהֲוָה רָשִׁים עַל פִּתְחָא, וְדָמָא דִּבְרִית, הֵיךְ הֲווֹ קַיְימִין עַל פִּתְחָא, דִּכְתִּיב, וּלְקַחְתֶּם אֲגֻדַּת אֵזוֹב וּטְבַלְתֶּם בַּדָּם אֲשֶׁר בַּסַּף וְהִגַּעְתֶּם וְגוֹ'. אֵזוֹבָא, הָא אוֹקִימְנָא דְּאִיהוּ מַעְבַּר רוּחִין (כ\"ב ע\"ב) בִּישִׁין, וְכָל סְטָר רוּחַ בִּישָׁא, מַעְבַּר בְּאִתְעָרוּתָא דִּילֵיהּ, בְּפוּרְקָנָא עִלָּאָה דְּיִשְׂרָאֵל.</p>\n<p>לְזִמְנָא דְּאָתֵי, יֵיתֵי קוּדְשָׁא בְּרִיךְ הוּא לְיֵצֶר הָרָע וְיִכּוֹס לֵיהּ. וְהַשְׁתָּא בְּפוּרְקָנָא דָּא, כְּתִיב וְשָׁחֲטוּ אוֹתוֹ כָּל קְהַל עֲדַת יִשְׂרָאֵל וְגוֹ'. דּוּכְרָנָא דְּזִמְנָא דְּאָתֵי, בְּהַהוּא פּוּרְקָנָא עִלָּאָה.</p>\n<p>עַל שְׁתֵּי הַמְּזוּזוֹת וְעַל הַמַּשְׁקוֹף בְּהַאי רְשִׁימוּ דְּאָת יוֹ\"ד, וּבְהַאי רְשִׁימוּ דְּאָת יוֹ\"ד, לְאַחֲזָאָה רְשִׁימוּ דִּבְרִית קַדִּישָׁא, וְאִתְּבַּר עָרְלָה מִקָּמֵי דָּמָא דִּבְרִית, רָשִׁים עַל כֹּלָּא, וְאָתָא דָּמָא עַל דָּמָא. כַּד עָבַר הַהוּא מַשְׁחִית, הֲוָה חָמֵי דָּמָא, וְאִזְדְּקִיף מִבֵּיתָא, כְּמָה דְּאַתְּ אָמֵר וְלֹא יִתֵּן הַמַּשְׁחִית וְגוֹ'.</p>\n<p>אִי קוּדְשָׁא בְּרִיךְ הוּא בִּלְחוֹדוֹי קָטִיל, אֲמַאי כְּתִיב וְלֹא יִתֵּן הַמַּשְׁחִית, דְּמַשְׁמַע דְּמַשְׁחִית הֲוָה אָזִיל וְלָא קוּדְשָׁא בְּרִיךְ הוּא. אֶלָּא וַדַּאי קוּדְשָׁא בְּרִיךְ הוּא הֲוָה קָטִיל, וּמַשְׁחִית הֲוָה אָזִיל <Nonei></i>לְאַשְׁכְּחָא עִילָה לְיִשְׂרָאֵל, כֵּיוָן דְּהֲוָה חָמֵי הַהוּא תְּבִירוּ דְּעָרְלָה, בִּתְרֵין סִטְרִין, הֲוָה עָרַק וְאִתְפְּרַשׁ מִנַּיְיהוּ.</p>\n<p>וְעַל דְּקָטַל קוּדְשָׁא בְּרִיךְ הוּא כָּל אִינּוּן בּוּכְרִין דְּהַהוּא סִטְרָא, יָהִיב בּוּכְרִין דְּיִשְׂרָאֵל לְפוּרְקָנָא, דְּלָא יִשְׁכַּח עָלַיְיהוּ סִטְרָא אַחֲרָא עִילָה כְּלָל, וּבְכֹלָּא נָטִיר לוֹן לְיִשְׂרָאֵל קוּדְשָׁא בְּרִיךְ הוּא, כְּאַבָּא עַל בְּנִין.</p>\n<p>(שמות י״ב:מ״ו) בְּבַיִת אֶחָד יֵאָכֵל לא תוֹצִיא מִן הַבַּיִת וְגוֹ', (עיין לקמן סוף פרשת פנחס) פִּקּוּדָא כ\"ט דָּא, לְמֵיכַל הַאי פֶּסַח. עַל מַצּוֹת וּמְרוֹרִין, מַצּוֹת מַצַּת כְּתִיב. מַאי הַאי לָקֳבֵל הַאי, אֶלָּא לְאַחֲזָאָה גָּלוּתָא דִּשְׁכִינְתָּא עִמְּהוֹן דְּיִשְׂרָאֵל, בְּהַהוּא מְרִירוּ דִּלְהוֹן, דִּכְתִּיב וַיְמָרַרוּ אֶת חַיֵּיהֶם בַּעֲבוֹדָה קָשָׁה וְגוֹ'. וְכַד אַכְלִין לְהַאי פֶּסַח, לְאַחֲזָאָה כָּל הַאי דְּעָבְדוּ לוֹן בְּמִצְרַיִם, בְּהַהוּא גָּלוּתָא וּבְהַהוּא שִׁעְבּוּדָא.</p>\n<p>מַה כְּתִיב וְעֶצֶם לֹא תִשְׁבְּרוּ בוֹ, לְאַחֲזָאָה בֵּיהּ קְלָנָא, וּבְכָל אִינּוּן טַעֲוָון דְּמִצְרָאֵי. דְּהָא גַּרְמִין הֲווֹ רָמָאן בְּשׁוּקָא, וְאָתוּ כַּלְבֵּי וַהֲווּ גָּרְרֵי לוֹן מֵאֲתָר לַאֲתָר, וְדָא קַשְׁיָא לוֹן מִכֹּלָּא, דְּהָא גַּרְמֵי אִינּוּן תִּקּוּנָא דְּגוּפָא, וְדָמִי לְגַוְונָא אַחֲרָא, וְיִשְׂרָאֵל רָמָאן לוֹן בְּשׁוּקָא אוֹרַח קְלָנָא, וְעַל דָּא כְּתִיב וְעֶצֶם לֹא תִשְׁבְּרוּ בוֹ, אַתּוּן לָא תִּשְׁבְּרוּן, אֲבָל כַּלְבֵּי הֲווֹ אַתְיָין וּמְתַבְּרִין לֵיהּ.</p>\n<p>תּוּ, מִצְרָאֵי הֲווֹ אַתְיָין לְבָתַר, וַהֲווּ חָמָאן אִינּוּן גַּרְמֵי דַּהֲווֹ נַטְלֵי כַּלְבֵּי מֵאֲתָר לַאֲתָר, וּמַדְקָן לוֹן, וַהֲווּ מִצְרָאֵי טָמְנִי לוֹן גּוֹ עַפְרָא, בְּגִין כַּלְבֵּי דְּלָא יִשְׁכְּחוּן לוֹן, וְדָא אִיהוּ בִּטּוּלָה דְּעֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת, יַתִּיר, מִסִּטְרָא דִּלְהוֹן. וּבְדָא קוּדְשָׁא בְּרִיךְ הוּא אִסְתְּלַק בִּיקָרֵיהּ, וְאִתְכַּפְיָין כָּל חֵילִין אַחֲרָנִין, דְּהָא כְּדֵין אִתְכַּפְיָין יַתִּיר, כַּד בָּטִילוּ אִשְׁתְּכַח מִסִּטְרָא דִּלְהוֹן, וְעַל דָּא יִשְׂרָאֵל לָא מְבַטְּלֵי לוֹן, דִּכְתִּיב וְעֶצֶם לֹא תִשְׁבְּרוּ בוֹ.</p>"],[9520011595,"<p>(שמות י״ג:ט״ו) קַדֶּשׁ לִי כָל בְּכוֹר פֶּטֶר רֶחֶם וְגוֹ'. פִּקּוּדָא דָּא לְקַדֵּשׁ בְּכוֹר בְּהֵמָה, וְעַם הָאָרֶץ צָרִיךְ תְּרֵין מִילִין, חַד דִּיהֵא פָּדוּי מִתְּחוֹת שֻׁלְטָנוּתָא דְּיֵצֶר הָרָע, דְּאִיהִי אֲדוֹן דִּילֵיהּ, כְּגַוְונָא דְּאָמַר יַעֲקֹב לְעֵשָׂו, (בראשית ל״ג:י״ד) יַעֲבָר נָא אֲדֹנִי לִפְנֵי עַבְדּוֹ. בְּהַאי עָלְמָא. אֲדוֹן מִצַּד חוֹבִין דִּנְפִישִׁין עַל גּוּפָא, כְּמָה דְּאוּקְמוּהָ, חַיָּיבָא, יֵצֶר הָרָע שׁוֹפְטוֹ. זַכָּאָה, יֵצֶר הַטּוֹב שׁוֹפְטוֹ. בֵּינוֹנִי זֶה וְזֶה שׁוֹפְטוֹ. בֵּינוֹנִי, הַיְינוּ אָח דְּיֵצֶר הָרָע, וְאָח דְּיֵצֶר הַטּוֹב, אָחִי יְהִי לְךָ אֲשֶׁר לָךְ.</p>\n<p>וְכַד זַכְוָון נְפִישִׁין, רוּחָא תָּבַר תְּרֵין מִשְׁמָרוֹת, דַּחֲמוֹר נוֹעֵר, כְלָבִים צוֹעֲקִים, וְסָלִיק לְמִשְׁמֶרֶת דְּשַׁחַר, דְּבֵיהּ אָדָם וְאִתְהַדָּר בַּר נָשׁ אֲדוֹן, הֲדָא הוּא דִכְתִיב, (בראשית ל״ב:ו׳) וַיְהִי לִי שׁוֹר וַחֲמוֹר צֹאן וְעֶבֶד וְשִׁפְחָה, וְסָלִיק לְדַרְגָּא דְּאָדָם, דְּאִתְּמַר בֵּיהּ, (בראשית א׳:כ״ח) וּרְדוּ בִּדְגַת הַיָּם וּבְעוֹף הַשָּׁמַיִם וְגוֹ', (בראשית ט׳:ב׳) וּמוֹרַאֲכֶם וְחִתְּכֶם וְגוֹ'.</p>\n<p>וְכַד זַכְוָון בֵּינוֹנִיִּם, (בראשית ל״ב:כ״ה) וַיֵּאָבֵק אִישׁ עִמּוֹ, זַכְוָון וְחוֹבִין מִתְחַבְּקָן לְאַגָּחָא קְרָבָא. מִסִּטְרָא דְּזַכְוָון, (בראשית ל״ב:כ״ו) וַיַּרְא כִּי לֹא יָכוֹל לוֹ. מִסִּטְרָא דְּחוֹבִין, וַיִּגַּע בְּכַף יְרֵכוֹ בְּגִיד הַנָּשֶׁה. נָשֶׁה: לָשׁוֹן (בראשית מ״א:נ״א) כִּי נַשַּׁנִי אֱלֹהִים אֶת כָּל עֲמָלִי וְאִיהוּ לְשׁוֹן נְשִׁיָּה. חַד מָדוֹרָא מֵאִינּוּן שִׁבְעָה אַרְעָאן, מַאן דְּנָחִית תַּמָן אִתְנְּשֵׁי מִנֵיהּ אוֹרַיְיתָא.</p>"],[9520011596,"<p>וְקֹדֶם דְּיֵיתֵי בַּר נָשׁ בְּהַאי עָלְמָא וְיִפּוּק מֵרֶחֶם אִמֵיהּ, וַיֵּאָבֵק אִישׁ עִמּוֹ, דָּא גַּבְרִיאֵל, בְּהַהוּא אָבָק דְּעָפָר, דְּאִתְּמַר (בראשית ב׳:ז׳) וַיִּיצֶר יְיָ' אֱלֹהִים אֶת הָאָדָם עָפָר מִן הָאֲדָמָה, וְאוֹלִיף לֵיהּ שִׁבְעִים לָשׁוֹן. וּבְגִין דָּא, וַיִּיצֶר: חַד יֵצֶר הַטּוֹב, דְּאוֹלִיף לֵיהּ שִׁבְעִים לָשׁוֹן. וְחַד, יֵצֶר הָרָע דְּאָבִיק עִמֵּיהּ. דְּאִתְּמַר, כִּי נָגַע בְּכַף יֶרֶךְ יַעֲקֹב בְּגִיד הַנָּשֶׁה, וְאַשְׁכַּח מִנֵיהּ שִׁבְעִין לָשׁוֹן, דְּאוֹלִיף לֵיהּ יֵצֶר הַטּוֹב.</p>\n<p>וְקֹדֶם כָּל דָּא, נַחְתִּין עִמֵּיהּ אַרְבְּעָה מַלְאָכִין, דְּאִתְּמַר בְּהוֹן (תהילים צ״א:י״א) כִּי מַלְאָכָיו יְצַוֶּה לָךְ. אִי אִית לֵיהּ זְכוּת אָבוֹת, חַד מִיכָאֵל, בִּזְכוּת אַבְרָהָם. וְתִנְיָינָא גַּבְרִיאֵל, בִּזְכוּת יִצְחָק. וּתְלִיתָאָה דְּנָחִית עִמֵּיהּ נוּרִיאֵל, בִּזְכוּתָא דְּיַעֲקֹב. וּרְבִיעָאָה רְפָאֵל, בִּזְכוּתָא דְּאָדָם קַדְמָאָה. וְיֵצֶר הַטּוֹב לְעֵילָּא מִנֵּיהּ.</p>\n<p>וְאִי לֵית לֵיהּ זְכוּת, אַזְלֵי עִמֵּיהּ ד', עָוֹן, מַשְׁחִית, אַף, וְחֵימָה, וְיֵצֶר הָרָע לְעֵילָּא מִנַיְיהוּ, לְמֵידָן לֵיהּ לְעָלְמָא דְּאָתֵי. וּבְגִין דָּא אוּקְמוּהָ, רָשָׁע, יֵצֶר הָרָע שׁוֹפְטוֹ. צַדִּיק, יֵצֶר הַטּוֹב שׁוֹפְטוֹ. בֵּינוֹנִי, זֶה וְזֶה שׁוֹפְטוֹ. וּבְגִין דָּא, אִי אִיהוּ בֵּינוֹנִי, גַּבְרִיאֵל דְּאִיהוּ יֵצֶר הַטּוֹב, <Nonei></i>וְסַמָאֵ\"ל דְּאִיהוּ יֵצֶר הָרָע, זֶה וְזֶה שׁוֹפְטוֹ.</p>\n<p>דִּלְכָל בַּר נָשׁ דְּאִית בֵּיהּ אַרְבַּע יְסוֹדִין, אַרְבַּע מַלְאָכִים נַחְתִּין עִמֵּיהּ מִימִינָא, וְאַרְבַּע מִשְּׂמָאלָא. אַרְבַּע מִימִינָא: מִיכָאֵ\"ל, גַּבְרִיאֵ\"ל, רְפָאֵ\"ל, נוּרִיאֵ\"ל. וְאַרְבַּע מִשְּׂמָאלָא: עָוֹ\"ן, מַשְׁחִי\"ת, אַ\"ף, וְחֵמָ\"ה. מִסִּטְרָא דְּגוּפָא, מְטַטְרוֹ\"ן נָחִית עָלֵיהּ מִימִינָא, וְסָמָאֵ\"ל מִשְּׂמָאלָא.</p>\n<p>וְלֵית בַּר נָשׁ דְּלֵית בֵּיהּ אַרְבַּע יְסוֹדִין, אֲבָל כְּפוּם יְסוֹדָא דְּאַקְדִּים בֵּיהּ, הָכִי מַתְחִילִין אִלֵּין אַרְבַּע. אִי מַזָּל דִּילֵיהּ אַרְיֵ\"ה, אַקְדִּים מִיכָאֵ\"ל, וַאֲבַתְרֵיהּ גַּבְרִיאֵ\"ל וַאֲבַתְרֵיהּ נוּרִיאֵ\"ל, וַאֲבַתְרֵהּ רְפָאֵ\"ל. וְאִי מַזָּלֵיהּ שׁוֹר, אַקְדִּים גַּבְרִיאֵ\"ל, וַאֲבַתְרֵיהּ מִיכָאֵ\"ל, וַאֲבַתְרֵיהּ נוּרִיאֵ\"ל, וַאֲבַתְרֵיהּ רְפָאֵ\"ל. וְאִי מַזָּלֵיהּ נְשֶׁר, אַקְדִּים נוּרִיאֵ\"ל, וַאֲבַתְרֵיהּ מִיכָאֵ\"ל, וַאֲבַתְרֵיהּ גַּבְרִיאֵ\"ל, וַאֲבַתְרֵיהּ רְפָאֵ\"ל. וְאִי מַזָּלֵיהּ אָדָ\"ם. אַקְדִּים רְפָאֵ\"ל, וַאֲבַתְרֵיהּ מִיכָאֵ\"ל, וַאֲבַתְרֵיהּ גַּבְרִיאֵ\"ל, וַאֲבַתְרֵיהּ נוּרִיאֵ\"ל.</p>\n<p>וְאִינּוּן מִסִּטְרָא דִּימִינָא, מִסִּטְרָא דְּמִיכָאֵל, כֻּלְּהוּ אַנְפִּין דִּילֵיהּ, אִינּוּן רַחֲמֵי, בַּעַל גְּמִילוּת חֲסָדִים, אַנְפּוֹי חִוָּורִין, וְהַאי בַּר נָשׁ גָּמִיל חֶסֶד. חָסִיד, וְחָכָם, אִי אִשְׁתַּדַּל בְּאוֹרַיְיתָא. וְאִי לָאו, בְּהִפֻּךְ, מִסִּטְרָא דְּיֵצֶר הָרָע, גַּזְלָן, טִפֵּשׁ, לֵית בֵּיהּ חֶסֶד. דְּלָא עַם הָאָרֶץ חָסִיד.</p>\n<p>מִסִּטְרָא דְּגַבְרִיאֵל, אַרְבַּע אַנְפִּין דִּילֵיהּ דִּינָא, מִדַּת הַדִּין עַל רַשִׁיעַיָּא, וּמִתְגָּרֶה בְּהוּ, כְּמָה דְּאוּקְמוּהָ, מוּתָּר לְהִתְגָּרוֹת בָּרְשָׁעִים בָּעוֹלָם הַזֶּה. גִּבּוֹר בְּיִצְרֵיהּ, יְרֵא חֵטְא, דַּיָּין יְהֵא, אִי יִתְעַסֵּק בְּאוֹרַיְיתָא, וְגִבּוֹר בְּתַלְמוּדֵיהּ. בְּהִפּוּכָא מִסִּטְרָא דְּיֵצֶר הָרָע, מִתְגָּרֶה בְּצַדִּיקַיָּא, דִּינָא קָשֶׁה לוֹן, גִּבּוֹר בַּעֲבֵירָה, לְמֶעְבַּד לֵיהּ, לָאו דָּחִיל חַטָּאָה הוּא, וּגְוָונִין דְּאַנְפּוֹי סוּמָקִין, עֵשָׂו שׁוֹפֵךְ דָּמִים.</p>\n<p>מַאן דְּמַזָּלֵיהּ נְשֶׁ\"ר, לָאו רַחֲמָן סַגִּי, וְלָאו מִדַּת הַדִּין סַגִּי, אֶלָּא בֵּינוֹנִי, בְּיֵצֶר טוֹב בְּמִדֹּת טָבִין דִּילֵיהּ, וּבֵינוֹנִי בְּיֵצֶר רָע בְּמִדּוֹת בִּישִׁין, וְלֵיהּ אַנְפִּין חִוָּורִין וְסוּמָקִין.</p>\n<p>מַאן דְּמַזָּלֵיהּ אָדָם, מִסִּטְרָא דְּטוֹב, כָּלִיל מִכָּל מִדּוֹת טוֹבוֹת, חָסִיד, וְחָכָם, וְגִבּוֹר בַּתּוֹרָה, יְרֵא חֵטְא, מְמוּלָּא בְּכָל מִדּוֹת טָבִין, וּגְוָון אַנְפּוֹי אוּכָּמִין. וּמִסִּטְרָא דְּיֵצֶר הָרָע, מְמוּלָּא מִכָּל מִדּוֹת בִּישִׁין.</p>\n<p>וְאִי חוֹבוֹי דְּבַר נָשׁ, נְפִישִׁין שַׁלְטִין עָלֵיהּ כָּל מַשִׁרְיָין דְּיֵצֶר הָרָע, עַד דְּיִסְתְּלָקוּ מִנֵיהּ כֻּלְּהוּ מַשִׁרְיָין דְּיֵצֶר טוֹב, וְאַמְלִיךְ עַל אֵבָרִין דִּילֵיהּ, סָמָאֵ\"ל וְכָל מַשִּׁרְיָיתֵיהּ.</p>\n<p>וְאִי נְפִישִׁין זַכְווֹי, שַׁלְטִין מַשִׁרְיָין דְּיֵצֶר הַטּוֹב, עַד דְּיִסְתְּלָקוּ מִנֵּיהּ כָּל מַשִׁרְיָין דְּיֵצֶר הָרָע. וְאַמְלִיךְ עַל כָּל אֵבָרִין דִּילֵיהּ, מַשִׁירְיָין דְּיֵצֶר הַטּוֹב, בְּהַהוּא זִמְנָא, שָׁלִיט עָלֵיהּ שֵׁם יְדוָ\"ד.</p>\n<p>וְאִם הוּא בֵּינוֹנִי, צְבָא הַשָּׁמַיִם עוֹמְדִים עָלָיו מִימִינוֹ וּמִשְּׂמֹאלוֹ, אִלֵּין מַיְימִינִים לִזְכוּת, וְאִלֵּין מַשְׂמְאִילִים לְחוֹבָה, וּמַאן דְּאָלִים גָּבַר. וּבְגִין דָּא אוּקְמוּהָ מָארֵי מַתְנִיתִין, לְעוֹלָם יִרָאֶה אָדָם עַצְמוֹ כְּאִילּוּ כָּל הָעוֹלָם כּוּלּוֹ תָּלוּי בּוֹ.</p>\n<p>וּמִסִּטְרָא דְּמִיכָאֵל, אִתְקְרֵי בְּכוֹר, דְּדַרְגֵּיהּ כֶּסֶף חִוָּורוּ, וּבְגִין דָּא, פִּדְיוֹן הַבְּכוֹר כֶּסֶף, ה' סְלָעִים, כְּחוּשְׁבָּן ה' דְּאַבְרָהָם, דְּאִי יַחְכִּים בַּתּוֹרָה יִתּוֹסַף עָלֵיהּ י', דְּאִיהוּ קֹדֶשׁ, דְּבֵיהּ צָרִיךְ לְקַדֵּשׁ בְּכוֹר בְּהֵמָה, דְּהַיְינוּ (ירמיה ב) קֹדֶשׁ יִשְׂרָאֵל לַיְיָ'. וּבֵיהּ צָרִיךְ לְעַשֶּׂר וְלָדוֹת, דְּכָל וָלָד אִיהוּ מִסִּטְרָא דְּבֶן י\"ה, וְאִיהוּ ו'.</p>\n<p>דְּכָל חֵיוָן דְּאִינּוּן חֵיוַת הַקּוֹדֶשׁ, בְּאַתְוָון דִּשְׁמָא קַדִּישָׁא אִתְקְרִיאוּ, הֲדָא הוּא דִּכְתִּיב, (ישעיהו מ״ג:ז׳) כֹּל הַנִּקְרָא בִשְׁמִי וְלִכְבוֹדִי בְּרָאתִיו. אֲפִילּוּ כָּל בִּרְיָין דְּאִתְבְּרִיאוּ בְּהוֹן, וְלֵית בְּרִיאָה דְּלָא אִתְרְשִׁים בְּהַאי שְׁמָא, בְּגִין לְאִשְׁתְּמוֹדְעָא לְמַאן דִּבְּרָא לֵיהּ, וְהַאי יוֹ\"ד, אִיהוּ דִּיּוּקְנָא דְּרֵישָׁא דְּכָל בִּרְיָין. ה' ה': דִּיּוּקְנָא דְּה' אֶצְבְּעָאָן דִּימִינָא, וְה' דִּשְׂמָאלָא. ו' דִּיּוּקְנָא דְּגוּפָא.</p>"],[9520011597,"<p>וּבְגִין דָּא אָמַר, (ישעיהו מ׳:כ״ה) וְאֶל מִי תְּדַמְּיוּנִי וְאֶשְׁוֶה יֹאמַר קָדוֹשׁ. לֵית בְּכָל בְּרִיָּה דְּאֶשְׁוֶה כְּוָותִי, וְאַף עַל גַּב דְּבָרָאתִי לָהּ כִּדְמוּת אַתְוָון דִּילִי, דַּאֲנָא יָכִיל לְמַחֲאָה הַהִיא צוּרָה, וּלְמֶעְבַּד לָהּ כַּמָּה זִמְנִין, וְלֵית אֱלוֹהַּ אַחֲרָא עָלַי דְּיָכִיל לְמִמְחֵי <Nonei></i>דִּיּוּקְנִי וּבְגִין דָּא (דברים ל״ב:ל״א) כִּי לא כְצוּרֵנוּ צוּרָם וְאוֹיְבֵינוּ פְּלִילִים.</p>\n<p>וְאִי יִקְשֶׁה בַּר נָשׁ, דְּהָא כְּתִיב (דברים ד׳:ט״ו) כִּי לֹא רְאִיתֶם כָּל תְּמוּנָה. אִיהוּ יְתָרֵץ לֵיהּ, הַאי תְּמוּנָה חָזֵינָא, דְּהָא כְּתִיב (במדבר י״ב:ח׳) וּתְמוּנַת ה' יַבִּיט. וְלא בְכָל תְּמוּנָה אַחֲרָא (ס\"א דברא ויצר באתווי), דְבָּר נַשׁ דְיָצַר בְּאַתְווֹי וּבְגִין דָּא אָמַר, (ישעיהו מ׳:י״ח) וְאֶל מִי תְּדַמְּיוּנִי וְאֶשְׁוֶה וְאֶל מִי תְּדַמְּיוּן אֵל וּמַה דְּמוּת תַּעַרְכוּ לוֹ.</p>\n<p>וַאֲפִילּוּ הַאי תְּמוּנָה, לֵית לֵיהּ בְּאַתְרֵיהּ, אֶלָּא כַּד נָחִית לְאַמְלְכָא עַל בִּרְיָין, וְיִתְפָּשַּׁט עָלַיְיהוּ, יִתְחָזֵי לוֹן לְכָל חַד, כְּפוּם מַרְאֶה וְחֶזְיוֹן וְדִמְיוֹן דִּלְהוֹן, וְהַאי אִיהוּ (הושע י״ב:י״א) וּבְיַד הַנְּבִיאִים אֲדַמֶּה.</p>\n<p>וּבְגִין דָּא יֵימָא אִיהוּ, אַף עַל גַּב דַּאֲנָא אֲדַמֶּה לְכוּ בְּדִיּוּקְנַיְיכוּ, אֶל מִי תְּדַמְּיוּנִי וְאֶשְׁוֶה, דְּהָא קֹדֶם דְּבָּרָא קוּדְשָׁא בְּרִיךְ הוּא דִּיּוּקְנָא בְּעָלְמָא, וְצִיֵּיר צוּרָה, הֲוָה הוּא יְחִידָאי בְּלא צוּרָה וְדִמְיוֹן, וּמַאן (נ\"א ואית) דְּאִשְׁתְּמוֹדָע לֵיהּ, קֹדֶם בְּרִיאָה, דְּאִיהוּ לְבַר מִדִּיוּקְנָא, אָסוּר לְמֶעְבַּד לֵיהּ צוּרָה וּדְיוּקְנָא בְּעָלְמָא, לא בְּאוֹת ה', וְלֹא בְּאוֹת י' וַאֲפִילּוּ בִּשְׁמָא קַדִּישָׁא, וְלא בְּשׁוּם אוֹת וּנְקוּדָה בְּעָלְמָא, וְהַאי אִיהוּ כִּי לֹא רְאִיתֶם כָּל תְּמוּנָה, מִכָּל דָּבָר דְּאִית בֵּיהּ תְּמוּנָה וְדִמְיוֹן לא רְאִיתֶם.</p>\n<p>אֲבָל בָּתַר דְּעָבַד הַאי דִּיּוּקְנָא דְּמֶרְכָּבָה דְּאָדָם עִלָּאָה, נָחִית תַּמָן, וְאִתְקְרֵי בְּהַהוּא דִּיּוּקְנָא יְדוָ\"ד, בְּגִין דְּיִשְׁתְּמוּדְעוּן לֵיהּ בְּמִדּוֹת דִּילֵיהּ, בְּכָל מִדָּה וּמִדָּה, וְקָרָא: אֵל, אֱלֹהִים, שַׁדַּי, צְבָאוֹת, אדי\"ד. בְּגִין דְּיִשְׁתְּמוּדְעוּן לֵיהּ, בְּכָל מִדָּה וּמִדָּה, אֵיךְ יִתְנַהֵג עָלְמָא, בְּחֶסֶ\"ד וּבְדִינָא, כְּפוּם עוֹבָדֵיהוֹן דִּבְנֵי נָשָׁא, דְּאִי לָא יִתְפָּשַּׁט נְהוֹרֵיהּ עַל כָּל בִּרְיָין, אֵיךְ יִשְׁתְּמוֹדְעוּן לֵיהּ, וְאֵיךְ יִתְקָיֵּים, (ישעיהו ו׳:ג׳) מְלֹא כָל הָאָרֶץ כְּבוֹדוֹ.</p>\n<p>וַוי לֵיהּ, מַאן דְּיַשְׁוֶה לֵיהּ, לְשׁוּם מִדָּה, וַאֲפִילּוּ מֵאִלֵּין מִדּוֹת דִּילֵיהּ, כָּל שֶׁכֵּן לִבְנֵי הָאָדָם, (איוב ד׳:י״ט) אֲשֶׁר בֶּעָפָר יְסוֹדָם, דְּכָלִים וְנִפְסָדִים. אֶלָּא דִּמְיוֹנָא דִּילֵיהּ, כְּפוּם שָׁלְטָנוּתֵיהּ עַל הַהִיא מִדָּה, וַאֲפִילּוּ עַל כָּל בִּרְיָין. וּלְעֵילָּא מֵהַהִיא מִדָּה. וְכַד אִסְתְּלִיק מִינָהּ, לֵית לֵיהּ מִדָּה, וְלֹא דִּמְיוֹן, וְלֹא צוּרָה.</p>\n<p>כְּגַוְונָא דְּיַמָּא, דְּלֵית בְּמַיָּא דְּיַמָּא דְּנַפְקֵי מִינֵּיהּ, תְּפִיסוּ כְּלָל וְלֹא צוּרָה, אֶלָּא דְּאִתְפַּשָּׁטוּתָא דְּמַיָּא דְּיַמָּא עַל מָאנָא, דְּאִיהוּ אַרְעָא, אִתְעָבִיד דִּמְיוֹן, וְיָכִילְנָא לְמֶעְבַּד חוּשְׁבַּן תַּמָן, כְּגוֹן הַמָּקוֹר דְּיַמָּא הָא חַד. נָפִיק מִינֵּיהּ מַעְיָן, כְּפוּם אִתְפַּשָּׁטוּתָא דִּילֵיהּ מֵהַהוּא מָאנָא, כְּעִגּוּלָא דְּאִיהִי י', הָא מָקוֹר חַד, וּמַעְיָן דְּנָפִיק מִנֵיהּ הָא תְּרֵין.</p>\n<p>לְבָתַר עָבֵד מָאנָא רַבְרְבָא כְּגוֹן מַאן דְּעָבַד (נ\"א דחפר) חֲפִירָא רַבְרְבָא וְאִתְמְלֵי מִן מַיָּא, דְּנָפִיק מִן מַעְיָין. הַהִיא מָאנָא אִתְקְרֵי יָם, וְהוּא מָאנָא תְּלִיתָאָה, וְהַהוּא מָאנָא רַבְרְבָא, וְאִתְפְּלִיג לְז' נְחָלִין, (נ\"א מאנין) כְּפוּם מָאנִין אֲרִיכִין, הָכִי אִתְפָּשַׁט מַיָּא מִן יַמָּא, לְשִׁבְעָה נְחָלִין וְהָא מָקוֹר, וּמַעְיָין, וְיַמָּא, וְז' נְחָלִין, אִינּוּן י' וְאִי יְתָבַּר אוּמָנָא אִלֵּין מָאנִין דְּתַקִּין, יְהַדְּרוּן מַיָּא לְמָקוֹר, וְיִשְׁתָּאֲרוּ מָאנִין תְּבִירִין יְבֵשִׁין בְּלא מַיָּא.</p>\n<p>הָכִי עִלַּת הָעִלּוֹת, עָבִיד עֶשֶׂר סְפִירוֹת, וְקָרָא לְכֶתֶר מָקוֹר, וּבֵיהּ לֵית סוֹף לִנְבִיעוּ דִּנְהוֹרֵיהּ. וּבְגִין דָּא קָרָא לְגַרְמֵיהּ אֵין סוֹף, וְלֵית לֵיהּ דְּמוּת וְצוּרָה, וְתַמָּן לֵית מָאנָא לְמִתְפַּס לֵיהּ, לְמִנְדַּע בֵּיהּ יְדִיעָא כְּלָל. וּבְגִין דָּא אָמְרוּ בֵּיהּ, בַּמּוּפְלָא מִמְּךָ אַל תִּדְרוֹשׁ, וּבַמְכוּסֶה מִמְּךָ אַל תַּחְקוֹר.</p>\n<p>לְבָתַר עָבֵד מָאנָא זְעֵירָא, וְדָא י', וְאִתְמַלְיָא מִנֵּיהּ, וְקָרָא לֵיהּ מַעְיָן נוֹבֵעַ חָכְמָה, וְקָרָא גַּרְמֵיהּ בָּהּ חָכָם, וּלְהַהוּא מָאנָא קָרָא לֵיהּ חָכְמָ\"ה. וּלְבָתַר עָבֵד מָאנָא רַבְרְבָא, וְקָרָא לֵיהּ יָם, וְקָרָא לֵיהּ בִּינָה, וְהוּא קָרָא לְגַרְמֵיהּ מֵבִין בָּהּ.</p>\n<p>חָכָם מֵעַצְמוֹ, וּמֵבִין מֵעַצְמוֹ, כִּי חָכְמָה אִיהִי לָא אִתְקְרִיאַת חָכְמָה מִגַּרְמָהּ, אֶלָּא בְּגִין הַהוּא חָכָם דְּאַמְלֵי לָהּ מִנְּבִיעוּ דִּילֵיהּ. וְאִיהִי לָא אִתְקְרִיאַת בִּינָה מִגַּרְמָהּ, אֶלָּא עַל שֵׁם (נ\"א בגין) הַהוּא מֵבִין דְּאַמְלֵי לָהּ מִנֵּיהּ. דְּאִי הֲוָה מִסְתָּלַּק מִנָהּ, אִשְׁתַּאֲרַת יְבֵשָׁה. הֲדָא הוּא דִכְתִיב, (איוב י״ד:י״א) אָזְלוּ מַיִם מִנִּי יָם וְנָהָר יֶחרָב וְיָבֵשׁ.</p>\n<p>לְבָתַר וְהִכָּהוּ לְשִׁבְעָה נְחָלִים. וְעָבִיד לֵיהּ לְז' מָאנִין יַקִּירִין, וְקָרָא לוֹן: גְּדוּלָ\"ה. גְּבוּרָ\"ה. תִפְאֶרֶת. נֶצַ\"ח. הוֹ\"ד. יְסוֹ\"ד. מַלְכוּ\"ת. וְקָרָא גַּרְמֵיהּ גָּדוֹל בַּגְּדוּלָ\"ה וְחָסִי\"ד. גִּבּוֹר, בַּגְּבוּרָ\"ה. מְפוֹאָר, בַּתִּפְאֶרֶ\"ת. מָארֵי נַצְחָן קְרָבִין, בְּנֶצַ\"ח נְצָחִים. וּבְהוֹ\"ד קָרָא שְׁמֵיהּ, הוֹד יוֹצְרֵנוּ. וּבַיְסוֹ\"ד קָרָא שְׁמֵיהּ צַדִּיק. וִיסוֹ\"ד, כֹּלָּא סָמִיךְ בֵּיהּ, כָּל מָאנִין וְכָל עָלְמִין. <Nonei></i>וּבְמַלְכוּת, קָרָא שְׁמֵיהּ מֶלֶךְ. וְלוֹ הַגְּדוּלָּ\"ה וְהַגְּבוּרָ\"ה וְהַתִּפְאֶרֶ\"ת וְהַנֵּצַ\"ח וְהַהוֹ\"ד כִּי כֹ\"ל בַּשָּׁמַיִם, דְּאִיהוּ צַדִּי\"ק. וְלוֹ הַמַּמְלָכָה: דְּאִיהוּ מַלְכוּ\"ת.</p>\n<p>כֹּלָּא בִּרְשׁוּתֵיהּ, לְמֶחסַר בְּמָאנִין, וּלְאוֹסָפָא בְּהוֹן נְבִיעוּ, וּלְמֶחֱסַר כְּפוּם רְעוּתֵיהּ (ס\"א בהון) וְלֵית עָלֵיהּ אֱלָהָא, דְּיוֹסִיף בֵּיהּ, אוֹ יִגְרָע בֵּיהּ.</p>\n<p>לְבָתַר עָבֵד מְשַׁמְּשִׁין, לְאִלֵּין מָאנִין, כֻּרְסְיָיא בְּאַרְבַּע סַמְכִין. וְשִׁית דַּרְגִּין לְכֻרְסְיָיא. הָא עֶשֶׂר. וְכֹלָּא אִיהוּ כֻּרְסְיָיא. כְּגוֹן כּוֹס דִּבְרָכָה, דְּתָקִינוּ בוֹ עֲשָׂרָה דְּבָרִים, בְּגִין תּוֹרָה דְּאִתְיְיהִיבַת בַּעֲשָׂרָה דִּבְּרָן. בְּגִין עָלְמָא דְּאִיהוּ מַעֲשֵׂה בְּרֵאשִׁית, דְּאִתְבְּרֵי בַּעֲשָׂרָה מַאֲמָרוֹת.</p>\n<p>וְתָקִין לְכֻרְסְיָיא כִּתּוֹת לְשַׁמְּשָׁא לֵיהּ, דְּאִינּוּן מַלְאָכִים. אֶרְאֵלִים שְׂרָפִים. חַיּוֹת. אוֹפַנִּים. חַשְׁמַלִּים. אֵלִים. אֱלהִים. בְּנֵי אֱלהִי\"ם. אִישִׁי\"ם. וּלְאִלֵּין עָבִיד שַׁמָּשִׁין, סָמָאֵ\"ל, וְכָל כִּתּוֹת דִּילֵיהּ, דְּאִינּוּן כַּעֲנָנִים לְמֶרְכַּב בְּהוֹן לְנַחְתָּא בְּאַרְעָא, וְאִינּוּן כְּסוּסִין לוֹן.</p>\n<p>וּמְנָלָן דַּעֲנָנִים אִקְרוּן מֶרְכָּב. הֲדָא הוּא דִכְתִיב, (ישעיהו י״ט:א׳) הִנֵּה יְיָ' רוֹכֵב עַל עָב קַל וּבָא מִצְרַיִם. וְדָא מְמָנָא דְּמִצְרַיִם, וּמִיָּד דְּחָזוּ (ממנא) דֶּאֱלָהָא דִּי הוּא אֱלָהָא מְמָנָא דִּלְהוֹן, חֲזוּ לֵיהּ כְּסוּסְיָא, תְּחוֹת מֶרְכַּבְתֵּיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא, מִיָּד וְנָעוּ אֱלִילֵי מִצְרַיִם מִפָּנָיו, וּלְבַב מִצְרַיִם יִמַּס, נָעוּ מֵאֱמוּנָה דִּלְהוֹן, וְלֵב דִּלְהוֹן נָמֵס כַּדּוֹנַג, מֵהַהִיא אֱמוּנָה, וְאַמְרִי, וְכִי עַד כְּעַן אֱמוּנָה מְמָנָא דִּילָן כְּסוּסְיָא, הֲוָה נָע לִבְּהוֹן מֵאֱמוּנָה דִּלְהוֹן, וְנָמֵס כַּדּוֹנַג. וּמְנָלָן דְּיִמַס לְשׁוֹן נָמֵס כַּדּוֹנַג אִיהוּ כְּמָה דְאַתְּ אָמֵר, (תהילים כ״ב:ט״ו) הָיָה לִבִּי כַּדּוֹנַג נָמֵס בְּתוֹךְ מֵעַי.</p>"],[9520011598,"<p>(ויקרא כ' ע\"א) (שמות י״ג:י״ג) וְכָל פֶּטֶר חֲמוֹר תִּפְדֶּה בְשֶׂה וְגוֹ'. (פקודא להביא קרב וכו') פִּקּוּדָא דָּא לִפְדּוֹת פֶּטֶר חֲמוֹר, וְלַעֲרוֹף פֶּטֶר חֲמוֹר, אִם לֹא יִפְדֶּה לֵיהּ. הֲדָא הוּא דִכְתִיב וְאִם לֹא תִפְדֶּה וַעֲרַפְתּוֹ. וְרָזָא דָּא יֵצֶר הָרָע, יָכוֹל לְאַחְזְרָא בְּתִיּוּבְתָּא, (ס\"א ולבתר יצר הטוב וכו') וּלְבָתַר לְאַחְזְרָא יֵצֶר הַטּוֹב, כְּמָה דְּאוּקְמוּהָ, אִם זָכָה עֵזֶר, אִם לֹא זָכָה כְּנֶגְדּוֹ. בְּגִין דְּאִינּוּן דִּיּוּקְנָא, חַד דְּשֶׂה, וְחַד דַּחֲמוֹר, וְאִי זָכָה לְאַחְזְרָא בְּתִיּוּבְתָּא, אַף עַל גַּב דְּאִיהוּ חֲמוֹר עַם הָאָרֶץ, תִּפְדֶּה מִן גָּלוּתָא בְשֶׂה, דְּאִיהוּ (ירמיהו נ׳:י״ז) שֶׂה פְזוּרָה יִשְׂרָאֵל. וְאִי לָא הֲדַר בְּתִיּוּבְתָּא, וַעֲרַפְתּוֹ, שָׁוֵי לֵיהּ עַם קְשֵׁה קְדָל, דַּעֲתִידִין לְאִתְמָחֲאָה מִן סֵפֶר חַיִּים, דְּעָלַיְיהוּ אִתְּמַר, (שמות ל״ב:ל״ג) מִי אֲשֶׁר חָטָא לִי אֶמְחֶנּוּ מִסִּפְרִי.</p>"],[9520011599,"<p>(שמות י״ג:ט״ז) וְהָיָה לְאוֹת עַל יָדְכָה וּלְטוֹטָפוֹת בֵּין עֵינֶיךָ וְגוֹ' (בהר ק\"ח ע\"ב ובמשנה) (ח) פִּקּוּדָא דָּא, פִּקּוּדָא דְּאִקְרֵי בְּגַוְונָא אַחֲרָא, דְּלָא אִקְרֵי מִצְוָה, אֶלָּא קְדוּשָׁה, וְאִלֵּין אִינּוּן תְּפִילִין. תְּפִלָּה שֶׁל יַד, וּתְפִלָּה שֶׁל רֹאשׁ. תִּקּוּנָא פְּאֵרָא שַׁפִּירוּ דִּגְוָונִין עִלָּאִין. וְעַל דָּא אִקְרוּן טוֹטָפוֹת, כְּמָה דְאַתְּ אָמֵר, (ישעיהו מ״ט:ג׳) יִשְׂרָאֵל אֲשֶׁר בְּךָ אֶתְפָּאָר.</p>\n<p>וּכְתִיב (הושע י״א:א׳) כִּי נַעַר יִשְׂרָאֵל וָאֹהֲבֵהוּ, יִשְׂרָאֵל זוּטָא. שְׁמַע יִשְׂרָאֵל, יִשְׂרָאֵל סָבָא, שַׁפִּירוּ דִּגְוָונִין, עֵילָּא וְתַתָּא. יוֹסֵף סָלִיק וְאִתְעַטָּר בִּתְרֵין גַּוְונִין (נ\"א דרגין) בְּקַדְמִיתָא נַעַ\"ר, וּבְסוֹפָא צַדִּי\"ק. כַּמָּה יָאַן בֵּיהּ גַּוְונִין לְמֵחזֵי, וְרָזָא דָּא (בראשית ל״ט:ו׳) וַיְהִי יוֹסֵף יְפֵה תֹאַר וִיפֵה מַרְאֶה. שַׁפִּירָא בִּתְרֵין סִטְרִין, בִּתְרֵין דַּרְגִּין, בִּתְרֵין גַּוְונִין, עֵילָּא וְתַתָּא.</p>\n<p>כְּתִיב (דברים ו׳:י״ח) וְעָשִׂיתָ הַיָּשָׁר וְהַטּוֹב. הַיָּשָׁר: דָּא תְּפִלָּה שֶׁל יַד, לְאַמְשָׁכָא (ס\"א לאסמכא) לֵיהּ בִּתְפִילִין שֶׁל רֹאשׁ, לְאִתְיַחֲדָא כַּחֲדָא. וּתְפִלָּה שֶׁל יַד, אַקְדִּים לְשֶׁל רֹאשׁ. וְאִצְטְרִיךְ דְּלָא הֲוֵי פִּרוּדָא בֵּינַיְיהוּ כְּלָל.</p>\n<p>מַאן דְּמִתְעַטְרָא בִּתְפִלִין, קָאִים בְּרָזָא דְּגַוְונָא עִלָּאָה וְקָאִים בְּאִינּוּן תְּרֵין רָזִין דְּקַאמְרָן כְּיוֹסֵף, דְּאִקְרֵי נַעַר, וְאִקְרֵי צַדִּיק, בְּרָזָא דְּעֶבֶד נֶאֱמָן, בְּרָזָא דְּבֶן יְחִידָאי. וְאִלֵּין אִינּוּן תְּפִלָּה שֶׁל יַד, וּתְפִלָּה שֶׁל רֹאשׁ, וְאִינּוּן כְּלָלָא חֲדָא בְּלָא פִּרוּדָא.</p>\n<p>אַרְבַּע פָּרְשִׁיָין דִּתְפִלִין בְּד' בָּתִּים, בְּאִינּוּן תְּפִלִין שֶׁל רֹאשׁ. וּכְמָה דְּאִינּוּן ד' פָּרְשִׁיָין בְּאִינּוּן תְּפִלִין שֶׁל רֹאשׁ, אוּף הָכִי כֻּלְּהוּ בִּתְפִלִין שֶׁל יַד בְּבַיִת א'. דְּהָא בַּתְּפִלָה שֶׁל יַד, לֵית לָהּ מִגַּרְמָהּ כְּלוּם, אֶלָּא מַה דְּנַקְטָא מִלְּעֵילָּא. וְרָזָא דָּא, (קהלת א׳:ז׳) כָּל הַנְּחָלִים הוֹלְכִים אֶל הַיָּם. וּמִגּוֹ דְּנַקְטָא לוֹן מִלְּעֵילָּא, אִקְרֵי תְּפִלָּה, וְאִתְקַדְּשַׁת בִּקְדוּשַׁתְהוֹן (וכלא) אִקְרֵי קְדוּשָׁה. וְאִקְרֵי תְּפִלָּה וּכְדֵין אִקְרֵי מַלְכוּת, מַלְכוּת שָׁמַיִם שְׁלֵימָה.</p>\n<p>ד' פָּרְשִׁיָין, הָא אוֹקִימְנָא רָזָא דִּלְהוֹן, בְּכַמָּה דּוּכְתֵּי. אֲבָל פָּרָשָׁה קַדְמָאָה, קַדֶּשׁ לִי כָל בְּכוֹר, דָּא אִיהוּ רָזָא <Nonei></i>עִלָּאָה, דְּכָלִיל כָּל ד' בָּתִּים, בְּרָזָא דִּנְהִירוּ עִלָּאָה, דְּנָפְקָא מֵאַיִן.</p>\n<p>וְכָל אִינּוּן ד' אִתְרְמִיזוּ הָכָא, קַדֶּשׁ: דָּא קְדוּשָׁה עִלָּאָה. רָזָא דְּחָכְמְתָא עִלָּאָה, דְּמִתַּמָּן כֹּלָּא אִתְקַדָּשׁ, בְּרָזָא דְּגָנִיזוּ עִלָּאָה, דְּאִתְקְרֵי קַדֶּשׁ. לִי: דָּא בִּינָה, רָזָא דְּעָלְמָא עִלָּאָה, הֵיכְלָא פְּנִימָאָה. (ורזא דא (ויקרא כ\"ה) כי לי בני ישראל עבדים (במדבר ג') כי לי כל בכור (שמות י״ט:ה׳) והייתם לי סגלה) כָ\"ל: רָזָא דְּחֶסֶד, בְּכָל דּוּכְתָּא, בֵּין לְעֵילָּא בֵּין לְתַתָּא. בְּכוֹ\"ר: דָּא בֶּן בְּכוֹר, דִּכְתִּיב, (שמות ד) בְּנִי בְכוֹרִי יִשְׂרָאֵל, וְהַאי בֶּן בְּכוֹר, כָּלִיל כָּל סִטְרִין, וְכָל גַּוְונִין. וּבְגִין כַּךְ, קְרָא כָּלִיל כֻּלְּהוּ אַרְבַּע, בְּרָזָא דְּחָכְמְתָא עִלָּאָה. אֲבָל דָּא בְּאוֹרַח כְּלָל, לְמִנְדַּע דְּכֹלָּא כָּלִיל בְּהַאי, אֲבָל בְּאוֹרַח פְּרָט, כָּל חַד בִּלְחוֹדוֹי, דָּא אִיהוּ פַּרְשְׁתָּא קַדְמָאָה, דְּכָלִיל כָּל שְׁאַר פָּרְשִׁיָין.</p>\n<p>פָּרָשָׁה תִּנְיָינָא, וְהָיָה כִּי יְבִיאֲךָ וְגוֹ', דָּא בִּינָה, דְּהָא בְּפַרְשְׁתָּא דָּא, אִיהִי יְצִיאַת מִצְרַיִם, דְּהֲוָה מִסִּטְרָא דְּיוֹבְלָא. וְעַל דָּא שֵׁירוּתָא דִּילָהּ וְהָיָ\"ה, דְּהָא מִלָּה דָּא אִיהִי בְּיוֹבְלָא. וּבְגִין כַּךְ שְׁמָא דִּילָהּ וְהָיָ\"ה, דְּלֵית וְהָיָה (נ\"א הויה) אֶלָּא בַּאֲתָר דָּא, דְּאִיהוּ זַמִּין לְאִתְמַשְּׁכָא לְתַתָּא, וּלְאַנְהָרָא בּוּצִינִין, וּלְאִשְׁתַּכְּחָא בְּדַרְגָּא תַּתָּאָה, (נ\"א והיה כמאן דאמר על מלכא דאיהי הוי) (נ\"א דיהוי זמין לאתמשכא לתתא ולאנהרא בוצינין) וְכֹלָּא בְּרָזָא חֲדָא. וּבְגִין דְּאִיהוּ בְּאוֹרַח טָמִיר, לָא אִקְרֵי בְּאִתְגַּלְּיָיא בִּשְׁמָא דָּא, אֶלָּא אִתְמְסַר לְחַכִּימִין לְמִנְדַּע. וְעַל דָּא אִתְרְשִׁים בִּשְׁמָא קַדִּישָׁא, בְּמִלָּה דָּא.</p>\n<p>פָּרָשָׁה תְּלִיתָאָה, שְׁמַע, דָּא אִיהוּ רָזָא דִּימִינָא, דְּאִקְרֵי חֶסֶד עִלָּאָה. דְּאִיהוּ קָא מְיַיחֵד יִחוּדָא דְּכֹלָּא לְד' סִטְרִין, וְקוּדְשָׁא בְּרִיךְ הוּא מְסַדֵּר בֵּיהּ, סִדּוּרָא דְּכָל עָלְמָא, וְדָא אִיהוּ דְּקָא מִתְפַּשַּׁט בְּכָל סִטְרִין, אֲפִילּוּ גּוֹ תְּהוֹמֵי תַּתָּאֵי. בְּדָא קוּדְשָׁא בְּרִיךְ הוּא בָּרָא עָלְמָא, כַּד אִתְעַטָּף קוּדְשָׁא בְּרִיךְ הוּא בְּעִטּוּפָא דְּזִהֲרָא, וְדָא דְּקָא מְיַיחֵד יִחוּדָא, וּבְגִין כַּךְ, שְׁמַע סָמִיךְ לִוְהָיָ\"ה.</p>\n<p>יִחוּדָא דְּכָל יוֹמָא, אִיהוּ, יִחוּדָא לְמִנְדַּע וּלְשַׁוָּאָה רְעוּתָא. יִחוּדָא דָּא הָא אַמָרָן בְּכַמָּה דּוּכְתֵּי, יִחוּדָא דְּכָל יוֹמָא, אִיהוּ יִחוּדָא דִּקְרָא, (דברים ו׳:ד׳) שְׁמַע יִשְׂרָאֵל יְיָ' אֱלֹהֵינוּ יְיָ' הָא כֻּלְּהוּ חַד, וְעַל דָּא אִקְרֵי אֶחָד. הָא תְּלַת שְׁמָהָן אִינּוּן, הֵיךְ אִינּוּן חַד, וְאַף עַל גַּב דְּקָרֵינָן אֶחָד, הֵיךְ אִינּוּן חַד.</p>\n<p>אֶלָּא, בְּחֶזְיוֹנָא דְּרוּחַ קֻדְשָׁא אִתְיְידָע, וְאִינּוּן בְּחֵיזוּ דְּעֵינָא סְתִימָא, לְמִנְדַּע דִּתְלָתָא אִלֵּין אֶחָד. וְדָא אִיהוּ רָזָא דְּקוֹל דְּאִשְׁתְּמַע, קוֹל אִיהוּ חַד, וְאִיהוּ תְּלָתָא גַּוְונִין, אֶשָּׁא וְרוּחָא וּמַיָּא, וְכֻלְּהוּ חַד, בְּרָזָא דְּקוֹל. (ולאו אינון אלא חד) אוּף הָכָא: יְיָ' אֱלהֵינוּ יְיָ' אִינּוּן חַד. תְּלָתָא גַּוְונִין, וְאִינּוּן חַד.</p>\n<p>וְדָא אִיהוּ קוֹל דְּעָבִיד בַּר נָשׁ בְּיִחוּדָא, וּלְשַׁוָּואָה רְעוּתֵיהּ בְּיִחוּדָא דְּכֹלָּא, מֵאֵין סוֹף עַד סוֹפָא דְּכֹלָּא, בְּהַאי קוֹל דְּקָא עָבִיד בְּהָנֵי תְּלָתָא דְּאִינּוּן חַד. וְדָא אִיהוּ יִחוּדָא דְּכָל יוֹמָא, דְּאִתְגְלֵי בְּרָזָא דְּרוּחַ קוּדְשָׁא.</p>\n<p>וְכַמָּה גַּוְונִין דְּיִחוּדָא אִתְעֲרוּ, וְכֻלְּהוּ קְשׁוֹט. מַאן דְּעָבִיד הַאי עָבִיד. וּמַאן דְּעָבִיד הַאי עָבִיד. אֲבָל הַאי יִחוּדָא דְּקָא אֲנָן מִתְעָרֵי מִתַּתָּא, בְּרָזָא דְּקוֹל דְּאִיהוּ חַד, דָּא הוּא בְּרִירָא דְּמִלָּה, הַאי בִּכְלָלָא, לְבָתַר פְּרָט, כִּדְקָאַמְרָן.</p>\n<p>פָּרָשָׁה רְבִיעָאָה, הוּא רָזָא דְּדִינָא קַשְׁיָא, (דברים י״א:ט״ז) הִשָּׁמְרוּ לָכֶם. אִלֵּין אִינּוּן תְּפִלִין דְּרֵישָׁא. וּתְפִלִּין דִּדְרוֹעָא, כְּגַוְונָא דָּא בְּחַד בֵּיתָא, וְהָא אִתְּעַרְנָא בְּהוּ, וְכֻלְּהוּ רָזָא חֲדָא.</p>\n<p>קִשְׁרָא דִּתְפִלִין דְּרִישָׁא, אִיהוּ דָּלֶ\"ת, וְעַל דָּא כְּתִיב, (שמות ל״ג:כ״ג) וְרָאִיתָ אֶת אֲחוֹרָי. וְעַל דָּא אִיהוּ לַאֲחוֹרָא, וְתַמָּן אִתְקַשַּׁר כֹּלָּא בְּקִשְׁרָא חֲדָא.</p>\n<p>וְאִיהִי, כַּד מַנְחָת אִלֵּין תְּפִלִין דִּדְרוֹעָא לְאִתְקַשְּׁרָא, (ס\"א אית קשרא) אַחֲרָא, רָזָא דִּבְרִית קַדִּישָׁא, רָזָא דָּא, כְּמָה דְּאִתְּעַר בְּכַמָּה דּוּכְתֵּי, וְכֹלָּא רָזָא חֲדָא. זַכָּאִין אִינּוּן יִשְׂרָאֵל דְּיַדְעִין רָזָא דָּא, וְאִצְטְרִיךְ בַּר נָשׁ לַאֲנָחָא לוֹן כָּל יוֹמָא, לְמֶהֱוֵי בְּדִיּוּקְנָא עִלָּאָה, וְעָלֵיהּ כְּתִיב, (דברים כ״ח:י׳) וְרָאוּ כָּל עַמֵּי הָאָרֶץ כִּי שֵׁם יְיָ' נִקְרָא עָלֶיךָ וְיָּרְאוּ מִמֶּךָּ. (ע\"כ רעיא מהימנא) בילאו\"א.</p>"],[9520011600,"<p><Nonei></i>וַיְהִי בְּשַׁלַּח פַּרְעֹה אֶת הָעָם וְלֹא נָחָם אֱלהִים דֶּרֶךְ אֶרֶץ פְּלִשְׁתִּים וְגוֹ'. רִבִּי שִׁמְעוֹן פָּתַח, (חבקוק ג׳:א׳) תְּפִלָּה לַחֲבַקּוּק הַנָּבִיא עַל שִׁגְיוֹנוֹת. הַאי קְרָא קַשְׁיָא, וְאִית לְאִסְתַּכְּלָא בֵּיהּ, מַאי שְׁנָא תְּפִלָּה לַחֲבַקּוּק הַנָּבִיא, יַתִּיר מִכָּל שְׁאַר נְבִיאֵי עָלְמָא, דְּלָא כְּתִיב בְּהוּ תְּפִלָּה לִישַׁעְיָה הַנָּבִיא, אוֹ לְיִרְמִיָּה, אוֹ לִיחֶזְקֵאל, אוֹ לְהוֹשֵׁעַ, אוֹ לִשְׁאַר נְבִיאֵי עָלְמָא.</p>\n<p>אֶלָּא הָכִי תָּנֵינָן, אֱלִישָׁע זָכָה בְּהַאי עָלְמָא מַה דְּלָא זָכָה נְבִיאָה אָחֳרָא, בַּר מִמֹּשֶׁה. (ועם כל דא לא בעא לאטרחא למריה) תָּא חֲזִי, מַאי כְּתִיב, (מלכים ב ד׳:ח׳) וַיְהִי הַיּוֹם וַיַּעֲבוֹר אֱלִישָׁע אֶל שׁוּנֵם וְשָׁם אִשָּׁה גְּדוֹלָה. מַאי אִשָּׁה גְּדוֹלָה. אֶלָּא גְּדוֹלָה בְּעוֹבָדָהָא, דְּכָל בְּנֵי (ס\"א דרא) בֵּיתָא, מִשְׁתַּבְּחִין בָּהּ, וְהִיא עִקָרָא דְּבֵיתָא, וּבְגִין דְּבַעֲלָהּ לָא הֲוָה שְׁכִיחַ בְּבֵיתָא, לְמֶהֱוֵי עִקָרָא, לָא הֲוָה אִדְכַּר הוּא, אֶלָּא הִיא.</p>\n<p>וְתוּ, וְשָׁם אִשָּׁה גְּדוֹלָה: גְּדוֹלָה עַל כָּל שְׁאַר נְשֵׁי עָלְמָא, דְּהָא שְׁאַר נְשֵׁי עָלְמָא, כַּד חָמָאן אוּשְׁפִּיזָא בְּבֵיתָא, מִצְטַעֲרָן בֵּיהּ, וְדָחֲקָן בֵּיהּ כָּל שֶׁכֵּן לְאַפָּקָא עָלֵיהּ מָמוֹנָא, וְהִיא חֲדַת בֵּיהּ בְּאוּשְׁפִּיזָא, וּלְאַפָּקָא עָלֵיהּ מָמוֹנָא, כָּל שֶׁכֵּן כֵּיוָן דְּחָמַת לֵיהּ לֶאֱלִישָׁע חַדַת בֵּיהּ לַחֲדָּא. וְעַל דָּא, שְׁבָחָא דְּכֹלָּא דְּאִתְּתָא הִיא, דְּהָא אוּשְׁפִּיזָא דְּבֵיתָא דְּאִתְּתָא הִיא. וּבְגִין כַּךְ וְשָׁם אִשָּׁה גְּדוֹלָה, גְּדוֹלָה עַל שְׁאַר נָשִׁין.</p>\n<p>וַתֹּאמֶר אֶל אִישָׁהּ הִנֵּה נָא יָדַעְתִּי כִּי אִישׁ אֱלהִים קָדוֹשׁ הוּא, בְּמָּה יַדְעָה. אֶלָּא הָא אוּקְמוּהָ חַבְרַיָּא, דְּשׁוּשִׁיפָא חִוָּורָא זְרִיקַת לֵיהּ בְּעַרְסֵיהּ. וְלָא חָמַת בֵּיהּ קֶרִי מֵעוֹלָם, וְלָא אַעְבָּר זְבוּבָא בְּפָתוֹרֵיהּ.</p>\n<p>הָנֵי מִילֵי קַשְׁיָין, אִי תֵּימָא דְּלָא חָמַת בֵּיהּ קֶרִי, הָא סַגִּיאִין אִינּוּן בְּנֵי נָשָׁא הָכִי בְּעָלְמָא, מַה שִׁנּוּיָא הָכָא. וְאִי תֵּימָא דְּלָא עָבַר זְבוּבָא בְּפָתוֹרֵיהּ. אֲמַאי כְּתִיב, הִנֵּה נָא יָדַעְתִּי, וְכִי הִיא יַדְעַת, וְלָא אָחֳרָא, וְהָא כָּל אִינּוּן דְּחָמוּ לֵיהּ אָכִיל בְּפָתוֹרֵיהּ הֲווֹ יַדְעֵי.</p>\n<p>אֶלָּא שַׁפִּיר קָאַמְרַת, אֲבָל הִנִּה נָא יָדַעְתִּי, הִיא יַדְעָה, וְלָא אָחֳרָא, בְּגִין דְּהִיא מְתַקְנַת עַרְסֵיהּ, בְּשַׁעֲתָא דְּשָׁכִיב בְּלֵילְיָא, וּבְשַׁעֲתָא דְּקָאִים בְּצַפְרָא. וְהַאי דְּקַאמְרֵי דְּשׁוּשִׁיפָא חִוָּורָא זְרִיקַת לֵיהּ בְּעַרְסֵיהּ, הָכִי הֲוָה, וּבָהּ יַדְעָה, דְּאָרְחָא דְּעָלְמָא, כֵּיוָן דְּקָאִים בַּר נָשׁ מֵעַרְסֵיהּ, סָלִיק שׁוּשִׁיפָא דְּנָאִים בָּהּ, רֵיחָא מְנוּוָלָא. וְהַאי, בְּשַׁעֲתָא דְּסַלְקַת הַהוּא שׁוּשִׁיפָא מֵעַרְסֵיהּ, הֲוָה סָלִיק רֵיחִין, (קכ\"ז) כְּרֵיחִין דְּגִנְתָּא דְּעֵדֶן. אָמְרָה אִי לָאו דְּקַדִּישָׁא הוּא, וּקְדוּשָׁה דְּמָרֵיהּ עָלֵיהּ, לָא סָלִיק רֵיחָא קַדִּישָׁא הָכִי.</p>\n<p>בְּגִינֵי כַּךְ, בָּעֵי לְאִתְפָּרְשָׁא מִן בֵּיתָא, דְּלָא אִזְדְּהַר בַּר נָשׁ כָּל כַּךְ בְּבֵיתָא. אֲבָל אַמְרַת, (מלכים ב ד׳:י׳) נַעֲשֶׂה נָא עֲלִיַּית קִיר קְטַנָּה וְנָשִׂים לוֹ שָׁם מִטָּה וְשֻׁלְחָן וְכִסֵּא וּמְנוֹרָה, אַרְבַּע אִלֵּין לָמָּה. אֶלָּא בְּגִין דְּאִינּוּן תִּקּוּנָא דִּכְנֶסֶת יִשְׂרָאֵל, דְּאִתְקְרִיאַת עֲלִיַּית קִיר, וְהָכִי אִתְקַרְיא, כְּמָה דִּכְתִּיב, (ישעיהו ל״ח:ב׳) וַיַּסֵּב חִזְקִיָּה פָּנָיו אֶל הַקִּיר.</p>\n<p>מִטָּה וְשֻׁלְחָן וְכִסֵּא וּמְנוֹרָה, לָאו אִינּוּן כְּתִיקוּן דְּשִׁמּוּשָׁא, דְּהָא כִּסֵּא קָא בָּעֵי בְּקַדְמִיתָא, וּלְבָתַר שֻׁלְחָן, לְבָתַר מְנוֹרָה, לְבָתַר מִטָּה, אֲמַאי אַקְדִּימַת מִטָּה. בְּגִין דְּהִיא חֲבִיבָה עָלֵיהּ יַתִּיר מִכֹּלָּא, וְאַקְדִּים בַּר נָשׁ מַה דְּחָבִיב עָלֵיהּ.</p>\n<p>(מלכים ב ד׳:י׳-י״א) וַיְהִי הַיּוֹם וַיָּבוֹא שָׁמָּה. וַיְהִי הַיּוֹם, מַאן הוּא יוֹמָא דָּא. אֶלָּא כְּמָה דְּאוּקְמוּהָ. וְתָּא חֲזֵי. הַהוּא יוֹמָא, יוֹמָא טָבָא דְּרֹאשׁ הַשָּׁנָה הֲוָה, דְּאִתְפְּקָדוּ בֵּיהּ עֲקָרוֹת דְּעָלְמָא, וְאִתְפַּקְּדָן בֵּיהּ בְּנֵי עָלְמָא. קָרָא לַשּׁוּנַמִּית וְאָמַר, (מלכים ב ד׳:י״ג) הִנֵּה חָרַדְתְּ אֵלֵינוּ אֶת כָּל הַחֲרָדָה הַזֹּאת. בְּגִינֵי כַּךְ, אִצְטְרִיכְנָא לְעַיְּינָא יוֹמָא דָּא בְּדִינִי דְּעָלְמָא, דְּקוּדְשָׁא בְּרִיךְ הוּא דָּאִין בְּיוֹמָא דָּא <Nonei></i>לְעָלְמָא, וּבְגִין דְּאִתְפָּרַשְׁנָא בִּלְחוֹד בַּאֲתָר דָּא, אִצְטְרִיכְנָא לְאִסְתַּכְּלָא בִּרְגִיזוּ דְּעָלְמָא.</p>\n<p>(מלכים ב ד׳:י״ג) וּמַה לַעֲשׂוֹת לָךְ הֲיֵשׁ לְדַבֵּר לָךְ אֶל הַמֶּלֶךְ אוֹ אֶל שַׂר הַצָּבָא. וְכִי מִלָּה דָּא לְמָה אִצְטְרִיכָא לְגַבֵּי אִתְּתָא, דְּלָא נַפְקַת וְלָא אַזְלַת וְלָא עָאלַת בְּהֵיכְלָא דְּמַלְכָּא. אֶלָּא, יוֹמָא דָּא הֲוָה גָּרִים, דְּכָל בְּנֵי עָלְמָא יַתְבִין (נ\"א קיימין) בְּדִינָא, וּבְהַהוּא יוֹמָא אִקְרֵי קוּדְשָׁא בְּרִיךְ הוּא מֶלֶךְ. הַמֶּלֶךְ הַמִּשְׁפָּט. אָמַר לָהּ, אִי אַתְּ אִצְטְרִיךְ לָךְ לְגַבֵּי מַלְכָּא עִלָּאָה, עַל עוֹבָדִין דִּי בִּידָךְ.</p>\n<p>וַתֹּאמֶר בְּתוֹךְ עַמִּי אָנֹכִי יֹשָׁבֶת. מַאי קָאַמְרַת. אֶלָּא בְּשַׁעֲתָא (נ\"א בזמנא) דְּדִינָא תַּלְיָא בְּעָלְמָא, לָא יִתְפְּרַשׁ בַּר נָשׁ בִּלְחוֹדוֹי, וְלָא יִתְרְשִׁים לְעֵילָּא, וְלָא יִשְׁתְּמוֹדְעוּן בֵּיהּ בִּלְחוֹדוֹי, דְּהָא בְּזִמְנָא (אחרא) דְּדִינָא תַּלְיָא בְּעָלְמָא, אִינּוּן דְּאִשְׁתְּמוֹדְעוּן וּרְשִׁימִין בִּלְחוֹדַיְיהוּ, אַף עַל גַּב דְּזַכָּאִין אִינּוּן, אִינּוּן אִתָּפְסָן בְּקַדְמִיתָא. וְעַל דָּא, לָא לִבָעֵי לֵיהּ לְאִינִישׁ, לְאִתְפָּרְשָׁא מִבֵּין עַמָּא לְעָלַם, דִּבְכָל זִמְנָא רַחֲמֵי דְּקוּדְשָׁא בְּרִיךְ הוּא עַל עַמָּא כֻּלְּהוּ כְּחַד. (ולא לבעי ליה לאיניש לאתפרש מן עמא לעלם) וּבְגִינֵי כַּךְ אָמְרָה, בְּתוֹךְ עַמִּי אָנֹכִי יֹשָׁבֶת, וְלָא בְּעֵינָא לְאִתְפָּרְשָׁא מִנַּיְיהוּ, כְּמָה דְּעָבֵדְנָא עַד יוֹמָא דֵּין.</p>\n<p>וַיֹּאמֶר גֵּחֲזִי אֲבָל בֵּן אֵין לָהּ וְגוֹ'. אָמַר לָהּ אֱלִישָׁע. הָא וַדַּאי שַׁעֲתָא קַיְּימָא, דְּהָא יוֹמָא גָּרִים. וַיֹּאמֶר לַמּוֹעֵד הַזֶּה כָּעֵת חַיָּה אַתְּ חוֹבֶקֶת בֶּן. וַתַּהַר הָאִשָּׁה וַתֵּלֶד בֶּן לַמּוֹעֵד הַזֶּה כָּעֵת חַיָּה אֲשֶׁר דִּבֶּר אֵלֶיהָ אֱלִישָׁע. לַמּוֹעֵד וַדַּאי. לְבָתַר מִית. מַאי טַעֲמָא מִית. אֶלָּא בְּגִין דְּאִתְיְיהִב לָהּ, וְלָא לְבַעְלָהּ. וּמֵאֲתָר דְּנוּקְבָּא אִתְקָשָּׁר, וּמַאן דְּאִתְקָשָּׁר בְּנוּקְבָּא, מוֹתָא אִזְדַּמְּנַת קָמֵיהּ. מְנָא לָן דְּלָהּ אִתְיְהִיב, דִּכְתִּיב אַתְּ חוֹבֶקֶת בֵּן.</p>\n<p>תָּא חֲזֵי, בְּאַבְרָהָם כְּתִיב (בראשית י״ח:י׳) שׁוֹב אָשׁוּב אֵלֶיךָ, וְלֹא אֵלֶיהָ, אֵלֶיךָ וַדַּאי, בָּךְ אִתְקָשָּׁר, וְלָא בְּנוּקְבָא. מַאן דְּאָתֵי מִסִּטְרָא דְּנוּקְבָּא, מוֹתָא אַקְדִּים לְרַגְלוֹי. וַתַּעַל וַתַּשְׁכִּיבֵהוּ עַל מִטַּת אִישׁ הָאֱלהִים, בְּגִין דְּתַמָּן חָמַת קְדוּשָׁה עִלָּאָה מִכֹּלָּא.</p>\n<p>וַיֹּאמֶר לָהּ הֲשָׁלוֹם לָךְ הֲשָׁלוֹם לְאִישֵׁךְ הֲשָׁלוֹם לַיָּלֶד. מִכָּאן, דְּהִיא עִקָרָא דְּבֵיתָא, וְלֹא עוֹד אֶלָּא דְּאִיהִי אַזְלַת אֲבַתְרֵיהּ, וְלֹא בַּעְלָהּ. וַיִּגַּשׁ גֵּחֲזִי לְהָדְפָהּ הָא אוּקְמוּהָ.</p>\n<p>וַיֹּאמֶר אִישׁ הָאֱלהִים הַרְפֵּה לָהּ. מַאי שְׁנָא הָכָא דְּאָמַר אִישׁ הָאֱלֹהִים, וְכַד הֲוָה בְּמָתָא אֱלִישָׁע. אֶלָּא הָכָא וַדַּאי אִישׁ הָאֱלהִים, דְּהָכָא (ס\"א הוא) חַזָא דּוּכְתֵּיהּ, וְלָא בְּמָתָא, וְלָא בְּשַׁעֲתָא דַּהֲווֹ בְּנִי נְבִיאֵי קָמֵיהּ.</p>\n<p>וַיְיָ' הֶעְלִים מִמֶּנִּי וְגוֹ', כְּמָה דְּאַתְּ אָמֵר (בראשית י״ט:כ״ד) וַיְיָ' הִמְטִיר עַל סְדוֹם וְעַל עֲמוֹרָה, דָּא בֵּי דִּינָא דִּלְתַתָּא. וְלֹא הִגִּיד לִי, מַאי טַעֲמָא לֹא יָדַע אֱלִישָׁע. אֶלָּא אָמַר קוּדְשָׁא בְּרִיךְ הוּא, וּמָה אֲנָא קָטִיל לְהַאי, אִי אֵימָא לֵיהּ, לא יָמוּת, דְּהָא נְבִזְבְּזָא דִּילֵיהּ הוּא. וַדַּאי אִית לֵיהּ לְמֵימָת, דְּהָא אִתְּמַר, דִּכְתִּיב אַתְּ חוֹבֶקֶת בֵּן, וּמֵאֲתָר דְּנוּקְבָּא גָּרִים מוֹתָא, וּבְגִינֵי כַּךְ לָא אָמַר לֵיהּ.</p>\n<p>וַיֹּאמֶר לְגֵחֲזִי חֲגוֹר מָתְנֶיךָ וְקַח מִשְׁעַנְתִּי בְיָדְךָ וָלֵךְ. וְהָא אוּקְמוּהָ וְאִסְתְּלַק נִיסָא מִנֵּיהּ. חַי יְיָ' וְחֵי נַפְשְׁךָ אִם אֶעֶזְבֶךָּ, אֲמַאי כֵּיוָן דְּגֵיחֲזִי הֲוָה אָזִיל. אֶלָּא הִיא יַדְעַת אָרְחוֹי דְּהַהוּא רָשָׁע דְּגֵיחֲזִי, דְּלָאו אִיהוּ כְּדַאי דְּיִשְׁתְּכַח נִיסָא עַל יְדוֹי.</p>\n<p>וַיָּשֶׂם פִּיו עַל פִּיו וְעֵינָיו עַל עֵינָיו וְגוֹ'. אֲמַאי, אֶלָּא דְּאַשְׁגַּח אֱלִישָׁע וְיָדַע דְּאַתְרָא (דאתתא הוא) דָּא הוּא דְּגָרִים, דְּאִתְקְשָׁר בֵּיהּ הַשְׁתָּא. וַיָּשֶׂם פִּיו עַל פִּיו וְעֵינָיו עַל עֵינָיו, לְקַשְּׁרָא לֵיהּ בְּאַתְרָא אָחֳרָא עִלָּאָה, אֲתָר דְּחַיִּין אִשְׁתְּכָחוּ בֵּיהּ.</p>\n<p>וְלָא יָכִיל לְאַעְקְרָא לֵיהּ מֵאֲתָר דְּאִתְקַשָּׁר בֵּיהּ בְּקַדְמִיתָא, אֶלָּא אִתְּעַר רוּחָא חֲדָא מִלְּעֵילָּא, וְאִתְקְשַׁר בְּהַאי אֲתָר, וְאָתִיב לֵיהּ נַפְשֵׁיהּ. דְּאִי לָאו הָכִי לָא הֲוָה קָאִים לְעָלְמִין. וַיְזוֹרֵר הַנַּעַר עַד שֶׁבַע פְּעָמִים, וְלָא סָלִיק יַתִּיר, כְּמָה דְּאַתְּ אָמֵר (תהילים צ׳:י׳) יְמֵי שְׁנוֹתֵינוּ בָּהֶם שִׁבְעִים שָׁנָה.</p>\n<p>וְדָא הוּא חֲבַקּוּק נְבִיאָה, כְּמָה דְּאַתְּ אָמֵר אַתְּ חוֹבֶקֶת בֵּן. אִי הָכִי חָבוּק מִבָּעֵי לֵיהּ, אֲמַאי חֲבַקּוּק תְּרֵי. אֶלָּא, חַד <Nonei></i>דְּאִמֵּיהּ, וְחַד דְּאֱלִישָׁע, דְּאִתְחַבָּק עִמֵּיהּ. דָּבָר אַחֵר תְּרֵי חִבּוּקִין הֲווֹ בֵּיהּ, בֵּין לְהַאי סִטְרָא בֵּין לְהַאי סִטְרָא. חִבּוּקָא חֲדָא, הַהוּא אֲתָר דְּהֲוָה תָּלֵי בֵּיהּ בְּקַדְמִיתָא. חִבּוּקָא אַחֲרִינָא דְּסָלִיק לֵיהּ לְדַרְגִּין עִלָּאִין יַתִּיר, וּבְגִין כָּךְ חֲבַקּוּק תְּרֵי.</p>\n<p>(חבקוק ג׳:א׳) תְּפִלָּה לַחֲבַקּוּק הַנָּבִיא, מַאי תְּפִלָּה. אֶלָּא דָּא הוּא אֲתָר, דְּהֲוָה קָשִׁיר בֵּיהּ בְּקַדְמִיתָא, וְדָא הוּא תְּפִלָּה שֶׁל יָד. עַל שִׁגְיוֹנוֹת. דְּהַהוּא יוֹמָא דְּאִתְקְשָׁר בֵּיהּ, שִׁגְיוֹנוֹת דְּעָלְמָא הֲווֹ תַּלְיָין קָמֵי קוּדְשָׁא בְּרִיךְ הוּא, וּגְבוּרָה הֲוָה שָׁלִיט, וְעַל דָּא אִתְקְשַׁר בֵּיהּ הַאי תְּפִלָּה. (נ\"א בהאי תפלה)</p>\n<p>דָּבָר אַחֵר תְּפִלָּה לַחֲבַקּוּק הַנָּבִיא, תְּפִלָּה לַחֲבַקּוּק: בְּגִין חֲבַקּוּק, דְּאִיהוּ עָבִיד בְּגִינֵיהּ. יְיָ' שָׁמַעְתִּי שִׁמְעֲךָ יָרֵאתִי וְגוֹ', תָּא חֲזֵי, כַּד הֲוָה אִתְּעַר עָלֵיהּ רוּחָא דִּנְבוּאָה עַל אֲתָר דָּא דְּהוּא תְּפִלָּה, הֲוָה אָתֵי וַהֲוָה דָּחִיל וּמִזְדַּעְזִע. מַתְלָא אַמְרִי, מַאן דְּנָשִׁיךְ מִכַּלְבָּא, מִקָּלֵיהּ אִזְדַּעְזָע.</p>\n<p>יְיָ' פָּעָלְךָ בְּקֶרֶב שָׁנִים חַיֵּיהוּ, מַאן פָּעָלְךָ. אֶלָּא, עָלֵיהּ קָאָמַר, דְּאִיהוּ פֹּעַל דִּילֵיהּ. בְּקֶרֶב שָׁנִים חַיֵּיהוּ. הָב לֵיהּ חַיִּין לְהַאי פָּעָלְךָ, בְּקֶרֶב שְׁנִין עִלָּאִין. דָּבָר אַחֵר, חַיֵּיהוּ דְּלָא יָמוּת כַּד בְּקַדְמִיתָא.</p>\n<p>עַל שִׁגְיוֹנוֹת, מַאי עַל שִׁגְיוֹנוֹת, עַל שְׁגִיאוֹת מִבָּעֵי לֵיהּ. כְּמָה דְאַתְּ אָמֵר (תהילים י״ט:י״ג) שְׁגִיאוֹת מִי יָבִין. אֶלָּא (כלא הוא אבל) שִׁגְיוֹנוֹת, כְּמָה דְאַתְּ אָמֵר (תהילים ז׳:א׳) שִׁגָּיוֹן לְדָוִד. זִינִי תּוּשְׁבְּחָן הֲווֹ קָמַיְיהוּ דִּנְבִיאֵי, לְמִישְׁרֵי עָלַיְיהוּ רוּחַ נְבוּאָה, כְּמָה דְאַתְּ אָמֵר (שמואל א י׳:ה׳) וּפָגַעְתָּ חֶבֶל נְבִיאִים יוֹרְדִים מֵהַבָּמָה וְלִפְנֵיהֶם נֵבֶל וְתוֹף וְגוֹ', וּכְתִיב (מלכים ב ג׳:ט״ו) וְעַתָּה קְחוּ לִי מְנַגֵּן וְגוֹ'. וְכָל שֶׁכֵּן חֲבַקּוּק, דְּאִצְטְרִיךְ לֵיהּ יַתִּיר מִכֻּלְּהוֹן, לְנַיְיחָא דְּרוּחָא, וּלְבַסְּמָא לְהַהוּא אֲתָר, לְאַמְשָׁכָא עָלֵיהּ רוּחַ נְבוּאָה. וְכֵן כֻּלְּהוּ נְבִיאֵי כְּהַאי גַּוְונָא, בַּר מִמֹּשֶׁה דְּסָלִיק עַל כָּל שְׁאַר נְבִיאֵי דְּעָלְמָא, זַכָּאָה חוּלָקֵיהּ.</p>\n<p>תָּא חֲזֵי, כַּד נַפְקוּ יִשְׂרָאֵל מִמִּצְרַיִם, רוּחֵיהוֹן הֲוָה תָּבִיר בְּגַוַּויְיהוּ, וַהֲווּ שַׁמְעִין אִינּוּן תּוּשְׁבְּחָן, וְלָא יַכְלִין לְמֶחדֵי, וּבְשַׁעֲתָא דְּכֻלְּהוּ אוֹכְלֹסִין וּרְתִיכִין נַפְקוּ בִּשְׁכִינְתָּא, כֻּלְּהוּ אָרִימוּ תּוּשְׁבְּחָן וְשִׁירִין קָמֵי קוּדְשָׁא בְּרִיךְ הוּא, וְאִתְּעַר קוּדְשָׁא בְּרִיךְ הוּא רוּחֵיהוֹן דְּיִשְׂרָאֵל, וַהֲווּ שַׁמְעִין אִינּוּן תּוּשְׁבְּחָן, וְקָאִים רוּחֵיהוֹן בְּגַוַויְיהוּ דְּלָא פַּרְחָן.</p>\n<p>בַּר נָשׁ כַּד אִיהוּ שָׁבִיק פּוּלְחָנָא, כְּדֵין יָדַע תְּבִירוּ דְּגַרְמוֹי, תְּבִירוּ דְּרוּחֵיהּ. כַּךְ יִשְׂרָאֵל, כַּד נַפְקוּ מִמִּצְרַיִם, כְּדֵין טָעִימוּ טַעֲמָא דְּמוֹתָא, וְקוּדְשָׁא בְּרִיךְ הוּא אַסֵּי לוֹן, דִּכְתִּיב, (שמות י״ג:כ״א) וַיְיָ' הוֹלֵךְ לִפְנֵיהֶם יוֹמָם וְגוֹ'. וְכָל אוֹרְחִין, הֲווֹ סַלְּקִין רֵיחִין דְּאַסְוָתָא, וְעָאלִין לְגוּפַיְיהוּ וְאִתָּסְיָין, וְקַל תּוּשְׁבְּחָן דַּהֲווֹ שַׁמְעִין, הֲווֹ חַדָּאן וְנַיְיחִין בְּרוּחֵיהוֹן.</p>\n<p>וּפַרְעֹה וְכָל אִינּוּן אוּכְלוֹסִין דִּילֵיהּ, הֲווֹ אַזְלֵי בַּתְרַיְיהוּ, לְאוֹזְפָא לוֹן, עַד דְּנַפְקוּ מֵאַרְעָא דְּמִצְרַיִם. וְכֵן כָּל אִינּוּן רַבְרְבִין דִּמְמָנָן עָלֵיהוֹן, וְעַל שְׁאַר עַמִּין, אוֹזִיפוּ לָהּ לִשְׁכִינְתָּא וּלְיִשְׂרָאֵל כֻּלְּהוּ, עַד דְּשָׁארוּ בְּאֵיתָם בִּקְצֵה הַמִּדְבָּר, הֲדָא הוּא דִכְתִיב, וַיְהִי בְּשַׁלַּח פַּרְעֹה אֶת הָעָם וְגוֹ'. כִּי קָרוֹב הוּא, כִּי קָרוֹב הוּא. הַהוּא אוֹמָאָה דְּאוֹמֵי אֲבִימֶלֶךְ לַאֲבָהָן, עַל הַהוּא טִיבוּ דְּעָבְדוּ פְּלִשְׁתִּים לַאֲבָהָן, דִּכְתִּיב (בראשית כ״א:כ״ג) כַּחֶסֶד אֲשֶׁר עָשִׂיתִי עִמְּךָ תַּעֲשֶׂה עִמָּדִי וְעִם הָאָרֶץ אֲשֶׁר גַּרְתָּה בָּהּ.</p>"],[9520011601,"<p>וַיְהִי בְּשַׁלַּח פַּרְעֹה אֶת הָעָם, מַה כְּתִיב לְעֵילָּא, וַיָּקָם פַּרְעֹה לַיְלָה הוּא וְכָל עֲבָדָיו. תָּא חֲזֵי, נוּקְמָא עִלָּאָה דְּעָבַד קוּדְשָׁא בְּרִיךְ הוּא בְּמִצְרַיִם. תְּלַת מוֹתָנִי הֲווֹ. חַד, דְּעָבְדוּ בּוּכְרִין בְּמִצְרַיִם, דְּקָטִילוּ כָּל אִינּוּן דְּאַשְׁכָּחוּ. וְחַד, דְּקָטַל קוּדְשָׁא בְּרִיךְ הוּא בְּפַלְגוּת לֵילְיָא. וְחַד, כַּד חָמָא פַּרְעֹה מוֹתָנָא בְּבֵיתֵיהּ בִּבְנוֹי וּבְעַבְדוֹי, קָם וְזָרִיז גַּרְמֵיהּ, וְקָטִיל אֲפַרְכִין וְסַרְכִין, וְכָל דְּאַמְלִיכוּ לֵיהּ לְסָרְבָא בְּעַמָּא עַד דְּאוֹרַיְיתָא אַסְהִידַת עָלֵיהּ דְּאִיהוּ קָם בְּלֵילְיָא מַמָּשׁ. כְּמָה (דקודשא בריך הוא בפלגות) דְּלֵילְיָא קָטַל בּוּכְרִין וְעָבִיד נוּקְמִין, הָכִי קָם פַּרְעֹה בְּאַרְעָא דְּמִצְרַיִם, וְקָטַל וְעָבִיד נוּקְמִין בְּסַרְכוֹי, וְאָפַרְכוֹי, וַאֲמַרְכְּלוֹי, וּבְכָל אִינּוּן רַבְרְבִין <Nonei></i>הֲדָא הוּא דִכְתִיב, (שמות י״ב:ל׳) וַיָּקָם פַּרְעֹה (לילה ממש), דְּקָם לְקַטָלָא וּלְשֵׁיצָאָה.</p>\n<p>אוֹרְחוֹי דְּכַלְבָּא, כַּד מַחְיָין לֵיהּ בְּאַבְנָא, אִיהוּ אָתֵי וְנָשִׁיךְ לְחַבְרֵיהּ, כַּךְ פַּרְעֹה, לְבָתַר אִיהוּ הֲוָה אָזִיל בַּשְּׁוָקֵי, וַהֲוָה מַכְרִיז וְאָמַר, קוּמוּ צְּאוּ מִתּוֹךְ עַמִּי, אַתּוּן קָטַלְתּוּן לְכָל בְּנִי מָתָא, אַתּוּן קָטַלְתּוּן סַרְכֵי וְאָפַרְכֵי וְכָל בְּנֵי בֵּיתִי, הֲדָא הוּא דִכְתִיב וַיִּקְרָא לְמֹשֶׁה וּלְאַהֲרֹן לַיְלָה. כֵּיוָן דְּבִידְכוֹן הֲוָה כֹּלָּא, וּבֵרַכְתֶּם גַּם אוֹתִי, דְּלָא תִּקְטְלוּן לִי. לְבָתַר אִיהוּ בְּגַרְמֵיהּ אוֹזִיף לוֹן, וְאַפִּיק לוֹן מֵאַרְעָא, הֲדָא הוּא דִכְתִיב וַיְהִי בְּשַׁלַּח פַּרְעֹה אֶת הָעָם וְגוֹ'.</p>"],[9520011602,"<p>(שמות י״ג:י״ח) וַיַּסֵּב אֱלֹהִים אֶת הָעָם דֶּרֶךְ הַמִּדְבָּר יַם סוּף לְתַקְּנָא אָרְחָא לְאַתְרֵיהּ. ר' יְהוּדָה אָמַר, מַאי שְׁנָא כַּד הֲווֹ יִשְׂרָאֵל בְּמִצְרַיִם, דִּכְתִּיב, (שמות ה׳:א׳) שַׁלַּח אֶת עַמִּי, (שמות ט׳:ב׳) כִּי אִם מָאֵן אַתָּה לְשַׁלֵּחַ אֶת עַמִּי, (שמות ד) בְּנִי בְכוֹרִי יִשְׂרָאֵל, וּבְהַהוּא זִמְנָא לָא הֲווֹ גְּזִירִין, וְלָא אִתְקַשָּׁרוּ בֵּיהּ כְּדְקָא יֵאוֹת. וְהָכָא דַּהֲווֹ גְּזִירִין, וְעָבְדוּ פִּסְחָא, וְאִתְקַשָּׁרוּ בֵּיהּ, קָרֵי לוֹן אֶת הָעָם.</p>\n<p>אֶלָּא בְּגִין הַהוּא עֵרֶב רַב, דְּאִתְדְּבָקוּ בְּהוּ, וְאִתְעָרְבוּ בַּהֲדַיְיהוּ, קָרֵי לוֹן אֶת הָעָם סְתָם. כְּמָה דְאַתְּ אָמֵר, (שמות לכ) וַיִּגּוֹף יְיָ' אֶת הָעָם עַל אֲשֶׁר עָשׂוּ אֶת הָעֵגֶל. וַיִּקָּהֵל הָעָם עַל אַהֲרֹן. וַיַּרְא הָעָם כִּי בֹשֵׁשׁ מֹשֶׁה. וְכֵן כֻּלְּהוּ.</p>\n<p>ר' יִצְחָק ור' יְהוּדָה הֲווֹ אַזְלֵי מֵאוּשָׁא לְלוּד, וַהֲוָה עִמְּהוֹן יוֹסֵי טַיָּיעָא, בִּקְטִירָא דְּגַמָּלֵי עֲטוּפִירָא בְּכַתְפַיְיהוּ. עַד דַּהֲווֹ אַזְלֵי, אַשְׁכַּח הַהוּא יוֹסֵי טַיָּיעָא אִנְתּוּ חֲדָא דִּשְׁאַר עַמִּין, דְּקָטִיר בִּירוֹקֵי חַקְלָא, אִשְׁתְּמִיט מִנַּיְיהוּ וְאַתְקִיף בָּהּ, וְאָתָא עָלָּה. תַּוְוהוּ ר' יִצְחָק ור' יְהוּדָה, אָמְרוּ נֵיתוּב מֵאָרְחָא דָּא, דְּהָא קוּדְשָׁא בְּרִיךְ הוּא בָּעָא לְאַחְזָאָה לָן, דְּלָא נִתְחַבַּר בַּהֲדֵיהּ. תָּבוּ מֵאָרְחָא, בָּדְקוּ בַּתְרֵיהּ, וְאַשְׁכָּחוּ דִּבְרֵיהּ דְּבַת אֵל נִכָר הֲוָה, וַאֲבוּהָ פָּסִיל זַרְעָא הֲוָה. אָמְרוּ, בְּרִיךְ רַחֲמָנָא דְּשֵׁזִיב לָן.</p>\n<p>פָּתַח ר' יִצְחָק וְאָמַר (תהילים ל״ז:א׳) אַל תִּתְחַר בַּמְּרֵעִים. מַאן אִינּוּן מְרֵעִים, דְּלָא כְּתִיב חַטָּאִים, אוֹ רְשָׁעִים. אֶלָּא מְרִעִים, דְּאַבְאִישִׁין לְגַרְמַיְיהוּ, וּלְהָנִי דְּמִתְחַבְּרָן בַּהֲדַיְיהוּ. ר' יְהוּדָה אָמַר, מְרֵעִים: אַרְחֵיק גַּרְמָךְ מִמְּרֵעִים דְּלָא תֶּהווֹן רֵעִים וַחֲבֵרִים כַּחֲדָא, דְּלָא יַבְאִישׁוּ לָךְ עוֹבָדוֹי, וְתִתְפַּס בְּחֶטְאוֹי.</p>\n<p>תָּא חֲזֵי, אִי לָא הֲווֹ אִינּוּן עֵרֶב רַב דְּאִתְחַבְּרוּ בְּהוֹן יִשְׂרָאֵל, לָא אִתְעָבִיד הַהוּא עוֹבָדָא, וְלָא מִיתוּ מִיִּשְׂרָאֵל, כָּל אִינּוּן דְּמִיתוּ, וְלָא גָּרִים לוֹן לְיִשְׂרָאֵל כָּל מַה דְּגָרִים. וְתָּא חֲזֵי, הַהוּא עוֹבָדָא, וְהַהוּא חוֹבָה מַמָּשׁ, גָּרִים גָּלוּתְהוֹן דְּיִשְׂרָאֵל.</p>\n<p>דְּתָנֵינָן, בָּעָא קוּדְשָׁא בְּרִיךְ הוּא, דְּיִשְׁתַּכְּחוּן יִשְׂרָאֵל בְּהַהוּא שַׁעֲתָא כְּמַלְאֲכֵי עִלָּאֵי, וּלְמֶעְבַּד לוֹן חֵירִין מִכֹּלָּא, חֵירִין מִמּוֹתָא, וּלְמֶהֱוֵי חֵירִין מִן שִׁעְבּוּדָא דִּשְׁאַר עַמִּין, כְּמָה דְאַתְּ אָמֵר, (שמות ל״ב:ט״ז) חָרוּת עַל הַלּוּחוֹת, אַל תִּקְרֵי חָרוּת, אֶלָּא חֵירוּת.</p>\n<p>כֵּיוָן דְּאִתְעָבִיד הַהוּא עוֹבָדָא, גָּרִימוּ כֹּלָּא. גָּרִימוּ מוֹתָא, גָּרִימוּ שִׁעְבּוּד מַלְכְּוָון, גָּרִימוּ דְּאִתְּבָּרוּ אִינּוּן לוּחֵי קַדְמָאֵי, גָּרִימוּ דְּמִיתוּ מִיִּשְׂרָאֵל, כַּמָּה אַלְפִין מִנַּיְיהוּ. וְכָל דָּא, בְּגִין אִתְחַבְּרוּתָא דְּאִינּוּן עֵרֶב רַב, דְּאִתְחַבְּרוּ בְּהוּ.</p>\n<p>אוּף הָכָא, בְּגִינֵיהוֹן, לָא אִתְקְרוּן בְּנִי יִשְׂרָאֵל, וְלָא יִשְׂרָאֵל, וְלָא עַמִּי, אֶלָּא הָעָם סְתָם. וְאִי תֵּימָא וַחֲמוּשִׁים עָלוּ בְּנֵי יִשְׂרָאֵל. כַּד הֲווֹ סַלְּקִין מִמִּצְרַיִם, וְלָא אִתְחַבְּרוּ בַּהֲדַיְיהוּ אִינּוּן עֵרֶב רַב, קָרֵי לוֹן בְּנֵי יִשְׂרָאֵל, כֵּיוָן דְּאִתְחַבְּרוּ בַּהֲדַיְיהוּ, דִּכְתִּיב וְגַם עֵרֶב רַב עָלָה אִתָּם, קָרֵי לוֹן הָעָם.</p>\n<p>רִבִּי יוֹסֵי אַקְשֵׁי וְאָמַר, כְּתִיב כִּי אַשֶׁר רְאִיתֶם אֶת מִצְרַיִם הַיּוֹם לא תּוֹסִיפוּ לִרְאוֹתָם עוֹד עַד עוֹלָם. אִי הָכִי, כָּל יוֹמָא הֲווֹ חָמָאן לְהַהוּא עֵרֶב רַב. אָמַר רִבִּי יְהוּדָה, עֵרֶב רַב כְּתִיב, וְלֹא מִצְרַיִם, דְּהָא כַּמָּה שְׁאַר עַמִּין הֲווֹ דַּיְּירֵי בְּמִצְרַיִם. וְלֹא עוֹד אֶלָּא דְּכֻלְּהוּ אִתְגְּזָרוּ, וְכֵיוָן דְּאִתְגְּזָרוּ, לָא אִקְרוּן מִצְרָאֵי.</p>\n<p>וְעַל פּוּמָא דְּמֹשֶׁה קַבִּילוּ לוֹן. וְהַיְינוּ מַה <Nonei></i>דְּאָמַר הַכָּתוּב, (שמות ל״ב:ח׳) לֶךְ רֵד כִּי שִׁחֵת עַמְּךָ סָרוּ מַהֵר מִן הַדֶּרֶךְ אֲשֶׁר צִוִּיתִם. צִוִּיתָם כְּתִיב. וַחֲמֻשִׁים עָלוּ בְּנִי יִשְׂרָאֵל מֵאֶרֶץ מִצְרָיִם, חַד מֵחֲמִשָּׁה הֲווֹ. וְר' יוֹסֵי אוֹמֵר חֲמִשָּׁה מִיִּשְׂרָאֵל, וְחַד מִנַּיְיהוּ. רִבִּי יְהוּדָה אוֹמֵר, וַחֲמֻשִׁים: אֶחָד מֵחֲמִשִּׁים.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, בְּגִין (בראשית נ\"א ע\"ב) דְּהַהוּא יוֹבְלָא סָלִיק לוֹן מִמִּצְרַיִם, בְּגִין כָּךְ וַחֲמֻשִׁים עָלוּ בְּנֵי יִשְׂרָאֵל מֵאֶרֶץ מִצְרָיִם. וְאִי לָאו, לָא סְלִיקוּ, וְעַל דָּא אִתְעַכְּבוּ חַמְשִׁין יוֹמִין לְקַבְּלָא אוֹרַיְיתָא. וּמֵהַהוּא אֲתָר נַפְקַת אוֹרַיְיתָא, וְאִתְיְהִיבַת, וְעַל דָּא וַחֲמֻשִׁים חָסֵר. דִּבְגִין דָּא עָלוּ בְּנֵי יִשְׂרָאֵל מֵאֶרֶץ מִצְרָיִם.</p>\n<p>(שמות י״ג:י״ט) וַיִּקַּח מֹשֶׁה אֶת עַצְמוֹת יוֹסֵף וְגוֹ'. אֲמַאי סָלִיק גַּרְמוֹי. אֶלָּא, בְּגִין דְּהֲוָה רֵישָׁא לְנַחְתָּא לְגָלוּתָא. וְלֹא עוֹד, אֶלָּא דְּאִיהוּ סִימָנָא דִּגְאוּלָה הֲוָה לֵיהּ וְאוּמֵי לְהוּ לְיִשְׂרָאֵל עַל דָּא, הֲדָא הוּא דִכְתִיב כִּי הַשְׁבֵּעַ הִשְׁבִּיעַ אֶת בְּנֵי יִשְׂרָאֵל, וְהָא אִתְּמַר.</p>\n<p>זַכָּאָה חוּלָקָא דְּמֹשֶׁה, דְּיִשְׂרָאֵל הֲווֹ עַסְקֵי לְמִשְׁאַל מָמוֹנָא מִמִּצְרָאֵי, וּמֹשֶׁה הֲוָה עָסִיק בְּאוּמָאָה דְּיוֹסֵף. וְאִית דְּאַמְרֵי אֲרוֹנָא בְּנִילוּס הֲוָה, וּבִשְׁמָא קַדִּישָׁא סָלִיק לֵיהּ, וְעוֹד אָמַר מֹשֶׁה, יוֹסֵף, הִגִיעַ זְמַן פּוּרְקָנָא דְּיִשְׂרָאֵל, וְאָמַר עֲלֵה שׁוֹר. וְסָלִיק. וְאִית דְּאַמְרֵי, בֵּין מַלְכֵי מִצְרָאֵי הֲוָה, וּמִתַּמָּן סָלִיק (ס\"א ליה). וְאִית דְּאַמְרֵי, בְּגִין דְּלָא יַעַבְדוּן לֵיהּ עֲבוֹדָה זָרָה, שָׁווֹ בְּנִילוּס וְסֶרַח בַּת אָשֵׁר חַוִּיאַת לֵיהּ לְמֹשֶׁה.</p>"],[9520011603,"<p>(שמות י״ג:כ״א) וַיְיָ' הוֹלֵךְ לִפְנֵיהֶם יוֹמָם. רִבִּי יוֹסֵי פָּתַח, (תהילים כ״ב:א׳) לַמְנַצֵּחַ עַל אַיֶּלֶת הַשַּׁחַר מִזְמוֹר לְדָוִד. כַּמָּה חֲבִיבָא אוֹרַיְיתָא קָמֵיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא, דְּכָל מַאן דְּאִשְׁתָּדַּל בְּאוֹרַיְיתָא, רָחִים הוּא לְעֵילָּא, רָחִים הוּא לְתַתָּא, קוּדְשָׁא בְּרִיךְ הוּא אָצִית לֵיהּ לְמִלוּלוֹי, לָא שָׁבִיק לֵיהּ בְּהַאי עָלְמָא וְלָא שָׁבִיק לֵיהּ בְּעָלְמָא דְּאָתֵי.</p>\n<p>וְאוֹרַיְיתָא בָּעֵי לְמִלְעֵי בָּהּ בִּימָמָא וּבְלֵילְיָא, דִּכְתִּיב, (יהושע א׳:ח׳) וְהָגִיתָ בּוֹ יוֹמָם וָלַיְלָה. וּכְתִיב (ירמיהו ל״ג:כ״ה) אִם לֹא בְרִיתִי יוֹמָם וָלַיְלָה וְגוֹ'. תִּינַח בִּימָמָא, בְּלֵילְיָא אֲמַאי. בְּגִין דִּיְהֵא שְׁכִיחַ לְגַבֵּי שְׁמָא קַדִּישָׁא שְׁלִים. כְּמָה דְּלֵית יוֹמָם בְּלָא לֵילְיָא, וְלָאו אִיהוּ שְׁלִים, אֶלָּא דָּא עִם דָּא, כַּךְ בָּעֵי אוֹרַיְיתָא, לְאִשְׁתַּכְּחָא עִמֵּיהּ דְּבַּר נָשׁ יוֹמָא וְלֵילְיָא, לְמֶהֱוֵי שְׁלֵימוּתָא לְגַבֵּי דְּבַּר נָשׁ יוֹמָם וָלַיְלָה.</p>\n<p>וְהָא אִתְּמַר, דְעִקָרָא דְּלֵילְיָא, מִפַּלְגוּתָא וְאִילָךְ. וְאַף עַל גַּב דְּפָלְגוּ קַדְמִיתָא בִּכְלָלָא דְּלֵילְיָא הוּא, אֲבָל בְּפַלְגוּת לֵילְיָא, קוּדְשָׁא בְּרִיךְ הוּא עָאל בְּגִנְתָּא דְּעֵדֶן, לְאִשְׁתַּעְשְׁעָא עִם צַדִּיקַיָּא, וּכְדֵין, בָּעֵי לֵיהּ לְבַר נָשׁ לְמֵיקָם, וּלְמִלְעֵי בְּאוֹרַיְיתָא.</p>\n<p>וְהָא אִתְּמַר, דְּקוּדְשָׁא בְּרִיךְ הוּא וְכָל צַדִּיקַיָּא דִּבְגִּנְתָּא דְּעֵדֶן, כֻּלְּהוּ צַיְיתִין לְקָלֵּיהּ, הֲדָא הוּא דִכְתִיב, (שיר השירים ח׳:י״ג) הַיּוֹשֶׁבֶת בַּגַּנִּים חֲבֵרִים מַקְשִׁיבִים לְקוֹלֵךְ הַשְׁמִיעִנִי, וְהָא אוּקְמוּהָ, הַיּוֹשֶׁבֶת בַּגַּנִּים: דָּא כְּנֶסֶת יִשְׂרָאֵל, דְּאִיהִי מְשַׁבָּחַת לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא, בִּשְׁבָחָא דְּאוֹרַיְיתָא, בְּלֵילְיָא. זַכָּאָה חוּלָקֵיהּ, מַאן דְּאִשְׁתַּתַּף בַּהֲדָהּ, לְשַׁבְּחָא לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא, בִּשְׁבָחָא דְּאוֹרַיְיתָא.</p>\n<p>וְכַד אָתֵי צַפְרָא, כְּנֶסֶת יִשְׂרָאֵל אַתְיָא וּמִשְׁתַּעְשְׁעָא בֵּיהּ בְּקוּדְשָׁא בְּרִיךְ הוּא, וְאוֹשִׁיט לָהּ לְגַבָּהּ שַׁרְבִיטָא דְּחֶסֶד, וְלָא עַלָּה בִּלְחוֹדָהָא, אֶלָּא עַלָּה, וְעַל אִינּוּן דְּמִשְׁתַּתְּפִין בַּהֲדָהּ, וְהָא אִתְּמַר דִּכְתִּיב, (תהילים מ״ב:ט׳) יוֹמָם יְצַוְּה יְיָ' חַסְדּוֹ וּבַלַּיְלָה וְגוֹ'. וְעַל דָּא אַיֶּלֶת הַשַּׁחַר אִקְרֵי.</p>\n<p>וְאָמַר רַבִּי שִׁמְעוֹן, בְּשַׁעֲתָא דְּבָעֵי לְאִתְנַהֲרָא צַפְרָא, אִתְחֲשָׁךְ וְאִתְקַדַּר נְהוֹרָא, וְקַדְרוּתָא אִשְׁתְּכַח. כְּדֵין אִתְחַבְּרַת אִתְּתָא בְּבַעְלָהּ, דְּתָנֵינָן, אִשָּׁה מְסַפֶּרֶת עִם בַּעְלָהּ, לְמִשְׁתָּעֵי בַּהֲדֵיהּ, וְעָאלַת לְהֵיכְלֵיהּ.</p>\n<p>לְבָתַר כַּד בָּעֵי שִׁמְשָׁא לְמֵיעַל, אִתְנְהִיר וְאָתַת לֵילְיָא, וְנָטִיל לֵיהּ. כְּדֵין כָּל תַּרְעִין סְתִימִין, וְחַמְרִין נַעֲרִין, וְכַלְבִּין נַבְחִין, כַּד אִתְפְּלַג לֵילְיָא, שָׁאֲרִי מַלְכָּא (למקרי) לְמֵיקָם, וּמַטְרוֹנִיתָא לְזַמְּרָא, וְאָתֵי מַלְכָּא וְאָקִישׁ לְתַרְעָא דְּהֵיכְלָא, וְאָמַר (שיר השירים ה׳:ב׳) פִּתְחִי לִי אֲחוֹתִי רַעְיָתִי וְגוֹ'. וּכְדֵין מִשְׁתַּעֲשָׁע בְּנִשְׁמַתְהוֹן דְּצַדִּיקַיָּא.</p>\n<p>זַכָּאָה חוּלָקֵיהּ דְּהַהוּא, דְּאִתְּעַר הַהוּא זִמְנָא בְּמִלֵּי דְּאוֹרַיְיתָא, בְּגִין דָּא, כָּל אִינּוּן דִּבְנֵי הֵיכְלָא דְּמַטְרוֹנִיתָא, כֻּלְּהוּ בַּעְיָין לְמֵיקָם בְּהַהוּא זִמְנָא, לְשַׁבְּחָא לְמַלְכָּא וְכֻלְּהוּ מְשַׁבְּחָן קָמֵיהּ, וּשְׁבָחָא דְּסָלִיק מֵהַאי עָלְמָא, דָּא דְּאִיהוּ רָחִיק, (יתיר) דָּא נִיחָא לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא מִכֹּלָּא.</p>\n<p>כַּד אִסְתְּלִיק לֵילְיָא, וְאָתֵי צַפְרָא, (נ\"א ואיתחשיך) וְאִתְקָדַּר, כְּדֵין מַלְכָּא וּמַטְרוֹנִיתָא בְּרָזָא בְּחֶדְוָה, וְיָהִיב לָהּ מַתְּנָן, וּלְכָל בְּנֵי הֵיכְלָהּ. זַכָּאָה חוּלָקֵיהּ מַאן דְּאִיהוּ בְּמִנְיָינָא.</p>\n<p>וַיְיָ' הוֹלֵךְ לִפְנֵיהֶם יוֹמָם. קוּדְשָׁא בְּרִיךְ הוּא, וּבֵית דִּינֵיהּ. <Nonei></i>אָמַר רִבִּי יִצְחָק, הַיְינוּ דְּתָנֵינָן, שְׁכִינְתָּא בַּאֲבָהָתָא נַטְלָא. הוֹלֵךְ לִפְנֵיהֶם יוֹמָם: דָּא אַבְרָהָם. בְּעַמּוּד עָנָן: דָּא יִצְחָק. לַנְחוֹתָם הַדֶּרֶךְ: דָּא יַעֲקֹב. דִּכְתִּיב בֵּיהּ (בראשית ל״ב:ב׳) וְיַעֲקֹב הָלַךְ לְדַרְכּוֹ. וְלַיְלָה בְּעַמּוּד אֵשׁ לְהָאִיר לָהֶם: דָּא דָּוִד מַלְכָּא.</p>\n<p>וְכֻלְּהוּ רְתִיכָא עִלָּאָה קַדִּישָׁא, לְמֵהַךְ יִשְׂרָאֵל בִּשְׁלִימוּתָא דְּכֹלָּא, בְּגִין דְּיֶחזוּן אֲבָהָן פּוּרְקָנָא (ס\"א דבינייהו) דִּלְהוֹן, דִּכְתִּיב, (בראשית מ״ו:ד׳) וְאָנֹכִי אֲעַלְךָ גַּם עָלה, עִם הַמֶּרְכָּבָה. וּכְתִיב וַיְיָ' הוֹלֵךְ וְגוֹ', לָלֶכֶת יוֹמָם וְלָיְלָה. וְכִי אֲמַאי הֲווֹ אַזְלֵי יוֹמָם וְלַיְלָה, יַהֲכוּן בִּימָמָא, וְלָא יַהֲכוּן בְּלֵילְיָא, כִּבְנִי אֱנָשָׁא דְּעַרְקִין, כֵּיוָן דְּקוּדְשָׁא בְּרִיךְ הוּא נָטִיר לוֹן, אֲמַאי אַזְלִין בִּימָמָא וּבְלֵילְיָא. אֶלָּא, לְאִשְׁתַּכְּחָא בְּהוּ שְׁלֵימוּתָא דְּכֹלָּא, דְּלֵית שְׁלִימוּ אֶלָּא יוֹם וְלַיְלָה.</p>\n<p>אָמַר רִבִּי אַבָּא, הָכִי אוֹקִימְנָא, וַיְיָ' הוֹלֵךְ לִפְנֵיהֶם יוֹמָם בְּעַמּוּד עָנָן: דָּא אַבְרָהָם. וְלַיְלָה בְּעַמּוּד אֵשׁ: דָּא יִצְחָק. וְאִי הָכִי יַעֲקֹב אָן הוּא. אֶלָּא בְּמִלָּה קַדְמָאָה אִתְּמַר, וְתַמָּן שָׁאֲרִי, כְּמָה דִּכְתִּיב וַיְיָ'.</p>\n<p>וְלַיְלָה בְּעַמּוּד אֵשׁ, הֲוָה נָהִיר, בְּסִטְרָא דָּא וּבְדָא. בְּגִין דְּיִרְדְּפוּן מִצְרָאֵי בַּתְרֵיהוֹן, לְאִתְיַיקְרָא שְׁמָא דְּקוּדְשָׁא בְּרִיךְ הוּא, בִּרְתִּיכוֹי וּפָרָשׁוֹי. בְּגִין לְמֵיזַל יְמָמָא וְלֵילְיָא, אַסְפָּקָלַרְיָא דְּנָהֲרָא, וּדְלָא נָהֲרָא. וְתוּ, בְּגִין לְאַטְעָאָה לְמִצְרָאֵי דְּיֵמְרוּן מִקְרֶה הוּא, דִּכְתִּיב, (ישעיהו י״ט:י״ג) נוֹאֲלוּ שָׂרֵי צוֹעַן, וּכְתִיב (ישעיה מה) מֵשִׁיב חֲכָמִים אָחוֹר, וְעַל דָּא אַזְלֵי בִּימָמָא וּבְלֵילְיָא.</p>\n<p>רִבִּי אַבָּא אָמַר, זַכָּאָה חוּלָקֵיהוֹן דְּיִשְׂרָאֵל, דְּקוּדְשָׁא בְּרִיךְ הוּא אַפִּיק לוֹן מִמִּצְרַיִם, לְמֶהֱוֵי חוּלָקֵיהּ וְאַחֲסַנְתֵּיהּ. וְתָּא חֲזֵי, בְּסִטְרָא דְּיוֹבְלָא, אִשְׁתְּכַח חֵירוּ לְיִשְׂרָאֵל. וְכֵן לְזִמְנָא דְּאָתֵי, דִּכְתִּיב, (ישעיהו כ״ז:י״ג) וְהָיָה בַּיּוֹם הַהוּא יִתָּקַע בְּשׁוֹפָר גָּדוֹל וְגוֹ'.</p>\n<p>וּבְגִין הַהוּא יוֹבְלָא עִלָּאָה, אִתְעַכְּבוּ חַמְשִׁין יוֹמִין, לְקַבְּלָא אוֹרַיְיתָא, וּלְמִקְרַב לְטוּרָא דְּסִינַי. וְכֵיוָן דְּאָזְלֵי בִּיְמָמָא, אָזְלֵי בְּלֵילְיָא, לְמֶהוֵי כֹּלָּא חַד יוֹמָא, בֵּין יְמָמָא וְלֵילְיָא, וְלָא אִשְׁתְּכַח פְּרִישׁוּ.</p>\n<p>וְלֹא עוֹד, אֶלָּא דְּכֻלְּהוּ בְּנַיְיחָא אַזְלִין, לִרְעוּתָא דְּנַפְשַׁיְיהוּ, בְּיוֹמָא דְּקַבִּילוּ אוֹרַיְיתָא, הֲווֹ חַמְשִׁין יוֹמִין שְׁלֵמִין, יוֹמֵי וְלֵילֵי כְּדְקָא יֵאוֹת, דְּלֵית יוֹם בְּלֹא לַיְלָה, וְלֵית לַיְלָה בְּלא יוֹם, וְלַיְלָה וְיוֹם אִקְרֵי יוֹם אֶחָד. וְכֵיוָן דְּאָזְלוּ חַמְשִׁין יוֹמִין שְׁלֵימִין, כְּדֵין (לקבל נ' דיובלא וכמה) שָׁארוּ עָלַיְיהוּ אִינּוּן נ' יוֹמִין דְּיוֹבְלָא, וּמִסִּטְרָא דְּיוֹבְלָא אִתְיְיהִיב לְהוּ אוֹרַיְיתָא, וּבְגִין כָּךְ אַזְלִין יוֹמָא וְלֵילְיָא.</p>\n<p>וְאָמַר רִבִּי אַבָּא, כְּתִיב (בראשית כ״ז:א׳) וַיְהִי כִּי זָקֵן יִצְחָק וַתִּכְהֶיןָ עֵינָיו, אֲמַאי. הָא אוֹקִימְנָא, מַאן דְּרָחִים לַחַיָּיבָא, הָכִי הוּא. וְתָּא חֲזֵי, בְּיִצְחָק אִתְכְּלִיל לֵילְיָא, וְלֵילְיָא לא בָּהִיר, וְעַל דָּא וַתִּכְהֶיןָ עֵינָיו, וְכֹלָּא חַד.</p>\n<p>ר' יִצְחָק פָּתַח וְאָמַר, (שמות י״ד:ה׳) וַיֻּגַּד לְמֶלֶךְ מִצְרַיִם כִּי בָּרַח הָעָם, וַיֻּגַּד, מַאן קָאָמַר לֵיהּ. אֶלָּא, הָא אוּקְמוּהָ. אֲבָל חַכְמוֹי וְחַרְשׁוֹי אִתְכְּנָשׁוּ לְגַבֵּיהּ, וְאוֹדְעוּהוּ כִּי בָּרַח הָעָם. וַאֲמַאי קַאמְרוּ דָּא. אֶלָּא חָמוּ בְּחָכְמְתָא דִּלְהוֹן, דַּהֲווֹ אַזְלֵי יְמָמָא וְלֵילְיָא, אָמְרוּ וַדַּאי עַרְקִין אִינּוּן. וְלא עוֹד אֶלָּא דְּחָמוּ דְּלָא הֲווֹ אַזְלֵי בְּאוֹרַח מֵישָׁר, כְּמָה דִּכְתִּיב וְיָּשׁוּבוּ וְיַּחֲנוּ לִפְנֵי פִּי הַחִירוֹת.</p>"],[9520011604,"<p>(שמות י״ד:ז׳) וַיִּקַּח שֵׁשׁ מֵאוֹת וְגוֹ'. שֵׁשׁ מֵאוֹת אֲמַאי. אָמַר רִבִּי יוֹסֵי, לָקֳבֵל מִנְיָינָא דְּיִשְׂרָאֵל, דִּכְתִּיב כְּשֵׁשׁ מֵאוֹת אֶלֶף רַגְלִי. בָּחוּר: לָקֳבֵל הַגְּבָרִים דְּאִינּוּן עִקָרָא דְּכָל יִשְׂרָאֵל. וְכָל רֶכֶב מִצְרָיִם: שְׁאַר רְתִיכִין, דְּאִינּוּן טְפָלִין לַאֲחוֹרֵי, (נ\"א לאחרנין) לָקֳבֵל הַטַּף דִּכְתִּיב לְבַד מִטָּף. וְכֹלָּא עָבִיד בְּעֵיטָא דְּחַרְשׁוֹי וְחַכְמוֹי. וְשָׁלִישִׁים עַל כֻּלּוֹ, כֹּלָּא בְּחָכְמְתָא, לָקֳבֵל דַּרְגִּין עִלָּאִין, תְּרֵין וְחָד. ר' יִצְחָק אָמַר, כְּתַרְגּוּמוֹ, וּמְזָרְזִין. זְרִיזִין הֲווֹ בְּכֹלָּא.</p>\n<p>וַיִּקַּח שֵׁשׁ מֵאוֹת רֶכֶב בָּחוּר. ר' חִיָּיא אָמַר, כְּתִיב (ישעיהו כ״ד:כ״א) יִפְקוֹד יְיָ' עַל צְבָא הַמָּרוֹם בַּמָּרוֹם וְעַל מַלְכֵי הָאֲדָמָה עַל הָאֲדָמָה. בְּזִמְנָא דְּקוּדְשָׁא בְּרִיךְ הוּא יָהִיב שֻׁלְטָנוּתָא לְרַבְרְבֵי עַמִּין לְעֵילָּא, יָהִיב לְהוּ לְעַמָּא דִּלְהוֹן לְתַתָּא. וּבְשַׁעֲתָא דְּנָחִית לוֹן מִדַּרְגֵּיהוֹן דִּלְעֵילָּא, נָחִית לוֹן לְעַמָּא לְתַתָּא, וַיִּקַּח שֵׁשׁ מֵאוֹת רֶכֶב בָּחוּר, הָא מְמָנָא דִּלְהוֹן, וְאוּקְמוּהָ, דְּדָבַר רְתִיכִין דִּשְׁאַר עַמִּין, וְכֻלְּהוּ נָפְלוּ בְּמַשְׁרִיתָא דְּסִיסְרָא לְבָתַר וְהַיְינוּ בָּחוּר (נ\"א ולבתר) וְכֹל רֶכֶב מִצְרָיִם.</p>\n<p>כְּתִיב (שיר השירים א׳:ט׳) לְסֻסָתִי בְּרִכְבֵי פַרְעֹה דִּמִּיתִיךְ רַעְיָתִי. תָּא חֲזֵי, כְּדוּגְמַת סוּסְיָא נוּקְבָּא, אִתְחָזֵי לְהוֹן לְסוּסֵיהוֹן דְּפַרְעֹה, וְאוּקְמוּהָ. אֶלָּא לְסוּסָּתִי בְּרִכְבֵי פַרְעֹה, <Nonei></i>תָּא חֲזֵי, פַּרְעֹה בְּשַׁעֲתָא דְּהֲוָה רָדִיף אֲבָתְרַיְיהוּ דְּיִשְׂרָאֵל, מַה עָבֵד, נָטַל סוּסְוָון נוּקְבָן, וְכָפַת לוֹן בִּרְתִּיכוֹי בְּקַדְמִיתָא, וְסוּסִין דּוּכְרָאֵי כָּפַת לוֹן לַאֲחוֹרֵיהוֹן, וַהֲווּ מְזַיְּינִין דּוּכְרֵי לָקֳבֵל נוּקְבֵי, וְנוּקְבֵי לָא בָּעָאן, וְאוֹחָן לְמֵיזָל. כֵּיוָן דְּקָרִיב (נ\"א וכד אדביק) לְגַבַּיְיהוּ דְּיִשְׂרָאֵל, נָטַל נוּקְבֵי וְשַׁוֵּי לוֹן לַאֲחוֹרֵי, וְסוּסְוָון דּוּכְרִין לְקַדְמִין, לְאַבְאָשָׁא לְיִשְׂרָאֵל, וּלְאַגָּחָא בְּהוּ קְרָבָא.</p>\n<p>כְּגַוְונָא דָּא, וַיְיָ' הוֹלֵךְ לִפְנֵיהֶם יוֹמָם, וּבָתַר חָזְרָה שְׁכִינְתָּא לַאֲחוֹרֵיהוֹן דְּיִשְׂרָאֵל, דִּכְתִּיב וַיִּסַּע מַלְאַךְ הָאֱלהִים וְגוֹ'. בְּגִינֵי כַּךְ דִּמִּיתִיךְ רַעְיָתִי.</p>"],[9520011605,"<p>(שמות י״ד:י׳) וּפַרְעֹה הִקְרִיב, וְהַאי קְרָא הָא אוּקְמוּהָ. דְּאַקְרִיב לְכָל חֵילוֹי וּרְתִיכוֹי, לְאַגָּחָא קְרָבָא. וְתוּ וּפַרְעֹה הִקְרִיב. רִבִּי יוֹסֵי אָמַר, הָא אִתְּמַר דְּקָרִיב לוֹן לִתְשׁוּבָה. וּפַרְעֹה הִקְרִיב.</p>\n<p>כְּתִיב (ישעיהו כ״ו:ט״ז) יְיָ' בַּצַּר פְּקָדוּךָ צָקוּן לַחַשׁ וְגוֹ'. בַּצַּר פְּקָדוּךָ: לָא פַּקְדִין יִשְׂרָאֵל לְקוּדְשָׁא בְּרִיךְ הוּא, בְּשַׁעֲתָא דְּנַיְיחָא, אֶלָּא בְּשַׁעֲתָא דְּעָקִין לְהוּ, וּכְדֵין כֻּלְּהוּ פַּקְדִין לֵיהּ. צָקוּן לַחַשׁ: וְכֻלְּהוּ צַלָּאן בִּצְלוֹתִין וּבְבָעוּתִין, וְאָרִיקוּ קָמֵיהּ צְלוֹתִין. אֵימָתַי. (ישעיהו כ״ו:ט״ז) מוּסָרְךָ לָמוֹ, בְּשַׁעֲתָא דְּפָקִיד לוֹן קוּדְשָׁא בְּרִיךְ הוּא בִּרְצוּעוֹי. כְּדֵין קוּדְשָׁא בְּרִיךְ הוּא קָאִים עָלַיְיהוּ בְּרַחֲמֵי, וְנִיחָא קָמֵיהּ הַהוּא קָלָא דִּלְהוֹן, בְּגִין לְאִתְפָּרְעָא מִן שַׂנְאֵיהוֹן, וְאִתְמְלֵי עָלַיְיהוּ בְּרַחֲמֵי.</p>\n<p>כְּמָה דְּאוֹקִימְנָא, מְתָל לְיוֹנָה עִם הַנִּץ וְכוּ', כַּךְ יִשְׂרָאֵל הֲווֹ קְרִיבִין לְיַמָּא, וַהֲווּ חָמָאן לְיַמָּא קָמַיְיהוּ, אָזִיל וְסָעִיר וְגַלְגַּלּוֹהִי זַקְפִין לְעֵילָּא, הֲווֹ דְּחִילִין. זָקְפוּ עֵינַיְיהוּ וְחָמוּ לְפַרְעֹה וּלְמַשִׁירְיָיתֵיהּ, וְאַבְנֵי גִּירִין וּבַלִּסְטְרָאִין, כְּדֵין וַיִּירְאוּ מְאֹד. מַה עָבְדוּ, וַיִּצְעֲקוּ בְּנֵי יִשְׂרָאֵל מַאן גָּרִים הַאי דְּקָרִיבוּ יִשְׂרָאֵל לְגַבֵּי אֲבוּהוֹן דִּלְעֵילָּא, פַּרְעֹה. הֲדָא הוּא דִּכְתִּיב וּפַרְעֹה הִקְרִיב וְהָא אִתְּמַר.</p>\n<p>(שמות י״ד:י״ג) וַיֹּאמֶר מֹשֶׁה אֶל הָעָם אַל תִּירָאוּ הִתְיַצְּבוּ וּרְאוּ אֶת יְשׁוּעַת יְיָ'. אָמַר רִבִּי שִׁמְעוֹן זַכָּאָה חוּלָקֵיהוֹן דְּיִשְׂרָאֵל, דְּהָא רַעְיָא כְּמֹּשֶׁה אָזִיל בְּגַוַּויְיהוּ. כְּתִיב (ישעיהו ס״ג:י״א) וַיִּזְכּוֹר יְמֵי עוֹלָם מֹשֶׁה עַמּוֹ. וַיִּזְכּוֹר יְמֵי עוֹלָם: דָּא קוּדְשָׁא בְּרִיךְ הוּא. מֹשֶׁה עַמּוֹ (מכאן שלי הוא) שָׁקִיל הֲוָה מֹשֶׁה כְּכָל יִשְׂרָאֵל. וְאוֹלִיפְנָא מֵהָא, כִּי רַעְיָא דְּעַמָּא הוּא מַמָּשׁ עַמָּא כֻּלְּהוּ, אִי אִיהוּ זָכֵי, עַמָּא כֻּלְּהוּ זָכָאן. וְאִי אִיהוּ לָא זָכֵי, עַמָּא כֻּלְּהוּ לָא זָכָאן וְאִתְעֲנָשׁוּ בְּגִינֵיהּ, וְהָא אוּקְמוּהָ.</p>\n<p>הִתְיַצְּבוּ וּרְאוּ, לֵית לְכוּ לְאַגָּחָא קְרָבָא, דְּהָא קוּדְשָׁא בְּרִיךְ הוּא, יַגִּיחַ קְרָבָא בְּגִינֵיכוֹן, כְּמָה דְּאַתְּ אָמֵר, יְיָ' יִלָּחֵם לָכֶם וְאַתֶּם תַּחֲרִישׁוּן. תָּא חֲזֵי, הַהוּא לֵילְיָא, כָּנַשׁ קוּדְשָׁא בְּרִיךְ הוּא לְפָּמַלְיָא דִּילֵיהּ, וְדָאִין דִּינַיְיהוּ דְּיִשְׂרָאֵל, וְאִלְמָלֵא דְּאַקְדִּימוּ אֲבָהָן עָלַיְיהוּ דְּיִשְׂרָאֵל, לָא אִשְׁתֵּזִיבוּ מִן דִּינָא. רִבִּי יְהוּדָה אָמַר, זְכוּתָא דְּיַעֲקֹב אַגִּין עָלַיְיהוּ דְּיִשְׂרָאֵל, הֲדָא הוּא דִכְתִיב, (תהילים קכ״ד:א׳) לוּלֵי יְיָ' שֶׁהָיָה לָנוּ יֹאמַר נָא יִשְׂרָאֵל, יִשְׂרָאֵל סָבָא.</p>"],[9520011606,"<p>(שמות י״ד:י״ד) יְיָ יִלָּחֵם לָכֶם וְאַתֶּם תַּחֲרִישׁוּן. רִבִּי אַבָּא פָּתַח (ישעיהו נ״ח:י״ג) אִם תָּשִׁיב מִשַּׁבָּת רַגְלֶיךָ עֲשׂוֹת חֲפָצֶיךָ בְּיוֹם קָדְשִׁי. זַכָּאִין אִינּוּן יִשְׂרָאֵל, דְּקוּדְשָׁא בְּרִיךְ הוּא אִתְרָעֵי בְּהוֹן, לְאִתְדַּבְּקָא בְּהוּ, מִכָּל שְׁאַר עַמִּין דְּעָלְמָא, וּמִגּוֹ רְחִימוּתָא דִּלְהוֹן, קָרִיב לוֹן לְגַבֵּיהּ, וְיָהַב לוֹן אוֹרַיְיתָא, וְיָהַב לוֹן שַׁבָּת, דְּאִיהוּ קַדִּישָׁא מִכָּל שְׁאַר יוֹמִין, וְנַיְיחָא מִכֹּלָּא, וְחֶדְוָה דְּכֹלָּא, וְשָׁקִיל שַׁבָּת, לָקֳבֵל אוֹרַיְיתָא כְּלָּא, וּמַאן דְּנָטִיר שַׁבָּת, כְּאִילּוּ נָטִיר אוֹרַיְיתָא כֻּלָּא.</p>\n<p>וְקָרָאתָ לַשַּׁבָּת עוֹנֶג, עִנּוּגָא דְּכֹלָּא, עִנּוּגָא דְּנַפְשָׁא וְגוּפָא עִנּוּגָא דְּעִלָּאִין וְתַתָּאִין. וְקָרָאתָ לַשַּׁבָּת, מַאי וְקָרָאתָ. דְּיַזְמִין לֵיהּ. כְּמָה דְאַתְּ אָמֵר, (ויקרא כ״ג:ב׳) מִקְרָאֵי קֹדֶשׁ, כְּלוֹמַר, זְמִינִין, כְּמָה דִּמְזַמִּין אוּשְׁפִּיזָא לְבֵיתֵיהּ. וְעַל דָּא וְקָרָאתָ לַשַּׁבָּת עֹנֶג, דְּיַזְמִין לֵיהּ, כְּמָה דִּמְזַמְנִין אוּשְׁפִּיזָא, בְּפָתוֹרָא מְתַקְּנָא, בְּבֵיתָא מְתַקְּנָא כְּדְקָא יֵאוֹת, בְּמֵיכְלָא וּבְמִשְׁתְּיָא כְּדְקָא יֵאוֹת, יַתִּיר עַל שְׁאַר יוֹמִין. וְקָרָאתָ לַשַּׁבָּת מִבְּעוֹד יוֹם. (אמור כ\"ב ע\"א) לִקְדוֹשׁ יְיָ' מְכוּבָּד: דָּא יוֹם כִּפּוּרִים. תְּרֵי דְּאִינּוּן חַד. וְכִבַּדְתּוֹ מֵעֲשׂוֹת <Nonei></i>דְּרָכֶיךָ, כְּמָה דְּאוֹקִימְנָא.</p>\n<p>מִמְּצוֹא חֶפְצְךָ וְדַבֵּר דָּבָר, וְהָא אִתְּמַר, בְּגִין דְּהַהִיא מִלָּה סַלְּקָא, וְאִתְּעַר מִלָּה דְּחוֹל לְעֵילָּא. מַאן דִּמְזַמִּין אוּשְׁפִּיזָא, בֵּיהּ בָּעֵי לְאִשְׁתַּדְּלָא, וְלָא בָּאָחֳרָא.</p>\n<p>תָּא חֲזִיִ הַהוּא מִלָּה דְּנָפִיק מִפּוּמֵיהּ דְּבַר נָשׁ, סַלְּקָא וְאִתְּעַר אִתְעָרוּתָא לְעֵילָּא, אִי לְטָב, אִי לְבִישׁ. וּמַאן דְּיָתִיב בְּעִנּוּגָא דְּשַׁבְּתָא, אָסִיר לֵיהּ לְאִתְּעָרָא מִלָּה (מ\"ג ב') דְּחוֹל, דְּהָא פָּגִים פְּגִימוּ בְּיוֹמָא קַדִּישָׁא. מַאן דְּיָתִיב בְּהִילּוּלָא דְּמַלְכָּא, לָא יִתְחָזֵי לְמִשְׁבַּק לְמַלְכָּא, וְיִתְעַסֵּק בְּאַחֲרָא.</p>\n<p>וּבְכָל יוֹמָא בָּעֵי לְאַחֲזָאָה עוֹבָדָא, וּלְאִתְעֲרָא אַתְעָרוּתָא מִמָּה דְּאִצְטְרִיךְ. וּבְשַׁבָּת, בְּמִלֵּי דִּשְׁמַיָּא, וּבִקְדוּשָּׁה דְּיוֹמָא בָּעֵי לְאִתְּעָרָא, וְלָא בְּמִלָּה אַחֲרָא.</p>\n<p>תָּא חֲזֵי, הָכָא כַּד אִתְקְרִיב פַּרְעֹה לְאַגָּחָא קְרָבָא בְּהוּ בְּיִשְׂרָאֵל, בְּהַהִיא זִמְנָא, לָא בָּעֵי קוּדְשָׁא בְּרִיךְ הוּא, דְּיִתְּעֲרוּן יִשְׂרָאֵל אִתְעָרוּתָא לְתַתָּא כְּלָל, דְּהָא אִתְעָרוּתָא לְעֵילָּא הוּא, דְּהָא אֲבָהָן אַקְדִּימוּ וְאַתְּעֲרוּ אִתְעָרוּתָא דָּא לְעֵילָּא, וּזְכוּתָא דִּלְהוֹן קָאִים קָמֵיהּ, (ואתערו אתערותא דא) וְלָא בָּעָא קוּדְשָׁא בְּרִיךְ הוּא דְּיִשְׂרָאֵל יִתְּעָרוּן לְתַתָּא כְּלָל. (דהא באתרה לעילא הוה) הֲדָא הוּא דִּכְתִּיב יְיָ' יִלָּחֵם לָכֶם וְאַתֶּם תַּחֲרִישׁוּן. תַּחֲרִישׁוּן וַדַּאי, וְלָא תִּתְעֲרוּן מִלָּה, דְּלָא אִצְטְרִיךְ לְכוּ, וְהָכָא אִתְכְּלִיל שְׁמָא קַדִּישָׁא בְּאַתְוָון רְשִׁימָן, וְהָא אִתְעֲרוּ בֵּיהּ חַבְרַיָּיא.</p>\n<p>רִבִּי יוֹסֵי וְרִבִּי יְהוּדָה הֲווֹ אַזְלֵי בְּאָרְחָא. אָמַר רִבִּי יוֹסֵי לְרִבִּי יְהוּדָה, וַדַּאי תָּנִּינָא, יְיָ', בְּכָל אֲתָר רַחֲמֵי, וְאַף עַל גַּב דְּאַגָּח קְרָבָא, וְעָבִיד דִּינָא, הַהוּא דִּינָא בִּרְחִימוּתָא הוּא. וְהָכָא חֲמֵינָא, דִּכְתִּיב יְיָ' יִלָּחֵם לָכֶם, וְלָא אִתְחָזֵי בְּהַהוּא דִּינָא רַחֲמֵי כְּלָל, דְּהָא כְּתִיב לא נִשְׁאַר בָּהֶם עַד אֶחָד.</p>\n<p>אָמַר לֵיהּ, מִלָּה דָּא שְׁמַעְנָא מֵרִבִּי שִׁמְעוֹן דְּאָמַר, דְּאֲפִילּוּ הָכָא דִּינָא בְּרַחֲמֵי הֲוָה, דְּחָפָא עָלֵיהוֹן יַמָּא וּמִיתוּ, וּלְבָתַר אַפִּיק לוֹן יַמָּא, וְקוּדְשָׁא בְּרִיךְ הוּא בָּעָא בִּיקָרֵיהוֹן, וְאִתְקְבָרוּ בְּאַרְעָא, וְלָא בָּעָאת אַרְעָא לְקַבְּלָא לוֹן, עַד דְּאוֹשִׁיט לָהּ קוּדְשָׁא בְּרִיךְ הוּא יְמִינֵיהּ, וְקַבִּילַת לוֹן, הֲדָא הוּא דִכְתִיב, (שמות ט״ו:י״ב) נָטִיתָ יְמִינְךָ תִּבְלָעֵמוֹ אָרֶץ. וּבְגִין דָּא, (הוה) הַאי דִּינָא בְּרַחֲמֵי הֲוָה.</p>\n<p>וְעַל דָּא, לָא בָּעָא קוּדְשָׁא בְּרִיךְ הוּא דְּיִתְּעָרוּן יִשְׂרָאֵל מִלָּה בְּעָלְמָא, דְּאִי יִתְעָרוּן יִשְׂרָאֵל מִלָּה, לָא יִתְעָרוּן שְׁמָא דְּרַחֲמֵי, וְלָא יִתְעֲבִיד דִּינָא בְּרַחֲמֵי, הֲדָא הוּא דִּכְתִּיב יְיָ' יִלָּחֵם לָכֶם וְאַתֶּם תַּחֲרִישׁוּן, דְּלָא תִּתְעֲרוּן מִידִי. דְּהָא שְׁמָא דְּרַחֲמֵי בָּעֵי לְאִתְּעָרָא עָלַיְיהוּ, לְמֶעְבַּד דִּינָא בְּרַחֲמֵי. וְעַל דָּא בָּעֵי, דְּלָא תַּעַבְדוּן פְּגִימוּ, וְתִתְעֲרוּן מִלָּה אַחֲרָא.</p>\n<p>אָמַר לֵיהּ, וְהָא כְּתִיב, (זכריה י״ד:ג׳) וְיָצָא יְיָ' וְנִלְחַם בַּגּוֹיִם הָהֵם. אִי הָכִי דָּא דִּינָא בְּרַחֲמֵי הֲוָה. אָמַר לֵיהּ, הָכִי הֲוָה וַדַּאי, דִּינָא הוּא בְּרַחֲמֵי, דְּמוֹתָא דִּלְהוֹן לָא אִשְׁתְּכַח כְּמוֹתָנָא דִּשְׁאַר בְּנֵי עָלְמָא, אֶלָּא חָס עָלַיְיהוּ קוּדְשָׁא בְּרִיךְ הוּא, דְּלָא יְהוֹן כְּמוֹתָנָא דִּשְׁאַר בְּנֵי עָלְמָא, דְּקָטִילוּ לוֹן, אֶלָּא בְּנַחַת בְּלא צַעֲרָא, הָא דִּינָא בְּרַחֲמֵי אִיהוּ.</p>\n<p>וּבְכָל אֲתָר, שְׁמָא דָּא, דִּינָא בְּרַחֲמֵי אִיהוּ, בַּר אֲתָר חַד, דִּכְתִּיב, (ישעיהו מ״ב:י״ג) יְיָ' כַּגִבּוֹר יֵצֵא וְגוֹ'. וְכִי כַּגִבּוֹר וְלֹא גִּבּוֹר. אֶלָּא יְשַׁנֵּי לְבוּשׁוֹי, וְיִלְבַּשׁ לְבוּשִׁין אַחֲרָנִין. כְּאִישׁ מִלְחָמוֹת, יְשַׁנֵּי זִינֵיהּ.</p>\n<p>וְעִם כָּל דָּא, דִּינָא הוּא יַתִּיר, אֲבָל רַחֲמֵי בֵּיהּ, כְּמָה דִּכְתִּיב, כַּגִבּוֹר, וְלֹא גִּבּוֹר. כְּאִישׁ מִלְחָמוֹת, וְלֹא אִישׁ מִלְחָמוֹת. דְּוַדַּאי אַף עַל גַּב דְּעָבִיד דִּינָא, חָס עַל עוֹבָדוֹי, וְעַל דָּא, יְיָ' יִלָּחֵם לָכֶם וַדַּאי וְאַתֶּם תַּחֲרִישׁוּן. זַכָּאָה חוּלָקֵיהוֹן דְּיִשְׂרָאֵל, דְּקוּדְשָׁא בְּרִיךְ הוּא בָּרִיר לוֹן לְחוּלָקֵיהּ וְאַחֲסָנְתֵּיהּ, דִּכְתִּיב, (דברים ל״ב:ט׳) כִּי חֵלֶק יְיָ' עַמּוֹ יַעֲקֹב חֶבֶל נַחֲלָתוֹ.</p>"],[9520011607,"<p>(שמות י״ד:ט״ו) וַיֹּאמֶר (קע\"ח ע\"ב) יְיָ' אֶל מֹשֶׁה מַה תִּצְעַק אֵלָי. מִלָּה דָּא הָא אוּקְמוּהָ בְּסִפְרָא דִּצְנִיעוּתָא, וְתַמָּן הוּא רָזָא דִּילֵיהּ, וַיֹּאמֶר יְיָ' אֶל מֹשֶׁה. ר' יְהוּדָה פָּתַח וְאָמַר, (יונה ב׳:ב׳) וַיִּתְפַּלֵּל יוֹנָה אֶל יְיָ' אֱלֹהָיו מִמְּעֵי הַדָּגָה, מַה כְּתִיב לְעֵילָּא, וַיְמַן יְיָ' דָּג גָּדוֹל. וַיְמַן: כְּמָה דְאַתְּ אָמֵר (דניאל א׳:ה׳) וַיְמַן לָהֶם הַמֶּלֶךְ דְּבַר יוֹם בְּיוֹמוֹ. אֲשֶׁר מִנָּהּ אֶת מַאֲכַלְכֶם.</p>\n<p>אֲבָל הַאי קְרָא הָכִי <Nonei></i>מִבָּעֵי לֵיהּ, וַיְמַן יְיָ' אֶת יוֹנָה לַדָּג, דְּהוּא מָנָה הוּא דִּמְשַׁדֵּר לֵיהּ. אֶלָּא וַדַּאי, הַהוּא דָּג הוּא הֲוָה מָנָה לְיוֹנָה, לְנַטְרָא לֵיהּ מִן שְׁאַר נוּנִי יַמָּא, וְיֶהוֵי גָּנִיז בְּגַוֵּיהּ. וְכֵיוָן דְּאַעֲלֵיהּ בְּגַוֵּיהּ, חָמָא יוֹנָה בְּמֵעוֹי, פּוּתְיָא דַּאֲתָר יַמָּא (נ\"א פותיא דאתר דמעוי) כְּמוֹ הֵיכְלָא רַבְרְבָא, וּתְרֵין עֵינוֹי דְּהַהוּא נוּנָא, דְּנָהֲרִין כְּשִׁמְשָׁא, וְאֶבֶן טָבָא הֲוָה בְּמֵעוֹי, דְּנָהִיר לֵיהּ, וַהֲוָה חָמֵי כָּל מַה דִּי בְּיַמָּא וּבִתְהוֹמוֹי.</p>\n<p>וְאִי תֵּימָא, אִי הָכִי, מַאי דִּכְתִּיב, (יונה ב׳:ג׳) קָרָאתִי מִצָּרָה לִי, הָא לָא אִתְחָזֵי, דְּכָל הַאי רְוָוחָא הֲוָה לֵיהּ. אֶלָּא וַדַּאי, כֵּיוָן דְּאַחְמֵי לֵיהּ הַהוּא נוּנָא, כָּל מַה דִּי בְּיַמָּא וּבִתְהוֹמוֹי, מִית, דְּלָא יָכִיל תְּלַת יוֹמִין לְמִסְבַּל. כְּדֵין עָקַת לֵיהּ לְיוֹנָה.</p>\n<p>דְּאָמַר רִבִּי אֶלְעָזָר, כֵּיוָן דְּחָמָא יוֹנָה כָּל הַהוּא רְוָוחָא, הֲוָה חַדֵּי. אָמַר קוּדְשָׁא בְּרִיךְ הוּא, וּמַה תִּבְעֵי יַתִּיר, לְהָא אֲעִילְנָא לָךְ הָכָא. מָה עֲבַד, קָטַל לְהַהוּא נוּנָא וּמִית, וְכָל שְׁאַר נוּנֵי יַמָּא, הֲווֹ סַחֲרֵי סַחֲרָנִיהּ דְּהַהוּא נוּנָא, דָּא נָשִׁיךְ לֵיהּ מֵהַאי גִּיסָא, וְדָא נָשִׁיךְ לֵיהּ מֵהַאי גִּיסָא. כְּדֵין חָמָא יוֹנָה גַּרְמוֹי בְּעָקוּ, מִיַּד וַיִּתְפַּלֵּל יוֹנָה אֶל יְיָ'.</p>\n<p>בְּקַדְמִיתָא דָּג, וְהַשְׁתָּא דָּגָה. כְּמָה דְאַתְּ אָמֵר, (שמות ז׳:כ״א) וְהַדָּגָה אֲשֶׁר בַּיְאוֹר מֵתָה. וּכְדֵין כְּתִיב, קָרָאתִי מִצָּרָה לִי. וְלָא כְּתִיב הָיִיתִי בַּצָּרָה, אוֹ יָשַׁבְתִּי בַּצָּרָה, אֶלָּא קָרָאתִי, מֵהַהוּא עָקוּ דְּעָאקִין לִי נוּנִי יַמָּא. מִבֶּטֶן שְׁאוֹל שִׁוַּעְתִּי, דְּהָא מִית. וְלָא כְּתִיב מִבֶּטֶן חַי, אוֹ מִבֶּטֶן דָּג, אֶלָּא דְּוַדַּאי הֲוָה מִית.</p>\n<p>כֵּיוָן דְּצַלֵּי צְלוֹתֵיהּ, קַבִּיל לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, וְאַחְיֵיהּ לֵיהּ לְהַאי נוּנָא, וְאַפִּיק לֵיהּ לְיַבֶּשְׁתָּא לְעֵינֵיהוֹן דְּכֹלָּא. דִּכְתִּיב, וַיֹּאמֶר יְיָ' לַדָּג וַיָּקֵא אֶת יוֹנָה. וְחָמוּ כֻּלְּהוּ, עֲבִידְתָּא דְּקוּדְשָׁא בְּרִיךְ הוּא.</p>\n<p>מַה כְּתִיב, וַיִּתְפַּלֵּל יוֹנָה אֶל יְיָ' אֱלֹהָיו מִמְּעֵי הַדָּגָה, לַאֲתָר דְּהֲוָה קָשִׁיר בֵּיהּ, מַשְׁמַע דִּכְתִּיב יְיָ' אֱלהָיו, וְלָא כְּתִיב וַיִּתְפַּלֵּל אֶל יְיָ' וְלָא יַתִּיר, אֶלָּא יְיָ' אֱלהָיו. אוּף הָכָא, וַיֹּאמֶר יְיָ' אֶל מֹשֶׁה מַה תִּצְעַק אֵלָי. אֵלָי דַּיְיקָא.</p>\n<p>דַּבֵּר אֶל בְּנֵי יִשְׂרָאֵל וְיִּסָעוּ. וְיִּסָעוּ מִלְּאַסְגָּאָה מִלִּין, לָאו עִידָנָא דִּצְלוֹתָא הַשְׁתָּא. וְיִּסָעוּ, וְכִי לְאָן אֲתָר פָּקִד לוֹן דְּיִנְטְלוּן, דְּהָא עַל יַמָּא הֲווֹ שָׁרָאן. אֶלָּא אַהְדָּר לְעֵילָּא, דִּכְתִּיב מַה תִּצְעַק אֵלָי, דְּהָא כֻּלְּהוּ בַּאֲתָר דָּא קַיְימֵי. וְעַל דָּא וַיִּסְעוּ, יִנְטְלוּן מִן דָּא, דְּלָאו עִדָנָא הוּא.</p>"],[9520011608,"<p>(ס\"א אלא בעתיקא תלייא מלתא) (שמות י״ד:ט״ז) וְאַתָּה הָרֵם אֶת מַטְּךָ וְגוֹ'. הָרֵם אֶת מַטְּךָ, דִּי בֵּיהּ רָשִׁים שְׁמָא קַדִּישָׁא, אַרְכִּין יְדָךְ בְּסִטְרָא דִּשְׁמָא קַדִּישָׁא, וְכֵיוָן דִּיֶחמוּן מַיָּא שְׁמָא קַדִּישָׁא, יָעַרְקוּן מִנֵּיהּ. וּמִקַמֵיה (נ\"א קמיה) וְעַל דָּא, וּנְטֵה אֶת יָדְךָ, לְסִטְרָא חֲדָא, דְּסִטְרִין אַחֲרָנִין דְּהַהוּא מַטֶּה, אִצְטְרִיךְ לָךְ לְמַיִּין (נ\"א ליה למלין) אַחֲרָנִין.</p>\n<p>אָמַר רִבִּי אֶלְעָזָר, חֲמֵינָא, דְּזִמְנִין אִתְקְרֵי הַאי מַטֶּה, מַטֵּה הָאֱלהִים, וּלְזִמְנִין אִתְקְרֵי מַטֵּה דְּמֹשֶׁה. אָמַר ר' שִׁמְעוֹן (תרי הוו והכי אוקימנא) בְּסִפְרָא דְּרַב הַמְנוּנָא סָבָא, שַׁפִּיר קָאָמַר, דְּכֻלְּהוּ חַד, בֵּין תֵּימָא דְּקוּדְשָׁא בְּרִיךְ הוּא, וּבֵין תֵּימָא דְּמֹשֶׁה, וְהַאי מַטֶה, לְאַתְעֲרָא סִטְרָא דִּגְבוּרָה. וְעַל דָּא, וּנְטֵה אֶת יָדְךָ, יְדָא דִּשְׂמָאלָא, דְּאִיהוּ בְּסִטְרָא דִּגְבוּרָה.</p>\n<p>אָמַר רִבִּי שִׁמְעוֹן, וַוי לְאִינוּן דְּלָא חָמָאן, וְלָא מִסְתַּכְּלִין בְּאוֹרַיְיתָא, וְאוֹרַיְיתָא קָארֵי קָמַיְיהוּ בְּכָל יוֹמָא, (ס\"א ולא ידעין) וְלָא מַשְׁגִּיחִין. תָּא חֲזֵי, בְּסִטְרָא דִּגְבוּרָה מִתְעָרֵי מַיָּא בְּעָלְמָא, וְנַפְקֵי מַיָּא, וְהַשְׁתָּא בָּעֵי קוּדְשָׁא בְּרִיךְ הוּא לְנַגְבָא מַיָּא, אֲמַאי וּנְטֵה אֶת יָדְךָ, דְּאִיהוּ שְׂמָאלָא.</p>\n<p>אֶלָּא הָרֵם אֶת מַטְּךָ, לְנַגְבָא מַיָּא. וּנְטֵה אֶת יָדְךָ, לְאָתָבָא מַיָּא, לְאַתְעֲרָא סִטְרָא דִּגְבוּרָה, וּלְאָתָבָא מַיָּא עַל מִצְרַיִם. וּבְגִין כַּךְ, תְּרֵין מִלִּין הָכָא, דִּכְתִּיב הָרֵם אֶת מַטְּךָ, וּנְטֵה אֶת יָדְךָ עַל הַיָּם וּבְקָעֵהוּ.</p>\n<p>וְהָא תְּהוֹמֵי הֲווֹ. אֶלָּא קוּדְשָׁא בְּרִיךְ הוּא, עָבֵד נִיסָא גּוֹ נִיסָא, כְּמָה דְאַתְּ אָמֵר (שמות ט״ו:ח׳) קָפְאוּ תְהוֹמוֹת בְּלֶב יָם. וַהֲוָה אַזְלִין בְּיַבֶּשְׁתָּא בְּגוֹ יַמָּא, הֲדָא הוּא דִכְתִיב וַיָּבֹאוּ בְּנֵי יִשְׂרָאֵל בְּתוֹךְ הַיָּם בַּיַּבָּשָׁה.</p>"],[9520011609,"<p><Nonei></i>(שמות י״ד:כ״ה) וַיָּסַר אֶת אוֹפַן מַרְכְּבוֹתָיו. רַבִּי שִׁמְעוֹן פָּתַח, (יחזקאל א׳:ט״ו) וָאֵרֶא הַחַיּוֹת וְהִנֵּה אוֹפַן אֶחָד בָּאָרֶץ אֵצֶל הַחַיּוֹת. הַאי קְרָא אוּקְמוּהָ וְאִתְּמַר, אֲבָל תָּא חֲזֵי, קוּדְשָׁא בְּרִיךְ הוּא בְּכוֹלָּא אִתְחָזֵי שֻׁלְטָנוּתָא דִּילֵיהּ, וְשֻׁלְטָנֵיהּ דִּי לָא תַּעְדֵּי לְעָלַם וּלְעָלְמֵי עָלְמִין.</p>\n<p>וְעָבִיד שׁוּלְטָנוּתָא בַּאֲבָהָן, נָטַל לְאַבְרָהָם, וְקִיֵּים בֵּיהּ עָלְמָא, דִּכְתִּיב, (בראשית ב׳:ד׳) אֵלֶּה תוֹלְדוֹת הַשָּׁמַיִם וְהָאָרֶץ בְּהִבָּרְאָם, וְאוּקְמוּהָ. נָטִיל יִצְחָק, וְשָׁתִיל בֵּיהּ עָלְמָא, דְּאִיהוּ קַיָּים לְעָלְמִין, הֲדָא הוּא דִכְתִיב, (בראשית י״ז:כ״א) וְאֶת בְּרִיתִי אָקִים אֶת יִצְחָק. נָטַל יַעֲקֹב, וְאוֹתְבֵיהּ קָמֵיהּ, וְאִשְׁתַּעֲשַׁע בַּהֲדֵיהּ, וְאִתְפָּאַר בֵּיהּ, הֲדָא הוּא דִכְתִיב, (ישעיהו מ״ט:ג׳) יִשְׂרָאֵל אֲשֶׁר בְּךָ אֶתְפָּאָר.</p>\n<p>וְתָּא חֲזֵי, יַעֲקֹב אָחִיד בְּאִילָנָא דְּחַיֵּי, דְּלֵית בֵּיהּ מוֹתָא לְעָלְמִין, דְּכָל חַיִּין בְּהַהוּא אִילָנָא אִשְׁתָּכְלָלוּ, וְיָהַב חַיִּין לְכָל אִינּוּן דַּאֲחִידָן בֵּיהּ. וּבְגִין כָּךְ, יַעֲקֹב לָא מִית. וְאֵימָתַי מִית, בְּשַׁעֲתָא דִּכְתִּיב, (בראשית מ״ט:ל״ג) וַיֶּאֱסוֹף רַגְלָיו אֶל הַמִּטָּה. הַמִּטָּה. כְּמָה דְאַתְּ אָמֵר (שיר השירים ג׳:ז׳) הִנֵּה מִטָּתוֹ שֶׁלִּשְׁלֹמֹה, בְּגִין דִּבְהַאי מִטָּה כְּתִיב, (משלי ה׳:ה׳) רַגְלֶיהָ יוֹרְדוֹת מָוְת, וּבְגִין כָּךְ וַיֶּאֱסוֹף רַגְלָיו אֶל הַמִּטָּה כְּתִיב, כְּדֵין וַיִּגְוַע וַיֵּאָסֶף אֶל עַמָּיו. וְעָבִיד קוּדְשָׁא בְּרִיךְ הוּא לְיַעֲקֹב שְׁלִימוּ דַּאֲבָהָן, הֲדָא הוּא דִכְתִיב, (ישעיהו מ״א:ח׳) יַעֲקֹב אֲשֶׁר בְּחַרְתִּיךָ.</p>\n<p>תָּא חֲזֵי, כָּל מַשִׁרְיָין דִּלְעֵילָּא, וְכָל אִינּוּן רְתִיכִין, כֻּלְּהוּ אֲחִידָן אִלֵּין בְּאִלֵּין, דַּרְגִּין בְּדַרְגִּין, אִלֵּין עִלָּאִין וְאִלֵּין תַּתָּאִין. וְחֵיוָותָא קַדִּישָׁא עָלַיְיהוּ, וְכֻלְּהוּ אוֹכְלוֹסִין וּמַשִׁרְיָין, כֻּלְּהוּ נַטְלִין תְּחוֹת יְדָהָא, עַל מֵימְרָהָא נַטְלִין, וְעַל מֵימְרָהָא שָׁרָאן.</p>\n<p>וְדָא הוּא חֵיוָתָא, (ס\"א עילא קדישא) דְּכָל שְׁאַר חֵיוָתָא, אֲחִידָן בָּהּ וְאִשְׁתַּלְשָׁלוּ (ס\"א ואשתכללו) בְּגִינָהּ כַּמָּה חֵיוָן לְחֵיוָן (ס\"א אלין סלקין ואלין נחתין) וְאִתְאַחֲדָן דַּרְגִּין בְּדַרְגִּין, וְכֻלְּהוּ עִלָּאִין וְתַתָּאִין אַזְלִין וְשָׁאטִין בְּיַמָּא, הֲדָא הוּא דִכְתִיב, (תהילים ק״ד:כ״ה) זֶה הַיָּם גָּדוֹל וּרְחַב יָדַיִם שָׁם רֶמֶשׂ וְאֵין מִסְפָּר וְגוֹ'.</p>\n<p>וְכַד סָלִיק יַמָּא גַּלְגַּלּוֹי, כֻּלְּהוּ אַרְבִּין סַלְּקִין נַחְתִּין, וְזַעְפָּא אִשְׁתְּכַח, וְרוּחָא תַּקִּיפָא אַזְלָא עָלֵיהּ בִּתְקִיפוּ. וְנוּנֵי יַמָּא מִתְבַּדְּרִין לְכָל סְטַר, אִלֵּין לְמִזְרָח, וְאִלֵּין לְמַעֲרָב, אִלֵּין לַצָּפוֹן, וְאִלֵּין לַדָּרוֹם. וְכָל אִינּוּן בְּנִי עָלְמָא, דְּחָמָאן רְשִׁימָא עָלַיְיהוּ, נַטְלִין לוֹן, וּבַלְעִין לוֹן בְּקַפְטִיִרִי עַפְרָא.</p>\n<p>וְכָל אַרְבִּין לָא נַטְלִין מֵאַתְרַיְיהוּ, וְלָא סַלְּקִין וְנַחְתִּין, בַּר מֵהַהוּא שַׁעֲתָא, דְּאָתֵי חַד דַּבְּרָא בְּיַמָּא, וְיָדַע לְאַשְׁלְמָא רוּחָא דְּזַעְפָּא דְּיַמָּא, כֵּיוָן דְּסָלִיק דָּא עָלֵיהּ דְּיַמָּא, שָׁכִיךְ מֵרוּגְזָא, וְנַיְיחָא אִשְׁתְּכַח, וּכְדֵין כֻּלְּהוּ אַרְבִּין אַזְלִין בְּאֹרַח מֵישָׁר, וְלָא סָטָאן לִימִינָא וּשְׂמָאלָא, הֲדָא הוּא דִכְתִיב, (תהילים ק״ד:כ״ו) שָׁם אֳנִיּוֹת יְהַלֵּכוּן לִוְיָתָן זֶה יָצַרְתָּ לְשַׂחֶק בּוֹ. זֶה דַּיְיקָא. וְכָל נוּנֵי יַמָּא מִתְכַּנְּשִׁין לְאַתְרַיְיהוּ. וְכָל אִינּוּן חֵיוָון חַדָּאן עָלָהּ, וְחֵיוָון חַקְלָא עִלָּאָה חַדָּאן, הֲדָא הוּא דִכְתִיב, (איוב מ׳:כ׳) וְכָל חַיַּת הַשָּׂדֶה יְשַׂחֲקוּ שָׁם.</p>\n<p>תָּא חֲזֵי, כְּגַוְונָא דִּלְעֵילָּא, אִית לְתַתָּא. כְּגַוְונָא דִּלְתַתָּא, אִית בְּיַמָּא. כְּגַוְונָא דִּלְעֵילָּא, אִית לְעֵילָּא בְּיַמָּא עִלָּאָה. כְּגַוְונָא דִּלְעֵילָּא אִית לְתַתָּא. כְּגַוְונָא דִּלְתַתָּא, אִית בְּיַמָּא תַּתָּאָה.</p>\n<p>גּוּפָא דְּהַהוּא יַמָּא, הָא אִתְעַרְנָא לְחַבְרָנָא, אוֹרְכָא וּפוּתְיָא, רֵישָׁא וּדְרֹעִין וְשַׂעֲרֵי גוּפָא, כֹּלָּא כְּמָה דְּאִצְטְרִיךְ, וְכֹלָּא בִּשְׁמֵיהּ (ויחי רמ\"ה) אִתְקְרֵי. וּכְגַוְונָא דָּא לְתַתָּא לְיַמָּא דִּלְתַתָּא, הָכִי נָמֵי רֵישָׁא דְּיַמָּא, וּדְרוֹעִין דְּיַמָּא, וְגוּפָא דְּיַמָּא.</p>\n<p>כְּתִיב (בראשית מ״ט:י״ג) זְבוּלוּן לְחוֹף יַמִים יִשְׁכּוֹן. וְהָא יַמָּא חַד הֲוָה בְּעַדְבֵיהּ אֶלָּא מַאי לְחוֹף יַמִים, וַדַּאי אוּקְמוּהָ חַבְרַיָּיא בְּרָזָא עִלָּאָה. וְיַרְכָתוֹ עַל צִידוֹן, כְּמָה דְאַתְּ אָמֵר (שמות א׳:ה׳) יוֹצְאֵי יֶרֶךְ יַעֲקֹב. זְבוּלוּן שׁוֹקָא דִּימִינָא דְּגוּפָא הֲוָה, וְיַם כִּנֶּרֶת הֲוָה בְּעַדְבֵיהּ, וּמֵהָכָא אִשְׁתְּכַח חִלָּזוֹן לִתְכֶלְתָּא.</p>\n<p>תָּא חֲזֵי, כַּמָּה רְתִיכִין עַל רְתִיכִין אִשְׁתְּכָחוּ, וְגַלְגַּלּוֹי דִּרְתִּיכָא רָהֲטִין בִּבְהִילוּ, וְלָא מִתְעַכְּבֵי אִינּוּן סַמְכֵי רְתִיכָא, לְנַטְלָא עֲלֵיהוֹן. וְכֵן כֻּלְּהוּ. (נ\"א והכא שנהגו בכבדות בבהילו) תָּא חֲזֵי, רְתִיכָא דִּי מְמָנָא עַל מִצְרָאֵי, (אי תימא) אוּקְמוּהָ, רְתִיכָא שְׁלֵימָתָא לָא אִשְׁתְּכַח, דְּהָא כְּתִיב וַיָּסַר אֵת אוֹפַן מַרְכְּבוֹתָיו, כַּמָּה רְתִיכִין הֲווֹ, דַּהֲווֹ נַטְלִין עַל חַד סָמִיךְ גַּלְגַּלָּא, דְּאִתְפָּקְדוּ עֲלַיְיהוּ, כֵּיוָן דְּאִתְעֲבָר הַאי מִשּׁוּלְטָנוּתָא דִּילֵיהּ, כֻּלְּהוּ רְתִיכִין אִתְעֲבָרוּ מִשּׁוּלְטָנִיהוֹן, וְלָא נַטְלוּ. כְּדֵין כֻּלְּהוּ לְתַתָּא אִתְעֲבָרוּ מְשּׁוּלְטָנוּתָא, דִּכְתִּיב, (ירמיהו מ״ו:כ״ה) עַל מִצְרַיִם וְעַל פַּרְעֹה וְעַל הַבּוֹטְחִים <Nonei></i>בוֹ.</p>\n<p>וּבְהַהוּא זִמְנָא, שֻׁלְטָנוּתָא דְּמִצְרַיִם שָׁלִיט עַל כָּל שְׁאַר עַמִּין, כֵּיוָן דְּאִתְבַּר חֵילָא דְּמִצְרַיִם, אִתְּבַר חֵילָא דִּשְׁאַר עַמִּין. מְנָלָן, דִּכְתִּיב, (שמות ט״ו:ט״ו) אָז נִבְהֲלוּ אַלּוּפֵי אֱדוֹם וְגוֹ'. וּכְתִיב (שמות ט״ו:י״ד) שָׁמְעוּ עַמִּים יִרְגָּזוּן וְגוֹ'. בְּגִין דְּכֻלְּהוּ הֲווֹ אֲחִידָן בְּפוּלְחָנָא דְּמִצְרַיִם, וַאֲחִידָן בְּמִצְרַיִם לְסִיּוּעָא דִּלְהוֹן. וּבְהַהוּא זִמְנָא, כֻּלְּהוּ בָּעָאן לְסִיּוּעָא דְּמִצְרַיִם, לְאִתַּתְקְפָא. וְעַל דָּא, כֵּיוָן דְּשָׁמְעוּ גְּבוּרָן דְּעָבַד קוּדְשָׁא בְּרִיךְ הוּא בְּמִצְרַיִם, רָפוּ יְדֵיהוֹן, וְלָא יָכִילוּ לְמֵיקָם, וְאִזְדַּעֲזָעוּ כֻּלְּהוּ, וְאִתְּבָּרוּ (משולשליהון) מִשּׁוּלְטָנַתְהוֹן.</p>\n<p>וַדַּאי כַּד אִתְּבַר חֵילָא דִּלְהוֹן לְעֵילָּא, אִתְּבַר חֵילָא דְּכָל אִינּוּן דַּאֲחִידָן בֵּיהּ, כֵּיוָן דְּאִתְבַּר חֵילָא דְּכֻלְּהוּ לְעֵילָּא, כָּל הָנֵי דִּלְתַתָּא אִתְּבָּרוּ, בְּגִין (ההוא) הַאי חֵילָא דְּאִתְבַּר בְּקַדְמִיתָא. וּבְגִין כָּךְ וַיָּסַר אֵת אֹפַן מַרְכְּבוֹתָיו כְּתִיב. וַיְנַהֲגֵהוּ בִּכְבֵדוּת, דְּהָא כַּד דָּא אִתְּבַר, לָא הֲווֹ אַזְלִין.</p>\n<p>תָּא חֲזֵי דְּהָכִי הוּא, דְּלָא כְּתִיב וַיָּסַר אֵת אוֹפַנִּי מַרְכְּבוֹתָיו, אוֹ אוֹפַן מֶרְכַּבְתּוֹ, אֶלָּא וַיָּסַר אֵת אוֹפַן מַרְכְּבוֹתָיו. בְּגִין הַאי חֵילָא, דְּכֻלְּהוּ הֲווֹ מִתְדַבְּקָן בֵּיהּ. (הכי אקרון)</p>\n<p>וְתוּ, וַיָּסַר אֵת אוֹפַן מַרְכְּבוֹתָיו, תָּא חֲזֵי, (ויסר את אופן מרכבותיו) זַכָּאָה חוּלָקֵיהוֹן דְּיִשְׂרָאֵל, דְּקוּדְשָׁא בְּרִיךְ הוּא אִתְרָעֵי בְּהוּ, לְאִתְדַּבְּקָא בְּהוּ, וּלְמֶהֱוֵי לְהוּ חוּלָק, וּלְמֶהוֵי אִינּוּן חוּלָקֵיהּ. הֲדָא הוּא דִּכְתִּיב, (דברים יג) וּבוֹ תִדְבָּקוּן. וּכְתִיב (דברים ד׳:ד׳) וְאַתֶּם הַדְּבֵקִים בַּיְיָ' אֱלֹהֵיכֶם, בַּיְיָ' מַמָּשׁ. וּכְתִיב (תהילים קל״ה:ד׳) כִּי יַעֲקֹב בָּחַר לוֹ יָהּ. וּכְתִיב (דברים ל״ב:ט׳) כִּי חֵלֶק יְיָ' עַמּוֹ יַעֲקֹב חֶבֶל נַחֲלָתוֹ. דְּאַפִּיק לוֹן מִזַּרְעָא קַדִּישָׁא, לְמֶהֱוֵי חוּלָקֵיהּ, וְעַל דָּא יָהַב לוֹן אוֹרַיְיתָא קַדִּישָׁא עִלָּאָה, גְּנִיזָא תְּרֵי אַלְפִין שְׁנִין, עַד לָא יִתְבְּרֵי עָלְמָא, וְהָא אִתְּמַר. וּבְגִין רְחִימוּתָא דִּילֵיהּ יָהֲבָא לְיִשְׂרָאֵל, לְמֵהַךְ אֲבַתְרָהּ, וּלְאִתְדַּבְּקָא בָּהּ.</p>\n<p>תָּא חֲזֵי, כָּל מַשִׁירְיָין דִּלְעֵילָּא, וְכָל אִינּוּן רְתִיכִין, כֻּלְּהוּ אֲחִידָן אִלֵּין בְּאִלֵּין, דַּרְגִּין בְּדַרְגִּין, אִלֵּין עִלָּאִין, וְאִלֵּין תַּתָּאִין, וְהָא אוּקְמוּהָ, דִּכְתִּיב, (תהילים ק״ד:כ״ה) זֶה הַיָּם גָּדוֹל. וְחֵיוָתָא קַדִּישָׁא עָלֵיהּ, וְכֻלְּהוּ אוּכְלוֹסִין וּמַשִּׁרְיָין, כֻּלְּהוּ נַטְלִין תְּחוֹת יְדָהּ, עַל מֵימְרָהּ נַטְלִין, וְעַל מֵימְרָהּ שָׁרָאן. בְּעִדָנָא דְּהִיא נַטְלָא, כֻּלְּהוּ נְטִילִין, בְּגִין דְּכֻלְּהוּ אֲחִידָן בָּהּ. (אמר ר' יצחק)</p>\n<p>וְתָּא חֲזֵי, בְּשַׁעֲתָא דְּבָעֵי קוּדְשָׁא בְּרִיךְ הוּא, לְאַעְבְּרָא לְאוּכְלוֹסִין דְּפַרְעֹה לְתַתָּא, אַעְבַּר בְּקַדְמִיתָא לְהַהוּא חֵילָא דִּלְהוֹן, כְּמָה דְּאוֹקִימְנָא. מַה עָבֵד. אַעְבָּר וְסָלִיק הַהוּא אֲתָר קַדִּישָׁא עִלָּאָה, דְּהֲוָה מַדְבָּר (פי' מנהיג) לְכָל אִינּוּן רְתִיכִין, כֵּיוָן דְּהַאי אִסְתְּלִיק, הַנְהוּ כֻּלְּהוּ מַשִּׁירְיָין לָא יָכִילוּ לְדַבְּרָא, כֵּיוָן דְּאִינּוּן לָא יָכִילוּ, הַהוּא מְמָנָא דְּמִצְרָאֵי אַעְבְּרוּ לֵיהּ מִשּׁוּלְטָנֵיהּ, וְאַעְבַּר (י' ע\"ב) בְּנוּרָא דְּדָלִיק, וּכְדֵין שֻׁלְטָנוּתָא דְּמִצְרָאֵי אִתְעָדֵי. וְעַל דָּא, אָנוּסָה מִפְּנִי יִשְׂרָאֵל. מַאי טַעְמָא, בְּגִין דְּחָמוּ מְמָנָא דְּמִצְרַיִם אִתּוֹקַד בְּנוּרָא.</p>\n<p>ר' יִצְחָק אָמַר, בְּשַׁעֲתָא דְּקָרִיבוּ יִשְׂרָאֵל לְיַמָּא, קָרָא קוּדְשָׁא בְּרִיךְ הוּא לַמְמָנָא רַבְרְבָא דְּעַל יַמָּא, אָמַר לֵיהּ, בְּשַׁעֲתָא דַּעֲבָדִית אֲנָא עָלְמָא, מָנִיתִי לָךְ עַל יַמָּא, וּתְנַאי אִית לִי עַל יַמָּא, דִּי יִבְזַע מֵימוֹי מִקָּמֵי בָּנַי. הַשְׁתָּא מָטָא עִדָנָא, דְּיָעַבְרוּן בָּנַי בְּגוֹ יַמָּא. לְבָתַר מַה כְּתִיב, וַיָּשָׁב הַיָּם לִפְנוֹת בֹּקֶר לְאֵיתָנוֹ. מַאי לְאֵיתָנוֹ, לִתְנָאוֹ דְּהֲוָה לֵיהּ בְּקוּדְשָׁא בְּרִיךְ הוּא כַּד בָּרָא עָלְמָא.</p>\n<p>וַהֲווּ יִשְׂרָאֵל שָׁרָאן עַל יַמָּא, וַהֲווּ יִשְׂרָאֵל חָמָאן, גַּלְגַּלֵּי יַמָּא סַלְּקִין וְנַחְתִּין, זָקְפוּ עֵינַיְיהוּ, וְחָמוּ לְפַרְעֹה וּלְאוּכְלוֹסִין דִּילֵיהּ, דְּחִילוּ וְצָעֲקוּ. וְהָא אִתְּמַר. הַיָּם רָאָה, מָה חָמָא יַמָּא. אֲרוֹנָא דְּיוֹסֵף קָא חָמָא, וְעָרַק מִקָּמֵיהּ. מַאי טַעְמָא, (בגין) דִּכְתִּיב, (בראשית ל״ט:י״ב) וַיָּנָס וַיֵּצֵא הַחוּצָה. וְעַל דָּא הַיָּם רָאָה וַיָּנוֹס, וּכְתִיב וַיָּסַר אֶת אוֹפַן מַרְכְּבוֹתָיו וְגוֹ' אָנוּסָה מִפְּנֵי יִשְׂרָאֵל. מַאי טַעֲמָא. בְּגִין דְּחָמוּ אַרְעָא דְּמִצְרַיִם, כְּאִלּוּ אִתּוֹקַד בְּנוּרָא, כְּדֵין אָמְרוּ אָנוּסָה מִפְּנִי יִשְׂרָאֵל.</p>\n<p>רִבִּי חִיָּיא וְרִבִּי יוֹסֵי, הֲווֹ אַזְלֵי בְּמַדְבְּרָא, אָמַר רִבִּי חִיָּיא לְרִבִּי יוֹסֵי, תָּא וְאֵימָא לָךְ, דְּכַד קוּדְשָׁא בְּרִיךְ הוּא בָּעֵי לְאַעְבְּרָא שׁוּלְטָנוּתָא דְּאַרְעָא, לָא עָבִיד, עַד דְּאַעְבַּר שֻׁלְטָנוּתָא דִּלְהוֹן בִּרְקִיעָא, וְלָא אַעְבָּר שֻׁלְטָנָא דִּלְהוֹן, עַד דְּמָנֵי אַחֲרָא בְּאַתְרֵיהּ, בְּגִין דְּלָא יִגְרַע (שולטנותא) שִׁמּוּשָׁא דִּלְהוֹן <Nonei></i>בִּרְקִיעָא, בְּגִין לְקַיְּימָא מַה דִּכְתִּיב, (דניאלד) וּלְמַן דִּי יִצְבֵּא יִתְּנִינַּהּ. אָמַר רִבִּי יוֹסֵי, ודַּאי הָכִי הוּא.</p>\n<p>פָּתַח ר' יוֹסֵי וְאָמַר, (תהילים ח׳:ב׳) יְיָ' אֲדוֹנֵינוּ מַה אַדִּיר שִׁמְךָ בְּכָל הָאָרֶץ. יְיָ' אֲדוֹנִינוּ: כַּד בָּעֵי קוּדְשָׁא בְּרִיךְ הוּא לְתַבְרָא חֵילָא דְּעַמִּין עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת, אַתְקִיף דִּינֵיהּ עָלַיְיהוּ, וְתָבַר לוֹן, וְאַעְבָּר מִקָּמֵיהּ שׁוּלְטָנוּתָא דִּלְהוֹן.</p>\n<p>אֲשֶׁר תְּנָה הוֹדְךָ עַל הַשָּׁמָיִם, אֲשֶׁר נָתַתָּ מִבָּעֵי לֵיהּ, אוֹ תְּנָה הוֹדְךָ, מַהוּ אֲשֶׁר תְּנָה הוֹדְךָ. אֶלָּא דָּא הוּא רָזָא דְּנָהֲרָא עֲמִיקָא דְּכֹלָּא, וְדָוִד בָּעָא בָּעוּתֵיהּ, לְמִנְגַּד מִנֵּיהּ עַל הַשָּׁמַיִם, וְדָא הוּא (ויקרא ס\"ה ע\"ב) אֲשֶׁר. כְּמָה דְאַתְּ אָמֵר, (שמות ג׳:י״ד) אֶהְיֶה אֲשֶׁר אֶהְיֶה.</p>\n<p>בְּשַׁעֲתָא דְּהַאי נָהֲרָא (ס\"ג ע\"ב, בראשית רכ\"א ע\"א) עֲמִיקְתָא דְּכֹלָּא, נָגִיד וְנָפִיק עַל הַשָּׁמַיִם, כְּדִין כֹּלָּא בְּחִידוּ, וּמַטְרוֹנִיתָא אִתְעַטְּרָת בְּמַלְכָּא, וְכָל עָלְמִין כֻּלְּהוּ בְּחִידוּ, וְשֻׁלְטָנוּתָא דְּעַמִּין עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת, אִתְעֲבָר מִקָּמֵי מַטְרוֹנִיתָא, וּכְדֵין זַקְפִין רֵישָׁא כָּל מַאן דַאֲחִידוּ בָּהּ.</p>\n<p>אַדְּהָכִי חָמוּ חַד בַּר נָשׁ, דְּהֲוָה אָתֵי, וְחַד מָטוּלָא קָמֵיהּ. אָמַר רִבִּי חִיָּיא, נֵזִיל, דִּלְמָא הַאי בַּר נָשׁ עוֹבֵד עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת הוּא, אוֹ עַם הָאָרֶץ הוּא, וְאָסִיר לְאִשְׁתַּתְּפָא בַּהֲדֵיהּ בְּאָרְחָא. אָמַר רִבִּי יוֹסֵי, נֵיתִיב הָכָא, וְנֶחמֵי, דִּלְמָא גַּבְרָא רַבָּא הוּא.</p>\n<p>אַדְּהָכִי, אַעְבָּר קָמַיְיהוּ, אֲמַר לֵיהּ, בְּדוּקְפָא דִּמַעְבָּרָא דְּקוֹטִיפָא דְּהַאי, חַבְרוּתָא אִבָעֵי, וַאֲנָא יְדַעְנָא אָרְחָא אַחֲרָא, וְנִסְטֵי מֵהַאי, וַאֲנָא בָּעִינָא דְּאֵימָא לְכוּ, וְלָא אִתְחַיַּיבְנָא בְּכוּ, וְלָא אַעְבָּר עַל מַה דִּכְתִּיב, (ויקרא י״ט:י״ד) וְלִפְנִי עִוֵּר לֹא תִתֵּן מִכְשׁוֹל, וְאַתּוּן כְּסוּמִין בְּאָרְחָא דָּא, וְלָא תִּסְתַּכְּנוּ בְּנַפְשַׁיְיכוּ. אָמַר רִבִּי יוֹסֵי, בְּרִיךְ רַחֲמָנָא דְּאוֹרִיכְנָא הָכָא, אִתְחַבְּרוּ בַּהֲדֵיהּ. אָמַר לוֹן, לָא תִּשְׁתָּעוּ מִידִי הָכָא, עַד דְּנַעֲבֹר בְּהַאי. סָטוּ בְּאָרְחָא אַחֲרָא.</p>\n<p>בָּתַר דְּנָפְקוּ מֵהַהוּא אֲתָר, אָמַר לוֹן, בְּהַהוּא אָרְחָא אַחֲרָא, הֲווֹ אַזְלֵי זִמְנָא חֲדָא, חַד כֹּהֵן חָכָם, וְחַד כֹּהֵן עַם הָאָרֶץ בַּהֲדֵיהּ, קָם הַהוּא עַם הָאָרֶץ בְּהַהוּא אֲתָר עָלֵיהּ וְקַטְלֵיהּ. מֵהַהוּא יוֹמָא כָּל מַאן דְּאַעְבָּר בְּהַהוּא אֲתָר, מִסְתַּכֵּן בְּנַפְשֵׁיהּ. וְהָא מִתְחַבְּרִין תַּמָן מְשַׁדְּדֵי טוּרַיָא, וְקַטְלִין וְקַפְּחִין לִבְנֵי נָשָׁא, וְאִינּוּן דְּיַדְעֵי לָא עַבְרֵי תַּמָּן, וּבָעֵי קוּדְשָׁא בְּרִיךְ הוּא דָּמָא דְּהַהוּא כַּהֲנָא כָּל יוֹמָא.</p>\n<p>פָּתַח וְאָמַר, (ישעיהו י׳:ל״ב) עוֹד הַיּוֹם בְּנוֹב לַעֲמוֹד וְגוֹ' הָא אוּקְמוּהָ אִינּוּן מָארֵי מְתִיבְתָּא. אֲבָל אֲנָא לָא אֲמֵינָא לְכוּ הָכִי, אֶלָּא דְרָזָא דְּמִלָּה אוֹלִיפְנָא. עוֹד הַיּוֹם, מַאן יוֹמָא דֵּין. אֶלָּא, הָכִי כְּתִיב, (שמות ו׳:כ״ג) וַיִּקַּח אַהֲרֹן אֶת אֱלִישֶׁבַע בַּת עֲמִּינָדָב. וְרָזָא הוּא, עַל כְּנֶסֶת יִשְׂרָאֵל, דְּאַהֲרֹן הוּא שׁוֹשְׁבִינָא דִּילָהּ, לְתַקְּנָא בֵּיתָה וּלְשַׁמְּשָׁא לָהּ, וּלְמֵיעַל לָהּ לְמַלְכָּא לְאִזְדַּוְּוגָא כַּחֲדָא, מִכָּאן וּלְהָלְאָה, כָּל כֹּהֵן דִּמְשַׁמֵּשׁ בְּמַקְדְּשָׁא, כְּגַוְונָא דְּאַהֲרֹן.</p>\n<p>אֲחִימֶלֶךָ כַּהֲנָא רַבָּא עִלָּאָה הֲוָה, וְכָל אִינּוּן כַּהֲנִי בַּהֲדֵיהּ, כֻּלְּהוּ הֲווֹ שׁוּשְׁבִינִין דְּמַטְרוֹנִיתָא, כֵּיוָן דְּאִתְקָטִילוּ, אִשְׁתַּאָרַת מַטְרוֹנִיתָא בִּלְחוֹדָהָא, וְאִתְאֲבִיד שׁוֹשְׁבִינָא דִּילָהּ, וְלָא אִשְׁתְּכַח מַאן דִּמְשַׁמֵּשׁ קָמָהּ, וִיתַקֵּן בֵּיתָה, וִיחַדֵּי לָהּ לְאִזְדַּוְּוגָא עִם מַלְכָּא. כְּדֵין מֵהַהוּא יוֹמָא, אִתְעַבְּרָא לִשְׂמָאלָא, וְקַיְּימָא עַל עָלְמָא, כָּמִין עַל כֹּלָּא, קָטִיל לְשָׁאוּל וְלִבְנוֹי, אִתְאֲבִיד מִינַיְיהוּ מַלְכוּ, מִיתוּ מִיִּשְׂרָאֵל כַּמָּה אַלְפִין וְכַמָּה רִבְוָון. וְעַד כְּעַן, הַהוּא חוֹבָה הֲוָה תָּלֵי, עַד דְּאָתָא סַנְחֵרִיב וְאַרְגִּיז כֹּלָּא.</p>\n<p>וְדָא הוּא עוֹד הַיּוֹם בְּנוֹב, דָּא הוּא יוֹמָא עִלָּאָה, וּמַאן אִיהוּ. דָּא כְּנֶסֶת יִשְׂרָאֵל, דְּאַבְדַת שׁוּשְׁבִינִין דִּילָהּ, הַהִיא דְּאִשְׁתְּאָרַת בְּלא יְמִינָא, (דהוי ליה) לְאִתְדַּבְּקָא בִּשְׂמָאלָא. דְּכַהֲנָא יְמִינָא הוּא. (אמר ליה לאתדבקא בשמאלא) וּבְגִין כַּךְ, עוֹד הַיּוֹם בְּנוֹב לַעֲמוֹד.</p>\n<p>תָּא חֲזֵי, כְּתִיב גִּבְעַת שָׁאוּל נָסָה, שָׁאוּל אֲמַאי הָכָא. אֶלָּא בְּגִין דְּהוּא קָטִיל לְכַהֲנֵי, וְגָרִים דְּרוֹעָא יְמִינָא, לְאִתְעַקְרָא מֵעָלְמָא. אוּף הָכָא, מֵהַהוּא יוֹמָא, לָא אַעְבָּר בַּר נָשׁ בְּהַהוּא דּוּכְתָּא, בְּגִין דְּלָא אִסְתַּכֵּן בְּנַפְשֵׁיהּ. אָמַר לֵיהּ רִבִּי יוֹסֵי לְרִבִּי חִיָּיא, וְלָא אֲמָרִית לָךְ דִּלְמָא גַּבְרָא רַבָּא הוּא.</p>\n<p>פָּתַח וְאָמַר, (משלי ג׳:י״ג) אַשְׁרֵי אָדָם מָצָא חָכְמָה. אַשְׁרֵי אָדָם, <Nonei></i>כְּגוֹן אֲנָן, דְּאַשְׁכַּחְנָא לָךְ, וְיָדַעְנָא מִינָךְ מִלָּה דְּחָכְמְתָא. וְאָדָם יָפִיק תְּבוּנָה, כְּגוֹן אֲנָן, דְּאוֹרִיכְנָא לָךְ לְאִתְחַבְּרָא בַּהֲדָךְ. וְדָא הוּא בַּר נָשׁ דְּזַמִּין לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא נְבִזְבְּזָא בְּאָרְחָא, אַנְפּוֹי דִּשְׁכִינְתָּא, וְעַל דָּא כְּתִיב, (משלי ד׳:י״ח) וְאֹרַח צַדִּיקִים כְּאוֹר נֹגַהּ. אָזְלוּ.</p>\n<p>פָּתַח הַהוּא גַּבְרָא וְאָמַר (תהילים כ״ד:א׳) לְדָוִד מִזְמוֹר לַיְיָ' הָאָרֶץ וּמְלוֹאָהּ וְגוֹ'. לְדָוִד מִזְמוֹר בַּאֲתָר חַד, וּבַאֲתַר אַחֲרָא מִזְמוֹר לְדָוִד, מַה בֵּין הַאי (ק\"ע ע\"א) לְהַאי. אֶלָּא לְדָוִד מִזְמוֹר, שִׁירָתָא דְּקָאָמַר דָּוִד, עַל כְּנֶסֶת יִשְׂרָאֵל. מִזְמוֹר לְדָוִד, שִׁירָתָא דְּקָאָמַר דָּוִד, עַל גַּרְמֵיהּ.</p>\n<p>לַיְיָ' (כ\"ב ע\"ב) הָאָרֶץ וּמְלוֹאָהּ. לַיְיָ': דָּא קוּדְשָׁא בְּרִיךְ הוּא. הָאָרֶץ וּמְלוֹאָהּ: דָּא כְּנֶסֶת יִשְׂרָאֵל, וְכָל אוּכְלוֹסִין דִּילָהּ, דְּמִתְחַבְּרָן בַּהֲדָהּ, וְאִקְרוּן מְלוֹאָהּ וַדַּאי הוּא. כְּמָה דְּאַתְּ אָמֵר, (ישעיהו ו׳:ג׳) מְלֹא כָל הָאָרֶץ כְּבוֹדוֹ תֵּבֵל וְיוֹשְׁבֵי בָהּ: דָּא הוּא אַרְעָא דִּלְתַתָּא, דְּאִקְרֵי תֵּבֵל, וַאֲחִידַת בְּדִינָא (דעלמא) דִּלְעֵילָּא, הֲדָא הוּא דִּכְתִּיב, (תהילים ט׳:ט׳) וְהוּא יִשְׁפוֹט תֵּבֵל בְּצֶדֶק, בֵּין לְחָד, בֵּין לְעַמָּא חַד, בֵּין לְכָל עָלְמָא, מֵהַאי דִּינָא הוּא אִתְּדָן.</p>\n<p>תָּא חֲזֵי, פַּרְעֹה מֵהַאי דִּינָא יָנִיק, עַד דְּאִתְאֲבִידוּ הוּא וְכָל עַמֵּיהּ. כֵּיוָן דְּהַאי דִּינָא אִתְּעַר עָלֵיהּ, הַהוּא מְמָנָא דְּאִתְמָנָא עֲלַיְיהוּ בְּשֻׁלְטָנוּתָא, אִתְעָדֵי וְאִתְעֲבָר, כְּדֵין כֻּלְּהוּ דִּלְתַתָּא, אִתְאֲבִידוּ, דִּכְתִּיב וַיָּסַר אֶת אוֹפַן מַרְכְּבוֹתָיו. מַאי אוֹפַן מַרְכְּבוֹתָיו. מַרְכְּבוֹתָיו דְּפַרְעֹה. וּמַאן אִיהוּ הַהוּא אוֹפַן דִּלְהוֹן, הַהוּא מְמָנָא דְּשָׁלִיט עֲלַיְיהוּ. וְעַל דָּא מִיתוּ כֻּלְּהוּ בְּיַמָּא. אֲמַאי בְּיַמָּא, אֶלָּא יַמָּא עִלָּאָה אִתְּעַר עֲלַיְיהוּ, וְאִתְמְחוּ (נ\"א ואתמסרו) בִּידָהָא. וּבְגִין כַּךְ טֻבְּעוּ בַּיָּם סוֹף כְּתִיב. אָמַר רִבִּי יוֹסֵי וַדַּאי הָכִי הוּא, וְעַל דָּא כְּתִיב, טֻבְּעוּ בְּיַם סוּף. סוֹפָא דְּדַרְגִּין.</p>\n<p>רִבִּי חִיָּיא אָמַר, וַיְנַהֲגֵהוּ בִּכְבֵדוּת. בִּכְבֵדוּת מַהוּ. אֶלָּא מִכָּאן אוֹלִיפְנָא, דִּבְהַהוּא דַּבְּרוּתָא דְּאִתְדָּבַּר בֵּיהּ בַּר נָשׁ, מְדַבְּרִין לֵיהּ. בְּפַרְעֹה כְּתִיב (שמות ט׳:ז׳) וַיִּכְבַּד לֵב פַּרְעֹה. בְּהַהוּא מִלָּה, דָּבַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, בִּכְבֵדוּת מַמָּשׁ. אָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, רָשָׁע, אַתְּ אוֹקִיר לִבָּךְ. אֲנָא אַדְבַּר לָךְ בְּהַאי, עַל דָּא וַיְנַהֲגֵהוּ בִּכְבֵדוּת.</p>\n<p>וַיֹּאמֶר מִצְרַיִם אָנוּסָה מִפְּנֵי יִשְׂרָאֵל וְגוֹ'. וַיֹּאמֶר מִצְרַיִם, דָּא מְמָנָא דְּאִתְמְנֵי עַל מִצְרָאֵי. אָמַר רִבִּי יוֹסֵי, הַאי מִלָּה קַשְׁיָא, כֵּיוָן דְּאַעְבְּרוּ לֵיהּ מִשּׁוּלְטָנוּתֵיה, הֵיךְ יָכִיל הוּא לְמִרְדַּף אֲבַתְרַיְיהוּ דְּיִשְׂרָאֵל.</p>\n<p>אֶלָּא וַדַּאי הָכִי הוּא. אֲבָל דָּא וַיֹּאמֶר מִצְרַיִם, מִצְרַיִם דִּלְתַתָּא. כִּי יְיָ' נִלְחָם לָהֶם בְמִצְרָיִם, מִצְרַיִם דִּלְעֵילָּא, דְּכֵיוָן דְּאִתְבַּר חֵילֵהוֹן מִלְּעֵילָּא, כְּדֵין אִתְּבַר חֵילָא וְתּוּקְפָּא דִּלְהוֹן לְתַתָּא, הֲדָא הוּא דִּכְתִּיב כִּי יְיָ' נִלְחָם לָהֶם בְמִצְרָיִם. בְּמִצְרַיִם דַּיְקָא. דָּא הוּא תּוּקְפָּא דִּלְהוֹן דִּלְעֵילָּא. וְדָא הוּא דְּאוּקְמוּהָ מֶלֶךְ מִצְרַיִם סְתָם. הָכָא, וַיֹּאמֶר מִצְרַיִם אָנוּסָה מִפְּנֵי יִשְׂרָאֵל, דְּחָמוּ דְּהָא אִתְּבַר חֵילֵיהוֹן, וְתּוּקְפָּא דִּלְהוֹן, דִּלְעֵילָּא.</p>\n<p>תָּא חֲזֵי, כַּד אִתְּעָרַת הַאי כְּנֶסֶת יִשְׂרָאֵל, אִתְעֲרוּ כָּל אינון דאחידן בה, וכלהו אחרנין דלתתא, וישראל לעילא מכלהו, דהא אינון נטלי לה בגופא דאילנא, והא אוקמוה. ובגיני כך ישראל אחידן בה, יתיר מכל עובדי כוכבים ומזלות. וכד אינון מתערין, (כל עמים עכו\"ם) אתבר תוקפהון מאינון דשלטי עלייהו.</p>\n<p>תָּא חֲזִי, הַאי מְמָנָא שֻׁלְטָנָא דְּמִצְרָאֵי, דָּחִיק לוֹן לְיִשְׂרָאֵל, בְּכַמָּה שִׁעְבּוּדִין, כְּמָה דְּאוּקְמוּהָ. לְבָתַר דְּאִתְבַּר הוּא בְּקַדְמִיתָא, אִתְּבָּרוּ אִינּוּן מַלְכְּוָותָא (ס\"א מלתתא), הֲדָא הוּא דִכְתִיב כִּי יְיָ' נִלְחָם לָהֶם בְּמִצְרַיִם. נִלְחָם לָהֶם ודַּאי.</p>"],[9520011610,"<p><Noneb>ס\"א תוספתא</b> (שמות י״ד:י״ט) ויִּסַּע מַלְאַךְ הָאֱלהִים וגוֹ'. (מתניתין) עַד לָא (ס\"א אשתקע) אִשְׁתְּכַח אֲוִירָא דַּכְיָא, וְלָא נְהִירִין, אֲבָנִין נְקִיבָן הֲווֹ סְתִימָאן. תְּלַת רוּחִין דִּכְלִילָן בִּתְלַת, הֲווֹ שְׁקִיעָן. וּמַיִין סְתִימָן תְּחוֹת נוּקְבֵי. בְּשִׁבְעִין וּתְרֵין אַתְוָון אִתְהַדָּרוּ לְאַתְרַיְיהוּ <Nonei></i>אִינּוּן אֲבָנִין (ס\"א דרין).</p>\n<p>בָּתַר שִׁבְעִין וּתְרֵין דַּרְגִּין, וְכֵן תְּלַת זִמְנִין, אִתְבָּקָעוּ ואִתְנְקִיבוּ אֲבָנֵי, תְּחוֹת צְרוֹרָא דְּהֲוָה חָקִיק, וְאִתְכְּנָפוּ דַּרְגִּין, וְאִתְעָבִידוּ כְּנוּפְיָא חֲדָא. (ס\"א אתפלג ואתעבידו כנופיא חד)</p>\n<p>לְבָתַר אִתְפְּלָגוּ, וְאִתְעָבִידוּ תְּרֵין דַּרְגִּין, פַּלְגּוּתָא מַיָּא אַגְלִידוּ, וּפַלְגּוּתָא אִשְׁתְּקָעוּ. אִלֵּין סְלִיקוּ, וְאִלֵּין נַחְתּוּ, מֵהָכָא שָׁרָא עָלְמָא לְאִתְפַּלְגָא.</p>\n<p>צְרוֹרָא אַחֲרָא (נ\"א חדא) אִית לְעֵילָּא, (לעילא) וְהוּא גְּלִיפָא בע\"ב חֲתִימָן דְּגוּשְׁפַּנְקָא תַּקִּיפָא, וּבְהוּ שְׁקִיעַן גַּלְגַּלּוֹי דְּיַמָּא. כַּד נַטְלִין, אִתְפְּלָגוּ לְאַרְבַּע זַוְּיָין. פַּלְגּוּ חֲדָא סָלִיק, וּפַלְגּוּ חֲדָא נָחִית, פַּלְגּוּ חֲדָא לִסְטַר צָפוֹן, וּפַלְגּוּ חֲדָא לִסְטַר דָּרוֹם. כַּד מִתְחַבְּרָן כַּחֲדָא, גּוּמְרִין דְּלַהֲטִין קַיְימִין, בְּלַהַט שִׁנָּנָא דְּחַרְבָּא דְּמִתְהַפְּכָא.</p>\n<p>חַד קַיְּימָא נָעִיץ בְּגוֹ יַמָּא, דַּרְגָּא שְׁלִיחָא דְּאָפַרְכָא עִלָּאָה, סָלִיק בְּהַהוּא קַיָימָא לְעֵילָּא לְעֵילָּא, אִשְׁתֶכְלָל (נ\"א אסתכל) לְמֵרָחִיק, קְטוּרָא דְּאַרְבִּין דְּשָׁאטִין בְּיַמָּא. מַאן חָמֵי גַּלְגַּלִּין דְּסַלְּקִין וְנַחְתִּין וְרוּחָא דְּנָשִׁיב בְּהוּ, וְנוּנֵי יַמָּא נַגְדִּין כָּל אִינּוּן אַרְבִּין לְכָל סִטְרֵי עָלְמָא.</p>\n<p>הַהוּא דַּרְגָּא, כַּד נָחִית מֵהַהוּא, קַיְימֵי אֶלֶף מִימִינֵיהּ, וְאֶלֶף מִשְּׂמָאלֵיהּ, הֲוָה תָּב וְיָתִיב בְּאַתְרֵיהּ, כְּמַלְכָּא בְּכוּרְסְיֵהּ, הַהוּא דַּרְגָּא דְּכַד שָׁאטֵי יַמָּא לְאַרְבַּע סִטְרֵי עָלְמָא, עִמֵּיהּ נַפְקַת, בֵּיהּ תֵּבַת, הוּא תָּב בְּקִיּוּמָא דְּמַלְכָּא.</p>\n<p>כְּדֵין כָרוֹזִין נָפְקִין, מַאן מָארֵי דְּעַיְינִין, יִזְדַּקְפָאן לוֹן לְעֵילָּא לְעֵילָּא. מָארֵיהוֹן דְּגַדְפִּין יְקוּמוּן בְּקִיּוּמַיְיהוּ. מָארֵי דְּאַנְפִּין, חַפְיָין לוֹן, עַד דְּנָטִיל בְּמַטְלָנוֹי. כְּדֵין וַיִּסַּע מַלְאַךְ הָאֱלהִים. (עד כאן).</p>"],[9520011611,"<p>רִבִּי חִיָּיא פָּתַח, (משלי ל״א:י״ד) הָיְתָה כָּאֳנִיּוֹת סוֹחֵר מִמֶּרְחָק תָּבִיא לַחְמָהּ. הָיְתָה כָּאֳנִיּוֹת סוֹחֵר, דָּא כְנֶסֶת יִשְׂרָאֵל. מִמֶּרְחָק תָּבִיא לַחְמָהּ, כְּמָה דְּאַתְּ אָמֵר, (ישעיהו ל׳:כ״ז) הִנֵּה שֵׁם יְיָ' בָּא מִמֶּרְחָק. תָּבִיא לַחְמָהּ, בְּחַד דַּרְגָּא דְּשָׁארִי עָלָהּ, וּבֵיהּ אִתְמְשָׁכוּ כָּל אִלֵּין נְחָלִין וּמַבּוּעִין דְּאַזְלִין בְּיַמָּא, כְּמָה דְּאַתְּ אָמֵר, (קהלת א׳:ז׳) כָּל (ויקרא נ\"ח ע\"א) הַנְּחָלִים הוֹלְכִים אֶל הַיָּם וְגוֹ'.</p>\n<p>אֶל מָקוֹם שֶׁהַנְּחָלִים הוֹלְכִים, אַף עַל גַּב דְּכֻלְּהוּ נְחָלִין אִתְמַשְּׁכָן בְּהַהוּא דַּרְגָּא, וְהַהוּא דַּרְגָּא נָחִית (נ\"א נגיד) לוֹן לְהַהוּא יַמָּא, לָא תֵּימָא. דְּהָא אָרִיק לוֹן, וְהָא לָא שַׁרְיָין בֵּיהּ אַחֲרָנִין, וְלָא נַגְדִּין בֵּיהּ כְּמִלְקַדְּמִין, אַהְדָּר וְאָמַר אֶל מָקוֹם שֶׁהַנְּחָלִים הוֹלְכִים שָׁם הֵם שָׁבִים, אֶל מָקוֹם דְּהַהוּא דַּרְגָּא דְּנַחֲלִין אַזְלִין זִמְנָא חֲדָא, שָׁם הֵם שָׁבִים לָלָכֶת, תַּמָּן אִינּוּן תַּיְיבִין מֵהַהוּא אֲתָר עִלָּאָה, וְלָא פַּסְקִין לְעָלְמִין, וּמִתְכַּנְּשֵׁי כֻּלְּהוּ בְּהַהוּא אֲתָר. וְלָמָּה. לָלָכֶת. לְמֵהַךְ לְהַהוּא אֲתָר דְּיַמָּא, כְּמָה דְּאִתְּמַר, מַה שְׁמֵיהּ דְּהַהוּא דַּרְגָּא. צַדִּיק אִקְרֵי.</p>\n<p>רִבִּי יְהוּדָה אָמַר, כְּתִיב (תהילים ק״ד:כ״ו) שָׁם אֳנִיּוֹת יְהַלֵּכוּן לִוְיָתָן זֶה יָצַרְתָּ לְשַׂחֶק בּוֹ. שָׁם אֳנִיּוֹת יְהַלֵּכוּן, בְּהַהוּא יַמָּא דְּאַזְלִין וְשָׁאטִין, עַד דְּאַתְיָין לְאִתְחַבְּרָא בְּהַהוּא דַּרְגָּא, כְּדֵין כְּתִיב לִוְיָתָן זֶה יָצַרְתָּ לְשַׂחֶק בּוֹ.</p>\n<p>רִבִּי יִצְחָק אָמַר, לְעֵילָּא לְעֵילָּא יַתִּיר, אִית זִוּוּגָא אַחֲרָא, דְּשָׁארִי בַּחֲבִיבוּתָא, וְלָא (ויקרא ס\"א ע\"ב, ע\"ז ע\"ב, נ\"ה ע\"א, כ\"ו ע\"א) מִתְפְּרַשׁ לְעָלְמִין. אָמַר רִבִּי יְהוּדָה, מַאן זָכֵי לְהַהוּא זִוּוּגָא. אָמַר לֵיהּ, מַאן דְּאִית לֵיהּ חוּלָקָא בְּעָלְמָא דְּאָתֵי. בְּעָלְמָא דְּאָתֵי דַּיְקָא.</p>\n<p>אָמַר לֵיהּ, וְהָא מֵהָכָא אוֹלִיפְנָא, דִּכְתִּיב, (תהילים ק״ד:כ״ו) לִוְיָתָן זֶה יָצַרְתָּ לְשַׂחֶק בּוֹ, מַשְׁמַע דְּקָאָמַר זֶה, וְזֶה וְזֹאת יְדִיעָן אִינּוּן. אָמַר רִבִּי אַבָּא, תַּרְוַויְיכוּ שַׁפִּיר קָאָמְרִיתּוּ, וְהָא דְּרִבִּי יְהוּדָה שַׁפִּיר דַּיְקָא, וְכֹלָּא זַמִּין קוּדְשָׁא בְּרִיךְ הוּא לְאִתְעַנְגָּא בְּהוּ לְצַדִּיקַיָּיא, הֲדָא הוּא דִכְתִיב, (ישעיהו נ״ח:י״ד) אָז תִּתְעַנַּג עַל יְיָ'.</p>\n<p>אָמַר רִבִּי אַבָּא, כַּמָּה אַלְפִין, כַּמָּה רִבְּבָן דְּמַשִּׁירְיָין קַדִּישִׁין, אִית לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא, מָארֵי דְּאַנְפִּין עִלָּאִין, מָארֵי דְּעַיְינִין, מָארֵי דְּזַיְינִין, מָארֵי דִּילָלָה, מָארֵי דִּיבָבָא, מָארֵי דְּרַחֲמֵי, מָארֵי דְּדִינָא, וְעֵילָּא מִנַּיְיהוּ אַפְקַד לְמַטְרוֹנִיתָא לְשַׁמְשָׁא בְּהֵיכְלָא קָמֵיהּ.</p>\n<p>לָקֳבֵיל אִלֵּין, אִית לָהּ לְמַטְרוֹנִיתָא, מַשִׁירְיָן מְזְיָּינִין. בְּשִׁתִּין (בשתא) אַנְפִּין מִשְׁתַּכְחוּ מַשְׁרְיָין מְזוּיָינִין. וְכֻלְּהוּ חֲגִירָן חֲרְבָּא, קַיְּימָאן בְּסַחֲרָנָהָא, כַּמָה נָפְקִין, כַּמָה עַיְילִין. בְּשִׁית גַּדְפִּין טָאסִין כָּל עָלְמָא. קַמֵי כָּל חַד וְחַד גּוּמָרִין דְּנוּר דָּלִיק. לְבוּשׁוֹי, מִתְלָהֲטָא אֶשָּׁא. בְּגַבּוֹי, שִׁנָּנָא דְּחַרְבָּא מִתְלָהֲטָא בְּכָל עָלְמָא, לְנַטְרָא <Nonei></i>קָמָהּ. הֲדָא הוּא דִכְתִיב, (בראשית ג׳:כ״ד) וְאֵת לַהַט הַחֶרֶב הַמִּתְהַפֶּכֶת לִשְׁמוֹר אֶת דֶּרֶךְ עֵץ הַחַיִּים.</p>\n<p>מַאן דֶּרֶךְ עֵץ הַחַיִּים. דָּא הִיא מַטְרוֹנִיתָא רַבְּתָא, דְּהִיא אָרְחָא, לְהַהוּא אִילָנָא רַבְרְבָא תַּקִּיף, אִילָנָא דְּחַיֵּי. דִּכְתִּיב, (שיר השירים ג׳:ז׳) הִנֵּה מִטָּתוֹ שֶׁלִּשְׁלֹמֹה שִׁשִּׁים גִּבּוֹרִים סָבִיב לָהּ מִגִּבּוֹרֵי יִשְׂרָאֵל. יִשְׂרָאֵל דִּלְעֵילָּא, כֻּלָּם אֲחוּזֵי חֶרֶב.</p>\n<p>כַּד נַטְלָא מַטְרוֹנִיתָא, כֻּלְּהוּ נַטְלִין בַּהֲדָהּ, הֲדָא הוּא דִכְתִיב וַיִּסַּע מַלְאַךְ הָאֱלהִים. וְכִי מַלְאַךְ הָאֱלֹהִים אִתְקְרֵי. אָמַר רִבִּי אַבָּא אִין. תָּא חֲזֵי, הָכִי אָמַר רִבִּי שִׁמְעוֹן, אַתְקִין קוּדְשָׁא בְּרִיךְ הוּא קָמֵיהּ, הֵיכָלָא קַדִּישָׁא, הֵיכָלָא עִלָּאָה, (קדישא) קַרְתָּא קַדִּישָׁא, קַרְתָּא עִלָּאָה. יְרוּשְׁלֵים עִיר הַקֹּדֶשׁ אִקְרֵי, מַאן דְּעָאל לְמַלְכָּא, לָא עָאל אֶלָּא מֵהַהוּא קַרְתָּא קַדִּישָׁא, נָטִיל אָרְחָא לְמַלְכָּא, דְּאָרְחָא מֵהָכָא אִתָּתְקָן.</p>\n<p>הֲדָא הוּא דִכְתִיב, (תהילים קי״ח:כ׳) זֶה הַשַּׁעַר לַיְיָ' צַדִּיקִים יָבוֹאוּ בוֹ. כָּל שְׁלִיחוּתָא דְּבָעֵי מַלְכָּא מִבֵּי מַטְרוֹנִיתָא נָפְקָא, וְכָל שְׁלִיחוּתָא מִתַּתָּא לְמַלְכָּא, (נ\"א דבעי מלכא) לְבֵי מַטְרוֹנִיתָא עָיִיִל בְּקַדְמִיתָא, וּמִתַּמָּן לְמַלְכָּא. אִשְׁתְּכַח דְּמַטְרוֹנִיתָא אִיהִי שְׁלִיחָא דְּכֹלָּא, מֵעֵילָּא לְתַתָּא, וּמִתַּתָּא לְעֵילָּא. וְעַל דָּא, אִיהִי שְׁלִיחָא דְּכֹלָּא, הֲדָא הוּא דִכְתִיב וַיִּסַּע מַלְאַךְ הָאֱלֹהִים הַהוֹלֵךְ לִפְנֵי מַחֲנֵה יִשְׂרָאֵל, יִשְׂרָאֵל דִּלְעֵילָּא. מַלְאַךְ הָאֱלהִים, הֲדָא הוּא דִכְתִיב בֵּיהּ, וַיְיָ' הוֹלֵךְ לִפְנֵיהֶם וְגוֹ', וְהַאי לָלֶכֶת יוֹמָם וְלַיְלָה, כְּמָה דְּאוּקְמוּהָ.</p>\n<p>וְכִי יְקָרָא הוּא דְּמַלְכָּא, דְּמַטְרוֹנִיתָא תֵּזִּיל, וְהִיא תִּגַּח קְרָבָא, וְהִיא אַזְלַת שְׁלִיחָא. אֶלָּא, לְמַלְכָּא דְּאִזְדָּוַּוג בְּמַטְרוֹנִיתָא עִלָּאָה, חָמָא מַלְכָּא יְקִירוּ דִּילָהּ, עַל כָּל שְׁאַר מַטְרוֹנִיתָא דְּעָלְמָא, אָמַר כֻּלְּהוּ מִשְׁתַּכְּחִין לְחֵינָתָא (נ\"א לחופתא), לָקֳבֵל הַאי מַטְרוֹנִיתָא דִּילִי. הִיא סַלְּקָא עַל כֹּלָּא, מַה אַעְבִיד לָהּ. אֶלָּא כָּל בֵּיתָא דִּילִי יְהֵא בִּידָהָא, אַפִּיק מַלְכָּא כָּרוֹזָא, מֵהָכָא כָּל מִלִּין דְּמַלְכָּא בִּידָא דְּמַטְרוֹנִיתָא יִתְמַסְּרוּן. מַה עָבִיד. אַפְקִיד מַלְכָּא בִּידָהָא כָּל זַיְינִין דִּילֵיהּ, כָּל אִינּוּן מָארֵי מַגִּיחִין קְרָבָא, כָּל אִינּוּן אֲבָנִין יְקִרִין דְּמַלְכָּא, כָּל גִּנְזַיָּיא דְּמַלְכָּא. אָמַר, מֵהָכָא, כָּל מַאן דְּיִצְטְרִיךְ לְמַלְּלָא עִמִּי, לָא יָכִיל לְמַלְּלָא עִמִּי, עַד דְּאוֹדַע לָהּ מַטְרוֹנִיתָא.</p>\n<p>כַּךָ קוּדְשָׁא בְּרִיךְ הוּא, מִסְּגִיאוּת חֲבִיבוּתָא וּרְחִימוּתָא דִּילֵיהּ בְּכְּנְסֶת יִשְׂרָאֵל, אַפְקִיד כֹּלָּא בִּרְשׁוּתָהּ, אָמַר, הָא כָּל שָׁאֲרִי, לָא מִשְׁתַּכְּחֵי כְּלוּם לְגַבָּהָא. אָמַר, (שיר השירים ו׳:ט׳) שִׁשִּׁים הֵמָּה מְלָכוֹת וְגוֹ', אַחַת הִיא יוֹנָתִי תַמָּתִי. מַה אַעְבִיד לָהּ, אֶלָּא, הָא כָּל בֵּיתָא דִּילִי בִּידָהָא. אַפִּיק מַלְכָּא כָּרוֹזָא, מֵהָכָא כָּל מִלִּין דְּמַלְכָּא, בִּידָא דְּמַטְרוֹנִיתָא יִתְמַסְּרוּן. אַפְקִיד בִּידָהָא כָּל זַיְינִין דִּילֵיהּ, רוֹמְחִין, וְסַיְיפִין, קַשְׁתִּין, חִצִּין, וַחֲרָבִין, בַּלִסְטְרִין. קַסְטִירָאִין, אָעִין, אֲבָנִין, כָּל אִינּוּן מָארֵי (נ\"א מאני) מַגִּיחֵי קְרָבָא. הֲדָא הוּא דִכְתִיב, הִנִּה מִטָּתוֹ שֶׁלִּשְׁלֹמֹה שִׁשִּׁים גִּבּוֹרִים וְגוֹ' כֻּלָּם אֲחוּזִיִ חֶרֶב מְלוּמְּדֵי וְגוֹ'.</p>\n<p>אָמַר מַלְכָּא, מִכָּאן וּלְהָלְאָה, קְרָבָא דִּילִי אִתְמְסַר בִּידָךְ, זַיְינִין דִּילִי, מָארֵי מַגִּיחֵי קְרָבָא בִּידָךְ. מִכָּאן וּלְהָלְאָה אַתְּ הֲוֵי נַטְרָא לִי, הֲדָא הוּא דִכְתִיב, (תהלים קכא) שׁוֹמֵר יִשְׂרָאֵל. מִכָּאן וּלְהָלְאָה, מַאן דְּאִצְטְרִיךְ לִי, לָא יָכִיל לְמַלְּלָא עִמִּי, עַד דְּאוֹדַע לְמַטְרוֹנִיתָא, הֲדָא הוּא דִכְתִיב, (ויקרא ט״ז:ג׳) בְּזֹאת יָבֹא אַהֲרֹן אֶל הַקֹּדֶשׁ. שְׁלִיחָא דְּמַלְכָּא בְּכֹלָּא, כְּמָה דְּאוֹקִימְנָא. אִשְׁתְּכַח דְּכֹלָּא בִּידָהָא, וְדָא הוּא יְקָרָא דְּמַטְרוֹנִיתָא. הֲדָא הוּא דִּכְתִּיב, וַיִּסַּע מַלְאַךְ הָאֱלהִים וְגוֹ', כְּמָה דְּאִתְּמַר.</p>\n<p>וַיֵּלֶךָ מֵאַחֲרֵיהֶם, מַאי טַעְמָא מֵאַחֲרֵיהֶם. בְּגִין דְּיִשְׁתְּכָחוּ לְקַמָהָא (נ\"א לגבהא) מָארֵי מַגִּיחֵי קְרָבָא, מָארֵי בַּלִּסְטְרָאוֹת, מָארֵי רוֹמְחִין וְסַיְיפִין, וְאִתְגְּלוּן קַמָהָא, דְּהָא הֲווֹ אַתְיָין מַשִׁירְיָין אַחֲרָנִין, לְאַגָּחָא קְרָבָא בְּיִשְׂרָאֵל מִלְּעֵילָּא, וְעַל דָּא וַיֵּלֶךְ מֵאַחֲרֵיהֶם.</p>\n<p>וְתָאנָא, בְּהַהִיא שַׁעֲתָא, אָתָא רַבְרְבָא שֻׁלְטָנָא דִּמְמָנָא עַל מִצְרָאֵי, וְכָנַשׁ שִׁית מֵאָה (רבוון) רְתִיכִין מְקַטְרְגִין, וְעַל כָּל רְתִיכָא וּרְתִיכָא, שִׁית מֵאָה שָׁלְטָנִין מְמָנָן קַטֵיגוֹרִין, הֲדָא הוּא דִכְתִיב וַיִּקַּח שֵׁשׁ מֵאוֹת רֶכֶב בָּחוּר וְגוֹ'. וְכִי שֵׁשׁ מֵאוֹת רֶכֶב בָּחוּר, לָא הֲווֹ רִכְבֵי מִצְרַיִם, מַאי טַעְמָא וְכֹל רֶכֶב מִצְרָיִם. אֶלָּא הָכִי תָּאנָא, הֲוָה סָמָאֵ\"ל אוֹזִיף לֵיהּ, שִׁית מֵאָה רְתִיכִין מְקַטְרְגִין לְסַיְּיעָא לֵיהּ. הֲדָא הוּא דִכְתִיב וַיִּקַּח שֵׁשׁ מֵאוֹת רֶכֶב <Nonei></i>בָּחוּר.</p>\n<p>אֵימָתַי אַשְׁלִים קוּדְשָׁא בְּרִיךְ הוּא לְסָמָאֵ\"ל. בִּקְרָבָא דְּסִיסְרָא, דְּעִקֵּר קוּדְשָׁא בְּרִיךְ הוּא לְכָל אִינּוּן רְתִיכִין, וְאִתְמְסָרוּ בִּידָא דְּמַטְרוֹנִיתָא. הֲדָא הוּא דִכְתִיב, (שופטים ה׳:כ״א) נַחַל קִישׁוֹן גְּרָפָם נַחַל קְדוּמִים וְגוֹ'. וּלְזִמְנָא דְּאָתֵי, יִתְמְסָרוּ כֻּלְּהוּ, הֲדָא הוּא דִכְתִיב, (ישעיהו ס״ג:א׳) מִי זֶה בָּא מֵאָדוֹם חֲמוּץ בְּגָדִים מִבָּצְרָה וְגוֹ'. וְעַל דָּא וַיֵּלֶךְ מֵאַחֲרֵיהֶם, דִּזְמִינָא שְׁכִינְתָּא בְּסוֹף יוֹמַיָּא לְאַעְקְרָא לוֹן מִן עָלְמָא.</p>\n<p>וַיִּסַּע עַמּוּד הֶעָנָן מִפְּנֵיהֶם, מַאן עַמּוּד הֶעָנָן דָּא. רִבִּי יוֹסֵי אָמַר, דָּא הוּא עֲנָנָא דְּאִתְחָזֵי תָּדִיר עִם שְׁכִינְתָּא. וְדָא הוּא עֲנָנָא דְּעָאל מֹשֶׁה בְּגַוֵּיהּ. רִבִּי אַבָּא אָמַר, כְּתִיב וַיְיָ' הוֹלֵךְ לִפְנֵיהֶם יוֹמָם, אֶלָּא סִיוּעָא דְּצַדִּיק הוּא, וּפְרִישׂוּ דִּרְשִׁימוּ דִּילֵיהּ, וְעַל דָּא אָזִיל הַאי עָנָן יוֹמָם, וּכְתִיב (תהילים מ״ב:ט׳) יוֹמָם יְצַוֶּה יְיָ' חַסְדּוֹ. וּמִסִּטְרָא דְּחֶסֶ\"ד אָתָא עֲנָנָא דָּא, וְדָא חֶסֶד אִתְקְרֵי, וַעֲנָנָא אַחֲרָא אָזִיל בְּלֵילְיָא, וְאִתְקְרֵי עַמּוּד אֵשׁ.</p>\n<p>רִבִּי שִׁמְעוֹן אָמַר, עַמּוּד הֶעָנָן יוֹמָם: דָּא אַבְרָהָם. וְעַמּוּד הָאֵשׁ לַיְלָה: דָּא יִצְחָק. וְתַרְוַויְיהוּ אִשְׁתְּכָחוּ בִּשְׁכִינְתָּא, וּמַה דְּאָמַר רִבִּי אַבָּא, הָכִי הוּא וַדַּאי, דְּעַל יְדָא דְּהַאי (נ\"א דבהאי) דַּרְגָּא, אִשְׁתְּכָחוּ.</p>\n<p>וְהַאי וַיִּסַּע מַלְאַךְ הָאֱלהִים הַהוֹלֵךְ לִפְנִי מַחֲנֵה יִשְׂרָאֵל וַיֵּלֶךְ מֵאַחֲרֵיהֶם. וַיִּסַּע: דְּנָטִיל מִסִּטְרָא דְּחֶסֶ\"ד, וְאִתְדְּבַק בְּסִטְרָא דִּגְבוּרָה, בְּגִין דְּהָא מָטָא שַׁעֲתָא לְאִתְלַבְּשָׁא בְּדִינָא.</p>"],[9520011612,"<p>תָּא חֲזֵי, בְּהַהִיא שַׁעֲתָא אִשְׁתְּלִים סִיהֲרָא מִכֹּלָּא, וְיָרְתָא שִׁבְעִין וּתְרֵין שְׁמָהָן קַדִּישִׁין, בִּתְלַת סִטְרִין. סִטְרָא חֲדָא אִתְלַבְּשָׁא בְּעִטְרוֹי דְּחֶסֶד עִלָּאָה, בְּשִׁבְעִין גְּלִיפִין דִּנְהִירוּ דְּאַבָּא עִלָּאָה, דְּאַנְהִיר לָהּ.</p>\n<p>סִטְרָא תִּנְיָינָא, אִתְלַבְּשַׁת בְּרוֹמְחֵי דִּגְבוּרָ\"ה, בְּשִׁתִין פּוּלְסֵי דְּנוּרָא, וַעֲשָׂרָה דִּילָהּ דִּנְחַתוּ מִסִּטְרָא דְּאִמָא עִלָּאָה בְּנִימוּסֵי גְּלִיפִין.</p>\n<p>סִטְרָא תְּלַתָאֵי, אִתְלַבְּשַׁת בִּלְבוּשֵׁי אַרְגְוָנָא, דְּלָבִישׁ מַלְכָּא עִלָּאָה קַדִּישָׁא, דְּאִקְרוּן תִּפְאֶרֶ\"ת, דְּיָרִית בְּרָא קַדִּישָׁא, בְּשִׁבְעִין עִטְרִין עִלָּאִין, מִסִּטְרָא דְּאַבָּא וְאִמָא, וְהוּא כָּלִיל לְהַאי סִטְרָא וּלְהַאי סִטְרָא.</p>\n<p>(ס\"א ותרין עטרין מסטרא דאבא ואימא, ואינון שבעין ותרין שמהן.) וְתָנֵינָן מִסִּטְרָא דְּחֶסֶ\"ד שִׁבְעִין וּתְרֵין סָהֲדִין. מִסִּטְרָא דִּגְבוּרָא שִׁבְעִין וּתְרֵין סוֹפְרִין. מִסִּטְרָא דְּת\"ת שִׁבְעִין וּתְרֵין גַּוְונִין לְאִתְפָּאַרָא.</p>\n<p>וּבְהַאי אֲתָר, אִתְגְּלִיף חַד בְּחַד, וְאִסְתְּלִיק שְׁמָא קַדִּישָׁא, רָזָא דִּרְתִּיכָא, וְהָכָא אִתְגְּלִיפוּ אֲבָהָתָא, לְאִתְחַבְּרָא בְּחַד, וְהוּא שְׁמָא קַדִּישָׁא גְּלִיפָא בְּאַתווֹי.</p>\n<p>צֵרוּפָא דְּאַתְוָון אִלֵּין, אַתְוָון קַדְמָאֵי, רְשִׁימִין כְּסִדְרָן בְּאֹרַח מֵישָׁר, בְּגִין דְּכֻלְּהוּ אַתְוָון קַדְמָאֵי אִשְׁתְּכָחוּ בְּחֶסֶ\"ד, לְמֵהַךְ בְּאֹרַח מֵישָׁר, בְּסִדּוּרָא מִתְתְּקָן.</p>\n<p>אַתְוָון תִּנְיָינֵי, רְשִׁימִין בְּגִלְגּוּלָא לְמַפְרֵעַ, בְּגִין דְּכֻלְּהוּ אַתְוָון תִּנְיָינֵי, מִשְׁתַּכְחוּ בִּגְבוּרָה, (ס\"א מגבורה) לְגַלָּאָה דִּינִין וְּזִינִין דְּאַתְיָין מִסִּטְרָא דִּשְׂמָאלָא.</p>\n<p>אַתְוָון תְּלִיתָאֵי, אִינּוּן אַתְוָון רְשִׁימָן, לְאַחֲזָאָה גַּוְונִין, לְאִתְעַטְּרָא בְּמַלְכָּא קַדִּישָׁא. וְכֹלָּא בֵּיהּ מִתְחַבְּרָן וּמִתְקַשְּׁרָן, וְהוּא אִתְעַטָּר בְּעִטְּרוֹי בְּאֹרַח מֵישָׁר, וְרָשִׁים לְהַאי סִטְרָא וּלְהַאי סִטְרָא, כְּמַלְכָּא דְּאִתְעַטָּר בְּכֹלָּא.</p>\n<p>הָכָא אִתְרְשִׁים שְׁמָא קַדִּישָׁא גְּלִיפָא בְּע\"ב תֵּיבִין, דְּמִתְעַטְּרֵי בַּאֲבָהָתָא, רְתִיכָא קַדִּישָׁא עִלָּאָה. וְאִי תֵּימָא, הָנֵי אַתְוָון תְּלִיתָאֵי, מַאי טַעְמָא לָאו אִינּוּן כְּתִיבִין, מִנְּהוֹן בְּאֹרַח מֵישָׁר כְּסִדּוּרָן, וּמִנְהוֹן לְמַפְרֵעַ, לְיַשְּׁרָא לְהַאי סִטְרָא, וּלְהַאי סִטְרָא, דְּהָא תָּנֵינָן, (תהילים צ״ט:ד׳) אַתָּה כּוֹנַנְתָּ מֵישָׁרִים, קוּדְשָׁא בְּרִיךְ הוּא עָבִיד מֵישָׁרִים לִתְרֵי סִטְרֵי, וּכְתִיב (שמותכו) וְהַבְּרִיחַ הַתִּיכוֹן בְּתוֹךְ הַקְּרָשִׁים וְגוֹ', דָּא קוּדְשָׁא בְּרִיךְ הוּא. רִבִּי יִצְחָק אָמַר, דָּא יַעֲקֹב, וְכֹלָּא חַד.</p>\n<p>אֶלָּא לְמַלְכָּא דְּאִיהוּ שְׁלִים מִכֹּלָּא, דַּעְתֵּיהּ שְׁלִים מִכֹּלָּא, מָה אָרְחֵיהּ דְּהַהוּא מַלְכָּא. אַנְפּוֹי נְהִירִין כְּשִׁמְשָׁא תָּדִיר, בְּגִין דְּאִיהוּ שְׁלִים. וְכַד דָּאִין, דָּאִין לְטָב וְדָאִין לְבִישׁ. וְעַל דָּא בָּעֵי לְאִסְתַּמְּרָא מִינֵּיהּ. מַאן דְּאִיהוּ טִפְּשָׁא, חָמֵי אַנְפּוֹי דְּמַלְכָּא נְהִירִין וְחַיְּיכָן, וְלָא אִסִתְּמַר מִינֵּיהּ. וּמַאן דְּאִיהוּ חַכִּימָא, אַף עַל גַּב דְּחָמֵי אַנְפּוֹי דְּמַלְכָּא נְהִירִין, אָמַר מַלְכָּא וַדַּאי שְׁלִים הוּא, שְׁלִים הוּא מִכֹּלָּא, דַּעְתֵּיהּ שְׁלִים, אֲנָא חָמֵי דִּבְהַהוּא נְהִירוּ, דִּינָא יָתִיב <Nonei></i>וְאִתְכַּסְיָא, אַף עַל גַּב דְּלָא אִתְחַזְיָא, דְּאִי לָאו הָכִי, לָא יְהֵא מַלְכָּא שְׁלִים, וְעַל דָּא בָּעֵי לְאִסְתַּמְּרָא.</p>\n<p>כַּךָ קוּדְשָׁא בְּרִיךְ הוּא, שְׁלִים תָּדִיר בְּהַאי גַּוְונָא וּבְהַאי גַּוְונָא, אֲבָל לָא אִתְחַזְיָא, אֶלָּא בִּנְהִירוּ דְּאַפִּין. וּבְגִין כַּךְ, אִינּוּן טִפְּשִׁין חַיָּיבִין לָא אִסְתַּמְּרָן מִנֵּיהּ. אִינּוּן חַכִּימִין זַכָּאִין, אַמְרִין, מַלְכָּא שְׁלִים הוּא, אַף עַל גַּב [אָמְרוּ הַמָגִיהִים כָּאן מָצָאנוּ כָּתוּב פָּסוּק וַיִסָע כָּסֶדֶר כָּל אוֹת וְאוֹת בְּבַיִת אֶחָד בִּמְרוּבָּע עִם זה בָּעֵי לְאִסְתַּמְּרָא מִנֵּיהּ.</p>\n<p>אָמַר רִבִּי יְהוּדָה, מֵהָכָא, (מלאכי ג׳:ו׳) אֲנִי יְיָ' לֹא שָׁנִיתִי. לָא דָּלִיגְנָא לַאֲתָר אַחֲרָא, בִּי אִתְכְּלִיל כֹּלָּא. הָנִי תְּרֵי גַּוְונֵי בִּי אִתְּכְּלִילָן, בְּגִין כַּךְ כֹּלָּא בְּאֹרַח מֵישָׁר אִתְחַזְיָא, וְאַף עַל גַּב דְּאַתְוָון אֲחִידָן לְהַאי סִטְרָא וּלְהַאי סִטְרָא, כְּסִדְרָן כְּתִיבִין.</p>\n<p>(שמות י״ד:י״ט) וַיִּסַּע מַלְאַךְ הָאֱלֹהִים הַהוֹלֵךְ לִפְנֵי מַחֲנֵה יִשְׂרָאֵל וַיֵּלֶךְ מֵאַחֲרֵיהֶם וַיִּסַּע עַמּוּד הֶעָנָן מִפְּנֵיהֶם וַיַּעֲמוֹד מֵאַחֲרֵיהֶם. עַד כָּאן סִטְרָא חַד, חֶסֶד לְאַבְרָהָם. אָמַר רִבִּי שִׁמְעוֹן, אֶלְעָזָר בְּרִי, תָּא חֲזֵי רָזָא דָּא. כַּד עַתִּיקָא קַדִּישָׁא אַנְהִיר לְמַלְכָּא, אַנְהִיר לֵיהּ, (ס\"א עטר ליה ואחסין ליה, בכתרין וכו') וְעִטְּרִין לֵיהּ, בְּכִתְרִין קַדִּישִׁין עִלָּאִין, כַּד מָטָאן לְגַבֵּיהּ מִתְעַטְּרֵי אֲבָהָתָא, בְּשַׁעֲתָה דְּמִתְעַטְּרֵי אֲבָהָתָא, כְּדֵין הוּא שְׁלִימוּ דְּכֹלָּא. כְּדֵין מַטְרוֹנִיתָא, נַטְלָא בְּמַטְלָנָהָא, (בההוא) (נ\"א בשולטנא בההיא) שְׁלִימוּ דַּאֲבָהָתָא. וְכַד מִתְעַטְּרָא מִכֻּלְּהוֹן, כְּדֵין אִתְבָּרְכָא, וּרְשׁוּתָא דְּכֹלָּא בִּידָהָא.</p>\n<p>כְּגַוונָא דָּא שְׁמָא קַדִּישָׁא גְּלִיפָא בְּאַתווֹי רְשִׁימִין בִּרְתִיכָא עִלָּאָה קַדִּישָׁא עִטּוּרָא דַּאֲבָהָן. <Nonesmall>אָמְרוּ הַמָגִיהִים כָּאן מָצָאנוּ כָּתוּב פָּסוּק וַיִסָע כָּסֶדֶר כָּל אוֹת וְאוֹת בְּבַיִת אֶחָד בִּמְרוּבָּע עִם זה הַלָּשׁוֹן עַד כָּאן אִתְתְקַנוּ טוּרִין כְּסִדְרָן בְּרָזָא דְחֶסֶד לָא סַטָאן לִימִּינָא וּשְׂמָאלָא. אַחַר כֵּן מָצָאנוּ פָּסוּק וַיָּבֹא לְמַפְרֵעַ כּמוֹ כֵן כָּל אוֹת וְאוֹת בְּבַיִת אֶחָד בִּמְרוּבָּע עִם זְהִ הַלָּשׁוֹן עַד כָּאן אִתְתְקַנוּ טוּרִין לְמפרֵעַ בְּרָזָא דִּגְבוּרָה כֻּלְהוּ שְׂמֹאלָא כְּלִילָן בִּימִינָא. אַחַר כָּךְ מָצָאנוּ פָּסוּק וָיֵט כַּסֶדֶר כְּמוֹ כֵן כָּל אוֹת וְאוֹת בְּבַיִת אֶחָד בִּמְרוּבָּע עִם זה הַלָּשׁוֹן עַד כָּאן כְּלִילָן טוּרִין דִּשְׁמָא קַדִּישָׁא בְּתִפְאֶרֶת לְבַתָר מִתְחֲבְּרָן אֲבָהָן וְאִתְעַבִידוּ שֶׁמָּא קַדִּישָׁא. וְאַחַר כָּךְ מָצָאנוּ הע\"ב שְׁמוֹת הַיוֹצְאִים מִשלשָׁה פְּסוּקִים אֵלּוּ בִּמְרוּבָּע כָּל שםׁ וְשֵׁם מִשלשָׁה אוֹתִיּוֹת הַיוֹצְאִים מִשְׁלשָׁה פְּסוּקִים אֵלּוּ יָשָׁר הָפוּךְ יָשָׁר וְהַסִימָן יה\"י אוֹר עִם זֶהּ הַלָּשׁוֹן הָא כְּגַוְנָא דָא שֶׁמָּא קַדִּישָׁא גְלִיפָא בְּאַתְווֹי רְשִׁימִין בִּרְתִיכָא עִלָּאָה קַדִּישָׁא עִטוּרָא דְאֲבַהָן. ולא הדפסנו אותו כאן מפני יקר תפארת גדולתו. (והודפס בסוף הספר)</small></p>\n<p>(אמר רבי ייסא, אשכחנא ברזא דא בתקיעותא (ס\"א דרב בבבל) דרב המנונא סבא, תלת ובכן ובכן ובכן, לקבלי הני תלת. וכך הוא סדורא. אמר רבי יוסי, כלא אתכליל בהאי שמא (נ\"א שליחא) קדישא, ואסתיים ביה, אשתכח דשלימו דרתיכא קדישא אית ביה.)</p>\n<p>אָמַר רִבִּי שִׁמְעוֹן, הַאי הוּא שְׁמָא קַדִּישָׁא, עִטּוּרָא דַּאֲבָהָן, דְּמִתְעַטְרָא בְּגִלּוּפַיְיהוּ, בְּחִבּוּרָא כַּחֲדָא. שְׁלִימוּ דִּרְתִיכָא קַדִּישָׁא. וְאִתְכְּלִיל בְּאַרְבְּעִין וּתְמַנְיָא תֵּיבוּתָא, דְּאִיהוּ שְׁלִימוּ דְּכֹלָּא, וְעִקָרָא דְּשָׁרָשִׁין.</p>\n<p>תָּא חֲזֵי, גּוּפָא דְּאִילָנָא, אֲנִ\"י אָלֶ\"ף (ויקרא קנ\"א) נוּ\"ן יוֹ\"ד. רֵישָׁא דְּכָל עַנְפֵי אִילָנָא, וָה\"וּ. (וה\"ו) וְהָא אִתְּעֲרוּ חַבְרַיָּא, כְּלָלָא דַּעֲנָפִין וְנוֹפָא וְשָׁרָשָׁא, בְּאַרְבְּעִין וּתְמַנְיָא תֵּיבִין. וְהָא אִתְרְשִׁים בִּתְלַת עָלְמִין עִלָּאִין, ובג' עָלְמִין תַּתָּאִין.</p>\n<p>לָקֳבְלֵיהּ, קָדוֹשׁ קָדוֹשׁ קָדוֹשׁ ה' צְבָאוֹת. קָדוֹשׁ לְעֵילָּא. קָדוֹשׁ בְּאֶמְצָעִיתָא. קָדוֹשׁ לְתַתָּא. קָדוֹשׁ חֶסֶד. קָדוֹשׁ גְּבוּרָה. קָדוֹשׁ תִּפְאֶרֶת. וְכֻלְּהוּ בְּשִׁבְעִין וּתְרֵין אִתְגְּלִיפוּ, כְּמָה דְּאִתְּמַר. בְּרִיךְ הוּא, בְּרִיךְ שְׁמֵיהּ לְעָלַם וּלְעָלְמֵי עָלְמִין אָמֵן.</p>\n<p>אָמַר רִבִּי יִצְחָק, בְּשַׁעֲתָא דְּשָׁרוּ יִשְׂרָאֵל עַל יַמָּא, חָמוּ לְכַמָּה <Nonei></i>אֹכְלוֹסִין, לְכַמָּה חַיָּילִין, לְכַמָּה מַשִּׁירְיָין, מֵעֵילָּא וְתַתָּא, וְכֻלְּהוּ בִּכְנוּפְיָא עֲלַיְיהוּ דְּיִשְׂרָאֵל, שָׁרִיאוּ בִּצְלּוֹ מִגּוֹ עָאקוּ דִּלְהוֹן.</p>\n<p>בֵּיהּ שַׁעֲתָא, חָמוּ יִשְׂרָאֵל עָאקוּ מִכָּל סִטְרִין, יַמָּא בְּגַלּוֹהִי דְּזַקְפָן קָמַיְיהוּ. בַּתְרַיְיהוּ, כָּל אִינּוּן אֹכְלוֹסִין, כָּל אִינּוּן מַשִּׁירְיָין דְּמִצְרַיִם, לְעֵילָּא עֲלַיְיהוּ כַּמָּה קַטֵיגוֹרִין. שָׁרִיאוּ צַוְוחִין לְקוּדְשָׁא בְּרִיךְ הוּא.</p>\n<p>כְּדֵין כְּתִיב, וַיֹּאמֶר יְיָ' אֶל מֹשֶׁה מַה תִּצְעַק אֵלָי. וְתָאנָא בְּסִפְרָא דִּצְנִיעוּתָא, אֵלַי, (כ\"א ע\"א) דַּיְיקָא, בְּעַתִּיקָא תַּלְיָא כֹּלָּא. בֵּיהּ שַׁעֲתָא אִתְגְּלֵי עַתִּיקָא קַדִּישָׁא, וְאִשְׁתְּכַח רַעֲוָא בְּכֻלְּהוּ עָלְמִין עִלָּאִין, כְּדֵין נְהִירוּ דְּכֹלָּא, אִתְנְהִיר.</p>\n<p>אָמַר רִבִּי יִצְחָק, כְּדֵין, כַּד אִתְנְהִיר כֹּלָּא כַּחֲדָא, וְעָבִיד יַמָּא נִימּוּסִין עִלָּאִין, וְאִתְמְסָרוּ בִּידוֹי עִלָּאִין וְתַתָּאִין. וּבְגִינֵי כַּךְ, קַשְׁיָא קַמֵי קוּדְשָׁא בְּרִיךְ הוּא כֹּלָּא, כִּקְרִיעַת יָם סוֹף, וְכֹלָּא הָכִי אוּקְמוּהָ. מַאי טַעֲמָא. בְּגִין דִּקְרִיעַת יָם (בראשית ר\"ס ע\"א) סוּף בְּעַתִּיקָא תַּלְיָיא.</p>\n<p>אָמַר רִבִּי שִׁמְעוֹן, חַד אַיַּילְתָּא אִית בְּאַרְעָא, וְקוּדְשָׁא בְּרִיךְ הוּא עָבִיד סַגְיָא בְּגִינָהּ, בְּשַׁעֲתָא דְּהִיא צוֹוַחַת, קוּדְשָׁא בְּרִיךְ הוּא שָׁמַע עָאקוּ דִּילָהּ, וְקָבִּיל קַלָהּ. וְכַד אִצְטְרִיךְ עָלְמָא לְרַחֲמֵי לְמַיָּיא, הִיא יָהָבַת קָלִין, וְקוּדְשָׁא בְּרִיךְ הוּא שָׁמַע קַלָהּ, וּכְדֵין חַיִּיס עַל עָלְמָא, הֲדָא הוּא דִכְתִיב, (תהילים מ״ב:ב׳) כְּאַיָּל תַּעֲרוֹג עַל אֲפִיקֵי מָיִם.</p>\n<p>וְכַד בַּעְיָא לְאוֹלָדָא, הִיא סְתִימָא מִכָּל סִטְרִין, כְּדֵין אַתְיָיא וְשַׁוִּיאַת רֵישָׁא בֵּין בִּרְכָּהָא, וְצוֹוַחַת וְרָמַת קַלִין, וְקוּדְשָׁא בְּרִיךְ הוּא חַיִּיס עָלָּה, (רי\"ט ע\"ב) וְזַמִּין לְקַבְּלָהּ חַד נָחָשׁ, וְנָשִׁיךְ בְּעַרְיָיתָא דִּילָהּ, וּפָתַח לָהּ, וְקָרַע לָהּ הַהוּא אֲתָר, וְאוֹלִידַת מִיָּד. אָמַר רַבִּי שִׁמְעוֹן בְּהַאי מִלָּה, לָא תִּשְׁאַל וְלָא תְּנַסֶּה אֶת יְיָ', וְהָכִי דַּיְיקָא.</p>\n<p>(שמות י״ד:ל׳) וַיּוֹשַע יְיָ' בְּיוֹם הַהוּא אֶת יִשְׂרָאֵל וְגוֹ', וַיַּרְא יִשְׂרָאֵל אֶת מִצְרַיִם מֵת, הַהוּא שֻׁלְטָנָא מְמָנָא דְּמִצְרָאֵי, אַחְמֵי לוֹן קוּדְשָׁא בְּרִיךְ הוּא, דְּאַעְבַּר לֵיהּ, בִּנְהַר (ז' ע\"א, רכ\"ב ע\"ב) דִּינוּר, דְּהֲוָה בִּשְׂפָתָא דְּיַמָּא רַבָּא. מֵת, מַאי טַעֲמָא מֵת. כְּמָה דְּאוּקְמוּהָ, דְּאַעְבְּרוּ לֵיהּ, מֵהַהוּא שֻׁלְטָנוּתָא דִּילֵיהּ.</p>"],[9520011613,"<p>(שמות י״ד:ל״א) וַיַּרְא יִשְׂרָאֵל אֶת הַיָּד הַגְּדוֹלָה וְגוֹ'. רִבִּי חִיָּיא אָמַר, הָכָא אִשְׁתְּלִים יְדָא, וְכֻלְּהוּ אֶצְבְּעָן, וְאִשְׁתְּלִים יְדָא, דְּאִתְכְּלִיל בֵּיהּ בִּימִינָא, דְּהָכִי תָּנִינָן, כֹּלָּא בִּימִינָא אִתְכְּלִיל, וּבִימִינָא תַּלְיָא, הֲדָא הוּא דִּכְתִּיב, יְמִינְךָ יְיָ' נֶאְדָּרִי בַּכֹּחַ יְמִינְךָ יְיָ' תִּרְעַץ אוֹיֵב.</p>\n<p>וְאָמַר רִבִּי יִצְחָק, לָא אַשְׁכַּחְנָא, מַאן דְּאַתְקִיף לִבֵּיהּ, לְגַבֵּיהּ קוּדְשָׁא בְּרִיךְ הוּא, כְּפַרְעֹה. אָמַר רִבִּי יוֹסֵי, סִיחוֹן וְעוֹג הָכִי נַמֵּי. אָמַר לֵיהּ, לָאו הָכִי. אִינּוּן לְגַבֵּיהּ דְּיִשְׂרָאֵל אִתְתְּקָפוּ, אֲבָל לְגַבֵּיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא, לָא, כְּמָה דְּאִתְּקַף פַּרְעֹה רוּחֵיהּ לָקֳבְלֵיהּ, וַהֲוָה חָמֵי כָּל יוֹמָא גְּבוּרָאן דִּילֵיהּ, וְלָא הֲוָה תָּב.</p>\n<p>אָמַר רִבִּי יְהוּדָה אָמַר רִבִּי יִצְחָק, פַּרְעֹה חַכִּים מִכָּל חֲרָשׁוֹי הֲוָה, וּבְכָל אִינּוּן כִּתְרִין, וּבְכָל אִינּוּן יְדִיעָן, אִסְתָּכַּל. וּבְכָל סִטְרָא דִּלְהוֹן, לָא חָמָא פּוּרְקָנָא דִּלְהוֹן יִשְׂרָאֵל, וְלָא הֲוָה תָּלֵי בְּחַד מִנַּיְיהוּ. וְעוֹד, דְּהָא בְּכֻלְּהוּ קְשִׁירוּ קִשְׁרָא עֲלַיְיהוּ דְּיִשְׂרָאֵל, וּפַרְעֹה לָא סָבַר דְּאִית קִשְׁרָא אַחֲרָא דִּמְהֵימָנוּתָא, דְּאִיהוּ שַׁלִיט עַל כֹּלָּא. וְעַל דָּא הֲוָה אַתְקִיף לִבֵּיהּ.</p>\n<p>רִבִּי אַבָּא אָמַר, לָא אַתְקִיף לִבָּא דְּפַרְעֹה, אֶלָּא שְׁמָא דָּא. דְּכַד הֲוָה אָמַר מֹשֶׁה, כֹּה אָמַר יְיָ', דָּא מִלָּה מַמָּשׁ, אַתְקִיף לִבֵּיהּ, הֲדָא הוּא דִּכְתִּיב, (שמות ט׳:י״ב) וַיְחַזֵּק יְיָ' אֶת לֵב פַּרְעֹה. דְּהָא בְּכָל חָכְמְתָא דִּילֵיהּ, לָא אִשְׁתְּכַח, דִּשְׁמָא דָּא שָׁלִיט בְּאַרְעָא. וְעַל דָּא אָמַר, מִי יְיָ'. וּלְבָתַר אָמַר, יְיָ' הַצַּדִּיק. אָמַר רִבִּי יוֹסֵי, לְבָתַר אָמַר, (שמות י) חָטָאתִי לַיְיָ' הַהוּא פּוּמָא דְּאָמַר דָּא, אָמַר דָּא.</p>\n<p>רִבִּי חִזְקִיָּה פָּתַח וְאָמַר, (איוב ט׳:כ״ב) אַחַת הִיא עַל כֵּן אָמַרְתִּי תָּם וְרָשָׁע הוּא מְכַלֶּה. הַאי קְרָא, אוּקְמוּהָ בְּרָזָא דְּחָכְמְתָא. אַחַת הִיא, מַאי אַחַת הִיא. הֲדָא הוּא דִּכְתִּיב, (שיר השירים ו׳:ט׳) אַחַת הִיא יוֹנָתִי תַמָּתִי אַחַת הִיא לְאִמָּהּ. וּבְהַאי, קוּדְשָׁא בְּרִיךְ הוּא דָּאִין דִּינוֹי לְתַתָּא, וְדָאִין דִּינוֹי לְעֵילָּא בְּכֹלָּא.</p>\n<p>וְכַד קוּדְשָׁא בְּרִיךְ הוּא אִתְּעַר דִּינוֹי, דָּאִין דִּינוֹי בְּהַאי כִּתְרָא, כְּדֵין כְּתִיב, תָּם וְרָשָׁע הוּא מְכַלֶּה. <Nonei></i>בְּגִין דְּאִינּוּן צַדִּיקַיָּיא, מִתַּפְסָאן בְּחוֹבֵיהוֹן דְּרַשִׁיעַיָּא, דִּכְתִּיב, (שמואל ב כ״ד:ט״ז) וַיֹּאמֶר יְיָ' לַמַּלְאָךְ הַמַּשְׁחִית בָּעָם רַב וְגוֹ', וְעַל דָּא אָמַר (ר' יוסי) אִיּוֹב מִלָּה דָּא, (אמר) וְלא אַגְמָר מִלָּה, וְאוֹקְמוּהָ טוֹל הַרָב, רִבִּי יֵיסָא אָמַר, אַחַת הִיא: דָּא כְּנֶסֶת יִשְׂרָאֵל בְּגָלוּתָא דְּמִצְרַיִם, דִּבְגִינָהּ קָטַל קוּדְשָׁא בְּרִיךְ הוּא בְּמִצְרָאֵי, וְעָבִיד בְּהוּ נוּקְמִין, הֲדָא הוּא דִכְתִיב תָּם וְרָשָׁע הוּא מְכַלֶּה.</p>\n<p>ר' חִיָּיא אָמַר, אִיּוֹב לָא אַלְקֵי, אֶלָּא בְּזִמְנָא דְּנָפְקוּ יִשְׂרָאֵל מִמִּצְרַיִם. אָמַר אִיּוֹב, אִי הָכִי, כָּל אַפַּיָּיא שָׁוִין, תָּם וְרָשָׁע הוּא מְכַלֶּה, פַּרְעֹה אַתְקִיף בְּהוּ בְּיִשְׂרָאֵל, וְאָמַר (שמות ה׳:ב׳) מִי יְיָ' אֲשֶׁר אֶשְׁמַע בְּקוֹלוֹ. וַאֲנָא לָא אַתְקִיפְנָא בְּהוּ, וְלָא עֲבִידְנָא מִידִי, תָּם וְרָשָׁע הוּא מְכַלֶּה. הֲדָא הוּא דִכְתִיב, (שמות ט׳:כ׳) הַיָּרֵא אֶת דְּבַר יְיָ' מֵעַבְדֵי פַּרְעֹה, זֶה אִיּוֹב.</p>\n<p>ר' יְהוּדָה אָמַר, אִינּוּן אַבְנֵי בַּרְדָּא, דַּהֲווֹ נַחְתִּין, אִתְעַכְּבוּ עַל יְדוֹי דְּמֹשֶׁה, לְבָתַר עָבְדוּ נוּקְמִין, בְּיוֹמֵי דִּיהוֹשֻׁעַ. וּלְזִמְנָא דְּאָתֵי, זְמִינִין לְאַחֲתָא אִינּוּן דְּאִשְׁתָּאָרוּ, עַל אֱדוֹם וּבְנוֹתֶיהָ. אָמַר רִבִּי יוֹסֵי, הֲדָא הוּא דִכְתִיב, (מיכה ז׳:ט״ו) כִּימֵי צֵאתְךָ מֵאֶרֶץ מִצְרָיִם אַרְאֶנּוּ נִפְלָאוֹת.</p>\n<p>דָּבָר אַחֵר וַיַּרְא יִשְׂרָאֵל אֶת הַיָּד הַגְּדוֹלָה וְגוֹ', הַאי קְרָא לָאו רֵישֵׁיהּ סֵיפֵיהּ, וְלָאו סֵיפֵיהּ רֵישֵׁיהּ. בְּקַדְמִיתָא וַיַּרְא יִשְׂרָאֵל, וּבָתַר וַיִּירְאוּ הָעָם אֶת יְיָ'. אֶלָּא אָמַר רִבִּי יְהוּדָה, הַהוּא סָבָא דְּנָחַת עִם בְּנוֹי בְּגָלוּתָא, וְסָבִיל עָלֵיהּ גָּלוּתָא, וְאָעִיל לִבְנוֹי בְּגָלוּתָא, הוּא מַמָּשׁ חָמָא, כָּל אִינּוּן נוּקְמִין, וְכָל גְּבוּרָאן, דְּעָבַד קוּדְשָׁא בְּרִיךְ הוּא בְּמִצְרַיִם, הֲדָא הוּא דִכְתִיב וַיַּרְא יִשְׂרָאֵל, יִשְׂרָאֵל מַמָּשׁ.</p>\n<p>וְאָמַר רִבִּי יְהוּדָה, סָלִיק קוּדְשָׁא בְּרִיךְ הוּא לְהַאי סָבָא, וְאֲמַר לֵיהּ, קוּם חָמֵי בְּנָיךְ דְּנָפְקִין מִגּוֹ עַמָּא תַּקִּיפָא. קוּם חָמֵי גְּבוּרָן דַּעֲבָדִית, בְּגִין בְּנָיךְ בְּמִצְרַיִם.</p>\n<p>וְהַיְינוּ דְּאָמַר רִבִּי יֵיסָא, בְּשַׁעֲתָא דְּנַטְלֵי יִשְׂרָאֵל לְנַחְתָּא בְּגָלוּתָא דְּמִצְרַיִם, דְּחִילוּ וְאֵימָתָא תַּקִּיפָא נָפַל עֲלוֹי. אָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא לְיַעֲקֹב, אֲמַאי אַתְּ דָּחִיל, (בראשית מ״ו:ג׳) אַל תִּירָא מֵרְדָה מִצְרַיְמָה. מִמַּה דִּכְתִּיב אַל תִּירָא, מַשְׁמַע דְּחִילוּ הֲוָה דָּחִיל.</p>\n<p>אָמַר לֵיהּ כִּי לְגוֹי גָּדוֹל אֲשִׂימְךָ שָׁם. אָמַר לֵיהּ, דָּחִילְנָא דִּי יְשִׁיצוּן בָּנַי. אָמַר לֵיהּ, אָנֹכִי אֵרֵד עִמְּךָ מִצְרַיְמָה. אָמַר לֵיהּ תּוּ דָּחִילְנָא, דְּלָא אַזְכֵּי לְאִתְקַבְּרָא בֵּינִי אֲבָהָתַי, וְלָא אַחְמֵי פּוּרְקָנָא דְּבָנַי, וּגְבוּרָאן דְּתַעְבִיד לְהוּ. אָמַר לֵיהּ, וְאָנֹכִי אֲעַלְךָ גַּם עָלה, אַעַלְךָ לְאִתְקַבְּרָא בְּקִבְרֵי אֲבָהָתָךְ. גַּם עָלֹה, לְמֵחֱמֵי פּוּרְקָנָא דִבְרָךְ, וּגְבוּרָאן דְּאַעֲבִיד לְהוּ.</p>\n<p>וְהַהוּא יוֹמָא דְּנָפְקוּ יִשְׂרָאֵל מִמִּצְרַיִם, סָלִיק לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא לְיַעֲקֹב, וְאָמַר לֵיהּ, קוּם, חָמֵי בְּפוּרְקָנָא דִבְרָךְ, דְּכַמָּה חֵילִין וּגְבוּרָאן עֲבָדִית לְהוּ, וְיַעֲקֹב הֲוָה תַּמָן, וְחָמָא כֹּלָּא, הֲדָא הוּא דִכְתִיב וַיַּרְא יִשְׂרָאֵל אֶת הַיָּד הַגְּדוֹלָה.</p>\n<p>ר' יִצְחָק אָמַר, מֵהָכָא, (דברים ד׳:ל״ז) וַיּוֹצִיאֲךָ בְּפָנָיו בְּכֹחוֹ הַגָּדוֹל מִמִּצְרַיִם. מַאי בְּפָנָיו. בְּפָנָיו דָּא יַעֲקֹב, דְּאָעִיל לְכֻלְּהוּ תַּמָּן. רִבִּי חִזְקִיָּה אָמַר, וַיּוֹצִיאֲךָ בְּפָנָיו, בְּפָנָיו: דָּא אַבְרָהָם. דִּכְתִּיב, (בראשית י״ז:י״ז) וַיִּפֹּל אַבְרָהָם עַל פָּנָיו.</p>\n<p>תָּא חֲזֵי, אַבְרָהָם אָמַר, הַלְּבֶן מֵאָה שָׁנָה יִוָּלֵד וְגוֹ', אָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, חַיֶּיךָ, אַתְּ תֶּחמֵי כַּמָּה אֹכְלוֹסִין, וְכַמָּה חַיָּילִין דְּיִפְקוּן מִמְּךָ. בְּשַׁעֲתָא דְּנָפְקוּ יִשְׂרָאֵל מִמִּצְרַיִם, כָּל אִינּוּן שְׁבָטִין, כָּל אִינּוּן רִבְוָון, סָלִיק קוּדְשָׁא בְּרִיךְ הוּא לְאַבְרָהָם, וְחָמָא לוֹן, הֲדָא הוּא דִכְתִיב וַיּוֹצִיאֲךָ בְּפָנָיו. רִבִּי אַבָּא אָמַר כֻּלְּהוּ אֲבָהָתָא אִזְדְּמָנוּ תַּמָּן בְּכָל הַהוּא פּוּרְקָנָא. הֲדָא הוּא דִּכְתִּיב וַיּוֹצִיאֲךָ בְּפָנָיו. מַאי בְּפָנָיו אִלֵּין אֲבָהָתָא.</p>\n<p>רִבִּי אֶלְעָזָר אָמַר, וַיּוֹצִיאֲךָ בְּפָנָיו: דָּא יַעֲקֹב. בְּכֹחוֹ: דָּא יִצְחָק. הַגָּדוֹל: דָּא אַבְרָהָם. אָמַר רִבִּי שִׁמְעוֹן, וְכֵן בְּגִינֵיהוֹן דַּאֲבָהָתָא, אִזְדָּמַן פּוּרְקָנָא תָּדִיר לְיִשְׂרָאֵל, דִּכְתִּיב (ויקרא כ״ו:מ״ב) וְזָכַרְתִּי אֶת בְּרִיתִי יַעֲקוֹב וְאַף אֶת בְּרִיתִי יִצְחָק וְאַף אֶת בְּרִיתִי אַבְרָהָם אֶזְכּוֹר וְהָאָרֶץ אֶזְכּוֹר. אֲבָהָתָא תִּינַח, מַהוּ וְהָאָרֶץ אֶזְכּוֹר. אֶלָּא, לְאַכְלְלָא עִמְּהוֹן דָּוִד מַלְכָּא, דְּאִיהוּ רְתִיכָא בַּאֲבָהָתָא <Nonei></i>וְאִינּוּן מִתְעָרִין פּוּרְקָנָא תָּדִיר לְיִשְׂרָאֵל.</p>\n<p>וַיַּרְא יִשְׂרָאֵל אֶת הַיָּד הַגְּדוֹלָה אֲשֶׁר עָשָׂה יְיָ' בְּמִצְרַיִם. וְכִי הַשְׁתָּא עָשָׂה, וְהָא מִקַּדְמַת דְּנָא אִתְעָבִיד, מַאי אֶת הַיָּד הַגְּדוֹלָה אֲשֶׁר עָשָׂה יְיָ'. אֶלָּא, יַד לָא אִקְרֵי פָּחוּת מֵחָמֵשׁ אֶצְבְּעָאן. הַגְּדוֹלָה: דִּכְלִילָן בָּהּ חָמֵשׁ אֶצְבְּעָאן אַחֲרָנִין, וְאִתְקְרוּן כְּדֵין גְּדוֹלָה. וְכָל אֶצְבְּעָא וְאֶצְבְּעָא, סָלִיק לְחוּשְׁבָּנָא רַבָּא, וְקוּדְשָׁא בְּרִיךְ הוּא עָבִיד בְּהוּ (ס\"א השתא ניסין) נִיסִּין וּגְבוּרָן, וּבְהַאי אִתְעַקְּרוּ כֻּלְּהוּ דַּרְגִּין מִשִּׁלְשׁוּלֵיהוֹן.</p>\n<p>מִכָּאן אוֹלִיפְנָא דָּא, דִּבְחָמֵשׁ אֶצְבְּעָאן קָמָאי, כְּתִיב, וַיְחַזֵּק לֵב פַּרְעֹה, כֵּיוָן דְּאִשְׁתְּלָמוּ אִינּוּן חָמֵשׁ, תּוּ לָא הֲוָה מִלָּה בִּרְשׁוּתֵיהּ דְּפַרְעֹה, כְּדֵין כְּתִיב וַיְחַזֵּק יְיָ' אֶת לֵב פַּרְעֹה.</p>\n<p>וְעַל דָּא וַיַּרְא יִשְׂרָאֵל אֶת הַיָּד הַגְּדוֹלָה וְגוֹ', וַיַּאֲמִינוּ בַּיְיָ'. וְכִי עַד הַשְׁתָּא לָא הֶאֱמִינוּ בַּיְיָ', וְהָא כְּתִיב (שמות ד׳:ל״א) וַיַּאֲמֵן הָעָם וַיִּשְׁמְעוּ וְגוֹ'. וְהָא חָמוּ כָּל אִינּוּן גְּבוּרָאן דְּעָבַד לְהוּ קוּדְשָׁא בְּרִיךְ הוּא בְּמִצְרַיִם. אֶלָּא מַאי וַיַּאֲמִינוּ, הַהוּא מִלָּה דְּאָמַר וַיֹּאמֶר מֹשֶׁה אֶל הָעָם אַל תִּירָאוּ הִתְיַצְּבוּ וּרְאוּ וְגוֹ'.</p>\n<p>ר' יֵיסָא שָׁאִיל וְאָמַר, כְּתִיב וַיַּרְא יִשְׂרָאֵל אֶת מִצְרַיִם מֵת, וּכְתִיב לא תּוֹסִיפוּ לִרְאוֹתָם עוֹד עַד עוֹלָם. אָמַר רִבִּי יוֹסֵי, מֵתִין חָמוּ לְהוּ. אָמַר לֵיהּ, אִי כְּתִיב לא תּוֹסִיפוּ לִרְאוֹתָם חַיִּים, הֲוָה אֲמֵינָא הָכִי. אָמַר לֵיהּ ר' אַבָּא יֵאוֹת שָׁאִילְתָּא.</p>\n<p>אֶלָּא תָּא חֲזֵי, כְּתִיב (דברי הימים א ט״ז:ל״ו) מִן הָעוֹלָם וְעַד הָעוֹלָם, וְתָנֵינָן, עוֹלָם לְעֵילָּא, וְעוֹלָם לְתַתָּא. עוֹלָם דִּלְעֵילָּא, מִתַּמָּן הוּא שֵׁירוּתָא לְאַדְלְקָא בּוּצִינִין. עוֹלָם דִּלְתַתָּא, תַּמָּן הוּא סִיּוּמָא, וְאִתְכְּלִיל מִכֹּלָּא, וּמֵהַאי עוֹלָם דִּלְתַתָּא, מִתְעֲרָן גְּבוּרָן לְתַתָּאֵי.</p>\n<p>וּבְהַאי עוֹלָם, עָבִיד קוּדְשָׁא בְּרִיךְ הוּא אָתִין לְיִשְׂרָאֵל, וְרָחִישׁ לוֹן נִיסָא. וְכַד אִתְּעַר הַאי עוֹלָם לְמֶעְבַּד נִסִּין, כֻּלְּהוּ מִצְרָאֵי אִשְׁתְּקָעוּ בְּיַמָּא, עַל יְדָא דְּהַאי עוֹלָם, וְאִתְרְחִישׁ לוֹן לְיִשְׂרָאֵל נִיסָא בְּהַאי עוֹלָם. וְעַל דָּא כְּתִיב, לֹא תּוֹסִיפוּ לִרְאוֹתָם עוֹד עַד עוֹלָם, עַד דְּיִתְּעַר הַהוּא עוֹלָם, וְיִתְמַסְּרוּן בְּדִינוֹי, וְכֵיוָן דְּאִתְמְסָרוּ בֵּיהּ לְמִתְּדָן, כְּדֵין כְּתִיב וַיַּרְא יִשְׂרָאֵל אֶת מִצְרַיִם מֵת עַל שְׂפַת הַיָּם, הֲדָא הוּא דִכְתִיב מִן הָעוֹלָם וְעַד הָעוֹלָם, עַד הָעוֹלָם דַּיְקָא. כְּדֵין כְּתִיב, וַיַּאֲמִינוּ בַּיְיָ' וּבְמֹשֶׁה עַבְדּוֹ.</p>"],[9520011614,"<p>(שמות ט״ו:א׳) אָז יָשִׁיר מֹשֶׁה. ר' יְהוּדָה פָּתַח, (ירמיהו א׳:ה׳) בְּטֶרֶם אֶצָּרְךָ בַבֶּטֶן יְדַעְתִּיךָ וְגוֹ'. זַכָּאָה חוּלָקֵיהוֹן דְּיִשְׂרָאֵל, דְּקוּדְשָׁא בְּרִיךְ הוּא אִתְרְעֵי בְּהוּ יַתִּיר מִכָּל שְׁאַר עַמִּין. וּמִסְּגִיאוּת רְחִימוּתָא דְּרָחִים לְהוּ, אוֹקִים עָלַיְיהוּ נְבִיאָה דִּקְשׁוֹט, וְרַעְיָא מְהֵימָנָא. וְאִתְּעַר עָלֵיהּ רוּחָא קַדִּישָׁא, יַתִּיר מִכָּל שְׁאַר נְבִיאֵי מְהֵימְנֵי, וְאַפִּיק לֵיהּ מֵחוּלָקֵיהּ מַמָּשׁ, מִמַּה דְּאַפְרִישׁ יַעֲקֹב מִבְּנוֹי לְקוּדְשָׁא בְּרִיךְ הוּא, שִׁבְטָא דְּלֵוִי, וְכֵיוָן דְּהֲוָה לֵוִי דִּילֵיהּ, נָטַל לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, וְאַעְטַר לֵיהּ בְּכַמָּה עִטְרִין, וּמָשַׁח לֵיהּ בִּמְשַׁח רְבוּת קַדִּישָׁא דִּלְעֵילָּא, וּכְדֵין אַפִּיק מִבְּנוֹי, רוּחָא קַדִּישָׁא לְעָלְמָא, וְזָרִיז לֵיהּ בְּהֵימְנוֹיֵי קַדִּישֵׁי, מְהֵימָנוּתָא רַבָּא.</p>\n<p>תָּנָא, בְּהַהִיא שַׁעֲתָא דְּמָטָא זִמְנֵיהּ דְּמֹשֶׁה נְבִיאָה מְהֵימָנָא לְאַחֲתָא לְעָלְמָא, אַפִּיק קוּדְשָׁא בְּרִיךְ הוּא רוּחָא קַדִּישָׁא מִגִּזְרָא דִּסַפִּירוּ דְּאֶבֶן טָבָא, דְּהֲוָה גָּנִיז בְּמָאתַן וְאַרְבְּעִין וּתְמַנְיָא (נהורין, ואתנהיר עליה. ואעטריה בשס\"ה) עִטְּרִין, קַיְימֵי קָמֵיהּ, וְאַפְקִיד לֵיהּ בְּכָל דִּילֵיהּ. (נ\"א ביתיה) וְיָהַב לֵיהּ מֵאָה וְשִׁבְעִין וּתְלַת מַפְתְּחִין. (נ\"א גניז תמן ואעטריה בתלת מאה ושתין וחמש עטרי ואנהיר עליה מאתן וארבעין ותמניא נהורין וקאים קמיה ואפקיד ליה בכל ביתא דיליה ויהב ליה מאה ושבעין ותלת מפתחן. (נ\"א מאתן ושבעין וחמש)) וְאַעְטַר לֵיהּ בְּחָמֵשׁ עִטְרִין, וְכָל עִטְרָא וְעִטְרָא סָלִיק וְאַנְהִיר בְּאֶלֶף עָלְמִין דְּנַהֲרִין, וּבוּצִינִין דּגְנִיזִין בְּגִנְזַיָּיא דְּמַלְכָּא קַדִּישָׁא עִלָּאָה.</p>\n<p>כְּדֵין אַעְבְּרֵיהּ בְּכָל בּוּצִינִין (נ\"א בוסמין) דִּבְגִּנְתָּא דְּעֵדֶן, וְאַעֲלֵיהּ בְּהֵיכָלֵיהּ, וְאַעְבְּרֵיהּ בְּכָל חַיָּילִין וְגַיָּיסִין דִּילֵיהּ. כְּדֵין אִזְדַּעְזְעוּ כֻּלְּהוּ, פָּתְחוּ וְאָמְרוּ, אִסְתָּלָקוּ מִסַּחֲרָנֵיהּ, (סטרא דסטרין) דְּהָא קוּדְשָׁא בְּרִיךְ הוּא אִתְּעַר רוּחָא לְשַׁלְּטָאָה לְמִרְגַּז עָלְמִין. קָלָא נָפַק וְאָמַר, מַאן הוּא דֵּין, דְּכָל מַפְתְּחָן אִלֵּין <Nonei></i>בִּידוֹי. פָּתַח קָלָא אַחֲרָא וְאָמַר, קַבִּילוּ לֵיהּ בְּגַוַּויְיכוּ, דָּא הוּא דְּזַמִּין לְנַחְתָּא בֵּין בְּנִי נָשָׁא, וּזְמִינָא אוֹרַיְיתָא, גְּנִיזָא דְּגִנְזַיָּיא, לְאִתְמַסְּרָא בִּידוֹי, וּלְאַרְעֲשָׁא עָלְמִין דִּלְעֵילָּא וְתַתָּא עַל יְדָא דְּדֵין. בֵּיהּ שַׁעֲתָא אִתְרְגִישׁו כֻּלְּהוּ, וְנַטְלִין אֲבַתְרֵיהּ, פָּתְחוּ וְאָמְרוּ, (תהילים ס״ו:י״ב) הִרְכַּבְתָּ אֱנוֹשׁ לְרֹאשֵׁנוּ בָּאנוּ בָּאֵשׁ וּבַמַּיִם.</p>\n<p>כְּדֵין סַלְּקָא הַהוּא רוּחָא, וְקַיְּימָא קָמֵי מַלְכָּא. מ פְּתִיחָא, סָלִיק וְאִתְעַטָּר בְּעִטְּרוֹי, וְאַעְטְרֵיהּ בִּתְלַת מְאָה וְעֶשְׂרִין וְחָמֵשׁ עִטְּרִין, וְאַפְקִיד מַפְתְּחוֹי בִּידוֹי. ש דַּאֲבָהָתָא, אַעְטְרוּ לֵיהּ בִּתְלַת עִטְּרִין קַדִּישִׁין, וְאַפְקִידוּ כָּל מַפְתְּחָן דְּמַלְכָּא בִּידֵיהּ, וְאַפְקִידוּ לֵיהּ בְּהֵימְנוּתָא, מְהֵימָנָא דְּבֵיתָא. ה סַלְּקָא וְאִתְעַטְּרָא בְּעִטְּרוֹי, וְקַבִּילַת לֵיהּ מִן מַלְכָּא.</p>\n<p>כְּדֵין, נָחַת הַהוּא רוּחָא בְּאַרְבִּין דְּשָׁאטָן, בְּהַהוּא יַמָּא רַבָּא, וְקַבִּילַת לֵיהּ לְגַדְּלָא לֵיהּ לְמַלְכָּא, וְהִיא יָהָבַת לֵיהּ מִתַּמָּן זִיּוּנִין, לְאַלְקָאָה לְפַרְעֹה וּלְכָל אַרְעֵיהּ. וּבְשַׁבְּתָא וּבְרֵישֵׁי יַרְחֵי, סַלְקַת לֵיהּ לְמַלְכָּא, כְּדֵין אִקְרֵי שְׁמֵיהּ, בְּאִלֵּין אַתְוָון רְשִׁימִין.</p>\n<p>וּבְהַהִיא שַׁעֲתָא, דְּנָפַק לְנַחְתָּא לְאַרְעָא, בְזַרְעָא דְּלֵוִי, אִתְתָּקָנוּ אַרְבַּע מְאָה וְעֶשְׂרִין וְחָמֵשׁ בּוּצִינִין לְמַלְכָּא, וְאַרְבַּע מְאָה וְעֶשְׂרִין וְחָמֵשׁ גְּלִיפִין מְמָנָן, אוֹזְפוּהָ לְהַהוּא רוּחָא לְאַתְרֵיהּ, כַּד נָפַק לְעָלְמָא, אִתְנַהֲרָא בְּאַנְפּוֹי, וּבֵיתָא אִתְמַלְיָיא מִזִּיוְתֵיהּ. בֵּיהּ שַׁעֲתָא, קָרָא עָלֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, בְּטֶרְם אֶצָּרְךָ בַבֶּטֶן יְדַעְתִּיךָ וּבְטֶרֶם תֵּצֵא מֵרֶחֶם הִקְדַּשְׁתִּיךָ נָבִיא לַגּוֹיִם נְתַתִּיךָ.</p>\n<p>רִבִּי יִצְחָק אָמַר, בֵּיהּ שַׁעֲתָא קָטַל (נ\"א אפיל) קוּדְשָׁא בְּרִיךְ הוּא לְרַבְרְבָא מְמָנָא דְּמִצְרָאֵי, וְחָמוּ לֵיהּ מֹשֶׁה וּבְנִי יִשְׂרָאֵל, כְּדֵין אָמְרוּ שִׁירָה. הֲדָא הוּא דִכְתִיב, וַיַּרְא יִשְׂרָאֵל אֶת מִצְרַיִם מֵת, אָז יָשִׁיר מֹשֶׁה וּבְנֵי יִשְׂרָאֵל.</p>\n<p>(שמות ט״ו:א׳) אָז יָשִׁיר מֹשֶׁה וּבְנִי יִשְׂרָאֵל וְגוֹ'. רִבִּי אַבָּא פָּתַח וְאָמַר, אִסְתַּכַּלְנָא בְּכָל תּוּשְׁבְּחָן דְּשַׁבְּחוּ לְקוּדְשָׁא בְּרִיךְ הוּא, וְכוּלָּם פָּתְחוּ בְּאָז. (מלכים א ח׳:י״ב) אָז אָמַר שְׁלֹמֹה. (יהושע י׳:י״ב) אָז יְדַבֵּר יְהוֹשֻׁעַ, (במדבר כ״א:י״ז) אָז יָשִׁיר יִשְׂרָאֵל. מַאי טַעְמָא.</p>\n<p>אֶלָּא הָכִי תָּאנָא, כָּל נִסִּין וְכָל גְּבוּרָן דְּאִתְעָבֵידוּ לְהוּ לְיִשְׂרָאֵל, כַּד אִתְנְהִיר נְהִירוּ דְּעַתִּיקָא קַדִּישָׁא בְּעִטְּרוֹי, גְּלִיפִין רְשִׁימִין בְּאָז, בא', וא', בד, אַנְקִיב בַּחֲשׁוֹכֵי, וְנָהִיר לְכָל עִיבָר. וְכַד אִתְחַבָּר נְהִירוּ דְּאָלֶ\"ף וּמָטֵי לְזַיִי\"ן, מַאן זַיִי\"ן, דָּא (ישעיה לה) חֶרֶב לַיְיָ' מָלְאָה דָּם. כְּדֵין עָבִיד נִסִּין וּגְבוּרָאן, בְּגִין דְּאִתְחֲבָּר א' עִם ז'. וְדָא הוּא שִׁירָתָא. שִׁירָתָא הִיא דְּכָל סִטְרִין, וְדָא הוּא אָז יָשִׁיר.</p>\n<p>יָשִׁיר, שַׂר מִבָּעֵי לֵיהּ. אֶלָּא מִלָּה דָּא תַּלְיָא, וְאַשְׁלִים לְהַהוּא זִמְנָא, וְאַשְׁלִים לְזִמְנָא דְּאָתֵי, דִּזְמִינִין יִשְׂרָאֵל לְשַׁבְּחָא שִׁירָתָא דָּא מֹשֶׁה וּבְנֵי יִשְׂרָאֵל, מִכָּאן אוֹלִיפְנָא, דְּצַדִּיקַיָּיא קַדְמָאֵי, אַף עַל גַּב דְּאִסְתָּלָקוּ בְּדַרְגִּין עִלָּאִין דִּלְעֵילָּא, וְאִתְקַשָּׁרוּ בְּקִשּׁוּרָא דִּצְרוֹרָא דְּחַיֵּי, זְמִינִין כֻּלְּהוּ לְאַחֲיָיא בְּגוּפָא, וּלְמֶחמֵי אַתְיָין וּגְבוּרָן דְּקָא עָבִיד קוּדְשָׁא בְּרִיךְ הוּא לְיִשְׂרָאֵל. וּלְמֵימָר שִׁירָתָא דָּא, הֲדָא הוּא דִכְתִיב אָז יָשִׁיר מֹשֶׁה וּבְנֵי יִשְׂרָאֵל.</p>\n<p>ר' שִׁמְעוֹן אָמַר מֵהָכָא, (ישעיהו י״א:י״א) יוֹסִיף יְיָ' שֵׁנִית יָדוֹ לִקְנוֹת אֶת שְׁאַר עַמּוֹ. לִקְנוֹת: כְּמָה דְאַתְּ אָמֵר, (משלי ח׳:כ״ב) יְיָ' קָנָנִי רֵאשִׁית דַּרְכּוֹ. אֶת שְׁאַר עַמּוֹ: אִלֵּין אִינּוּן צַדִּיקַיָּיא דִּבְּהוֹן, דְּאִקְרוּן שְׁאַר, כְּמָה דְאַתְּ אָמֵר (במדבר י״א:כ״ו) וַיִּשָּׁאֲרוּ שְׁנֵי אֲנָשִׁים בְּמַּחֲנֶה. וְתָנֵינָן, לֵית עָלְמָא מִתְקַיְּימָא אֶלָּא עַל אִינּוּן דְּעַבְדֵי גַּרְמַיְיהוּ שִׁירַיִים.</p>\n<p>וְאִי תֵּימָא, הוֹאִיל וְאִתְקַשָּׁרוּ בִּצְרוֹרָא דְּחַיֵּי, וּמִתְעַנְּגֵי בְּעִנּוּגָא עִלָּאָה, אֲמַאי יָחִית לוֹן קוּדְשָׁא בְּרִיךְ הוּא לְאַרְעָא. פּוּק וְאוֹלִיף מִזִּמְנָא קַדְמָאָה, דְּכָל אִינּוּן רוּחִין וְנִשְׁמָתִין, דַּהֲווֹ בְּדַרְגָּא עִלָּאָה דִּלְעֵילָּא וְקוּדְשָׁא בְּרִיךְ הוּא אָחִית לְהוּ לְאַרְעָא לְתַתָּא. כָּל שֶׁכֵּן הַשְׁתָּא, דְּבָעֵי קוּדְשָׁא בְּרִיךְ הוּא לְיַשְּׁרָא לַעֲקִימָא, כְּמָה דְאַתְּ אָמֵר (קהלת ז׳:כ׳) כִּי אָדָם אֵין צַדִּיק בָּאָרֶץ אֲשֶׁר יַעֲשֶׂה טוֹב וְלא יֶחטָא. וְאִי תֵּימָא, אִינּוּן דְּמִיתוּ בְּעֶטְיוֹ דְּנָחָשׁ. אֲפִילוּ אִינּוּן יְקוּמוּן, וִיהוֹן מָארֵי דְּעֵיטָא, לְמַלְכָּא מְשִׁיחָא.</p>\n<p>וְעַל דָּא תָּנֵינָן, מֹשֶׁה זַמִּין לְמֵימָר שִׁירָתָא לְזִמְנָא דְּאָתֵי. מַאי טַעְמָא. בְּגִין דִּכְתִּיב, (מיכה ז׳:ט״ו) כִּימֵי צֵאתְךָ מֵאֶרֶץ מִצְרַיִם אַרְאֶנּוּ נִפְלָאוֹת. אַרְאֶנּוּ, אַרְאֶךָ מִבָּעֵי לֵיהּ. אֶלָּא אַרְאֶנּוּ מַמָּשׁ, לְמַאן דְּחָמָא בְּקַדְמִיתָא, יֶחמֵי לֵיהּ תִּנְיָינוּת, וְדָא הוּא אַרְאֶנּוּ, וּכְתִיב (תהילים נ׳:כ״ג) אַרְאֶנּוּ בְּיֵשַׁע אֱלהִים, וְאַרְאֵהוּ בִּישׁוּעָתִי. <Nonei></i>וּכְדֵין אָז יָשִׁיר מֹשֶׁה וּבְנֵי יִשְׂרָאֵל אֶת הַשִּׁירָה הַזֹּאת לַיְיָ'.</p>\n<p>שִׁירָתָא דְּמַטְרוֹנִיתָא לְקוּדְשָׁא בְּרִיךְ הוּא. תָּנֵינָן, כָּל בַּר נָשׁ דְּאָמַר שִׁירָתָא דָּא בְּכָל יוֹמָא, וּמְכַוֵּון בָּהּ, זָכֵי לְמֵימְרָא לְזִמְנָא דְּאָתֵי. דְּהָא אִית בָּהּ עָלְמָא דְּעָבַר, וְאִית בָּהּ עָלְמָא דְּאָתֵי, וְאִית בָּהּ קִשְׁרֵי מְהֵימָנוּתָא, וְאִית בָּהּ יוֹמֵי דְּמַלְכָּא מְשִׁיחָא. (נ\"א את לעילא כל אינון וכו') וְתָלֵי עָלָהּ, כָּל אִינּוּן תּוּשְׁבְּחָאן אַחֲרָנִין, דְּקַאמְרֵי עִלָּאֵי וְתַתָּאֵי.</p>\n<p>הַשִּׁירָה שִׁיר זֶה מִבָּעֵי לֵיהּ. אֶלָּא שִׁירָתָא, דְּקָא מְשַׁבָּחַת מַטְרוֹנִיתָא לְמַלְכָּא. וּמֹשֶׁה מִתַּתָּא לְעֵילָּא קָאָמַר, וְהָא אוּקְמוּהָ. לַיְיָ': בְּגִין דְּאַנְהִיר לָהּ מַלְכָּא אַנְפָּהָא, (נ\"א דנהיר אנפוי מלכא לקבלה) ר' יוֹסֵי אָמַר, דְּכָל אִינּוּן מְשָׁחִין, דַּהֲווֹ נַגְדִּין, מָשִׁיךְ מַלְכָּא קַדִּישָׁא לְקַבְּלָהּ, בְּגִינִי כַּךְ מְשַׁבְּחָא לֵיהּ מַטְרוֹנִיתָא.</p>\n<p>אָמַר רִבִּי יְהוּדָה, אִי הָכִי, אֲמַאי כְּתִיב מֹשֶׁה וּבְנִי יִשְׂרָאֵל, וְהָא מַטְרוֹנִיתָא בַּעְיָא לְשַׁבְּחָא. אֶלָּא, זַכָּאָה חוּלָקֵיהוֹן דְּמֹשֶׁה וְיִשְׂרָאֵל, דְּאִינּוּן הֲווֹ יַדְעִין לְשַׁבְּחָא לְמַלְכָּא, בְּגִין מַטְרוֹנִיתָא כְּדְקָא יֵאוֹת, בְּגִין דְּכָל הַהוּא חֵילָא וּגְבוּרָה דִּילָהּ, יָרְתָא מִן מַלְכָּא.</p>\n<p>ר' חִיָּיא פָּתַח וְאָמַר, (איכה ב׳:י״ט) קוּמִי רוֹנִּי בַּלַּיְלָה לְרֹאשׁ אַשְׁמוּרוֹת. קוּמִי רוֹנִּי: דָּא כְּנֶסֶת יִשְׂרָאֵל. בַּלַּיְלָה: בְּגָלוּתָא. ר' יוֹסֵי אָמַר, בַּלַּיְלָה: בְּזִמְנָא דְּהִיא שַׁלְטָא וּמִתְּעָרָא, לְרֹאשׁ אַשְׁמוּרוֹת, בְּרֹאשׁ מִבָּעֵי לֵיהּ. אֶלָּא לְרֹאשׁ, כְּמָה דִּכְתִּיב, (בראשית מ״ז:ל״א) עַל רֹאשׁ הַמִּטָּה. וְאוֹקִימְנָא, רֹאשׁ הַמִּטָּה, דָּא יְסוֹד. אוּף הָכָא לְרֹאשׁ, דָּא יְסוֹד, דְּמַטְרוֹנִיתָא מִתְבָּרְכָא בֵּיהּ. רֹאשׁ אַשְׁמוּרוֹת: דָּא הוּא רֵישָׁא, דְּנֶצַח וְהוֹד.</p>\n<p>ר' יוֹסֵי אָמַר, דָּא הוּא רִישָׁא דְּכִתְרֵי מַלְכָּא וְסִיּוּמָא. רִבִּי אַבָּא אָמַר, לְרֹאשׁ אַשְׁמְרוֹת כְּתִיב חָסֵר, וְדָא הוּא רֵישָׁא, רֹאשׁ הַמִּטָּה. וְכֹלָּא בְּמַלְכָּא קַדִּישָׁא עִלָּאָה אִתְּמַר, וְדָא הוּא לַיְיָ'.</p>\n<p>רִבִּי יֵיסָא אָמַר, הַשִּׁירָה הַזֹּאת לַיְיָ', דָּא הוּא נַהֲרָא דְּנָפִיק מֵעֵדֶן, דְּכָל מִשְׁחָא וּרְבוּ נָפִיק מִנֵּיהּ, לְאַדְלְקָא בּוּצִינִין. וּמַשְׁמַע לְבָתַר דִּכְתִּיב אָשִׁירָה לַיְיָ', דָּא הוּא מַלְכָּא קַדִּישָׁא עִלָּאָה, וְעַל דָּא לָא כְּתִיב אָשִׁירָה לּוֹ.</p>\n<p>וַיֹּאמְרוּ לֵאמֹר, לְדָרֵי דָּרִין, בְּגִין דְּלָא יִתְנְשֵׁי מִנַּיְיהוּ לְעָלְמִין. דְּכָל מַאן דְּזָכֵי לְהַאי שִׁירָתָא בְּהַאי עָלְמָא, זָכֵי לָהּ בְּעָלְמָא דְּאָתֵי, וְזָכֵי לְשַׁבְּחָא בָּהּ בְּיוֹמוֹי דְּמַלְכָּא מְשִׁיחָא, בְּחֶדְוָותָא דְּכְּנְסֶת יִשְׂרָאֵל בְּקוּדְשָׁא בְּרִיךְ הוּא. דִּכְתִּיב לֵאמֹר, לֵאמֹר בְּהַהוּא זִמְנָא. לֵאמֹר בְּאַרְעָא קַדִּישָׁא, בְּזִמְנָא דְּשָׁרוּ יִשְׂרָאֵל בְּאַרְעָא. לֵאמֹר בְּגָלוּתָא. לֵאמֹר בְּפוּרְקָנָא דִּלְהוֹן דְּיִשְׂרָאֵל. לֵאמֹר לְעָלְמָא דְּאָתֵי.</p>\n<p>אָשִׁירָה לַיְיָ' נָשִׁיר מִבָּעֵי לֵיהּ, מַאי אָשִׁירָה. אֶלָּא בְּגִין דַּהֲווֹ מְשַׁבְּחָן תּוּשַׁבַּחְתָּא דְּמַטְרוֹנִיתָא. (בעו לשבחא) לַיְיָ': דָּא מַלְכָּא קַדִּישָׁא. כִּי גָאֹה גָּאָה (קמה): דְּסָלִיק וְאִתְעַטָּר בְּעִטְרוֹי, לְאַפָּקָא בִּרְכָּאן וְחֵילִין וּגְבוּרָאן, לְאַסָּקָא בְּכֹלָּא. כִּי גָאֹה גָּאָה: גָאֹה בְּהַאי עָלְמָא, גָּאָה בְּעָלְמָא דְּאָתֵי. כִּי גָאֹה בְּהַהוּא זִמְנָא, גָּאָה, בְּגִין דְּיִתְעֲטָּר בְּעִטְּרוֹי בְּחֶדְוָותָא שְׁלֵימוּתָא.</p>\n<p>סוּס וְרוֹכְבוֹ רָמָה בַּיָּם, שׁוּלְטָנוּתָא דִּלְתַתָּא, וְשׁוּלְטָנוּתָא דִּלְעֵילָּא דַּאֲחִידָן בְּהוּ, אִתְמְסָרוּ בְּהַהוּא יַמָּא רַבָּא, וְשֻׁלְטָנוּתָא רַבָּא לְמֶעְבַּד בְּהוּ נוּקְמִין. וְתָנֵינָן, לָא עָבִיד קוּדְשָׁא בְּרִיךְ הוּא דִּינָא לְתַתָּא, עַד דְּיַעֲבֵיד בְּשׁוּלְטָנֵיהוֹן לְעֵילָּא, הֲדָא הוּא דִכְתִיב, (ישעיהו כ״ד:כ״א) יִפְקוֹד יְיָ' עַל צְבָא הַמָּרוֹם בַּמָּרוֹם וְעַל מַלְכֵי הָאֲדָמָה עַל הָאֲדָמָה.</p>\n<p>רָמָה בַּיָּם, אָמַר ר' יְהוּדָה, בֵּיהּ בְּלֵילְיָא, אִתְּעַר גְּבוּרָא תַּקִּיפָא, דִּכְתִּיב בֵּיהּ וַיּוֹלֶךְ יְיָ' אֶת הַיָּם בְּרוּחַ קָדִים עַזָּה כָּל הַלַּיְלָה. (ס\"א דאתער ביה גבורה תקיפא) בְּהַהוּא זִמְנָא, בָּעָאת מַטְרוֹנִיתָא מִן מַלְכָּא, כָּל אִינּוּן אֹכְלוֹסִין דִּלְתַתָּא, וְכָל אִינּוּן שׁוּלְטָנִין דִּלְעֵילָּא, דְּיִתְמַסְּרוּן בִּידָהָא. וְכֻלְּהוּ אִתְמְסָרוּ בִּידָהָא, לְמֶעְבַּד בְּהוּ נוּקְמִין, הֲדָא הוּא דִכְתִיב סוּס וְרוֹכְבוֹ רָמָה בַּיָּם. בַּיָּם סְתָם, לְעֵילָּא וְתַתָּא.</p>"],[9520011615,"<p>(שמות ט״ו:ב׳) עָזִּי וְזִמְרָת יָהּ. רִבִּי חִיָּיא פָּתַח וְאָמַר, (תהילים קל״ט:ה׳) אָחוֹר וְקֹדֶם צַרְתָּנִי וַתָּשֶׁת עָלַי כַּפֶּכָה. כַּמָּה אִצְטְרִיכוּ בְּנֵי נָשָׁא לְיַקָרָא לְקוּדְשָׁא בְּרִיךְ הוּא, בְּגִין דְּקוּדְשָׁא בְּרִיךְ הוּא כַּד בָּרָא עָלְמָא, <Nonei></i>אִסְתָּכַּל בֵּיהּ בָּאָדָם לְמֶהוֵי שַׁלִּיט עַל כֹּלָּא. (נ\"א למהוי שלים בכלא ואתברי דו פרצופין) וַהֲוָה דָּאמֵי לְעִלָּאִין וְתַתָּאִין. נָחַת לֵיהּ בִּדְמוּת יַקִּירָא, וְחָמוּ לֵיהּ בִּרְיָין, כְּדֵין אִתְכְּנָשׁוּ לְגַבֵּיהּ, וְסָגִידוּ לָקֳבְלֵיהּ, וְאֵימָתָא וְדַחֲלָא נָפְלַת עָלַיְיהוּ מִדַּחַלְתֵּיהּ, הֲדָא הוּא דִכְתִיב, (בראשית ט׳:ב׳) וּמוֹרַאֲכֶם וְחִתְּכֶם יִהְיֶה עַל כָּל חַיַּת הָאָרֶץ וְעַל כָּל עוֹף הַשָּׁמָיִם.</p>\n<p>עַיְילֵיהּ לְגִנְתֵּיהּ דְּנָטַע, לְנַטְרֵיהּ לְמֶהֱוֵי לֵיהּ חֵדוּ עַל חִדוּ, וּלְאִשְׁתַּעְשְׁעָ בֵּיהּ. עָבֵד לֵיהּ טְרוֹצְטְבוּלִין מְחַפְּיָין בְּאַבְנֵי יְקָר, וּמַלְאָכִין עִלָּאִין חַדָּאן קָמֵיהּ. לְבָתַר פָּקִיד לֵיהּ עַל אִילָנָא חַד וְלָא קָאִים בְּפִקּוּדָא דְּמָארֵיהּ.</p>\n<p>אַשְׁכַּחְנָא בְּסִפְרָא דְּחֲנוֹךְ, דִּלְבָתַר דְּסָלִיק לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, וְאַחְמֵי לֵיהּ כָּל גִּנְזַיָּיא דְּמַלְכָּא, עִלָּאֵי וְתַתָּאֵי, אַחְמֵי לֵיהּ אִילָנָא דְּחַיֵּי, וְאִילָנָא דְּאִתְפְּקַד עָלֵיהּ אָדָם, וְאַחְמֵי לֵיהּ דּוּכְתֵּיהּ דְּאָדָם בְּגִנְתָּא דְּעֵדֶן. וְחָמָא, דְּאִלְמָלֵי נָטִיר אָדָם פִּקּוּדָא דָּא, יָכִיל לְקַיְּימָא תָּדִירָא, וּלְמֶהֱוֵי תָּדִירָא תַּמָּן. הוּא לָא נָטַר פִּקּוּדָא דְּמָארֵיהּ, נָפַק בְּדִימוֹס וְאִתְעֲנָשׁ.</p>\n<p>רִבִּי יִצְחָק אָמַר, אָדָם דּוּ פַּרְצוּפִין אִתְבְּרֵי, וְהָא אוֹקִימְנָא, (בראשית ב׳:כ״א) וַיִּקַּח אַחַת מִצַּלְעוֹתָיו, נְסָרוֹ הַקָדוֹשׁ בָּרוּךְ הוּא וְאִתְעָבִידוּ תְּרֵין, מִמִּזְרָח וּמִמַּעֲרָב, הֲדָא הוּא דִּכְתִּיב, (תהילים קל״ט:ה׳) אָחוֹר וְקֶדֶם צַרְתָּנִי. אָחוֹר דָּא מַעֲרָב, וְקֶדֶם דָּא מִזְרָח.</p>\n<p>ר' חִיָּיא אָמַר, מַה עָבִיד קוּדְשָׁא בְּרִיךְ הוּא, תַּקִּין לְהַהוּא נוּקְבָּא וְשַׁכְלִיל שְׁפִירוּתָהּ עַל כֹּלָּא, וְעַיְילָהּ לְאָדָם, הֲדָא הוּא דִכְתִיב וַיִּבֶן יְיָ' אֱלֹהִים אֶת הַצֵּלָע אֲשֶׁר לָקַח מִן הָאָדָם לְאִשָּׁה. תָּא חֲזֵי, מַה כְּתִיב לְעֵילָּא, וַיִּקַּח אַחַת מִצַּלְעוֹתָיו. מַאי אַחַת. כְּמָה דְאַתְּ אָמֵר (שיר השירים ו׳:ט׳) אַחַת הִיא יוֹנָתִי תַּמָּתִי אַחַת הִיא לְאִמָּהּ. מִצַּלְעוֹתָיו: מִסִּטְרוֹי. כְּמָה דְאַתְּ אָמֵר, (שמות כ״ו:כ׳) וּלְצֶלַע הַמִּשְׁכָּן.</p>\n<p>ר' יְהוּדָה אָמַר, קוּדְשָׁא בְּרִיךְ הוּא נִשְׁמְתָא עִלָּאָה יָהַב בֵּיהּ בְּאָדָם, וְכָלִיל בֵּיהּ חָכְמְתָא וְסָכְלְתָנוּ, לְמִנְדַּע כֹּלָּא. מֵאָן אֲתָר יָהַב בֵּיהּ נִשְׁמְתָא. ר' יִצְחָק אָמַר, מֵאֲתָר דִּשְׁאַר נִשְׁמָתִין קַדִּישִׁין קָא אַתְיָין.</p>\n<p>ר' יְהוּדָה אָמַר, מֵהָכָא. דִּכְתִּיב, (בראשית א׳:כ״ד) תּוֹצֵא הָאָרֶץ נֶפֶשׁ חַיָּה, מַאן הָאָרֶץ. מֵהַהוּא אֲתָר דְּמַקְדְּשָׁא אִשְׁתְּכַח בֵּיהּ. נֶפֶשׁ חַיָּה, נֶפֶשׁ חַיָּה סְתָם, דָּא נַפְשָׁא דְּאָדָם קַדְמָאָה דְּכֹלָּא.</p>\n<p>ר' חִיָּיא אָמַר, אָדָם הֲוָה יָדַע חָכְמְתָא עִלָּאָה, יַתִּיר מִמַּלְאֲכֵי עִלָּאֵי, וַהֲוָה מִסְתַּכֵּל בְּכֹלָּא, וְיָדַע וְאִשְׁתְּמוֹדָע לְמָארֵיהּ, יַתִּיר מִכָּל שְׁאַר בְּנֵי עָלְמָא. בָּתַר דְּחָב, אַסְתִּימוּ מִנֵיהּ מַבּוּעֵי דְּחָכְמְתָא, מַה כְּתִיב (נ\"א ממדז דכתיב) (בראשית ג׳:כ״ג) וַיְשַׁלְּחֵהוּ יְיָ' אֱלהִים מִגַּן עֵדֶן לַעֲבוֹד אֶת הָאֲדָמָה.</p>\n<p>ר' אַבָּא אָמַר, אָדָם הָרִאשׁוֹן מִדְּכַר וְנוּקְבָּא אִשְׁתְּכַח, הֲדָא הוּא דִכְתִיב, (בראשית א׳:כ״ו) וַיֹּאמֶר אֱלֹהִים נַעֲשֶׂה אָדָם בְּצַלְמֵנוּ כִּדְמוּתֵינוּ, וְעַל דָּא, דְּכַר וְנוּקְבָּא אִתְעָבִידוּ כַּחֲדָא, וְאִתְפְּרָשׁוּ לְבָתַר. וְאִי תֵּימָא, הָא דְּאָמַר הָאֲדָמָה אֲשֶׁר לֻקַּח מִשָׁם. הָכִי הוּא וַדַּאי, וְדָא הִיא נוּקְבָּא, וְקוּדְשָׁא בְּרִיךְ הוּא אִשְׁתָּתַּף עִמָּהּ, וְדָא הוּא דְּכָר וְנוּקְבָּא, וְכֹלָּא הוּא מִלָּה חֲדָא.</p>\n<p>ר' יוֹסֵי אָמַר, עָזִּי וְזִמְרָת יָהּ, אִינּוּן דִּכְלִילָן דָּא בְּדָא וְלָא (נ' ע\"ב) אִתְפָּרְשָׁאן דָּא מִן דָּא וּלְעָלְמִין אִינּוּן בַּחֲבִיבוּתָא, בִּרְעוּתָא חֲדָא, דְּמִתַּמָּן אִשְׁתְּכָחוּ (נ\"א אתמשכו) מְשִׁיכָן דְּנַחֲלִין וּמַבּוּעִין לְאִסְתַּפְּקָא כֹּלָּא, וּלְבָרְכָא כֹּלָּא, לָא כְּדִיבוּ מֵימֵי מַבּוּעִין, כְּמָה דְאַתְּ אָמֵר (ישעיהו נ״ח:י״א) וּכְמוֹצָא מַיִם אֲשֶׁר לא יְכַזְּבוּ מֵימָיו וְעַל דָּא וַיְהִי לִי לִישׁוּעָה, דִּבְגִינֵי כַּךְ, מַלְכָּא קַדִּישָׁא מָשִׁיךְ וְאַחֲסִין לְתַתָּא, וְאִתְּעַר יְמִינָא לְמֶעְבַּד נִסִּין.</p>\n<p>זֶה אֵלִי וְאַנְוֵהוּ. דָּא צַדִּיק, דְּמִנֵּיהּ נָפְקִין בִּרְכָּאן בְּזִוּוּג. וְאַנְוִהוּ: בְּהַהוּא אֲתָר דַּחֲבִיבוּתָא אִשְׁתְּכַח בֵּיהּ, וְדָא הוּא מַקְדְּשָׁא. אֱלהֵי אָבִי וַאֲרוֹמְמֶנְהוּ, מֹשֶׁה קָאָמַר דָּא, לְגַבֵּי אֲתָר דְּלֵוָאֵי אַתְיָין מֵהַהוּא סִטְרָא וְעַל דָּא (הוה) שְׁלֵימוּתָא דְּכֹלָּא הוּא בְּהַהוּא אֲתָר. (נ\"א בהאי קרא)</p>\n<p>ר' יִצְחָק אָמַר, וַיְהִי לִי לִישׁוּעָה, דָּא מַלְכָּא קַדִּישָׁא, וְהָכִי הוּא. וּמְנָלָן. מִקְרָא אַחֲרִינָא אַשְׁכַּחְנָא לֵיהּ, דִּכְתִּיב, (ישעיהו י״ב:ב׳) כִּי עָזִּי וְזִמְרָת יָהּ יְיָ' וַיְהִי לִי לִישׁוּעָה, מִמַּשְׁמַע דְּקָאָמַר יְיָ' וַיְהִי לִי לִישׁוּעָה, <Nonei></i>דָּא מַלְכָּא קַדִּישָׁא.</p>\n<p>(שמות ט״ו:ב׳) עָזִּי וְזִמְרָת יָהּ וְגוֹ', ר' חִזְקִיָּה פָּתַח וְאָמַר, בְּהַאי קְרָא דִּכְתִּיב, (משלי י״ז:י״ז) בְּכָל עֵת אוֹהֵב הָרֵעַ וְאָח לְצָרָה יִוָּלֵד. בְּכָל עֵת אוֹהֵב הָרֵעַ, דָּא קוּדְשָׁא בְּרִיךְ הוּא, דִּכְתִּיב בֵּיהּ (משלי כ״ז:י׳) רֵעֲךָ וְרֵעַ אָבִיךָ אַל תַּעֲזוֹב.</p>\n<p>וְאָח לְצָרָה יִוָּלֵד, בְּשַׁעֲתָא דִּיעִיקוּן לָךְ שַׂנְאָךְ, קוּדְשָׁא בְּרִיךְ הוּא מַה אָמַר, (תהילים קכ״ב:ח׳) לְמַעַן אַחַי וְרֵעָי אֲדַבְּרָה נָא שָׁלוֹם בְּךָ, דְּיִשְׂרָאֵל, אִקְרוּן אַחִים וְרֵעִים לְקוּדְשָׁא בְּרִיךְ הוּא. יִוָּלֵד מַהוּ, וְכִי הַשְׁתָּא יִוָּלֵד. אֶלָּא בְּשַׁעֲתָא דְּעַקְתָּא יִוָּלֵד בְּעָלְמָא, אָח יְהֵא לָקֳבְלָךְ, לְשֵׁזָבָא לָךְ מִכָּל אִינּוּן דְּעָקִין לָךְ.</p>\n<p>רִבִּי יְהוּדָה אָמַר, יִוָּלֵד: דְּמַלְכָּא קַדִּישָׁא יִתְּעַר בְּהַאי עֹז, לְנַקְמָא לָךְ מֵאוּמִין, לְיַנְקָא לָךְ מֵאִימָא, בְּהַהוּא סִטְרָא, כְּמָה דְאַתְּ אָמֵר, עָזִּי וְזִמְרָת יָהּ וַיְהִי לִי לִישׁוּעָה. לְאִתְּעָרָא גְּבוּרָאן לָקֳבֵל אוּמִין עוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת.</p>\n<p>ר' יֵיסָא פָּתַח וְאָמַר, כַּמָּה אִית לֵיהּ לְבַר נָשׁ לְרַחֲמָא, לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא, דְּהָא לֵית לֵיהּ פּוּלְחָנָא לְקוּדְשָׁא בְּרִיךְ הוּא, (אלא) (כמה) רְחִימוּתָא. וְכָל מַאן דְּרָחִים לֵיהּ, וְעָבִיד פּוּלְחָנָא בִּרְחִימוּתָא, קָארֵי לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא רְחִימָא. אִי הָכִי, בְּמָאי אוֹקִימְנָא הָנִי קְרָאֵי, רֵעֲךָ וְרֵעַ אָבִיךָ אַל תַּעֲזוֹב. וּכְתִיב (משלי כ״ה:י״ז) הוֹקַר רַגְלְךָ מִבֵּית רֵעֶךָ.</p>\n<p>אֶלָּא הָא אוּקְמוּהָ חַבְרַיָּיא, הַאי קְרָא (ס\"א בעולות ושלמים והאי בחטאות ואשמות וכתיב וכו') בְּעוֹלוֹת כְּתִיב. הַשְׁתָּא, רֵעֲךָ וְרֵעַ אָבִיךָ אַל תַּעֲזוֹב, לְמִפְלַח לֵיהּ, וּלְאִתְדַּבְּקָא בֵּיהּ, וּלְמֶעְבַּד פִּקּוּדוֹי. אַל תַּעֲזוֹב וַדַּאי. וְהָא דְּאִתְּמַר הוֹקַר רַגְלְךָ מִבֵּית רֵעֶךָ. כְּלוֹמַר הוֹקַר יִצְרְךָ, דְּלָא יִרְתַּח לָקֳבְלָךְ, וְלָא יִשְׁלוֹט בָּךְ, וְלַא תַּעֲבֵיד הִרְהוּרָא אַחֲרָא. מִבֵּית רֵעֶךָ, מַאן בֵּית רֵעֶךָ. דָּא נִשְׁמְתָא קַדִּישָׁא, דְּאָעִיל בָּהּ רֵעֶךָ וְיָהָבָהּ בְּגַוָּךְ.</p>\n<p>וְעַל דָּא פּוּלְחָנָא דְּקוּדְשָׁא בְּרִיךְ הוּא, לְרַחֲמָא לֵיהּ בְּכֹלָּא, כְּמָה דִּכְתִּיב, (דבהם ו) וְאָהַבְתָּ אֶת יְיָ' אֱלֹהֶיךָ. זֶה אֵלִי וְאַנְוֵהוּ, דְּכָל יִשְׂרָאֵל חָמוּ עַל יַמָּא, מַה דְּלָא חָמָא יְחֶזְקֵאל נְבִיאָה, וַאֲפִילּוּ אִינּוּן עוּבָּרֵי דְּבִמְעֵי אִמְּהוֹן, הֲווֹ חָמָאן וּמְשַׁבְּחָן לְקוּדְשָׁא בְּרִיךְ הוּא, וְכֻלְּהוּ הֲווֹ אַמְרִין זֶה אֵלִי וְאַנְוֵהוּ אֱלֹהֵי אָבִי וַאֲרוֹמְמֶנְהוּ, כְּמָה דְאַתְּ אָמֵר אֱלֹהֵי אַבְרָהָם.</p>\n<p>אָמַר רִבִּי יוֹסֵי, אִי הָכִי אֲמַאי וַאֲרוֹמְמֶנְהוּ, דְּהָא אֱלֹהֵי אַבְרָהָם לְעֵילָּא הוּא. אָמַר לֵיהּ, אֲפִילּוּ הָכִי אִצְטְרִיךְ, וְכֹלָּא חַד מִלָּה, וַאֲרוֹמְמֶנְהוּ בְּכֹלָּא, לְאַכְלְלָא, מַאן דְּיָדַע לְיַחֲדָא שְׁמָא קַדִּישָׁא רַבָּא, דְּהָא הוּא פֻּלְחָנָא עִלָּאָה דְּקוּדְשָׁא בְּרִיךְ הוּא.</p>\n<p>ר' יְהוּדָה הֲוָה יָתִיב קָמֵיהּ דְּר' שִׁמְעוֹן, וְהוּא קָארֵי, כְּתִיב (ישעיהו נ״ב:ח׳) קוֹל צוֹפַיִךְ נָשְׂאוּ קוֹל יַחְדָּיו יְרַנֵּנוּ. קוֹל צוֹפַיִךְ, מַאן אִינּוּן צוֹפַיִךְ. אֶלָּא אִלֵּין אִינּוּן דִּמְצָפָאן, אֵימָתַי יְרַחֵם קוּדְשָׁא בְּרִיךְ הוּא, לְמִבְנֵי בֵּיתֵיהּ. נָשְׂאוּ קוֹל, יִשְּׂאוּ קוֹל מִבָּעֵי לֵיהּ, מַאי נָשְׂאוּ קוֹל. אֶלָּא, כָּל בַּר נָשׁ דְּבָכֵי, וְאָרִים קַלֵיהּ עַל חָרְבַּן בֵּיתֵיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא, זָכֵי לְמָה דִּכְתִּיב לְבָתַר יַחְדָּיו יְרַנֵּנוּ. וְזָכֵי לְמֵחֱמֵי לֵיהּ בְּיִשּׁוּבָא בְּחֶדְוָותָא.</p>\n<p>בְּשׁוּב יְיָ' צִיּוֹן, (אמר ליה) בְּשׁוּב יְיָ' אֶל צִיּוֹן מִבָּעֵי לֵיהּ, מַאי בְּשׁוּב יְיָ' צִיּוֹן אֶלָּא בְּשׁוּב יְיָ' צִיּוֹן וַדַּאי. תָּא חֲזֵי, בְּשַׁעֲתָא דְּאִתְחֲרִיב יְרוּשָׁלַ ם לְתַתָּא, וּכְנֶסֶת יִשְׂרָאֵל אִתְתְּרָכַת, סָלִיק מַלְכָּא קַדִּישָׁא לְצִיּוֹן, וְאַנְגִיד לֵיהּ לָקֳבְלֵיהּ, בְּגִין דִּכְנֶסֶת יִשְׂרָאֵל (ויקרא ע\"ה) אִתְתְּרָכַת. (השתא דאתגליא כנסת ישראל סליק ליה לגביה) (ויצא קס\"ב ע\"ב) וְכַד תִּתְהַדָּר כְּנֶסֶת יִשְׂרָאֵל לְאַתְרָהּ, כְּדֵין יֵתוּב מַלְכָּא קַדִּישָׁא לְצִיּוֹן לְאַתְרֵיהּ, לְאִזְדַּוְּוגָא חַד בְּחַד, וְדָא הוּא בְּשׁוּב יְיָ' צִיּוֹן. וּכְדֵין זְמִינִין יִשְׂרָאֵל לְמֵימָר, זֶה אֵלִי וְאַנְוִהוּ. וּכְתִיב, זֶה יְיָ' קִוִּינוּ לוֹ נָגִילָה וְנִשְׂמְחָה בִּישׁוּעָתוֹ, בִּישׁוּעָתוֹ וַדַּאי.</p>"],[9520011616,"<p>(שמות ט״ו:ג׳) יְיָ' אִישׁ מִלְחָמָה יְיָ' שְׁמוֹ. רִבִּי אַבָּא פָּתַח (במדבר כ״א:י״ד) עַל כֵּן יֵאָמַר בְּסֵפֶר מִלְחֲמוֹת יְיָ' אֶת וָהֵב בְּסוּפָה וְאֶת הַנְּחָלִים אַרְנוֹן. כַּמָה אִית לָן לְאִסְתַּכְּלָא בְּפִתְגָּמֵי אוֹרַיְיתָא, כַּמָה אִית לָן לְעַיְּינָא בְּכָל מִלָּהָא, דְּלֵית לָךְ מִלָּה בְּאוֹרַיְיתָא, דְּלָא אִתְרְמִיזָא בִּשְׁמָא קַדִּישָׁא עִלָּאָה, וְלֵית לָךְ מִלָּה בְּאוֹרַיְיתָא, דְּלֵית בָּהּ כַּמָּה רָזִין, כַּמָּה טַעֲמִין, כַּמָּה שָׁרָשִׁין, כַּמָּה עֲנָפִין.</p>\n<p><Nonei></i>הָכָא אִית לְאִסְתַּכְּלָא, עַל כֵּן יֵאָמַר בְּסֵפֶר מִלְחֲמוֹת יְיָ', וְכִי סֵפֶר מִלְחֲמוֹת יְיָ', אָן הוּא. אֶלָּא הָכִי אִתְּעָרוּ חַבְרַיָּיא, כָּל מַאן דְּאַגָּח קְרָבָא בְּאוֹרַיְיתָא, זָכֵי לְאַסְגָּאָה שְׁלָמָא בְּסוֹף מִלּוֹי. כָּל קְרָבִין דְּעָלְמָא, קְטָטָה וְחֻרְבָּנָא. וְכָל קְרָבִין דְּאוֹרַיְיתָא, שְׁלָמָא וּרְחִימוּתָא, הֲדָא הוּא דִכְתִיב עַל כֵּן יֵאָמַר בְּסֵפֶר מִלְחֲמוֹת יְיָ' אֶת וָהֵב בְּסוּפָה, כְּלוֹמַר, אַהֲבָה בְּסוּפָה. דְּלֵית לָךְ אַהֲבָה וּשְׁלָמָא בַּר מֵהַאי.</p>\n<p>תּוּ קַשְׁיָא בְּאַתְרֵיהּ. עַל כֵּן יֵאָמַר בְּסֵפֶר מִלְחֲמוֹת יְיָ', בְּתוֹרַת מִלְחֲמוֹת יְיָ' מִבָּעֵי לֵיהּ, מַאי בְּסֵפֶר. אֶלָּא רָזָא עִלָּאָה הוּא, אֲתָר אִית לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא, דְּאִקְרֵי סֵפֶר (נ\"א ומספר) כְּמָה דְאַתְּ אָמֵר, (ישעיה לה) דִּרְשׁוּ מֵעַל סֵפֶר יְיָ' וּקְרָאוּ. דְּכָל חֵילִין וּגְבוּרָן דְּעָבִיד קוּדְשָׁא בְּרִיךְ הוּא, בְּהַהוּא סֵפֶר תַּלְיָין, (נ\"א ומתמן נפקין</p>\n<p>את והב בסופה. מאן והב, אלא כל אינון חילין, וכל אינון גבוראן דעביד קודשא בריך הוא, בההוא ספר תליין.) וְכַד אַגָּח קוּדְשָׁא בְּרִיךְ הוּא קְרָבוֹי, בְּחַד אֲתָר דְּאִיהוּ בְּסוֹפָא דְּדַרְגִּין, וְאִקְרֵי וָהֵב. כְּמָה דְאַתְּ אָמֵר (משלי ל׳:ט״ו) לַעֲלוּקָה שְׁתֵּי בָּנוֹת הַב הַב. בְּסוּפָה: בְּסוֹף דַּרְגִּין אִשְׁתְּכַח. בְּסוּפָה: יָם סוֹף אִתְקְרֵי, יָם דְּאִיהוּ סוֹף לְכָל דַּרְגִּין.</p>\n<p>וְאֶת הַנְּחָלִים אַרְנוֹן וְעִם נַחְלַיָיא דְּאִשְׁתָּכְחוּ וְאַתְנֶגִידוּ. לְגַבֵּיה, מֵהַהוּא אֲתָר עִלָּאָה, דְּאִקְרֵי אַרְנוֹן. מַאי אַרְנוֹן, זִוּוּגָא עִלָּאָה דַּחֲבִיבוּתָא, דְּלָא (נ' ע\"ב) מִתְפָּרְשָׁאן לְעָלְמִין, כְּמָה דְּאַתְּ אָמֵר (בראשית ב׳:י׳) וְנָהָר יוֹצֵא מֵעֵדֶן. וּבְדָא, מִשְׁתָּרְשָׁן שָׁרָשׁוֹי, וְאִתְרְבִיאוּ עֲנָפָיו, לְאוֹשָטָא קְרָבוֹי בְּכָל אֲתָר, לְאוֹשָטָא חֵילִין וּגְבוּרָאן, וּלְאִתְחֲזָאָה שׁוּלְטָנָא רַבָּא וְיַקִּירָא דְּכֹלָּא.</p>\n<p>תָּא חֲזֵי, כַּד מִתְעָרִין גְּבוּרָאן וּקְרָבִין דְּקוּדְשָׁא בְּרִיךְ הוּא, כַּמָּה גַּרְדִּינֵי טְהִירִין, מִתְעָרִין לְכָל עִיבָר, כְּדֵין שַׁנְּנָן רוּמְחִין, וְסַיְיפִין, וּמִתְעָרִין גְּבוּרָאן, וְיַמָּא אִתְרְגִישַׁת וְגַלְגַּלּוֹי סַלְּקִין וְנַחְתִּין, וְאַרְבִין דְּאַזְלִין וְשָׁאטָן בְּיַמָּא, לְכָל עִיבָר מִסְתַּלְּקִין. שִׁנָּנָא קְרָבָא (נ\"א חרבא) בְּאַבְנִי בַּלִּסְטְרָאוֹת, מָארֵי דְּרוֹמְחִין וְסַיְיפִין, כְּדֵין (תהילים מ״ה:ו׳) חִצֶּיךָ שְׁנוּנִים (נ\"א מתערין לאושטא קרבין בכל אתר ולאושטא חילין וגבוראן לכל עיבר כדין ימא אתרגישת וגלגלוי סלקין וארבין דאזלין ושאטין נחתין וסלקין וזעפא אשתכח. כדין מתערין מגיחי קרבא באבני בלסטראין מארי דרומחין וסייפין גירין וקשתין כמה דאת אמר חציך שנונים) וְקוּדְשָׁא בְּרִיךְ הוּא אִתְתָּקִיף בְּחֵילוֹי, וּלְאִתְעֲרָא קְרָבָא. וַוי לְאִינוּן דְּמַלְכָּא קַדִּישָׁא יִתְעָר עָלַיְיהוּ קְרָבָא. כְּדֵין כְּתִיב, יְיָ' אִישׁ מִלְחָמָה.</p>\n<p>וּמֵהָכָא, וּמֵאִינּוּן אַתְוָון, וּמֵהַאי קְרָא, נָפְקִין טוּרֵי קְרָבָא לְאִינוּן חַיָּיבַיָּא, לְאִילֵּין מָארֵי דְּבָבוּ דְּחָבוּ לְקוּדְשָׁא בְּרִיךְ הוּא. וְאַתְוָון אִתְגַּלְּיָין לְאִינוּן מָארֵי קְשׁוֹט, וְהָא אִתְפָּרְשָׁן מִלִּין וְהָא אִתְּמַר.</p>\n<p>יְיָ' אִישׁ מִלְחָמָה יְיָ' שְׁמוֹ. כֵּיוָן דִּכְתִּיב יְיָ' אִישׁ מִלְחָמָה, לָא יְדַעְנָא דַּיְיָ' שְׁמוֹ. אֶלָּא, כְּמָה דִּכְתִּיב, (בראשית י״ט:כ״ד) וַיְיָ' הִמְטִיר עַל סְדוֹם וְעַל עֲמוֹרָה גָּפְרִית וָאֵשׁ מֵאֵת יְיָ' מִן הַשָּׁמָיִם. וְכֹלָּא בְּהַאי סֵפֶר תַּלְיָין, כְּמָה דְאַתְּ אָמֵר (איוב כ׳:כ״ז) יְגַלּוּ שָׁמַיִם עֲוֹנוֹ וְאֶרֶץ מִתְקוֹמָמָה לוֹ. (ועל דא)</p>"],[9520011617,"<p>תָּא חֲזֵי, בְּשַׁעֲתָא דְּקוּדְשָׁא בְּרִיךְ הוּא אִתְּעַר קְרָבָא בְּעָלְמָא, עִלָּאֵי וְתַתָּאֵי אִתְעַקְּרוּ מֵאַתְרַיְיהוּ, כְּמָה דְּאוֹקִימְנָא הֲדָא הוּא דִכְתִיב מַרְכְּבוֹת פַּרְעֹה וְחֵילוֹ יָרָה בַיָּם. וּלְזִמְנָא דְּאָתֵי, זַמִין קוּדְשָׁא בְּרִיךְ הוּא לְאַגָּחָא קְרָבָא עִלָּאָה וְתַקִּיפָא בַּעֲמַמְיָא, בְּגִין לְאוֹקְרָא שְׁמֵיהּ, הֲדָא הוּא דִכְתִיב (זכריה י״ד:ג׳) וְיָצָא יְיָ' וְנִלְחַם בַּגּוֹיִם הָהֵם כַּיּוֹם הִלָּחֲמוֹ בְּיוֹם קְרָב וּכְתִיב (יחזקאל ל״ח:כ״ג) וְהִתְגַּדִּלְתִּי וְהִתְקַדִּשְׁתִּי וְנוֹדַעְתִּי וְגוֹ'. (מרכבות פרעה וחילו ירה בים. כד אתער קודשא בריך הוא קרבא כדין אתערו דרגין עלאין ודרגין תתאין דלתתא וכדין מרכבות פרעה וחילו ירה בים)</p>\n<p>ר' יְהוּדָה פָּתַח וְאָמַר, (תהילים ע״ז:י״ז) רָאוּךָ מַּיִם אֱלֹהִים רָאוּךָ מַּיִם יָחִילוּ וְגוֹ', בְּשַׁעֲתָא דְּעָבְרוּ יִשְׂרָאֵל יַת יַמָּא, אָמַר קוּדְשָׁא בְּרִיךְ הוּא לְמַלְאָכָא דִּי מְמָנָא עַל יַמָּא, פָּלִיג מֵימָךְ. אֲמַר לֵיהּ לָמָּה. אֲמַר לֵיהּ בְּגִין דְּבָנַי יַעַבְרוּן בְּגַוָּוךְ. אָמַר לֵיהּ, פּוּרְקָנָא דְּקִיטְנָא קְשׁוֹט. מַאי שְׁנָא אִלֵּין מֵאִלֵּין.</p>\n<p>אֲמַר לֵיהּ עַל תְּנַאי דָּא, עֲבָדִית לְיַמָּא כַּד בָּרָאתִי עָלְמָא. מַה עָבִיד קוּדְשָׁא בְּרִיךְ הוּא, אִתְּעַר גְּבוּרְתָּא דִּילֵיהּ, וְאִתְקְמָטוּ מַיָּא. הֲדָא הוּא דִכְתִיב רָאוּךָ מַּיִם אֱלהִים רָאוּךָ מַּיִם יָחִילוּ. אֲמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, קְטוֹל כָּל אִינּוּן אֹכְלוֹסִין, לְבָתַר אַרְמִי לוֹן לְבַר. לְבָתַר חָפֵי יַמָּא עָלַיְיהוּ, הֲדָא הוּא דִכְתִיב מַרְכְּבוֹת פַּרְעֹה וְחֵילוֹ יָרָה בַיָּם.</p>\n<p>אָמַר רִבִּי אֶלְעָזָר, פּוּק חָמֵי כַּמָּה רְתִיכִין עָבֵד קוּדְשָׁא בְּרִיךְ הוּא לְעֵילָּא, כַּמָּה אֹכְלוֹסִין, כַּמָּה חַיָּילִין, וְכֻלְּהוּ <Nonei></i>קְשִׁירִין אִלֵּין בְּאִלֵּין. (והא אוליפנא) כֻּלְּהוּ רְתִיכִין אִלֵּין לְאִלֵּין, דַּרְגִּין עַל דַּרְגִּין, וּמִסִּטְרָא דִּשְׂמָאלָא מִתְעָרִין רְתִיכִין (נ\"א דלא) קַדִּישִׁין שַׁלִּיטִין. וְכֻלְּהוּ דַּרְגִּין יְדִיעָן לְעֵילָּא.</p>\n<p>וְהָא אִתְּעַרְנָא בִּבְכוֹר פַּרְעֹה, דְּהוּא דַּרְגָּא חַד, דְּקָטַל קוּדְשָׁא בְּרִיךְ הוּא (דרגא דיליה נ\"א חיליה) וְתָבַר לֵיהּ מְשׁוּלְשֶׁלֵיהּ תַּקִּיפָא, (ודרגא דיליה) תְּחוֹת שׁוּלְטָנֵיהּ, כַּמָּה רְתִיכִין וְכַמָּה חַיָּילִין דְּקוּזְמִיטִין מִסְּטָר שְׂמָאלָא, מִנְּהוֹן אֲחִידָן בַּאֲתָר עִלָּאָה דְּשׁוּלְטָנוּתָא דִּלְהוֹן, וּמִנְהוֹן אֲחִידָן בְּמַלְכוּתָא דִּלְעֵילָּא. מִנְּהוֹן אֲחִידָן בָּתַר אַרְבַּע כָּרְסֶוָון (ס\"א חיון), (נ\"א רחיין) כְּמָה דְּאִתְּמַר.</p>\n<p>וְכֻלְּהוּ אִתְמְסָרוּ בִּידֵיהּ, בְּדִינָא דְּמַלְכוּתָא, דְּאִקְרֵי יַמָּא רַבָּא, לְתַבְרָא לוֹן מִדַּרְגֵּיהוֹן, וְכַד אִינּוּן אִתְּבָּרוּ לְעֵילָּא, כָּל אִינּוּן דִּלְתַתָּא אִתְּבָּרוּ, וְאִתְאֲבִידוּ בְּיַמָּא תַּתָּאָה. הֲדָא הוּא דִכְתִיב, מַרְכְּבוֹת פַּרְעֹה וְחֵילוֹ יָרָה בַיָּם. בַיָּם סְתָם.</p>\n<p>וּמִבְחַר שָׁלִישָׁיו טֻבְּעוּ בְיַם סוּף. וּמִבְחַר שָׁלִישָׁיו, הָא אִתְּמַר, וְשָׁלִישִׁים עַל כֻּלּוֹ, כֻּלְּהוּ דַּרְגִּין תְּרֵין וְחָד. אִלֵּין עַל אִלֵּין. כְּגַוְונָא עִלָּאָה הָכִי אִתְעָבִידוּ. וְכֻלְּהוּ אִתְמְסָרוּ בִּידָהָא, לְאִתָּבְּרָא מִשּׁוּלְטָנִיהוֹן, אִלֵּין וְאִלֵּין.</p>\n<p>תָּא חֲזֵי, הָא אִתְּמַר דְּכֻלְּהוּ עֶשֶׂר מָחָאן דְּעָבַד קוּדְשָׁא בְּרִיךְ הוּא בְּמִצְרַיִם, כֹּלָּא הֲוָה יְדָא חֲדָא, דִּשְׂמָאלָא אַכְלִיל בִּימִינָא. דְּעֶשֶׂר אֶצְבְּעָן כְּלִילָן דָּא בְּדָא, לָקֳבֵל עֶשֶׂר אֲמִירָן, דְּקוּדְשָׁא בְּרִיךְ הוּא אִתְקְרֵי בְּהוּ לְבָתַר. לָקֳבְלֵיהּ דְּכֹלָּא הַאי דְּיַמָּא, תַּקִּיף וְרַב וְשַׁלִּיטָא. כְּמָה דְאַתְּ אָמֵר, (ישעיהו ח׳:כ״ג) וְהָאַחֲרוֹן הִכְבִּיד. הֲדָא הוּא דִכְתִיב מַרְכְּבוֹת פַּרְעֹה וְחֵילוֹ יָרָה בַיָּם וְגוֹ'. וּלְזִמְנָא דְּאָתֵי, זַמִּין קוּדְשָׁא בְּרִיךְ הוּא לְקַטְּלָא אֹכְלוֹסִין וְקוּזְתוּרְנָטִין וְקוֹנְטְירִיסִין וְקָלַטְירוֹלְסִין דֶּאֱדוֹם הֲדָא הוּא דִכְתִיב, (ישעיהו ס״ג:א׳) מִי זֶה בָּא מֵאֱדוֹם חֲמוּץ בְּגָדִים מִבָּצְרָה.</p>\n<p>(שמות ט״ו:ד׳) מַרְכְּבוֹת פַּרְעֹה וְחֵילוֹ יָרָה בַיָּם. רִבִּי יִצְחָק פָּתַח, (ירמיהו י׳:י״ג) לְקוֹל תִּתּוֹ הֲמוֹן מַיִם בַּשָּׁמַיִם וַיַעֲלֶה נְשִׂיאִים מִקְּצֵה הָאָרֶץ בְּרָקִים לַמָּטָר עָשָׂה וַיּוֹצֵא רוּחַ מֵאוֹצְרוֹתָיו. הָא תָּנִינָן, שִׁבְעָה רְקִיעִין עָבֵד קוּדְשָׁא בְּרִיךְ הוּא, וּבְכָל רְקִיעָא וּרְקִיעָא כֹּכָבִין קְבִיעִין, וְרַהֲטִין בְּכָל רְקִיעָא וּרְקִיעָא, וּלְעֵילָּא מִכֻּלְּהוּ עֲרָבוֹת.</p>\n<p>וְכָל רְקִיעָא וּרְקִיעָא בְּהִלּוּכוֹ מָאתַן שְׁנִין, וְרוּמֵיהּ חֲמֵשׁ מְאָה שְׁנִין. וּבֵין רְקִיעָא וּרְקִיעָא, חֲמֵשׁ מְאָה שְׁנִין. וְהַאי עֲרָבוֹת הִלּוּכוֹ בְּאוֹרְכֵיהּ, אֶלֶף וַחֲמֵשׁ מֵאָה שְׁנִין. וּפוּתְיֵהּ, אֶלֶף וַחֲמֵשׁ מֵאָה שְׁנִין, וּמִזִּיוָא דִּילֵיהּ, נָהֲרִין כָּל אִינּוּן רְקִיעִין.</p>\n<p>וְהָא תָּנֵינָן, לְעֵילָּא מֵעֲרָבוֹת, רָקִיעַ דְּחַיּוֹת. פַּרְסוֹת דְּחַיּוֹת קַדִּישִׁין וְרוּמְהוֹן, כְּכֻלְּהוּ. לְעֵילָּא מִנְּהוֹן קַרְסוּלַיִן דְּחַיּוֹת כְּכֻלְּהוּ. שׁוֹקֵי הַחַיּוֹת, כְּכֻלְּהוּ. אַרְכּוּבִין דְּחַיּוֹת, כְּכֻלְּהוּ. יַרְכִין דְּחַיּוֹת, כְּכֻלְּהוּ. עַגְבֵי דְּחַיּוֹת, כְּכֻלְּהוּ. וְגוּפָא דְּחַיּוֹת כְּכֻלְּהוּ. גַּדְפַּיְיהוּ, כְּכֻלְּהוּ. וְצַוָּארַיְהוּ, כְּכֻלְּהוּ. רָאשֵׁי הַחַיּוֹת, כְּכֻלְּהוּ. מַאי כְּכֻלְּהוּ. כָּקֳבְלֵי כֻּלְּהוּ.</p>\n<p>וְכַל שַׁיְיפָא וְשַׁיְיפָא דִּבְחַיּוֹת, לָקֳבֵל שִׁבְעָה תְּהוֹמִין, וְלָקֳבֵל שִׁבְעָה הֵיכָלִין וְלָקֳבֵל מֵאַרְעָא לִרְקִיעָא. וְלָקֳבֵל מֵרְקִיעָא לִרְקִיעָא, וְשִׁיעוּרָא דְּכֻלְּהוּ וְרוּמְהוֹן עֶשְׂרִין וַחֲמִשָּׁה אַלְפִין חוּלָקִין, מִשִּׁיעוּרָא דְּקוּדְשָׁא בְּרִיךְ הוּא, כְּמָה דְּאוֹקִימְנָא.</p>\n<p>וְעוֹד רְקִיעָא חַד לְעֵילָּא, מִן קַרְנֵי הַחַיּוֹת, דִּכְתִּיב, (יחזקאל א׳:כ״ב) וּדְמוּת עַל רָאשֵׁי הַחַיָּה רָקִיעַ. מִלְּרַע כַּמָּה רְתִיכִין, בִּימִינָא וּשְׂמָאלָא.</p>\n<p>מִתְּחוֹת יַמָּא שָׁרָאן כֻּלְּהוּ נוּנֵי יַמָּא, וְשָׁטָאן, אִתְכְּנָפוּ בְּזָוִיהוֹן אַרְבַּע, נַחְתִּין בְּדַרְגַּיְיהוּ, וְכֻלְּהוּ רְתִיכִין אִקְרוּן בִּשְׁמָהָן. מִתְּחוֹת אִלֵּין, אַזְלִין וְשָׁאטִין אִינּוּן זְעִירִין, דַּרְגִּין עַל דַּרְגִּין, דִּכְתִּיב, (תהילים ק״ד:כ״ה) זֶה הַיָּם גָּדוֹל וּרְחַב יָדַיִם שָׁם רֶמֶשׂ וְאֵין מִסְפָּר חַיּוֹת קְטַנּוֹת עִם גְּדוֹלוֹת. וְהָא אוֹקִימְנָא מִלֵּי.</p>\n<p>מִסְּטָר שְׂמָאלָא תַּתָּאָה, קוּזְמִיטָא סִטְרָא אַחֲרָא וְאֲחִידָן מֵאִינּוּן דִּלְעֵילָּא, וְנַחְתּוּ לְאִתָּבְּרָא מֵחֵילָא תַּקִּיפָא קַדִּישָׁא. כְּמָה דְּאוֹקִימְנָא, מַרְכְּבֹת פַּרְעֹה וְחֵילוֹ וְגוֹ'.</p>"]]});
